ridge_model = CalibratedClassifierCV(RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced'), method='sigmoid')

# --- UZMAN 2: KLİNİK (BOOSTING TEAM) ---
clin_preprocessor = ColumnTransformer(
    transformers=[
        ('num', StandardScaler(), ['age'] + [f'nms_{i}' for i in range(30)]),
        ('cat', OrdinalEncoder(handle_unknown='use_encoded_value', unknown_value=-1), ['gender', 'task'])
    ]
)

# Klinik modeller (Sadece klinik veriye bakacaklar)
