import numpy as np
import pandas as pd
import zipfile
import json
from glob import glob
from tqdm import tqdm
from scipy.signal import detrend, resample
from sklearn.model_selection import StratifiedGroupKFold
from sklearn.preprocessing import StandardScaler, OrdinalEncoder
from sklearn.metrics import (balanced_accuracy_score, accuracy_score, f1_score,
                             roc_auc_score, confusion_matrix, recall_score, roc_curve)
from sklearn.pipeline import Pipeline
from sklearn.compose import ColumnTransformer
from sklearn.linear_model import RidgeClassifierCV, LogisticRegression
from sklearn.svm import SVC
from sklearn.decomposition import PCA
from sklearn.calibration import CalibratedClassifierCV
from sklearn.ensemble import VotingClassifier
from sktime.transformations.panel.rocket import MiniRocketMultivariate
from imblearn.under_sampling import RandomUnderSampler
from catboost import CatBoostClassifier
from xgboost import XGBClassifier
from lightgbm import LGBMClassifier

# --- 2. AYARLAR ---
ZIP_FILE_NAME = "pads-parkinsons-disease-smartwatch-dataset-1.0.0.zip"
METADATA_FILE = "subjects.csv"
EXTRACT_PATH = "./pads_data_v46"
SEQ_LEN = 400
CROP_START = 50

# --- 3. DOSYA HAZIRLIĞI ---
if not os.path.exists('/content/drive'):
    from google.colab import drive
    drive.mount('/content/drive')

zip_path = None
possible_paths = [f"/content/{ZIP_FILE_NAME}", f"/content/drive/MyDrive/{ZIP_FILE_NAME}"]
for p in possible_paths:
    if os.path.exists(p): zip_path = p; break

if not zip_path:
    try:
        res = subprocess.getoutput(f"find /content/drive -name '{ZIP_FILE_NAME}' -print -quit")
        if res and "No" not in res: zip_path = res.strip()
    except: pass

if zip_path and not os.path.exists(EXTRACT_PATH):
    print(f"📂 Zip açılıyor: {zip_path}")
    with zipfile.ZipFile(zip_path, 'r') as zip_ref:
        zip_ref.extractall(EXTRACT_PATH)
elif os.path.exists("./pads_data_final"):
    EXTRACT_PATH = "./pads_data_final"

meta_path = None
if os.path.exists(METADATA_FILE): meta_path = METADATA_FILE
elif os.path.exists(f"/content/drive/MyDrive/{METADATA_FILE}"): meta_path = f"/content/drive/MyDrive/{METADATA_FILE}"

# --- 4. VERİ OKUMA ---
print("\n--- Veri Okuma ---")
patient_info = {}
if meta_path:
    df_meta = pd.read_csv(meta_path)
    df_filtered = df_meta[df_meta['label'].isin([0, 1])]
    for _, row in df_filtered.iterrows():
        pid = str(row['id']).zfill(3)
        patient_info[pid] = {'label': int(row['label']), 'age': row['age'], 'gender': str(row['gender'])}
else:
    p_files = glob(os.path.join(EXTRACT_PATH, "**", "patient_*.json"), recursive=True)
    for pf in p_files:
        with open(pf) as f: d = json.load(f)
        pid = str(d.get('id', ''))
        cond = d.get('condition', '').lower()
        if "parkinson" in cond: lbl = 1
        elif "healthy" in cond: lbl = 0
        else: continue
        if pid: patient_info[pid] = {'label': lbl, 'age': d.get('age', 60), 'gender': str(d.get('gender', 'unknown'))}

nms_data = {}
q_files = glob(os.path.join(EXTRACT_PATH, "**", "questionnaire_response_*.json"), recursive=True)
for qf in q_files:
    try:
        with open(qf) as f: q = json.load(f)
        pid = str(q.get('subject_id', ''))
        if pid not in patient_info: continue
        items = q.get('item', [])
        answers = [0] * 30
        for item in items:
            link_id = item.get('link_id', '99')
            try:
                idx = int(link_id) - 1
                if 0 <= idx < 30:
                    ans = item.get('answer', False)
                    answers[idx] = 1 if ans is True else 0
            except: continue
        nms_data[pid] = answers
    except: continue

X_signals, X_clinical, y_list, group_list = [], [], [], []
s_files = glob(os.path.join(EXTRACT_PATH, "**", "*.txt"), recursive=True)
s_files = [f for f in s_files if "LICENSE" not in f]

print(f"Veriler işleniyor ({len(s_files)} dosya)...")
for f_path in tqdm(s_files):
    try:
        fname = os.path.basename(f_path)
        pid = fname.split('_')[0]
        if pid not in patient_info: continue

        task_name = "Unknown"
        if len(fname.split('_')) > 1: task_name = fname.split('_')[1]

        df = pd.read_csv(f_path, header=None)
        raw = df.select_dtypes(include=[np.number]).values
        if raw.shape[0] < 100: continue
        if raw.shape[0] > CROP_START: raw = raw[CROP_START:, :]
        raw = detrend(raw, axis=0)
        if raw.shape[0] > raw.shape[1]: raw = raw.T
        dat_res = resample(raw, SEQ_LEN, axis=1)

        X_signals.append(dat_res)

        p = patient_info[pid]
        nms = nms_data.get(pid, [0]*30)
        clin_vec = [float(p['age']), str(p['gender']), str(task_name)] + nms
        X_clinical.append(clin_vec)

        y_list.append(p['label'])
        group_list.append(pid)
    except: continue

max_ch = max([x.shape[0] for x in X_signals])
X_sig_arr = np.zeros((len(X_signals), max_ch, SEQ_LEN))
for i, x in enumerate(X_signals): X_sig_arr[i, :x.shape[0], :] = x

feat_cols = ['age', 'gender', 'task'] + [f'nms_{i}' for i in range(30)]
df_clinical = pd.DataFrame(X_clinical, columns=feat_cols)
y = np.array(y_list)
groups = np.array(group_list)

class_ratio = np.sum(y == 1) / np.sum(y == 0)
print(f"\n✅ Veri Hazır: {X_sig_arr.shape} Sinyal, {df_clinical.shape} Klinik.")

# --- 5. MODEL EĞİTİMİ (HYBRID SIGNAL EXPERT) ---
print("\n--- 🚀 Hibrit Uzman Eğitimi (Ridge + SVM) ---")

print("⏳ MiniRocket özellikleri çıkarılıyor...")
rocket = MiniRocketMultivariate(num_kernels=5000, random_state=42)
X_rocket = rocket.fit_transform(X_sig_arr)

# --- UZMAN 1: SİNYAL EKİBİ ---
# 1.a Ridge (Lineer)
ridge = CalibratedClassifierCV(RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced'), method='sigmoid')

# 1.b SVM (Non-Lineer) + PCA
# 10.000 özellik SVM'i yorar, PCA ile sıkıştırıp veriyoruz.
svm_pipe = Pipeline([
    ('scaler', StandardScaler()),
    ('pca', PCA(n_components=50, random_state=42)), # En önemli 50 bileşen
    ('svm', SVC(kernel='rbf', class_weight='balanced', probability=True, C=10, gamma='scale'))
])

# Sinyal Voting
signal_ensemble = VotingClassifier(
    estimators=[('ridge', ridge), ('svm', svm_pipe)],
    voting='soft', weights=[1, 1] # İkisine de eşit güven
)

# --- UZMAN 2: KLİNİK EKİBİ ---
clin_preprocessor = ColumnTransformer(
    transformers=[
        ('num', StandardScaler(), ['age'] + [f'nms_{i}' for i in range(30)]),
        ('cat', OrdinalEncoder(handle_unknown='use_encoded_value', unknown_value=-1), ['gender', 'task'])
    ]
)

# Boosting Takımı
cat_clf = CatBoostClassifier(iterations=600, learning_rate=0.03, depth=6, auto_class_weights='Balanced', verbose=0, allow_writing_files=False)
xgb_clf = XGBClassifier(n_estimators=400, learning_rate=0.03, max_depth=6, scale_pos_weight=1.0/class_ratio, eval_metric='logloss', verbosity=0)
lgbm_clf = LGBMClassifier(n_estimators=400, learning_rate=0.03, max_depth=6, class_weight='balanced', verbose=-1)

clinical_ensemble = VotingClassifier(
    estimators=[('cat', cat_clf), ('xgb', xgb_clf), ('lgbm', lgbm_clf)],
    voting='soft', weights=[1, 1, 1]
)

# 10-Fold CV
cv = StratifiedGroupKFold(n_splits=10, shuffle=True, random_state=42)
metrics = {'bal_acc': [], 'spec': [], 'sens': [], 'auc': []}

print("\n--- Cross-Validation (Hybrid Fusion) ---")
for fold, (train_idx, test_idx) in enumerate(cv.split(X_rocket, y, groups=groups)):
    # Veri Bölme
    X_r_tr, X_r_te = X_rocket.iloc[train_idx].values, X_rocket.iloc[test_idx].values
    df_c_tr, df_c_te = df_clinical.iloc[train_idx], df_clinical.iloc[test_idx]
    y_tr, y_te = y[train_idx], y[test_idx]
    g_te = groups[test_idx]

    # Klinik Transform
    clin_preprocessor.fit(df_c_tr)
    X_c_tr = clin_preprocessor.transform(df_c_tr)
    X_c_te = clin_preprocessor.transform(df_c_te)

    # --- EĞİTİM (AYRI KOLLAR) ---
    signal_ensemble.fit(X_r_tr, y_tr)
    clinical_ensemble.fit(X_c_tr, y_tr)

    # --- TAHMİN ---
    p_signal = signal_ensemble.predict_proba(X_r_te)[:, 1]
    p_clinical = clinical_ensemble.predict_proba(X_c_te)[:, 1]

    # --- FUSION ---
    # Sinyal modelimiz artık SVM ile güçlendiği için ona biraz daha ağırlık verebiliriz
    final_probs = (0.55 * p_signal) + (0.45 * p_clinical)

    # --- HASTA OYLAMASI ---
    df_res = pd.DataFrame({'pid': g_te, 'true': y_te, 'prob': final_probs})
    pat_res = df_res.groupby('pid').mean()
    y_true_pat = pat_res['true'].astype(int).values
    y_prob_pat = pat_res['prob'].values

    # Threshold Tuning
    fpr, tpr, thresholds = roc_curve(y_true_pat, y_prob_pat)
    best_th = thresholds[np.argmax(tpr - fpr)]
    y_pred_pat = (y_prob_pat > best_th).astype(int)

    # Skorlar
    bal = balanced_accuracy_score(y_true_pat, y_pred_pat)
    spec = recall_score(y_true_pat, y_pred_pat, pos_label=0)
    sens = recall_score(y_true_pat, y_pred_pat, pos_label=1)
    auc = roc_auc_score(y_true_pat, y_prob_pat)

    metrics['bal_acc'].append(bal)
    metrics['spec'].append(spec)
    metrics['sens'].append(sens)
    metrics['auc'].append(auc)

    print(f"Fold {fold+1}: BalAcc={bal:.3f} | Spec={spec:.3f} | Sens={sens:.3f} | AUC={auc:.3f}")

# --- FİNAL ---
print("\n" + "="*40)
print(f"ORTALAMA BALANCED ACCURACY: %{np.mean(metrics['bal_acc'])*100:.2f} (Hedef: >91.16)")
print(f"ORTALAMA SPECIFICITY (HC) : %{np.mean(metrics['spec'])*100:.2f}")
print(f"ORTALAMA SENSITIVITY (PD) : %{np.mean(metrics['sens'])*100:.2f}")
print(f"ORTALAMA ROC AUC          : %{np.mean(metrics['auc'])*100:.2f}")
print("="*40)

if np.mean(metrics['bal_acc']) > 0.9116:
    print("🚀 MİSYON TAMAMLANDI! SVM desteği ile skor geçildi.")

