# --- 4. ADVANCED FEATURE EXTRACTION ---
def extract_advanced_features(signal):
    """Extract comprehensive features from time-series signal"""
    features = []

    # Statistical features
    features.extend([
        np.mean(signal), np.std(signal), np.median(signal),
        np.min(signal), np.max(signal), np.ptp(signal),
        skew(signal), kurtosis(signal),
        np.percentile(signal, 25), np.percentile(signal, 75)
    ])

    # Wavelet features (using Daubechies wavelets)
    try:
        coeffs = pywt.wavedec(signal, 'db4', level=3)
        for c in coeffs:
            features.extend([np.mean(c), np.std(c), np.max(np.abs(c))])
    except:
        features.extend([0] * 12)  # Fallback

    # Frequency domain features
    try:
        freqs, psd = welch(signal, fs=100, nperseg=min(256, len(signal)))
        features.extend([
            np.sum(psd), np.max(psd), np.argmax(psd),
            entropy(psd + 1e-10)
        ])
    except:
        features.extend([0] * 4)

    # Temporal features
    diff1 = np.diff(signal)
    features.extend([
        np.mean(np.abs(diff1)), np.std(diff1),
        np.sum(np.abs(diff1))
    ])

    return np.array(features)

