        raw = detrend(raw, axis=0)
        if raw.shape[0] > raw.shape[1]:
            raw = raw.T

        dat_res = resample(raw, SEQ_LEN, axis=1)
        X_signals.append(dat_res)

        # Extract handcrafted features from each channel
        hc_features = []
        for ch in range(dat_res.shape[0]):
            hc_features.extend(extract_advanced_features(dat_res[ch, :]))
        X_handcrafted.append(hc_features)

        # Clinical features
        p = patient_info[pid]
