# Convert to arrays
max_ch = max([x.shape[0] for x in X_signals])
X_sig_arr = np.zeros((len(X_signals), max_ch, SEQ_LEN))
for i, x in enumerate(X_signals):
    X_sig_arr[i, :x.shape[0], :] = x

X_handcrafted_arr = np.array(X_handcrafted)

feat_cols = ['age', 'gender', 'task', 'nms_sum', 'nms_mean', 'nms_std', 'nms_nonzero'] + \
            [f'nms_{i}' for i in range(30)]
df_clinical = pd.DataFrame(X_clinical, columns=feat_cols)

y = np.array(y_list)
groups = np.array(group_list)

class_ratio = np.sum(y == 1) / (np.sum(y == 0) + 1e-10)
print(f"\n✅ Veri Hazır:")
print(f"   - Sinyal: {X_sig_arr.shape}")
print(f"   - El yapımı özellikler: {X_handcrafted_arr.shape}")
print(f"   - Klinik: {df_clinical.shape}")
print(f"   - Class ratio (PD/HC): {class_ratio:.2f}")

# --- 6. DEEP LEARNING MODEL ---
def create_cnn_lstm_model(input_shape, learning_rate=0.001):
    """1D CNN + LSTM hybrid model"""
    inputs = layers.Input(shape=input_shape)

    # CNN blocks for feature extraction
    x = layers.Conv1D(64, 7, padding='same', activation='relu',
                      kernel_regularizer=regularizers.l2(0.001))(inputs)
    x = layers.BatchNormalization()(x)
    x = layers.MaxPooling1D(2)(x)
    x = layers.Dropout(0.3)(x)

    x = layers.Conv1D(128, 5, padding='same', activation='relu',
                      kernel_regularizer=regularizers.l2(0.001))(x)
    x = layers.BatchNormalization()(x)
    x = layers.MaxPooling1D(2)(x)
    x = layers.Dropout(0.3)(x)

    x = layers.Conv1D(256, 3, padding='same', activation='relu',
                      kernel_regularizer=regularizers.l2(0.001))(x)
    x = layers.BatchNormalization()(x)
    x = layers.MaxPooling1D(2)(x)

    # LSTM for temporal patterns
    x = layers.LSTM(128, return_sequences=True)(x)
    x = layers.Dropout(0.4)(x)
    x = layers.LSTM(64)(x)
    x = layers.Dropout(0.4)(x)

    # Dense layers
    x = layers.Dense(64, activation='relu', kernel_regularizer=regularizers.l2(0.001))(x)
    x = layers.Dropout(0.5)(x)
    x = layers.Dense(32, activation='relu', kernel_regularizer=regularizers.l2(0.001))(x)

    outputs = layers.Dense(1, activation='sigmoid')(x)

    model = models.Model(inputs=inputs, outputs=outputs)

    optimizer = keras.optimizers.Adam(learning_rate=learning_rate)
    model.compile(
        optimizer=optimizer,
        loss='binary_crossentropy',
        metrics=['accuracy', tf.keras.metrics.AUC(name='auc')]
    )

    return model

# --- 7. OPTUNA HYPERPARAMETER OPTIMIZATION ---
def optimize_models(X_train, y_train, model_type='xgb'):
    """Optimize hyperparameters using Optuna"""

    def objective(trial):
        if model_type == 'xgb':
            params = {
                'n_estimators': trial.suggest_int('n_estimators', 200, 800),
                'learning_rate': trial.suggest_float('learning_rate', 0.01, 0.1),
                'max_depth': trial.suggest_int('max_depth', 4, 10),
                'min_child_weight': trial.suggest_int('min_child_weight', 1, 7),
                'subsample': trial.suggest_float('subsample', 0.6, 1.0),
                'colsample_bytree': trial.suggest_float('colsample_bytree', 0.6, 1.0),
                'gamma': trial.suggest_float('gamma', 0, 5),
                'scale_pos_weight': 1.0 / class_ratio,
                'random_state': RANDOM_STATE,
                'verbosity': 0
            }
            model = XGBClassifier(**params)

        elif model_type == 'lgbm':
            params = {
                'n_estimators': trial.suggest_int('n_estimators', 200, 800),
                'learning_rate': trial.suggest_float('learning_rate', 0.01, 0.1),
                'max_depth': trial.suggest_int('max_depth', 4, 10),
                'num_leaves': trial.suggest_int('num_leaves', 20, 100),
                'min_child_samples': trial.suggest_int('min_child_samples', 10, 50),
                'subsample': trial.suggest_float('subsample', 0.6, 1.0),
                'colsample_bytree': trial.suggest_float('colsample_bytree', 0.6, 1.0),
                'reg_alpha': trial.suggest_float('reg_alpha', 0, 10),
                'reg_lambda': trial.suggest_float('reg_lambda', 0, 10),
                'scale_pos_weight': 1.0 / class_ratio,
                'random_state': RANDOM_STATE,
                'verbosity': -1
            }
            model = LGBMClassifier(**params)

        elif model_type == 'cat':
            params = {
                'iterations': trial.suggest_int('iterations', 300, 1000),
                'learning_rate': trial.suggest_float('learning_rate', 0.01, 0.1),
                'depth': trial.suggest_int('depth', 4, 10),
                'l2_leaf_reg': trial.suggest_float('l2_leaf_reg', 1, 10),
                'random_strength': trial.suggest_float('random_strength', 0, 10),
                'bagging_temperature': trial.suggest_float('bagging_temperature', 0, 1),
                'auto_class_weights': 'Balanced',
                'random_state': RANDOM_STATE,
                'verbose': 0,
                'allow_writing_files': False
            }
            model = CatBoostClassifier(**params)

        # 5-fold CV for optimization
        cv_score = cross_val_score(
            model, X_train, y_train,
            cv=5, scoring='balanced_accuracy', n_jobs=-1
        )
        return cv_score.mean()

    study = optuna.create_study(direction='maximize', study_name=f'{model_type}_optimization')
    study.optimize(objective, n_trials=N_TRIALS, show_progress_bar=False)

    return study.best_params

# --- 8. ROCKET FEATURE EXTRACTION ---
print("\n🚀 MiniRocket özellikleri çıkarılıyor...")
rocket = MiniRocketMultivariate(num_kernels=10000, random_state=RANDOM_STATE)
X_rocket = rocket.fit_transform(X_sig_arr)
print(f"   Rocket features: {X_rocket.shape}")

# --- 9. CROSS-VALIDATION LOOP ---
print("\n🔬 10-Fold Nested Cross-Validation Başlıyor...")
cv = StratifiedGroupKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)

metrics = {
    'bal_acc': [], 'acc': [], 'spec': [], 'sens': [],
    'f1': [], 'auc': [], 'precision': []
}

fold_predictions = []

for fold, (train_idx, test_idx) in enumerate(cv.split(X_rocket, y, groups=groups), 1):
    print(f"\n{'='*60}")
    print(f"📌 FOLD {fold}/10")
    print(f"{'='*60}")

    # Split data
    X_r_tr, X_r_te = X_rocket.iloc[train_idx].values, X_rocket.iloc[test_idx].values
    X_hc_tr, X_hc_te = X_handcrafted_arr[train_idx], X_handcrafted_arr[test_idx]
    X_sig_tr, X_sig_te = X_sig_arr[train_idx], X_sig_arr[test_idx]
    df_c_tr, df_c_te = df_clinical.iloc[train_idx], df_clinical.iloc[test_idx]
    y_tr, y_te = y[train_idx], y[test_idx]
    g_te = groups[test_idx]

    # Clinical preprocessing
    clin_preprocessor = ColumnTransformer(
        transformers=[
            ('num', RobustScaler(),
             ['age', 'nms_sum', 'nms_mean', 'nms_std', 'nms_nonzero'] +
             [f'nms_{i}' for i in range(30)]),
            ('cat', OrdinalEncoder(handle_unknown='use_encoded_value', unknown_value=-1),
             ['gender', 'task'])
        ]
    )

    clin_preprocessor.fit(df_c_tr)
    X_c_tr = clin_preprocessor.transform(df_c_tr)
    X_c_te = clin_preprocessor.transform(df_c_te)

    # Handcrafted features scaling
    hc_scaler = RobustScaler()
    X_hc_tr_scaled = hc_scaler.fit_transform(X_hc_tr)
    X_hc_te_scaled = hc_scaler.transform(X_hc_te)

    # Combine Rocket + Handcrafted
    X_combined_tr = np.hstack([X_r_tr, X_hc_tr_scaled])
    X_combined_te = np.hstack([X_r_te, X_hc_te_scaled])

    # --- MODEL 1: DEEP LEARNING (CNN-LSTM) ---
    print("🧠 Deep Learning modeli eğitiliyor...")

    # Reshape for CNN input (samples, timesteps, channels)
    X_sig_tr_dl = np.transpose(X_sig_tr, (0, 2, 1))
    X_sig_te_dl = np.transpose(X_sig_te, (0, 2, 1))

    dl_model = create_cnn_lstm_model(
        input_shape=(SEQ_LEN, max_ch),
        learning_rate=0.0005
    )

    early_stop = callbacks.EarlyStopping(
        monitor='val_loss', patience=15, restore_best_weights=True
    )
    reduce_lr = callbacks.ReduceLROnPlateau(
        monitor='val_loss', factor=0.5, patience=7, min_lr=1e-6
    )

    dl_model.fit(
        X_sig_tr_dl, y_tr,
        validation_split=0.15,
        epochs=100,
        batch_size=32,
        callbacks=[early_stop, reduce_lr],
        verbose=0
    )

    p_dl = dl_model.predict(X_sig_te_dl, verbose=0).flatten()

    # --- MODEL 2-5: GRADIENT BOOSTING ENSEMBLE ---
    print("⚡ Gradient Boosting ensemble eğitiliyor...")

    if USE_OPTUNA and fold == 1:  # Optimize only on first fold
        print("   🔍 Optuna ile hyperparameter optimization...")
        xgb_params = optimize_models(X_combined_tr, y_tr, 'xgb')
        lgbm_params = optimize_models(X_combined_tr, y_tr, 'lgbm')
        cat_params = optimize_models(X_combined_tr, y_tr, 'cat')
    else:
        # Default optimized parameters
        xgb_params = {
            'n_estimators': 600, 'learning_rate': 0.03, 'max_depth': 7,
            'min_child_weight': 3, 'subsample': 0.8, 'colsample_bytree': 0.8,
            'gamma': 1, 'scale_pos_weight': 1.0/class_ratio, 'verbosity': 0
        }
        lgbm_params = {
            'n_estimators': 600, 'learning_rate': 0.03, 'max_depth': 7,
            'num_leaves': 60, 'min_child_samples': 20, 'subsample': 0.8,
            'colsample_bytree': 0.8, 'reg_alpha': 3, 'reg_lambda': 3,
            'scale_pos_weight': 1.0/class_ratio, 'verbosity': -1
        }
        cat_params = {
            'iterations': 700, 'learning_rate': 0.03, 'depth': 7,
            'l2_leaf_reg': 5, 'random_strength': 3, 'bagging_temperature': 0.5,
            'auto_class_weights': 'Balanced', 'verbose': 0, 'allow_writing_files': False
        }

    xgb_model = XGBClassifier(**xgb_params, random_state=RANDOM_STATE)
    lgbm_model = LGBMClassifier(**lgbm_params, random_state=RANDOM_STATE)
    cat_model = CatBoostClassifier(**cat_params, random_state=RANDOM_STATE)
    rf_model = RandomForestClassifier(
        n_estimators=500, max_depth=10, min_samples_split=5,
        class_weight='balanced', random_state=RANDOM_STATE, n_jobs=-1
    )

    # Train models
    xgb_model.fit(X_combined_tr, y_tr)
    lgbm_model.fit(X_combined_tr, y_tr)
    cat_model.fit(X_combined_tr, y_tr)
    rf_model.fit(X_combined_tr, y_tr)

    p_xgb = xgb_model.predict_proba(X_combined_te)[:, 1]
    p_lgbm = lgbm_model.predict_proba(X_combined_te)[:, 1]
    p_cat = cat_model.predict_proba(X_combined_te)[:, 1]
    p_rf = rf_model.predict_proba(X_combined_te)[:, 1]

    # --- MODEL 6: CLINICAL NEURAL NETWORK ---
    print("🏥 Clinical Neural Network eğitiliyor...")

    mlp_model = MLPClassifier(
        hidden_layer_sizes=(128, 64, 32),
        alpha=0.005,
        learning_rate_init=0.001,
        max_iter=1000,
        early_stopping=True,
        validation_fraction=0.15,
        random_state=RANDOM_STATE
    )
    mlp_model.fit(X_c_tr, y_tr)
    p_mlp = mlp_model.predict_proba(X_c_te)[:, 1]

    # --- STACKING META-LEARNER ---
    print("🎯 Stacking meta-learner ile birleştiriliyor...")

    # Create meta-features
    meta_features_te = np.column_stack([p_dl, p_xgb, p_lgbm, p_cat, p_rf, p_mlp])

    # Also create meta-features for training (using out-of-fold predictions)
    cv_inner = StratifiedGroupKFold(n_splits=5, shuffle=True, random_state=RANDOM_STATE)
    meta_features_tr = np.zeros((len(y_tr), 6))

    for inner_train, inner_val in cv_inner.split(X_combined_tr, y_tr, groups[train_idx]):
        # Train temporary models
        dl_temp = create_cnn_lstm_model((SEQ_LEN, max_ch), 0.0005)
        dl_temp.fit(
            np.transpose(X_sig_tr[inner_train], (0, 2, 1)),
            y_tr[inner_train],
            epochs=50, batch_size=32, verbose=0
        )
        meta_features_tr[inner_val, 0] = dl_temp.predict(
            np.transpose(X_sig_tr[inner_val], (0, 2, 1)), verbose=0
        ).flatten()

        xgb_temp = XGBClassifier(**xgb_params, random_state=RANDOM_STATE)
        xgb_temp.fit(X_combined_tr[inner_train], y_tr[inner_train])
        meta_features_tr[inner_val, 1] = xgb_temp.predict_proba(X_combined_tr[inner_val])[:, 1]

        lgbm_temp = LGBMClassifier(**lgbm_params, random_state=RANDOM_STATE)
        lgbm_temp.fit(X_combined_tr[inner_train], y_tr[inner_train])
        meta_features_tr[inner_val, 2] = lgbm_temp.predict_proba(X_combined_tr[inner_val])[:, 1]

        cat_temp = CatBoostClassifier(**cat_params, random_state=RANDOM_STATE)
        cat_temp.fit(X_combined_tr[inner_train], y_tr[inner_train])
        meta_features_tr[inner_val, 3] = cat_temp.predict_proba(X_combined_tr[inner_val])[:, 1]

        rf_temp = RandomForestClassifier(
            n_estimators=300, max_depth=10, class_weight='balanced',
            random_state=RANDOM_STATE, n_jobs=-1
        )
        rf_temp.fit(X_combined_tr[inner_train], y_tr[inner_train])
        meta_features_tr[inner_val, 4] = rf_temp.predict_proba(X_combined_tr[inner_val])[:, 1]

        mlp_temp = MLPClassifier(
            hidden_layer_sizes=(128, 64, 32), alpha=0.005,
            max_iter=500, random_state=RANDOM_STATE
        )
        mlp_temp.fit(X_c_tr[inner_train], y_tr[inner_train])
        meta_features_tr[inner_val, 5] = mlp_temp.predict_proba(X_c_te[inner_val])[:, 1]

    # Train meta-learner
    meta_learner = LogisticRegression(
        C=0.1,
        class_weight='balanced',
        random_state=RANDOM_STATE,
        max_iter=1000
    )
    meta_learner.fit(meta_features_tr, y_tr)

    # Final predictions
    final_probs = meta_learner.predict_proba(meta_features_te)[:, 1]

    # --- PATIENT-LEVEL AGGREGATION ---
    print("👤 Hasta seviyesinde birleştiriliyor...")

    df_res = pd.DataFrame({
        'pid': g_te,
        'true': y_te,
        'prob': final_probs,
        'task': task_list[test_idx] if isinstance(test_idx, (list, np.ndarray)) else [task_list[test_idx]]
    })

    # Weighted average by task confidence
    def weighted_mean(group):
        # Give more weight to tasks with higher confidence (further from 0.5)
        confidence = np.abs(group['prob'] - 0.5)
        weights = confidence / confidence.sum()
        return (group['prob'] * weights).sum()

    pat_res = df_res.groupby('pid').agg({
        'true': 'first',
        'prob': weighted_mean
    })

    y_true_pat = pat_res['true'].astype(int).values
    y_prob_pat = pat_res['prob'].values

    # Optimal threshold using Youden's J statistic
    fpr, tpr, thresholds = roc_curve(y_true_pat, y_prob_pat)
    j_scores = tpr - fpr
    best_th = thresholds[np.argmax(j_scores)]

    y_pred_pat = (y_prob_pat >= best_th).astype(int)

    # Calculate metrics
    bal_acc = balanced_accuracy_score(y_true_pat, y_pred_pat)
    acc = accuracy_score(y_true_pat, y_pred_pat)
    spec = recall_score(y_true_pat, y_pred_pat, pos_label=0)
    sens = recall_score(y_true_pat, y_pred_pat, pos_label=1)
    f1 = f1_score(y_true_pat, y_pred_pat)
    auc = roc_auc_score(y_true_pat, y_prob_pat)
    prec = precision_score(y_true_pat, y_pred_pat)

    metrics['bal_acc'].append(bal_acc)
    metrics['acc'].append(acc)
    metrics['spec'].append(spec)
    metrics['sens'].append(sens)
    metrics['f1'].append(f1)
    metrics['auc'].append(auc)
    metrics['precision'].append(prec)

    fold_predictions.append({
        'fold': fold,
        'y_true': y_true_pat,
        'y_pred': y_pred_pat,
        'y_prob': y_prob_pat
    })

    print(f"\n📊 Fold {fold} Sonuçları:")
    print(f"   ├─ Balanced Accuracy: {bal_acc*100:.2f}%")
    print(f"   ├─ Accuracy         : {acc*100:.2f}%")
    print(f"   ├─ Sensitivity (PD) : {sens*100:.2f}%")
    print(f"   ├─ Specificity (HC) : {spec*100:.2f}%")
    print(f"   ├─ F1-Score        : {f1*100:.2f}%")
    print(f"   ├─ Precision       : {prec*100:.2f}%")
    print(f"   ├─ ROC AUC         : {auc*100:.2f}%")
    print(f"   └─ Optimal Threshold: {best_th:.3f}")

# --- 10. FINAL RESULTS ---
print("\n" + "="*70)
print("🏆 FINAL RESULTS - 10-FOLD CROSS-VALIDATION")
print("="*70)

for metric_name, metric_values in metrics.items():
    mean_val = np.mean(metric_values)
    std_val = np.std(metric_values)
    print(f"{metric_name.upper():15s}: {mean_val*100:6.2f}% ± {std_val*100:5.2f}%")

print("="*70)

# Performance comparison
target_bal_acc = 91.16
current_bal_acc = np.mean(metrics['bal_acc']) * 100
improvement = current_bal_acc - target_bal_acc

print(f"\n📈 Makale Skoru      : {target_bal_acc:.2f}%")
print(f"🚀 Mevcut Skorumuz  : {current_bal_acc:.2f}%")
print(f"{'✅' if improvement > 0 else '⚠️'} Fark              : {improvement:+.2f}%")

if improvement > 0:
    print(f"\n🎉 BAŞARILI! Makale skorunu {improvement:.2f}% geçtik!")
else:
    print(f"\n⚡ Daha fazla iyileştirme için öneriler:")
    print("   1. N_TRIALS değerini artırın (daha uzun sürer)")
    print("   2. Daha fazla veri augmentation deneyin")
    print("   3. Ensemble ağırlıklarını fine-tune edin")

print("\n" + "="*70)
print("✨ Analiz Tamamlandı!")
print("="*70)

