def install(package):
    try:
        __import__(package.split('[')[0])
    except ImportError:
        print(f"📦 {package} kuruluyor...")
        subprocess.check_call([sys.executable, "-m", "pip", "install", package, "-q"])

packages = ["sktime", "catboost", "xgboost", "lightgbm", "pywavelets"]
for pkg in packages:
    install(pkg)

