print(f"Sinyal boyutu       : {X_sig_arr.shape}")
print(f"Handcrafted features: {X_handcrafted_arr.shape}")
print(f"Clinical features   : {df_clinical.shape}")
print(f"{'='*70}")

# Clear memory
del X_signals
gc.collect()

# --- 6. ROCKET FEATURES ---
print("\n🚀 MiniRocket özellikleri çıkarılıyor...")
rocket = MiniRocketMultivariate(num_kernels=8000, random_state=RANDOM_STATE)
X_rocket = rocket.fit_transform(X_sig_arr)
