# --- DOSYA BULMA ---
def find_file_in_drive(filename):
    common_paths = [
        f"/content/{filename}",
        f"/content/drive/MyDrive/{filename}",
        f"./{filename}",
    ]
    for path in common_paths:
        if os.path.exists(path):
            return path
    try:
        if os.path.exists("/content/drive"):
            result = subprocess.getoutput(f"find /content/drive -name '{filename}' -type f 2>/dev/null | head -1")
            if result and result.strip():
                return result.strip()
    except:
        pass
    return None

def find_extracted_data():
    for dir_path in ["./pads_data_extracted", "./pads_data_final", "./pads_data"]:
        if os.path.exists(dir_path):
            txt_files = glob(os.path.join(dir_path, "**", "*.txt"), recursive=True)
            if len(txt_files) > 10:
                return dir_path
    return None

