import sys, subprocess, os, warnings, gc
warnings.filterwarnings('ignore')
os.environ['TF_CPP_MIN_LOG_LEVEL'] = '3'

def install(package):
    try:
        __import__(package.split('[')[0])
    except ImportError:
        subprocess.check_call([sys.executable, "-m", "pip", "install", package, "-q"])

for pkg in ["sktime", "catboost", "xgboost", "lightgbm", "pywavelets", "matplotlib", "seaborn"]:
    install(pkg)

import numpy as np
import pandas as pd
import zipfile, json
from glob import glob
from tqdm import tqdm
from scipy.signal import detrend, resample, welch
from scipy.stats import skew, kurtosis
import pywt
