paper_sens = 92.40  # Ortalama (makaleye göre)
paper_spec = 92.00  # Tahmin
paper_f1 = 94.62

# Bizim sonuçlar
our_bal_acc = df['bal_acc'].mean()
our_sens = df['sens'].mean()
our_spec = df['spec'].mean()
our_f1 = df['f1'].mean()

