fig = plt.figure(figsize=(16, 12))
gs = GridSpec(3, 2, figure=fig, hspace=0.35, wspace=0.3)

# 1.1 Performance Comparison Bar Chart
ax1 = fig.add_subplot(gs[0, :])
metrics = ['Balanced\nAccuracy', 'Sensitivity', 'Specificity', 'F1-Score']
paper_vals = [paper_bal_acc, paper_sens, paper_spec, paper_f1]
our_vals = [our_bal_acc, our_sens, our_spec, our_f1]

x = np.arange(len(metrics))
width = 0.35

bars1 = ax1.bar(x - width/2, paper_vals, width, label='Varghese et al. (2024)',
               color='#8da0cb', edgecolor='black', linewidth=1.5, alpha=0.8)
bars2 = ax1.bar(x + width/2, our_vals, width, label='Our Method (2026)',
               color='#fc8d62', edgecolor='black', linewidth=1.5, alpha=0.8)

# Add value labels on bars
for bars in [bars1, bars2]:
    for bar in bars:
        height = bar.get_height()
        ax1.text(bar.get_x() + bar.get_width()/2., height,
                f'{height:.1f}%', ha='center', va='bottom', fontsize=10, weight='bold')

ax1.set_ylabel('Performance (%)', fontsize=13, weight='bold')
ax1.set_title('A. Performance Comparison: Our Method vs. Published Paper',
             fontsize=14, weight='bold', pad=20)
ax1.set_xticks(x)
ax1.set_xticklabels(metrics, fontsize=11)
ax1.legend(fontsize=11, frameon=True, shadow=True)
ax1.set_ylim([85, 105])
ax1.grid(axis='y', alpha=0.3, linestyle='--')

# 1.2 Fold-wise Performance (Like Paper's CV analysis)
ax2 = fig.add_subplot(gs[1, 0])
folds = df['fold'].values
