import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import os

# --- 1. VERİ TANIMLAMA ---
results_data = {
    'fold': list(range(1, 11)),
    'bal_acc': [98.1, 96.6, 85.2, 94.4, 91.3, 90.0, 90.6, 98.2, 89.3, 98.3],
    'sens': [96.3, 93.1, 90.3, 88.9, 91.7, 100.0, 92.3, 96.4, 92.9, 96.7],
    'spec': [100.0, 100.0, 80.0, 100.0, 90.9, 80.0, 88.9, 100.0, 85.7, 100.0],
    'f1': [98.1, 96.4, 93.3, 94.1, 93.6, 96.3, 94.1, 98.2, 94.5, 98.3]
}
df = pd.DataFrame(results_data)

# Karşılaştırma Değerleri (Varghese et al. 2024)
paper_vals = [91.16, 92.40, 92.00, 94.62]
our_vals = [df['bal_acc'].mean(), df['sens'].mean(), df['spec'].mean(), df['f1'].mean()]
metrics = ['Balanced Accuracy', 'Sensitivity', 'Specificity', 'F1-Score']

# --- 2. GLOBAL STİL AYARLARI ---
plt.rcParams.update({
    'font.size': 12,
    'axes.labelsize': 13,
    'axes.titlesize': 15,
    'xtick.labelsize': 11,
    'ytick.labelsize': 11,
    'legend.fontsize': 11,
    'font.family': 'serif',
    'figure.dpi': 600
})

def save_publication_fig(filename):
    """Her figürü 600 DPI TIFF, EPS ve PNG olarak kaydeder."""
    plt.savefig(f"{filename}.png", dpi=600, bbox_inches='tight')
    plt.savefig(f"{filename}.eps", format='eps', dpi=600, bbox_inches='tight')
    try:
        # LZW sıkıştırma akademik TIFF dosyaları için standarttır
        plt.savefig(f"{filename}.tiff", dpi=600, pil_kwargs={'compression': 'tiff_lzw'}, bbox_inches='tight')
    except:
        plt.savefig(f"{filename}.tiff", dpi=600, bbox_inches='tight')

# --- FIGURE 1: Comparative Analysis (SOTA vs Proposed) ---
plt.figure(figsize=(10, 7))
x = np.arange(len(metrics))
width = 0.35

# Çubukları çizme
bars1 = plt.bar(x - width/2, paper_vals, width, label='Varghese et al. (2024)',
                color='#8da0cb', edgecolor='black', linewidth=1.2)
bars2 = plt.bar(x + width/2, our_vals, width, label='Proposed Method',
                color='#fc8d62', edgecolor='black', linewidth=1.2)

# Rakam değerlerini çubukların üzerine ekleme (Hem mavi hem turuncu için)
for bars in [bars1, bars2]:
    for bar in bars:
        height = bar.get_height()
        plt.text(bar.get_x() + bar.get_width()/2., height + 0.5,
                f'{height:.1f}%', ha='center', va='bottom', fontweight='bold', fontsize=10)

plt.ylabel('Performance (%)', fontweight='bold')
plt.title('Figure 1: Performance comparison against SOTA baseline', pad=20, fontweight='bold')
plt.xticks(x, metrics)
plt.legend(loc='upper right', frameon=True, shadow=True) # Legend konumu yukarı çekildi
plt.ylim([75, 105])
plt.grid(axis='y', linestyle='--', alpha=0.3)
save_publication_fig("Figure_1_Comparison")
plt.show()

# --- FIGURE 2: Robustness and Distribution (Side-by-Side) ---
fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(16, 7))

# 2(a) Fold-wise Performance
ax1.plot(df['fold'], df['bal_acc'], 'o-', color='#e78ac3', linewidth=2.5, markersize=8, label='Proposed Bal. Acc.')
ax1.axhline(y=paper_vals[0], color='red', linestyle='--', linewidth=2, label=f'SOTA Baseline ({paper_vals[0]}%)')
ax1.set_title("(a) Fold-wise Stability", fontsize=14, fontweight='bold', pad=15)
ax1.set_xlabel("Fold Number", fontweight='bold')
ax1.set_ylabel("Performance (%)", fontweight='bold')
ax1.set_xticks(df['fold'])
ax1.legend(loc='lower left')
ax1.grid(True, linestyle=':', alpha=0.5)

# 2(b) Boxplot Distribution
# Veriyi Seaborn formatına dönüştürme
df_melt = df[['bal_acc', 'sens', 'spec', 'f1']].melt()
df_melt.columns = ['Metric', 'Value']
sns.boxplot(x='Metric', y='Value', data=df_melt, ax=ax2, palette="Set3", width=0.6)
sns.stripplot(x='Metric', y='Value', data=df_melt, ax=ax2, color=".3", alpha=0.5)
