ax2.set_ylabel("Performance (%)", fontweight='bold')
ax2.set_xlabel("")
ax2.set_ylim([75, 105])

save_publication_fig("Figure_2_Robustness")
plt.show()

# --- FIGURE 3: Confusion Matrix and Dataset Metrics ---
fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(16, 7))

# 3(a) Normalized Confusion Matrix
cm = np.array([[our_vals[2], 100-our_vals[2]], [100-our_vals[1], our_vals[1]]])
sns.heatmap(cm, annot=True, fmt='.1f', cmap='Blues', ax=ax1, annot_kws={"size": 14, "weight": "bold"},
            xticklabels=['HC', 'PD'], yticklabels=['HC', 'PD'], cbar_kws={'label': 'Percentage (%)'})
ax1.set_title("(a) Patient-Level Confusion Matrix", fontsize=14, fontweight='bold', pad=15)
ax1.set_xlabel("Predicted Label", fontweight='bold')
ax1.set_ylabel("True Label", fontweight='bold')

# 3(b) Sample Distribution
hc_samples, pd_samples = 1738, 6072
ax2.pie([hc_samples, pd_samples], labels=['Healthy (HC)', 'Parkinson (PD)'], autopct='%1.1f%%',
        colors=['#66c2a5', '#fc8d62'], startangle=140, explode=(0.05, 0), shadow=True,
        textprops={'fontsize': 12, 'fontweight': 'bold'})
ax2.set_title("(b) Dataset Composition (N=7,810)", fontsize=14, fontweight='bold', pad=15)

save_publication_fig("Figure_3_Metrics")
plt.show()

print("✅ Tüm figürler (Figure 1, 2 ve 3) ayrı dosyalar halinde 600 DPI olarak kaydedildi.")

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

# 1. VERİ HAZIRLIĞI (Raporunuzdaki değerler baz alınmıştır)
results_data = {
    'fold': list(range(1, 11)),
    'bal_acc': [98.1, 96.6, 85.2, 94.4, 91.3, 90.0, 90.6, 98.2, 89.3, 98.3],
    'sens': [96.3, 93.1, 90.3, 88.9, 91.7, 100.0, 92.3, 96.4, 92.9, 96.7],
    'spec': [100.0, 100.0, 80.0, 100.0, 90.9, 80.0, 88.9, 100.0, 85.7, 100.0],
    'f1': [98.1, 96.4, 93.3, 94.1, 93.6, 96.3, 94.1, 98.2, 94.5, 98.3]
}
df = pd.DataFrame(results_data)
paper_vals = [91.16, 92.40, 92.00, 94.62]
our_means = [df['bal_acc'].mean(), df['sens'].mean(), df['spec'].mean(), df['f1'].mean()]
metrics = ['Balanced\nAccuracy', 'Sensitivity', 'Specificity', 'F1-Score']

# 2. GLOBAL AKADEMİK AYARLAR
plt.rcParams.update({
    'font.size': 12, 'font.family': 'serif', 'axes.labelsize': 14,
    'axes.titlesize': 16, 'savefig.dpi': 600, 'figure.autolayout': True
})

def save_publication_fig(name):
    """Her figürü 600 DPI formatlarında ayrı ayrı kaydeder."""
    plt.savefig(f"{name}.tiff", dpi=600, pil_kwargs={'compression': 'tiff_lzw'}, bbox_inches='tight')
    plt.savefig(f"{name}.eps", format='eps', dpi=600, bbox_inches='tight')
    plt.savefig(f"{name}.png", dpi=600, bbox_inches='tight')
    plt.savefig(f"{name}.pdf", format='pdf', dpi=600, bbox_inches='tight')

# --- FIGURE 1: SOTA Karşılaştırma Bar Grafiği ---
plt.figure(figsize=(9, 6))
x = np.arange(len(metrics))
width = 0.35
b1 = plt.bar(x - width/2, paper_vals, width, label='Varghese et al. (2024)', color='#8da0cb', edgecolor='black')
b2 = plt.bar(x + width/2, our_means, width, label='Proposed Method', color='#fc8d62', edgecolor='black')
for bars in [b1, b2]:
    for bar in bars:
        h = bar.get_height()
        plt.text(bar.get_x() + bar.get_width()/2., h + 0.5, f'{h:.1f}%', ha='center', weight='bold')
plt.ylabel('Performance (%)'); plt.title('Figure 1: Comparison of Diagnostic Performance')
plt.xticks(x, metrics); plt.ylim([75, 105]); plt.legend(loc='upper right')
save_publication_fig("Figure_1_Comparison")

# --- FIGURE 2: 10-Fold CV Kararlılığı (Çizgi Grafik) ---
plt.figure(figsize=(9, 6))
plt.plot(df['fold'], df['bal_acc'], 'o-', color='#e78ac3', linewidth=3, markersize=10, label='Proposed Bal. Acc.')
plt.axhline(y=91.16, color='red', linestyle='--', linewidth=2, label='Paper Baseline')
plt.xlabel('Fold Number'); plt.ylabel('Balanced Accuracy (%)'); plt.title('Figure 2: Model Stability Across Folds')
plt.xticks(df['fold']); plt.legend(); plt.grid(True, linestyle=':', alpha=0.5)
save_publication_fig("Figure_2_Stability")

# --- FIGURE 3: Metrik Dağılımı (Boxplot) ---
plt.figure(figsize=(9, 6))
sns.boxplot(data=df[['bal_acc', 'sens', 'spec', 'f1']], palette="Set3")
plt.title('Figure 3: Distribution of Metrics Across Folds')
plt.ylabel('Performance (%)'); plt.xticks([0,1,2,3], ['Bal. Acc.', 'Sens.', 'Spec.', 'F1'])
save_publication_fig("Figure_3_Distribution")

# --- FIGURE 4: Sensitivity-Specificity Trade-off (Scatter) ---
plt.figure(figsize=(8, 7))
plt.scatter(df['spec'], df['sens'], s=200, c=df['bal_acc'], cmap='RdYlGn', edgecolor='black')
plt.plot([80, 100], [80, 100], 'k--', alpha=0.4, label='Perfect Balance')
plt.xlabel('Specificity (HC) %'); plt.ylabel('Sensitivity (PD) %'); plt.title('Figure 4: Sensitivity vs. Specificity')
plt.legend(); plt.grid(True, linestyle=':', alpha=0.5); plt.colorbar(label='Accuracy (%)')
save_publication_fig("Figure_4_Tradeoff")

# --- FIGURE 5: Korelasyon Matrisi ---
plt.figure(figsize=(8, 7))
sns.heatmap(df[['bal_acc', 'sens', 'spec', 'f1']].corr(), annot=True, cmap='coolwarm', square=True)
plt.title('Figure 5: Metric Correlation Matrix')
save_publication_fig("Figure_5_Correlation")

# --- FIGURE 6: Karmaşıklık Matrisi (Confusion Matrix) ---
plt.figure(figsize=(8, 7))
cm = np.array([[73, 6], [17, 259]]) # Raporunuzdaki hasta bazlı veriler [cite: 833, 933, 937]
sns.heatmap(cm, annot=True, fmt='d', cmap='Blues', xticklabels=['HC', 'PD'], yticklabels=['HC', 'PD'])
plt.ylabel('True Label'); plt.xlabel('Predicted Label'); plt.title('Figure 6: Confusion Matrix')
save_publication_fig("Figure_6_Confusion")

# --- FIGURE 7: Veri Seti Dağılımı (Pasta Grafiği) ---
plt.figure(figsize=(8, 7))
plt.pie([1738, 6072], labels=['HC', 'PD'], autopct='%1.1f%%', colors=['#66c2a5', '#fc8d62'], startangle=140)
plt.title('Figure 7: Dataset Composition (N=7,810)')
save_publication_fig("Figure_7_Dataset")

print("Tüm 7 figür ayrı ayrı ve 600 DPI olarak kaydedildi.")

