plt.axhline(y=91.16, color='red', linestyle='--', linewidth=2, label='Paper Baseline (91.2%)')
plt.fill_between(df['fold'], df['bal_acc'] - df['bal_acc'].std(), df['bal_acc'] + df['bal_acc'].std(), alpha=0.2, color='#e78ac3')
