print("\n📊 Loading metadata...")
patient_info = {}

if meta_path and os.path.exists(meta_path):
    df_meta = pd.read_csv(meta_path)
    df_filtered = df_meta[df_meta['label'].isin([0, 1])]

    for _, row in df_filtered.iterrows():
        pid = str(row['id']).zfill(3)
        patient_info[pid] = {
            'label': int(row['label']),
            'age': row['age'],
            'gender': str(row['gender'])
        }
    print(f"✅ Metadata loaded: {len(patient_info)} patients")
else:
    # Fallback: Read from patient JSON files
    print("  📄 Searching for patient JSON files...")
    p_files = glob(os.path.join(data_path, "**", "patient_*.json"), recursive=True)
    print(f"  Found {len(p_files)} patient files")

    for pf in p_files:
        try:
            with open(pf) as f:
                d = json.load(f)

            pid = str(d.get('id', ''))
            cond = d.get('condition', '').lower()

            if "parkinson" in cond:
                lbl = 1
            elif "healthy" in cond or "control" in cond:
                lbl = 0
            else:
                continue

            if pid:
                patient_info[pid] = {
                    'label': lbl,
                    'age': d.get('age', 60),
                    'gender': str(d.get('gender', 'unknown'))
                }
        except:
            continue

    print(f"✅ Loaded from patient JSONs: {len(patient_info)} patients")

if len(patient_info) == 0:
    print("❌ ERROR: Could not load patient information!")
    sys.exit(1)

# Load NMS Questionnaire data
print("\n📋 Loading questionnaire data...")
nms_data = {}
q_files = glob(os.path.join(data_path, "**", "questionnaire_response_*.json"),
               recursive=True)
print(f"  Found {len(q_files)} questionnaire files")

for qf in q_files:
    try:
        with open(qf) as f:
            q = json.load(f)

        pid = str(q.get('subject_id', ''))
        if pid not in patient_info:
            continue

        items = q.get('item', [])
        answers = [0] * 30

        for item in items:
            link_id = item.get('link_id', '99')
            try:
                idx = int(link_id) - 1
                if 0 <= idx < 30:
                    ans = item.get('answer', False)
                    answers[idx] = 1 if ans is True else 0
            except:
                continue

        nms_data[pid] = answers
    except:
        continue

print(f"✅ Questionnaire data loaded: {len(nms_data)} patients")

# Load signal data
print("\n📡 Loading signal files...")
s_files = glob(os.path.join(data_path, "**", "*.txt"), recursive=True)
s_files = [f for f in s_files if "LICENSE" not in f and "README" not in f]
print(f"  Found {len(s_files)} signal files")

if len(s_files) == 0:
    print("❌ ERROR: No signal files found!")
    print(f"  Searched location: {data_path}")
    sys.exit(1)

# Process signal files
X_signals, X_handcrafted, X_clinical = [], [], []
y_list, group_list, task_list = [], [], []

print(f"\n⚙️ Processing {len(s_files)} files...")
processed = 0
skipped = 0

for f_path in tqdm(s_files, desc="Processing data"):
    try:
        fname = os.path.basename(f_path)
        parts = fname.replace('.txt', '').split('_')

        if len(parts) < 1:
            skipped += 1
            continue

        pid = parts[0]
        if pid not in patient_info:
            skipped += 1
            continue

        task_name = parts[1] if len(parts) > 1 else "Unknown"

        # Read signal data
        df = pd.read_csv(f_path, header=None)
        raw = df.select_dtypes(include=[np.number]).values

        if raw.shape[0] < 100:
            skipped += 1
            continue

        # Crop and preprocess
        if raw.shape[0] > CROP_START:
            raw = raw[CROP_START:, :]

        raw = detrend(raw, axis=0)

        if raw.shape[0] > raw.shape[1]:
            raw = raw.T

        # Resample to fixed length
        dat_res = resample(raw, SEQ_LEN, axis=1)
        X_signals.append(dat_res)

        # Extract handcrafted features
        hc_features = []
        for ch in range(dat_res.shape[0]):
            hc_features.extend(extract_features_compact(dat_res[ch, :]))
        X_handcrafted.append(hc_features)

        # Clinical features
        p = patient_info[pid]
        nms = nms_data.get(pid, [0] * 30)

        nms_sum = sum(nms)
        nms_mean = np.mean(nms)
        nms_std = np.std(nms)
        nms_nonzero = np.count_nonzero(nms)

        # Grouped NMS features
        nms_motor = sum(nms[0:10])
        nms_sleep = sum(nms[10:15])
        nms_mood = sum(nms[15:20])
        nms_auto = sum(nms[20:30])

        clin_vec = [
            float(p['age']),
            str(p['gender']),
            str(task_name),
            nms_sum, nms_mean, nms_std, nms_nonzero,
            nms_motor, nms_sleep, nms_mood, nms_auto
        ] + nms

        X_clinical.append(clin_vec)
        y_list.append(p['label'])
        group_list.append(pid)
        task_list.append(task_name)

        processed += 1

    except Exception as e:
        skipped += 1
        continue

print(f"\n✅ Processing complete:")
print(f"  - Processed: {processed} files")
print(f"  - Skipped: {skipped} files")

if processed == 0:
    print("\n❌ ERROR: No files were processed!")
    sys.exit(1)

# Convert to arrays
max_ch = max([x.shape[0] for x in X_signals])
X_sig_arr = np.zeros((len(X_signals), max_ch, SEQ_LEN), dtype=np.float32)

for i, x in enumerate(X_signals):
    X_sig_arr[i, :x.shape[0], :] = x

X_handcrafted_arr = np.array(X_handcrafted, dtype=np.float32)

feat_cols = [
    'age', 'gender', 'task', 'nms_sum', 'nms_mean', 'nms_std', 'nms_nonzero',
    'nms_motor', 'nms_sleep', 'nms_mood', 'nms_auto'
] + [f'nms_{i}' for i in range(30)]

df_clinical = pd.DataFrame(X_clinical, columns=feat_cols)
y = np.array(y_list)
groups = np.array(group_list)
task_arr = np.array(task_list)

# Calculate class statistics
n_pd = np.sum(y == 1)
n_hc = np.sum(y == 0)
class_ratio = n_pd / (n_hc + 1e-10)

print(f"\n{'=' * 80}")
print("📊 DATA SUMMARY")
print(f"{'=' * 80}")
print(f"Total samples         : {len(y)}")
print(f"Parkinson's patients  : {n_pd}")
print(f"Healthy controls      : {n_hc}")
print(f"Class ratio (PD/HC)   : {class_ratio:.2f}")
print(f"Unique patients       : {len(np.unique(groups))}")
print(f"Signal shape          : {X_sig_arr.shape}")
print(f"Handcrafted features  : {X_handcrafted_arr.shape}")
print(f"Clinical features     : {df_clinical.shape}")
print(f"{'=' * 80}")

# Clear memory
del X_signals
gc.collect()

# ============================================================================
# 6. ROCKET FEATURE EXTRACTION
# ============================================================================

print("\n🚀 Extracting MiniRocket features...")
rocket = MiniRocketMultivariate(num_kernels=8000, random_state=RANDOM_STATE)
X_rocket = rocket.fit_transform(X_sig_arr)
print(f"  ✅ Rocket features: {X_rocket.shape}")

# Optional PCA for dimensionality reduction
if X_rocket.shape[1] > 5000:
    from sklearn.decomposition import PCA
    print("  🔧 Applying PCA for dimensionality reduction...")
    pca = PCA(n_components=0.95, random_state=RANDOM_STATE)
    X_rocket_dense = X_rocket.values if hasattr(X_rocket, 'values') else X_rocket
    X_rocket = pd.DataFrame(pca.fit_transform(X_rocket_dense))
    print(f"  ✅ After PCA: {X_rocket.shape}")

del X_sig_arr
gc.collect()

# ============================================================================
# 7. CROSS-VALIDATION WITH MODEL ENSEMBLE
# ============================================================================

print(f"\n{'=' * 80}")
print("🔬 10-FOLD CROSS-VALIDATION")
print(f"{'=' * 80}")

cv = StratifiedGroupKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)

# Storage for results
metrics = {
    'bal_acc': [], 'acc': [], 'spec': [], 'sens': [],
    'f1': [], 'auc': [], 'precision': []
}

# Store all fold results for detailed analysis
fold_results = []
all_y_true = []
all_y_pred = []
all_y_prob = []

# Model hyperparameters
xgb_params = {
    'n_estimators': 500, 'learning_rate': 0.03, 'max_depth': 7,
    'min_child_weight': 3, 'subsample': 0.8, 'colsample_bytree': 0.8,
    'gamma': 1.5, 'reg_alpha': 0.5, 'reg_lambda': 1.0,
    'scale_pos_weight': 1.0/class_ratio, 'verbosity': 0, 'n_jobs': 2,
    'tree_method': 'hist'
}

lgbm_params = {
    'n_estimators': 500, 'learning_rate': 0.03, 'max_depth': 7,
    'num_leaves': 50, 'min_child_samples': 20, 'subsample': 0.8,
    'colsample_bytree': 0.8, 'reg_alpha': 2, 'reg_lambda': 2,
    'scale_pos_weight': 1.0/class_ratio, 'verbosity': -1, 'n_jobs': 2
}

cat_params = {
    'iterations': 600, 'learning_rate': 0.03, 'depth': 7,
    'l2_leaf_reg': 4, 'random_strength': 2, 'bagging_temperature': 0.5,
    'auto_class_weights': 'Balanced', 'verbose': 0,
    'allow_writing_files': False, 'thread_count': 2
}

# Cross-validation loop
for fold, (train_idx, test_idx) in enumerate(cv.split(X_rocket, y, groups=groups), 1):
    print(f"\n{'─' * 80}")
    print(f"📌 FOLD {fold}/10")
    print(f"{'─' * 80}")

    # Split data
    X_r_tr = X_rocket.iloc[train_idx].values if hasattr(X_rocket, 'iloc') else X_rocket[train_idx]
    X_r_te = X_rocket.iloc[test_idx].values if hasattr(X_rocket, 'iloc') else X_rocket[test_idx]

    X_hc_tr, X_hc_te = X_handcrafted_arr[train_idx], X_handcrafted_arr[test_idx]
    df_c_tr, df_c_te = df_clinical.iloc[train_idx], df_clinical.iloc[test_idx]

    y_tr, y_te = y[train_idx], y[test_idx]
    g_te = groups[test_idx]
    task_te = task_arr[test_idx]

    # Clinical preprocessing
    clin_preprocessor = ColumnTransformer(
        transformers=[
            ('num', RobustScaler(),
             ['age', 'nms_sum', 'nms_mean', 'nms_std', 'nms_nonzero',
              'nms_motor', 'nms_sleep', 'nms_mood', 'nms_auto'] +
             [f'nms_{i}' for i in range(30)]),
            ('cat', OrdinalEncoder(handle_unknown='use_encoded_value', unknown_value=-1),
             ['gender', 'task'])
        ]
    )

    X_c_tr = clin_preprocessor.fit_transform(df_c_tr)
    X_c_te = clin_preprocessor.transform(df_c_te)

    # Handcrafted scaling
    hc_scaler = RobustScaler()
    X_hc_tr_scaled = hc_scaler.fit_transform(X_hc_tr)
    X_hc_te_scaled = hc_scaler.transform(X_hc_te)

    # Combine features
    X_combined_tr = np.hstack([X_r_tr, X_hc_tr_scaled]).astype(np.float32)
    X_combined_te = np.hstack([X_r_te, X_hc_te_scaled]).astype(np.float32)

    # Train models
    print("  🎯 Training models...")

    # 1. Ridge Classifier
    signal_model = CalibratedClassifierCV(
        RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced'),
        method='sigmoid', cv=3
    )
    signal_model.fit(X_combined_tr, y_tr)
    p_signal = signal_model.predict_proba(X_combined_te)[:, 1]

    # 2-4. Gradient Boosting Models
    xgb_model = XGBClassifier(**xgb_params, random_state=RANDOM_STATE)
    lgbm_model = LGBMClassifier(**lgbm_params, random_state=RANDOM_STATE)
    cat_model = CatBoostClassifier(**cat_params, random_state=RANDOM_STATE)

    xgb_model.fit(X_combined_tr, y_tr)
    lgbm_model.fit(X_combined_tr, y_tr)
    cat_model.fit(X_combined_tr, y_tr)

    p_xgb = xgb_model.predict_proba(X_combined_te)[:, 1]
    p_lgbm = lgbm_model.predict_proba(X_combined_te)[:, 1]
    p_cat = cat_model.predict_proba(X_combined_te)[:, 1]

    # 5. MLP Neural Network
    mlp_model = MLPClassifier(
        hidden_layer_sizes=(128, 64, 32), alpha=0.01,
        learning_rate_init=0.001, max_iter=500,
        early_stopping=True, validation_fraction=0.1,
        n_iter_no_change=15, random_state=RANDOM_STATE
    )
    mlp_model.fit(X_c_tr, y_tr)
    p_mlp = mlp_model.predict_proba(X_c_te)[:, 1]

    # 6. Random Forest
    rf_model = RandomForestClassifier(
        n_estimators=300, max_depth=12, min_samples_split=5,
        class_weight='balanced', random_state=RANDOM_STATE,
        n_jobs=2, max_samples=0.8
    )
    rf_model.fit(X_combined_tr, y_tr)
    p_rf = rf_model.predict_proba(X_combined_te)[:, 1]

    # Ensemble predictions
    ensemble_probs = (
        0.15 * p_signal + 0.20 * p_xgb + 0.20 * p_lgbm +
        0.20 * p_cat + 0.15 * p_mlp + 0.10 * p_rf
    )

    # Patient-level aggregation
    df_res = pd.DataFrame({
        'pid': g_te,
        'true': y_te,
        'prob': ensemble_probs,
        'task': task_te
    })

    # Weighted aggregation per patient
    patient_scores = []
    patient_labels = []

    for pid in df_res['pid'].unique():
        patient_data = df_res[df_res['pid'] == pid]

        # Confidence-weighted average
        probs = patient_data['prob'].values
        confidence = np.abs(probs - 0.5)

        if confidence.sum() > 0:
            weights = confidence / confidence.sum()
            final_prob = (probs * weights).sum()
        else:
            final_prob = probs.mean()

        patient_scores.append(final_prob)
        patient_labels.append(patient_data['true'].iloc[0])

    y_true_pat = np.array(patient_labels, dtype=int)
    y_prob_pat = np.array(patient_scores)

    # Optimal threshold using Youden's J statistic
    fpr, tpr, thresholds = roc_curve(y_true_pat, y_prob_pat)
    j_scores = tpr - fpr
    best_th = thresholds[np.argmax(j_scores)]
    y_pred_pat = (y_prob_pat >= best_th).astype(int)

    # Calculate metrics
    bal_acc = balanced_accuracy_score(y_true_pat, y_pred_pat)
    acc = accuracy_score(y_true_pat, y_pred_pat)
    spec = recall_score(y_true_pat, y_pred_pat, pos_label=0)
    sens = recall_score(y_true_pat, y_pred_pat, pos_label=1)
    f1 = f1_score(y_true_pat, y_pred_pat)
    auc = roc_auc_score(y_true_pat, y_prob_pat)
    prec = precision_score(y_true_pat, y_pred_pat)

    # Store metrics
    metrics['bal_acc'].append(bal_acc)
    metrics['acc'].append(acc)
    metrics['spec'].append(spec)
    metrics['sens'].append(sens)
    metrics['f1'].append(f1)
    metrics['auc'].append(auc)
    metrics['precision'].append(prec)

    # Store fold results
    fold_results.append({
        'fold': fold,
        'bal_acc': bal_acc,
        'sens': sens,
        'spec': spec,
        'f1': f1,
        'auc': auc,
        'precision': prec,
        'threshold': best_th
    })

    # Store for overall confusion matrix
    all_y_true.extend(y_true_pat)
    all_y_pred.extend(y_pred_pat)
    all_y_prob.extend(y_prob_pat)

    print(f"  BalAcc: {bal_acc*100:.2f}% | Sens: {sens*100:.2f}% | "
          f"Spec: {spec*100:.2f}% | F1: {f1*100:.2f}% | AUC: {auc*100:.2f}%")

    gc.collect()

# ============================================================================
# 8. RESULTS SUMMARY
# ============================================================================

print(f"\n{'=' * 80}")
print("🏆 FINAL RESULTS")
print(f"{'=' * 80}")

for metric_name, metric_values in metrics.items():
    mean_val = np.mean(metric_values)
    std_val = np.std(metric_values)
    print(f"{metric_name.upper():15s}: {mean_val*100:6.2f}% ± {std_val*100:5.2f}%")

print(f"{'=' * 80}")

# Comparison with paper
target = 91.16
current = np.mean(metrics['bal_acc']) * 100
diff = current - target

print(f"\n📈 Paper Score    : {target:.2f}%")
print(f"🚀 Our Score      : {current:.2f}%")
print(f"{'✅' if diff > 0 else '⚠️'} Difference    : {diff:+.2f}%")

if diff > 0:
    print(f"\n🎉 SUCCESS! We exceeded the paper's performance!")
else:
    print(f"\n💡 Rocket kernels can be increased for better performance")

print(f"\n{'=' * 80}")

