def save_fig_3_formats(name):
    """Figürü TIFF, JPG ve EPS olarak kaydeder."""
    base_path = os.path.join(output_dir, name)

    # TIFF (LZW Sıkıştırma)
    try:
        plt.savefig(f"{base_path}.tiff", dpi=600, pil_kwargs={'compression': 'tiff_lzw'}, bbox_inches='tight')
    except:
        plt.savefig(f"{base_path}.tiff", dpi=600, bbox_inches='tight')

    # JPG (Standart)
    plt.savefig(f"{base_path}.jpg", dpi=600, format='jpg', bbox_inches='tight')

    # EPS (Vektörel)
    plt.savefig(f"{base_path}.eps", format='eps', dpi=600, bbox_inches='tight')

    plt.close()

