def find_file_in_drive(filename, max_depth=5):
    """Search for file in Google Drive"""
    print(f"🔍 Searching for '{filename}'...")

    common_paths = [
        f"/content/{filename}",
        f"/content/drive/MyDrive/{filename}",
        f"./{filename}",
        f"../{filename}",
        f"/content/drive/MyDrive/Colab Notebooks/{filename}",
        f"/content/drive/MyDrive/datasets/{filename}",
        f"/content/drive/MyDrive/data/{filename}",
    ]

    for path in common_paths:
        if os.path.exists(path):
            print(f"✅ Found: {path}")
            return path

    try:
        if os.path.exists("/content/drive"):
            print("  📂 Scanning Drive...")
            result = subprocess.getoutput(
                f"find /content/drive -name '{filename}' -type f 2>/dev/null | head -1"
            )
            if result and result.strip() and "No such file" not in result:
                print(f"✅ Found: {result.strip()}")
                return result.strip()
    except:
        pass

    print(f"❌ '{filename}' not found!")
    return None

