# ============================================================================
# 4. ENHANCED FEATURE EXTRACTION WITH CHANNEL TRACKING
# ============================================================================

def extract_features_with_labels(signal, channel_name="unknown"):
    """Extract features with channel labels for importance analysis"""
    features = []
    feature_names = []

    # Statistical features (10)
    stat_features = [
        ('mean', np.mean(signal)),
        ('std', np.std(signal)),
        ('median', np.median(signal)),
        ('min', np.min(signal)),
        ('max', np.max(signal)),
        ('range', np.ptp(signal)),
        ('skewness', skew(signal)),
        ('kurtosis', kurtosis(signal)),
        ('q25', np.percentile(signal, 25)),
        ('q75', np.percentile(signal, 75))
    ]

    for name, val in stat_features:
        features.append(val)
        feature_names.append(f"{channel_name}_stat_{name}")

    # Wavelet features (9)
    try:
        coeffs = pywt.wavedec(signal, 'db4', level=2)
        for level_idx, c in enumerate(coeffs):
            features.extend([np.mean(c), np.std(c), np.max(np.abs(c))])
            feature_names.extend([
                f"{channel_name}_wavelet_L{level_idx}_mean",
                f"{channel_name}_wavelet_L{level_idx}_std",
                f"{channel_name}_wavelet_L{level_idx}_max"
            ])
    except:
        features.extend([0] * 9)
        for level_idx in range(3):
            feature_names.extend([
                f"{channel_name}_wavelet_L{level_idx}_mean",
                f"{channel_name}_wavelet_L{level_idx}_std",
                f"{channel_name}_wavelet_L{level_idx}_max"
            ])

    # Frequency features (3)
    try:
        freqs, psd = welch(signal, fs=100, nperseg=min(128, len(signal)))
        freq_features = [
            ('total_power', np.sum(psd)),
            ('peak_power', np.max(psd)),
            ('peak_freq', np.argmax(psd))
        ]
        for name, val in freq_features:
            features.append(val)
            feature_names.append(f"{channel_name}_freq_{name}")
    except:
        features.extend([0] * 3)
        for name in ['total_power', 'peak_power', 'peak_freq']:
            feature_names.append(f"{channel_name}_freq_{name}")

    # Temporal features (2)
    diff1 = np.diff(signal)
    features.extend([np.mean(np.abs(diff1)), np.std(diff1)])
    feature_names.extend([
        f"{channel_name}_temporal_diff_mean",
        f"{channel_name}_temporal_diff_std"
    ])

    return np.array(features), feature_names

