# 5. DATA LOADING
# ============================================================================

print("\n📊 Loading metadata...")
patient_info = {}

if meta_path and os.path.exists(meta_path):
    df_meta = pd.read_csv(meta_path)
    df_filtered = df_meta[df_meta['label'].isin([0, 1])]

    for _, row in df_filtered.iterrows():
        pid = str(row['id']).zfill(3)
        patient_info[pid] = {
            'label': int(row['label']),
            'age': row['age'],
            'gender': str(row['gender'])
        }
    print(f"✅ Metadata loaded: {len(patient_info)} patients")
else:
    print("  📄 Reading from patient JSON files...")
    p_files = glob(os.path.join(data_path, "**", "patient_*.json"), recursive=True)

    for pf in p_files:
        try:
            with open(pf) as f:
                d = json.load(f)

            pid = str(d.get('id', ''))
            cond = d.get('condition', '').lower()

            if "parkinson" in cond:
                lbl = 1
            elif "healthy" in cond or "control" in cond:
                lbl = 0
            else:
                continue

            if pid:
                patient_info[pid] = {
                    'label': lbl,
                    'age': d.get('age', 60),
                    'gender': str(d.get('gender', 'unknown'))
                }
        except:
            continue

    print(f"✅ Loaded from JSONs: {len(patient_info)} patients")

if len(patient_info) == 0:
    print("❌ ERROR: No patient data!")
    sys.exit(1)

# Load NMS Questionnaire
print("\n📋 Loading questionnaire data...")
nms_data = {}
q_files = glob(os.path.join(data_path, "**", "questionnaire_response_*.json"),
               recursive=True)

for qf in q_files:
    try:
        with open(qf) as f:
            q = json.load(f)

        pid = str(q.get('subject_id', ''))
        if pid not in patient_info:
            continue

        items = q.get('item', [])
        answers = [0] * 30

        for item in items:
            link_id = item.get('link_id', '99')
            try:
                idx = int(link_id) - 1
                if 0 <= idx < 30:
                    ans = item.get('answer', False)
                    answers[idx] = 1 if ans is True else 0
            except:
                continue

        nms_data[pid] = answers
    except:
        continue

print(f"✅ Questionnaire data: {len(nms_data)} patients")

# Load signals
print("\n📡 Loading signal files...")
s_files = glob(os.path.join(data_path, "**", "*.txt"), recursive=True)
s_files = [f for f in s_files if "LICENSE" not in f and "README" not in f]
print(f"  Found {len(s_files)} signal files")

if len(s_files) == 0:
    print("❌ ERROR: No signals!")
    sys.exit(1)

# Process signals with channel tracking
X_signals, X_handcrafted, X_clinical = [], [], []
y_list, group_list, task_list = [], [], []
handcrafted_feature_names = []
channel_names = ['accel_x', 'accel_y', 'accel_z']  # Example

print(f"\n⚙️ Processing {len(s_files)} files...")
processed = 0
skipped = 0

for f_path in tqdm(s_files, desc="Processing"):
    try:
        fname = os.path.basename(f_path)
        parts = fname.replace('.txt', '').split('_')

        if len(parts) < 1:
            skipped += 1
            continue

        pid = parts[0]
        if pid not in patient_info:
            skipped += 1
            continue

        task_name = parts[1] if len(parts) > 1 else "Unknown"

        df = pd.read_csv(f_path, header=None)
        raw = df.select_dtypes(include=[np.number]).values

        if raw.shape[0] < 100:
            skipped += 1
            continue

        if raw.shape[0] > CROP_START:
            raw = raw[CROP_START:, :]

        raw = detrend(raw, axis=0)

        if raw.shape[0] > raw.shape[1]:
            raw = raw.T

        dat_res = resample(raw, SEQ_LEN, axis=1)
        X_signals.append(dat_res)

        # Extract features with channel names
        hc_features = []
        if processed == 0:  # First file - store feature names
            for ch_idx in range(min(dat_res.shape[0], 3)):
                ch_name = channel_names[ch_idx] if ch_idx < len(channel_names) else f"ch{ch_idx}"
                feats, names = extract_features_with_labels(dat_res[ch_idx, :], ch_name)
                hc_features.extend(feats)
                if len(handcrafted_feature_names) < 24 * 3:  # 24 features per channel
                    handcrafted_feature_names.extend(names)
        else:
            for ch_idx in range(min(dat_res.shape[0], 3)):
                ch_name = channel_names[ch_idx] if ch_idx < len(channel_names) else f"ch{ch_idx}"
                feats, _ = extract_features_with_labels(dat_res[ch_idx, :], ch_name)
                hc_features.extend(feats)

        X_handcrafted.append(hc_features)

        # Clinical features
        p = patient_info[pid]
        nms = nms_data.get(pid, [0] * 30)

        nms_sum = sum(nms)
        nms_mean = np.mean(nms)
        nms_std = np.std(nms)
        nms_nonzero = np.count_nonzero(nms)

        nms_motor = sum(nms[0:10])
        nms_sleep = sum(nms[10:15])
        nms_mood = sum(nms[15:20])
        nms_auto = sum(nms[20:30])

        clin_vec = [
            float(p['age']),
            str(p['gender']),
            str(task_name),
            nms_sum, nms_mean, nms_std, nms_nonzero,
            nms_motor, nms_sleep, nms_mood, nms_auto
        ] + nms

        X_clinical.append(clin_vec)
        y_list.append(p['label'])
        group_list.append(pid)
        task_list.append(task_name)

        processed += 1

    except Exception as e:
        skipped += 1
        continue

print(f"\n✅ Processing complete:")
print(f"  - Processed: {processed}")
print(f"  - Skipped: {skipped}")

if processed == 0:
    print("\n❌ ERROR: No data processed!")
    sys.exit(1)

# Convert to arrays
max_ch = max([x.shape[0] for x in X_signals])
X_sig_arr = np.zeros((len(X_signals), max_ch, SEQ_LEN), dtype=np.float32)

for i, x in enumerate(X_signals):
    X_sig_arr[i, :x.shape[0], :] = x

X_handcrafted_arr = np.array(X_handcrafted, dtype=np.float32)

feat_cols = [
    'age', 'gender', 'task', 'nms_sum', 'nms_mean', 'nms_std', 'nms_nonzero',
    'nms_motor', 'nms_sleep', 'nms_mood', 'nms_auto'
] + [f'nms_{i}' for i in range(30)]

df_clinical = pd.DataFrame(X_clinical, columns=feat_cols)
y = np.array(y_list)
groups = np.array(group_list)
task_arr = np.array(task_list)

# Statistics
n_pd = np.sum(y == 1)
n_hc = np.sum(y == 0)
class_ratio = n_pd / (n_hc + 1e-10)

print(f"\n{'=' * 80}")
print("📊 DATA SUMMARY")
print(f"{'=' * 80}")
print(f"Total samples        : {len(y)}")
print(f"Parkinson's patients : {n_pd}")
print(f"Healthy controls     : {n_hc}")
print(f"Class ratio (PD/HC)  : {class_ratio:.2f}")
print(f"Unique patients      : {len(np.unique(groups))}")
print(f"Signal shape         : {X_sig_arr.shape}")
print(f"Handcrafted features : {X_handcrafted_arr.shape}")
print(f"Clinical features    : {df_clinical.shape}")
print(f"{'=' * 80}")

del X_signals
