# 8. STATISTICAL SIGNIFICANCE TESTING
# ============================================================================

print(f"\n{'=' * 80}")
print("📊 STATISTICAL SIGNIFICANCE ANALYSIS")
print(f"{'=' * 80}")

# Our results
our_bal_acc = np.array(metrics['bal_acc']) * 100
our_sens = np.array(metrics['sens']) * 100
our_spec = np.array(metrics['spec']) * 100
our_f1 = np.array(metrics['f1']) * 100

# Paper results (Varghese et al. 2024)
paper_bal_acc = 91.16
paper_sens = 92.40
paper_spec = 92.00
paper_f1 = 94.62

# One-sample t-test (comparing our mean to paper's value)
t_stat_bal, p_val_bal = stats.ttest_1samp(our_bal_acc, paper_bal_acc)
t_stat_sens, p_val_sens = stats.ttest_1samp(our_sens, paper_sens)
t_stat_spec, p_val_spec = stats.ttest_1samp(our_spec, paper_spec)
t_stat_f1, p_val_f1 = stats.ttest_1samp(our_f1, paper_f1)

# Effect size (Cohen's d)
def cohens_d(x, mu):
    return (np.mean(x) - mu) / np.std(x)

d_bal = cohens_d(our_bal_acc, paper_bal_acc)
d_sens = cohens_d(our_sens, paper_sens)
d_spec = cohens_d(our_spec, paper_spec)
d_f1 = cohens_d(our_f1, paper_f1)

# Confidence intervals (95%)
def ci_95(data):
    mean = np.mean(data)
    se = stats.sem(data)
    ci = stats.t.interval(0.95, len(data)-1, loc=mean, scale=se)
    return ci

ci_bal = ci_95(our_bal_acc)
ci_sens = ci_95(our_sens)
ci_spec = ci_95(our_spec)
ci_f1 = ci_95(our_f1)

print("\n📈 Comparison with Varghese et al. (2024):")
print(f"{'─' * 80}")
print(f"{'Metric':<20} {'Ours':<15} {'Paper':<10} {'Diff':<10} {'p-value':<12} {'Cohen d':<10}")
print(f"{'─' * 80}")

print(f"{'Balanced Accuracy':<20} {np.mean(our_bal_acc):>6.2f}±{np.std(our_bal_acc):>4.2f} "
      f"{paper_bal_acc:>8.2f}  {np.mean(our_bal_acc)-paper_bal_acc:>+7.2f}  "
      f"{'p<0.001' if p_val_bal < 0.001 else f'p={p_val_bal:.3f}':<12} "
      f"{d_bal:>+7.2f}")

print(f"{'Sensitivity':<20} {np.mean(our_sens):>6.2f}±{np.std(our_sens):>4.2f} "
      f"{paper_sens:>8.2f}  {np.mean(our_sens)-paper_sens:>+7.2f}  "
      f"{'p<0.001' if p_val_sens < 0.001 else f'p={p_val_sens:.3f}':<12} "
      f"{d_sens:>+7.2f}")

print(f"{'Specificity':<20} {np.mean(our_spec):>6.2f}±{np.std(our_spec):>4.2f} "
      f"{paper_spec:>8.2f}  {np.mean(our_spec)-paper_spec:>+7.2f}  "
      f"{'p<0.001' if p_val_spec < 0.001 else f'p={p_val_spec:.3f}':<12} "
      f"{d_spec:>+7.2f}")

print(f"{'F1-Score':<20} {np.mean(our_f1):>6.2f}±{np.std(our_f1):>4.2f} "
      f"{paper_f1:>8.2f}  {np.mean(our_f1)-paper_f1:>+7.2f}  "
      f"{'p<0.001' if p_val_f1 < 0.001 else f'p={p_val_f1:.3f}':<12} "
      f"{d_f1:>+7.2f}")

print(f"{'─' * 80}")

print(f"\n📊 95% Confidence Intervals:")
print(f"  Balanced Accuracy: [{ci_bal[0]:.2f}, {ci_bal[1]:.2f}]")
print(f"  Sensitivity:       [{ci_sens[0]:.2f}, {ci_sens[1]:.2f}]")
print(f"  Specificity:       [{ci_spec[0]:.2f}, {ci_spec[1]:.2f}]")
print(f"  F1-Score:          [{ci_f1[0]:.2f}, {ci_f1[1]:.2f}]")

