def find_file_in_drive(filename):
    """Search for file in Google Drive"""
    print(f"🔍 Searching for '{filename}'...")

    common_paths = [
        f"/content/{filename}",
        f"/content/drive/MyDrive/{filename}",
        f"./{filename}",
        f"../{filename}",
        f"/content/drive/MyDrive/Colab Notebooks/{filename}",
        f"/content/drive/MyDrive/datasets/{filename}",
    ]

    for path in common_paths:
        if os.path.exists(path):
            print(f"✅ Found: {path}")
            return path

    try:
        if os.path.exists("/content/drive"):
            result = subprocess.getoutput(
                f"find /content/drive -name '{filename}' -type f 2>/dev/null | head -1"
            )
            if result and result.strip():
                print(f"✅ Found: {result.strip()}")
                return result.strip()
    except:
        pass

    return None

def find_extracted_data():
    """Find previously extracted data"""
    possible_dirs = [
        "./pads_data_extracted", "/content/pads_data_extracted",
        "/content/drive/MyDrive/pads_data_extracted"
    ]

    for dir_path in possible_dirs:
        if os.path.exists(dir_path):
            txt_files = glob(os.path.join(dir_path, "**", "*.txt"), recursive=True)
            if len(txt_files) > 10:
                print(f"✅ Found data: {dir_path}")
                return dir_path

    return None

