print(f"Total samples        : {len(y)}")
print(f"Parkinson's Disease  : {n_pd} ({n_pd/len(y)*100:.1f}%)")
print(f"Healthy Controls     : {n_hc} ({n_hc/len(y)*100:.1f}%)")
print(f"Class ratio (PD/HC)  : 1:{class_ratio:.2f}")
print(f"Unique patients      : {unique_patients}")
print(f"  - PD patients      : {unique_pd_patients}")
print(f"  - HC patients      : {unique_hc_patients}")
