# 6. CROSS-VALIDATION (ZERO DATA LEAKAGE!)
# ============================================================================

print(f"\n{'=' * 80}")
print("🔬 10-FOLD CROSS-VALIDATION (ZERO DATA LEAKAGE)")
print(f"{'=' * 80}")
print("✓ Rocket fit ONLY on training per fold")
print("✓ PCA fit ONLY on training per fold")
print("✓ Threshold calculated ONLY on training per fold")
print(f"{'=' * 80}")

cv = StratifiedGroupKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)

metrics = {
    'bal_acc': [], 'acc': [], 'spec': [], 'sens': [],
    'f1': [], 'auc': [], 'precision': []
}

fold_results = []
all_y_true, all_y_pred, all_y_prob = [], [], []

# Model parameters
xgb_params = {
    'n_estimators': 500, 'learning_rate': 0.03, 'max_depth': 7,
    'min_child_weight': 3, 'subsample': 0.8, 'colsample_bytree': 0.8,
    'gamma': 1.5, 'reg_alpha': 0.5, 'reg_lambda': 1.0,
    'scale_pos_weight': 1.0/class_ratio, 'verbosity': 0, 'n_jobs': 2,
    'tree_method': 'hist'
}

lgbm_params = {
    'n_estimators': 500, 'learning_rate': 0.03, 'max_depth': 7,
    'num_leaves': 50, 'min_child_samples': 20, 'subsample': 0.8,
    'colsample_bytree': 0.8, 'reg_alpha': 2, 'reg_lambda': 2,
    'scale_pos_weight': 1.0/class_ratio, 'verbosity': -1, 'n_jobs': 2
}

cat_params = {
    'iterations': 600, 'learning_rate': 0.03, 'depth': 7,
    'l2_leaf_reg': 4, 'random_strength': 2, 'bagging_temperature': 0.5,
    'auto_class_weights': 'Balanced', 'verbose': 0,
    'allow_writing_files': False, 'thread_count': 2
}

for fold, (train_idx, test_idx) in enumerate(cv.split(X_sig_arr, y, groups=groups), 1):
    print(f"\n{'─' * 80}")
    print(f"📌 FOLD {fold}/10")
    print(f"{'─' * 80}")

    # Split
    X_sig_tr, X_sig_te = X_sig_arr[train_idx], X_sig_arr[test_idx]
    X_hc_tr, X_hc_te = X_handcrafted_arr[train_idx], X_handcrafted_arr[test_idx]
    df_c_tr, df_c_te = df_clinical.iloc[train_idx], df_clinical.iloc[test_idx]
    y_tr, y_te = y[train_idx], y[test_idx]
    g_tr, g_te = groups[train_idx], groups[test_idx]
    task_te = task_arr[test_idx]

    # Rocket fit on training ONLY
    print("  🚀 Rocket: fit on training...")
    rocket = MiniRocketMultivariate(num_kernels=8000, random_state=RANDOM_STATE)
    X_r_tr = rocket.fit_transform(X_sig_tr)
    X_r_te = rocket.transform(X_sig_te)

    # PCA fit on training ONLY (if needed)
    if X_r_tr.shape[1] > 5000:
        print("  🔧 PCA: fit on training...")
        pca = PCA(n_components=0.95, random_state=RANDOM_STATE)
        X_r_tr_dense = X_r_tr.values if hasattr(X_r_tr, 'values') else X_r_tr
        X_r_te_dense = X_r_te.values if hasattr(X_r_te, 'values') else X_r_te

        X_r_tr = pca.fit_transform(X_r_tr_dense)
        X_r_te = pca.transform(X_r_te_dense)
    else:
        X_r_tr = X_r_tr.values if hasattr(X_r_tr, 'values') else X_r_tr
        X_r_te = X_r_te.values if hasattr(X_r_te, 'values') else X_r_te

    # Clinical preprocessing (fit on train)
    clin_preprocessor = ColumnTransformer(
        transformers=[
            ('num', RobustScaler(),
             ['age', 'nms_sum', 'nms_mean', 'nms_std', 'nms_nonzero',
              'nms_motor', 'nms_sleep', 'nms_mood', 'nms_auto'] +
             [f'nms_{i}' for i in range(30)]),
            ('cat', OrdinalEncoder(handle_unknown='use_encoded_value', unknown_value=-1),
             ['gender', 'task'])
        ]
    )

    X_c_tr = clin_preprocessor.fit_transform(df_c_tr)
    X_c_te = clin_preprocessor.transform(df_c_te)

    # Handcrafted scaling
    hc_scaler = RobustScaler()
    X_hc_tr_scaled = hc_scaler.fit_transform(X_hc_tr)
    X_hc_te_scaled = hc_scaler.transform(X_hc_te)

    # Combine
    X_combined_tr = np.hstack([X_r_tr, X_hc_tr_scaled]).astype(np.float32)
    X_combined_te = np.hstack([X_r_te, X_hc_te_scaled]).astype(np.float32)

    # Train models
    print("  🎯 Training 6 models...")

    signal_model = CalibratedClassifierCV(
        RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced'),
        method='sigmoid', cv=3
    )
    signal_model.fit(X_combined_tr, y_tr)

    xgb_model = XGBClassifier(**xgb_params, random_state=RANDOM_STATE)
    lgbm_model = LGBMClassifier(**lgbm_params, random_state=RANDOM_STATE)
    cat_model = CatBoostClassifier(**cat_params, random_state=RANDOM_STATE)

    xgb_model.fit(X_combined_tr, y_tr)
    lgbm_model.fit(X_combined_tr, y_tr)
    cat_model.fit(X_combined_tr, y_tr)

    mlp_model = MLPClassifier(
        hidden_layer_sizes=(128, 64, 32), alpha=0.01,
        learning_rate_init=0.001, max_iter=500,
        early_stopping=True, validation_fraction=0.1,
        n_iter_no_change=15, random_state=RANDOM_STATE
    )
    mlp_model.fit(X_c_tr, y_tr)

    rf_model = RandomForestClassifier(
        n_estimators=300, max_depth=12, min_samples_split=5,
        class_weight='balanced', random_state=RANDOM_STATE,
        n_jobs=2, max_samples=0.8
    )
    rf_model.fit(X_combined_tr, y_tr)

    # Get predictions on TRAINING for threshold
    print("  🔧 Threshold: calculated on training...")

    p_signal_train = signal_model.predict_proba(X_combined_tr)[:, 1]
    p_xgb_train = xgb_model.predict_proba(X_combined_tr)[:, 1]
    p_lgbm_train = lgbm_model.predict_proba(X_combined_tr)[:, 1]
    p_cat_train = cat_model.predict_proba(X_combined_tr)[:, 1]
    p_mlp_train = mlp_model.predict_proba(X_c_tr)[:, 1]
    p_rf_train = rf_model.predict_proba(X_combined_tr)[:, 1]

    ensemble_probs_train = (
        0.15 * p_signal_train + 0.20 * p_xgb_train + 0.20 * p_lgbm_train +
        0.20 * p_cat_train + 0.15 * p_mlp_train + 0.10 * p_rf_train
    )

    # Patient-level aggregation for TRAINING
    df_res_train = pd.DataFrame({'pid': g_tr, 'true': y_tr, 'prob': ensemble_probs_train})

    patient_scores_train = []
    patient_labels_train = []

    for pid in df_res_train['pid'].unique():
        patient_data = df_res_train[df_res_train['pid'] == pid]
        probs = patient_data['prob'].values
        confidence = np.abs(probs - 0.5)

        if confidence.sum() > 0:
            weights = confidence / confidence.sum()
            final_prob = (probs * weights).sum()
        else:
            final_prob = probs.mean()

        patient_scores_train.append(final_prob)
        patient_labels_train.append(patient_data['true'].iloc[0])

    y_true_pat_train = np.array(patient_labels_train, dtype=int)
    y_prob_pat_train = np.array(patient_scores_train)

    # Calculate threshold on TRAINING
    fpr_train, tpr_train, thresholds_train = roc_curve(y_true_pat_train, y_prob_pat_train)
    j_scores_train = tpr_train - fpr_train
    best_th = thresholds_train[np.argmax(j_scores_train)]

    # Get predictions on TEST
    p_signal_test = signal_model.predict_proba(X_combined_te)[:, 1]
    p_xgb_test = xgb_model.predict_proba(X_combined_te)[:, 1]
    p_lgbm_test = lgbm_model.predict_proba(X_combined_te)[:, 1]
    p_cat_test = cat_model.predict_proba(X_combined_te)[:, 1]
    p_mlp_test = mlp_model.predict_proba(X_c_te)[:, 1]
    p_rf_test = rf_model.predict_proba(X_combined_te)[:, 1]

    ensemble_probs_test = (
        0.15 * p_signal_test + 0.20 * p_xgb_test + 0.20 * p_lgbm_test +
        0.20 * p_cat_test + 0.15 * p_mlp_test + 0.10 * p_rf_test
    )

    # Patient-level aggregation for TEST
    df_res_test = pd.DataFrame({
        'pid': g_te, 'true': y_te, 'prob': ensemble_probs_test, 'task': task_te
    })

    patient_scores_test = []
    patient_labels_test = []

    for pid in df_res_test['pid'].unique():
        patient_data = df_res_test[df_res_test['pid'] == pid]
        probs = patient_data['prob'].values
        confidence = np.abs(probs - 0.5)

        if confidence.sum() > 0:
            weights = confidence / confidence.sum()
            final_prob = (probs * weights).sum()
        else:
            final_prob = probs.mean()

        patient_scores_test.append(final_prob)
        patient_labels_test.append(patient_data['true'].iloc[0])

    y_true_pat = np.array(patient_labels_test, dtype=int)
    y_prob_pat = np.array(patient_scores_test)

    # Apply threshold from TRAINING to TEST
    y_pred_pat = (y_prob_pat >= best_th).astype(int)

    # Metrics
    bal_acc = balanced_accuracy_score(y_true_pat, y_pred_pat)
    acc = accuracy_score(y_true_pat, y_pred_pat)
    spec = recall_score(y_true_pat, y_pred_pat, pos_label=0)
    sens = recall_score(y_true_pat, y_pred_pat, pos_label=1)
    f1 = f1_score(y_true_pat, y_pred_pat)
    auc = roc_auc_score(y_true_pat, y_prob_pat)
    prec = precision_score(y_true_pat, y_pred_pat)

    metrics['bal_acc'].append(bal_acc)
    metrics['acc'].append(acc)
    metrics['spec'].append(spec)
    metrics['sens'].append(sens)
    metrics['f1'].append(f1)
    metrics['auc'].append(auc)
    metrics['precision'].append(prec)

    fold_results.append({
        'fold': fold, 'bal_acc': bal_acc, 'sens': sens,
        'spec': spec, 'f1': f1, 'auc': auc, 'threshold': best_th
    })

    all_y_true.extend(y_true_pat)
    all_y_pred.extend(y_pred_pat)
    all_y_prob.extend(y_prob_pat)

    print(f"  Results: BalAcc={bal_acc*100:.2f}% | Sens={sens*100:.2f}% | "
          f"Spec={spec*100:.2f}% | F1={f1*100:.2f}%")

    gc.collect()

# ============================================================================
# 7. STATISTICAL SIGNIFICANCE
# ============================================================================

print(f"\n{'=' * 80}")
print("📊 STATISTICAL SIGNIFICANCE ANALYSIS")
print(f"{'=' * 80}")

our_bal_acc = np.array(metrics['bal_acc']) * 100
our_sens = np.array(metrics['sens']) * 100
our_spec = np.array(metrics['spec']) * 100
our_f1 = np.array(metrics['f1']) * 100

paper_bal_acc, paper_sens, paper_spec, paper_f1 = 91.16, 92.40, 92.00, 94.62

# One-sample t-test
t_stat_bal, p_val_bal = stats.ttest_1samp(our_bal_acc, paper_bal_acc)
t_stat_sens, p_val_sens = stats.ttest_1samp(our_sens, paper_sens)
t_stat_spec, p_val_spec = stats.ttest_1samp(our_spec, paper_spec)
t_stat_f1, p_val_f1 = stats.ttest_1samp(our_f1, paper_f1)

# Cohen's d
def cohens_d(x, mu):
    return (np.mean(x) - mu) / np.std(x)

d_bal = cohens_d(our_bal_acc, paper_bal_acc)
d_sens = cohens_d(our_sens, paper_sens)
d_spec = cohens_d(our_spec, paper_spec)
d_f1 = cohens_d(our_f1, paper_f1)

# 95% CI
def ci_95(data):
    mean = np.mean(data)
    se = stats.sem(data)
    return stats.t.interval(0.95, len(data)-1, loc=mean, scale=se)

ci_bal = ci_95(our_bal_acc)
ci_sens = ci_95(our_sens)
ci_spec = ci_95(our_spec)
ci_f1 = ci_95(our_f1)

print(f"\n{'Metric':<20} {'Ours':<15} {'Paper':<10} {'Diff':<10} {'p-value':<12} {'Cohen d'}")
print(f"{'─' * 80}")

print(f"{'Balanced Accuracy':<20} {np.mean(our_bal_acc):>6.2f}±{np.std(our_bal_acc):>4.2f} "
      f"{paper_bal_acc:>8.2f}  {np.mean(our_bal_acc)-paper_bal_acc:>+7.2f}  "
      f"{'p<0.001' if p_val_bal < 0.001 else f'p={p_val_bal:.3f}':<12} {d_bal:>+7.2f}")

print(f"{'Sensitivity':<20} {np.mean(our_sens):>6.2f}±{np.std(our_sens):>4.2f} "
      f"{paper_sens:>8.2f}  {np.mean(our_sens)-paper_sens:>+7.2f}  "
      f"{'p<0.001' if p_val_sens < 0.001 else f'p={p_val_sens:.3f}':<12} {d_sens:>+7.2f}")

print(f"{'Specificity':<20} {np.mean(our_spec):>6.2f}±{np.std(our_spec):>4.2f} "
      f"{paper_spec:>8.2f}  {np.mean(our_spec)-paper_spec:>+7.2f}  "
      f"{'p<0.001' if p_val_spec < 0.001 else f'p={p_val_spec:.3f}':<12} {d_spec:>+7.2f}")

