def install(package):
    """Install package if not already installed"""
    try:
        __import__(package.split('[')[0])
    except ImportError:
        print(f"📦 Installing {package}...")
        subprocess.check_call([sys.executable, "-m", "pip", "install",
                             package, "-q", "--break-system-packages"])

