# 4. ENHANCED FEATURE EXTRACTION
# ============================================================================

def extract_enhanced_features(signal):
    """
    PERFORMANCE BOOST: Extract MORE discriminative features
    """
    features = []

    # Basic statistics (10)
    features.extend([
        np.mean(signal), np.std(signal), np.median(signal),
        np.min(signal), np.max(signal), np.ptp(signal),
        skew(signal), kurtosis(signal),
        np.percentile(signal, 25), np.percentile(signal, 75)
    ])

    # Advanced statistics (5) - NEW!
    features.extend([
        np.var(signal),
        stats.iqr(signal),
        np.mean(np.abs(signal)),
        stats.sem(signal) if len(signal) > 1 else 0,
        entropy(np.histogram(signal, bins=10)[0] + 1e-10)  # Signal entropy
    ])

    # Wavelet decomposition (12) - ENHANCED!
    try:
        coeffs = pywt.wavedec(signal, 'db4', level=3)  # Level 3 instead of 2
        for c in coeffs:
            features.extend([np.mean(c), np.std(c), np.max(np.abs(c))])
    except:
        features.extend([0] * 12)

    # Frequency domain (6) - ENHANCED!
    try:
        freqs, psd = welch(signal, fs=100, nperseg=min(256, len(signal)))
        features.extend([
            np.sum(psd),
            np.max(psd),
            freqs[np.argmax(psd)],
            np.median(psd),
            np.sum(psd[freqs < 10]),  # Low frequency power
            np.sum(psd[freqs > 10])   # High frequency power
        ])
    except:
        features.extend([0] * 6)

    # Temporal features (4) - ENHANCED!
    diff1 = np.diff(signal)
    diff2 = np.diff(diff1)
    features.extend([
        np.mean(np.abs(diff1)),
        np.std(diff1),
        np.mean(np.abs(diff2)) if len(diff2) > 0 else 0,
        np.sum(np.abs(diff1))  # Total variation
    ])

    # Zero-crossing rate (1) - NEW!
    zero_crossings = np.sum(np.diff(np.sign(signal)) != 0)
    features.append(zero_crossings / len(signal))

    # Peak detection (2) - NEW!
    from scipy.signal import find_peaks
    peaks, _ = find_peaks(signal)
    features.extend([
        len(peaks) / len(signal),  # Peak density
        np.std(signal[peaks]) if len(peaks) > 0 else 0  # Peak variability
    ])

    return np.array(features)

