# 6. ULTIMATE CROSS-VALIDATION
# ============================================================================

print(f"\n{'=' * 80}")
print("🚀 ULTIMATE 10-FOLD CV (ZERO LEAKAGE + MAX PERFORMANCE)")
print(f"{'=' * 80}")
print(f"✓ Rocket kernels: {ROCKET_KERNELS}")
print("✓ Stacking ensemble with meta-learner")
print("✓ Enhanced feature engineering")
print("✓ All fitting on training ONLY")
print(f"{'=' * 80}")

cv = StratifiedGroupKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)

metrics = {
    'bal_acc': [], 'acc': [], 'spec': [], 'sens': [],
    'f1': [], 'auc': [], 'precision': []
}

fold_results = []
all_y_true, all_y_pred, all_y_prob = [], [], []

# PERFORMANCE BOOST: Optimized hyperparameters
xgb_params = {
    'n_estimators': 700, 'learning_rate': 0.02, 'max_depth': 8,
    'min_child_weight': 2, 'subsample': 0.85, 'colsample_bytree': 0.85,
    'gamma': 1.0, 'reg_alpha': 0.3, 'reg_lambda': 0.8,
    'scale_pos_weight': 1.0/class_ratio, 'verbosity': 0, 'n_jobs': 2,
    'tree_method': 'hist'
}

lgbm_params = {
    'n_estimators': 700, 'learning_rate': 0.02, 'max_depth': 8,
    'num_leaves': 60, 'min_child_samples': 15, 'subsample': 0.85,
    'colsample_bytree': 0.85, 'reg_alpha': 1.5, 'reg_lambda': 1.5,
    'scale_pos_weight': 1.0/class_ratio, 'verbosity': -1, 'n_jobs': 2
}

cat_params = {
    'iterations': 800, 'learning_rate': 0.02, 'depth': 8,
    'l2_leaf_reg': 3, 'random_strength': 1.5, 'bagging_temperature': 0.3,
    'auto_class_weights': 'Balanced', 'verbose': 0,
    'allow_writing_files': False, 'thread_count': 2
}

for fold, (train_idx, test_idx) in enumerate(cv.split(X_sig_arr, y, groups=groups), 1):
    print(f"\n{'─' * 80}")
    print(f"📌 FOLD {fold}/10")
    print(f"{'─' * 80}")

    X_sig_tr, X_sig_te = X_sig_arr[train_idx], X_sig_arr[test_idx]
    X_hc_tr, X_hc_te = X_handcrafted_arr[train_idx], X_handcrafted_arr[test_idx]
    df_c_tr, df_c_te = df_clinical.iloc[train_idx], df_clinical.iloc[test_idx]
    y_tr, y_te = y[train_idx], y[test_idx]
    g_tr, g_te = groups[train_idx], groups[test_idx]
    task_te = task_arr[test_idx]

    # Rocket with MORE kernels
    print(f"  🚀 Rocket: {ROCKET_KERNELS} kernels on training...")
    rocket = MiniRocketMultivariate(num_kernels=ROCKET_KERNELS, random_state=RANDOM_STATE)
    X_r_tr = rocket.fit_transform(X_sig_tr)
    X_r_te = rocket.transform(X_sig_te)

    # PCA if needed
    if X_r_tr.shape[1] > 5000:
        print("  🔧 PCA: fit on training...")
        pca = PCA(n_components=0.95, random_state=RANDOM_STATE)
        X_r_tr_dense = X_r_tr.values if hasattr(X_r_tr, 'values') else X_r_tr
        X_r_te_dense = X_r_te.values if hasattr(X_r_te, 'values') else X_r_te

        X_r_tr = pca.fit_transform(X_r_tr_dense)
        X_r_te = pca.transform(X_r_te_dense)
    else:
        X_r_tr = X_r_tr.values if hasattr(X_r_tr, 'values') else X_r_tr
        X_r_te = X_r_te.values if hasattr(X_r_te, 'values') else X_r_te

    # Clinical preprocessing
    clin_preprocessor = ColumnTransformer(
        transformers=[
            ('num', RobustScaler(),
             ['age', 'nms_sum', 'nms_mean', 'nms_std', 'nms_nonzero',
              'nms_motor', 'nms_sleep', 'nms_mood', 'nms_auto'] +
             [f'nms_{i}' for i in range(30)]),
            ('cat', OrdinalEncoder(handle_unknown='use_encoded_value', unknown_value=-1),
             ['gender', 'task'])
        ]
    )

    X_c_tr = clin_preprocessor.fit_transform(df_c_tr)
    X_c_te = clin_preprocessor.transform(df_c_te)

    # Handcrafted scaling
    hc_scaler = RobustScaler()
    X_hc_tr_scaled = hc_scaler.fit_transform(X_hc_tr)
    X_hc_te_scaled = hc_scaler.transform(X_hc_te)

    # PERFORMANCE BOOST: Feature selection on training
    print("  🎯 Feature selection on training...")
    selector = SelectKBest(f_classif, k=min(1000, X_hc_tr_scaled.shape[1]))
    X_hc_tr_selected = selector.fit_transform(X_hc_tr_scaled, y_tr)
    X_hc_te_selected = selector.transform(X_hc_te_scaled)

    # Combine
    X_combined_tr = np.hstack([X_r_tr, X_hc_tr_selected]).astype(np.float32)
    X_combined_te = np.hstack([X_r_te, X_hc_te_selected]).astype(np.float32)

    # Train base models
    print("  🎯 Training base models...")

    ridge_model = CalibratedClassifierCV(
        RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced'),
        method='sigmoid', cv=3
    )
    ridge_model.fit(X_combined_tr, y_tr)

    xgb_model = XGBClassifier(**xgb_params, random_state=RANDOM_STATE)
    lgbm_model = LGBMClassifier(**lgbm_params, random_state=RANDOM_STATE)
    cat_model = CatBoostClassifier(**cat_params, random_state=RANDOM_STATE)

    xgb_model.fit(X_combined_tr, y_tr)
    lgbm_model.fit(X_combined_tr, y_tr)
    cat_model.fit(X_combined_tr, y_tr)

    mlp_model = MLPClassifier(
        hidden_layer_sizes=(256, 128, 64), alpha=0.005,
        learning_rate_init=0.0005, max_iter=600,
        early_stopping=True, validation_fraction=0.15,
        n_iter_no_change=20, random_state=RANDOM_STATE
    )
    mlp_model.fit(X_c_tr, y_tr)

    rf_model = RandomForestClassifier(
        n_estimators=400, max_depth=15, min_samples_split=4,
        class_weight='balanced', random_state=RANDOM_STATE,
        n_jobs=2, max_samples=0.85
    )
    rf_model.fit(X_combined_tr, y_tr)

    # PERFORMANCE BOOST: Stacking meta-learner
    print("  🔥 Training stacking meta-learner on training...")

    # Get base model predictions on TRAINING (with cross-validation to avoid overfitting)
    from sklearn.model_selection import cross_val_predict

    ridge_train_proba = cross_val_predict(ridge_model, X_combined_tr, y_tr, cv=3, method='predict_proba')[:, 1]
    xgb_train_proba = cross_val_predict(xgb_model, X_combined_tr, y_tr, cv=3, method='predict_proba')[:, 1]
    lgbm_train_proba = cross_val_predict(lgbm_model, X_combined_tr, y_tr, cv=3, method='predict_proba')[:, 1]
    cat_train_proba = cross_val_predict(cat_model, X_combined_tr, y_tr, cv=3, method='predict_proba')[:, 1]
    mlp_train_proba = cross_val_predict(mlp_model, X_c_tr, y_tr, cv=3, method='predict_proba')[:, 1]
    rf_train_proba = cross_val_predict(rf_model, X_combined_tr, y_tr, cv=3, method='predict_proba')[:, 1]

    # Stack predictions
    meta_features_train = np.column_stack([
        ridge_train_proba, xgb_train_proba, lgbm_train_proba,
        cat_train_proba, mlp_train_proba, rf_train_proba
    ])

    # Train meta-learner
    meta_learner = LogisticRegression(
        C=0.1, class_weight='balanced', random_state=RANDOM_STATE, max_iter=1000
    )
    meta_learner.fit(meta_features_train, y_tr)

    # Get predictions on TEST
    ridge_test_proba = ridge_model.predict_proba(X_combined_te)[:, 1]
    xgb_test_proba = xgb_model.predict_proba(X_combined_te)[:, 1]
    lgbm_test_proba = lgbm_model.predict_proba(X_combined_te)[:, 1]
    cat_test_proba = cat_model.predict_proba(X_combined_te)[:, 1]
    mlp_test_proba = mlp_model.predict_proba(X_c_te)[:, 1]
    rf_test_proba = rf_model.predict_proba(X_combined_te)[:, 1]

    meta_features_test = np.column_stack([
        ridge_test_proba, xgb_test_proba, lgbm_test_proba,
        cat_test_proba, mlp_test_proba, rf_test_proba
    ])

    # Stacked ensemble predictions
    ensemble_probs_test = meta_learner.predict_proba(meta_features_test)[:, 1]

    # Calculate threshold on TRAINING
    print("  🔧 Threshold: calculated on training...")

    # Refit models on full training for threshold calculation
    ridge_model_full = CalibratedClassifierCV(
        RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced'),
        method='sigmoid', cv=3
    )
    ridge_model_full.fit(X_combined_tr, y_tr)

    ridge_full_proba = ridge_model_full.predict_proba(X_combined_tr)[:, 1]
    xgb_full_proba = xgb_model.predict_proba(X_combined_tr)[:, 1]
    lgbm_full_proba = lgbm_model.predict_proba(X_combined_tr)[:, 1]
    cat_full_proba = cat_model.predict_proba(X_combined_tr)[:, 1]
    mlp_full_proba = mlp_model.predict_proba(X_c_tr)[:, 1]
    rf_full_proba = rf_model.predict_proba(X_combined_tr)[:, 1]

    meta_features_train_full = np.column_stack([
        ridge_full_proba, xgb_full_proba, lgbm_full_proba,
        cat_full_proba, mlp_full_proba, rf_full_proba
    ])

    ensemble_probs_train = meta_learner.predict_proba(meta_features_train_full)[:, 1]

    # Patient-level for TRAINING
    df_res_train = pd.DataFrame({'pid': g_tr, 'true': y_tr, 'prob': ensemble_probs_train})

    patient_scores_train = []
    patient_labels_train = []

    for pid in df_res_train['pid'].unique():
        patient_data = df_res_train[df_res_train['pid'] == pid]
        probs = patient_data['prob'].values

        # PERFORMANCE BOOST: Confidence-weighted aggregation
        confidence = np.abs(probs - 0.5)
        if confidence.sum() > 0:
            weights = confidence / confidence.sum()
            final_prob = (probs * weights).sum()
        else:
            final_prob = probs.mean()

        patient_scores_train.append(final_prob)
        patient_labels_train.append(patient_data['true'].iloc[0])

    y_true_pat_train = np.array(patient_labels_train, dtype=int)
    y_prob_pat_train = np.array(patient_scores_train)

    # Threshold on TRAINING
    fpr_train, tpr_train, thresholds_train = roc_curve(y_true_pat_train, y_prob_pat_train)
    j_scores_train = tpr_train - fpr_train
    best_th = thresholds_train[np.argmax(j_scores_train)]

    # Patient-level for TEST
    df_res_test = pd.DataFrame({
        'pid': g_te, 'true': y_te, 'prob': ensemble_probs_test, 'task': task_te
    })

    patient_scores_test = []
    patient_labels_test = []

    for pid in df_res_test['pid'].unique():
        patient_data = df_res_test[df_res_test['pid'] == pid]
        probs = patient_data['prob'].values
        confidence = np.abs(probs - 0.5)

        if confidence.sum() > 0:
            weights = confidence / confidence.sum()
            final_prob = (probs * weights).sum()
        else:
            final_prob = probs.mean()

        patient_scores_test.append(final_prob)
        patient_labels_test.append(patient_data['true'].iloc[0])

    y_true_pat = np.array(patient_labels_test, dtype=int)
    y_prob_pat = np.array(patient_scores_test)

    # Apply threshold from TRAINING
    y_pred_pat = (y_prob_pat >= best_th).astype(int)

    # Metrics
    bal_acc = balanced_accuracy_score(y_true_pat, y_pred_pat)
    acc = accuracy_score(y_true_pat, y_pred_pat)
    spec = recall_score(y_true_pat, y_pred_pat, pos_label=0)
    sens = recall_score(y_true_pat, y_pred_pat, pos_label=1)
    f1 = f1_score(y_true_pat, y_pred_pat)
    auc = roc_auc_score(y_true_pat, y_prob_pat)
    prec = precision_score(y_true_pat, y_pred_pat)

    metrics['bal_acc'].append(bal_acc)
    metrics['acc'].append(acc)
    metrics['spec'].append(spec)
    metrics['sens'].append(sens)
    metrics['f1'].append(f1)
    metrics['auc'].append(auc)
    metrics['precision'].append(prec)

    fold_results.append({
        'fold': fold, 'bal_acc': bal_acc, 'sens': sens,
        'spec': spec, 'f1': f1, 'auc': auc, 'threshold': best_th
    })

    all_y_true.extend(y_true_pat)
    all_y_pred.extend(y_pred_pat)
    all_y_prob.extend(y_prob_pat)

    print(f"  🎯 BalAcc={bal_acc*100:.2f}% | Sens={sens*100:.2f}% | "
          f"Spec={spec*100:.2f}% | F1={f1*100:.2f}%")

    gc.collect()

# ============================================================================
# 7. STATISTICAL TESTS & FIGURES
# ============================================================================

print(f"\n{'=' * 80}")
print("📊 STATISTICAL ANALYSIS")
print(f"{'=' * 80}")

our_bal_acc = np.array(metrics['bal_acc']) * 100
our_sens = np.array(metrics['sens']) * 100
our_spec = np.array(metrics['spec']) * 100
our_f1 = np.array(metrics['f1']) * 100

paper_bal_acc, paper_sens, paper_spec, paper_f1 = 91.16, 92.40, 92.00, 94.62

t_stat_bal, p_val_bal = stats.ttest_1samp(our_bal_acc, paper_bal_acc)

def cohens_d(x, mu):
    return (np.mean(x) - mu) / np.std(x)

d_bal = cohens_d(our_bal_acc, paper_bal_acc)

def ci_95(data):
    mean = np.mean(data)
    se = stats.sem(data)
    return stats.t.interval(0.95, len(data)-1, loc=mean, scale=se)

ci_bal = ci_95(our_bal_acc)

print(f"\nBalanced Accuracy: {np.mean(our_bal_acc):.2f}% ± {np.std(our_bal_acc):.2f}%")
print(f"  vs Paper: {paper_bal_acc:.2f}% ({np.mean(our_bal_acc)-paper_bal_acc:+.2f}%)")
print(f"  p-value: {'<0.001' if p_val_bal < 0.001 else f'{p_val_bal:.3f}'}")
print(f"  Cohen's d: {d_bal:.2f}")
print(f"  95% CI: [{ci_bal[0]:.2f}%, {ci_bal[1]:.2f}%]")

# Generate all 8 figures (same as before but with new results)
print(f"\n{'=' * 80}")
print("🎨 GENERATING FIGURES...")
print(f"{'=' * 80}")

# [Figures 1-8 generation code - exact same as previous version]
