import os, sys, subprocess, warnings, gc, zipfile as zf
from glob import glob
from tqdm import tqdm
import numpy as np
import pandas as pd
import json

warnings.filterwarnings('ignore')
os.environ['TF_CPP_MIN_LOG_LEVEL'] = '3'

def install(pkg):
    try: __import__(pkg.split('[')[0])
    except: subprocess.check_call([sys.executable, "-m", "pip", "install", pkg, "-q", "--break-system-packages"])

for pkg in ["numpy", "pandas", "scipy", "scikit-learn", "sktime", "catboost", "xgboost", "lightgbm", "pywavelets"]:
    install(pkg)

from scipy.signal import detrend, resample, welch
from scipy.stats import skew, kurtosis
from scipy import stats
import pywt
from sklearn.model_selection import StratifiedGroupKFold
from sklearn.preprocessing import RobustScaler, OrdinalEncoder
from sklearn.metrics import *
from sklearn.compose import ColumnTransformer
from sktime.transformations.panel.rocket import MiniRocketMultivariate
from catboost import CatBoostClassifier
from xgboost import XGBClassifier
from lightgbm import LGBMClassifier

# Config
ROCKET_KERNELS = 15000  # Balance: speed vs performance
RANDOM_STATE = 42
OUTPUT_DIR = './pads_gpu_fast_results'
os.makedirs(OUTPUT_DIR, exist_ok=True)
np.random.seed(RANDOM_STATE)

print("=" * 80)
print("🚀 PADS GPU-ACCELERATED (ZERO LEAKAGE)")
print("=" * 80)
print(f"Rocket Kernels: {ROCKET_KERNELS}")
print("GPU: XGBoost + CatBoost + LightGBM")
print("Data Leakage: NONE (Rocket fit per fold)")
print("=" * 80)

# --- I/O OPTIMIZATION ---
print("\n📦 Data optimization...")
DRIVE_ZIP = "/content/drive/MyDrive/pads-parkinsons-disease-smartwatch-dataset-1.0.0.zip"
LOCAL_DATA = "/content/pads_extracted"

if os.path.exists(DRIVE_ZIP) and not os.path.exists(LOCAL_DATA):
    print("  Extracting to local NVMe...")
    with zf.ZipFile(DRIVE_ZIP, 'r') as z:
        z.extractall(LOCAL_DATA)
    print("  ✅ Data on fast storage")

data_path = LOCAL_DATA if os.path.exists(LOCAL_DATA) else "./pads_data_extracted"

# --- FEATURE EXTRACTION ---
def extract_features(sig):
    f = []
    f.extend([np.mean(sig), np.std(sig), np.median(sig), np.min(sig), np.max(sig),
              np.ptp(sig), skew(sig), kurtosis(sig),
              np.percentile(sig, 25), np.percentile(sig, 75)])
    try:
        c = pywt.wavedec(sig, 'db4', level=2)
        for cc in c: f.extend([np.mean(cc), np.std(cc), np.max(np.abs(cc))])
    except: f.extend([0]*9)
    try:
        fr, ps = welch(sig, fs=100, nperseg=min(128, len(sig)))
        f.extend([np.sum(ps), np.max(ps), np.argmax(ps)])
    except: f.extend([0]*3)
    d1 = np.diff(sig)
    f.extend([np.mean(np.abs(d1)), np.std(d1)])
    return np.array(f)

# --- LOAD DATA ---
print("\n📊 Loading data...")

# Patient info
patient_info = {}
meta_files = glob(f"{data_path}/**/subjects.csv", recursive=True)
if meta_files:
    df = pd.read_csv(meta_files[0])
    for _, r in df[df['label'].isin([0,1])].iterrows():
        patient_info[str(r['id']).zfill(3)] = {
            'label': int(r['label']),
            'age': r['age'],
            'gender': str(r['gender'])
        }

# NMS data
nms_data = {}
for qf in glob(f"{data_path}/**/questionnaire_response_*.json", recursive=True):
    try:
        q = json.load(open(qf))
        pid = str(q.get('subject_id', ''))
        if pid not in patient_info: continue
        ans = [0]*30
        for it in q.get('item', []):
            try:
                i = int(it.get('link_id', '99')) - 1
                if 0 <= i < 30: ans[i] = 1 if it.get('answer') else 0
            except: pass
        nms_data[pid] = ans
    except: pass

# Signals
s_files = [f for f in glob(f"{data_path}/**/*.txt", recursive=True) if "LICENSE" not in f]
X_sig, X_hc, X_clin = [], [], []
y_list, grp_list, task_list = [], [], []

print(f"  Processing {len(s_files)} files...")
for fp in tqdm(s_files, desc="Loading"):
    try:
        parts = os.path.basename(fp).replace('.txt','').split('_')
        pid = parts[0]
        task = parts[1] if len(parts) > 1 else "Unknown"

        if pid not in patient_info: continue

        raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
        if len(raw) < 100: continue

        if len(raw) > 50: raw = raw[50:, :]
        raw = detrend(raw, axis=0)
        if raw.shape[0] > raw.shape[1]: raw = raw.T
        raw = resample(raw, 400, axis=1)

        X_sig.append(raw)

        # Handcrafted features
        hc = [f for ch in range(raw.shape[0]) for f in extract_features(raw[ch])]
        X_hc.append(hc)

        # Clinical
        p = patient_info[pid]
        nms = nms_data.get(pid, [0]*30)
        X_clin.append([float(p['age']), str(p['gender']), str(task),
                       sum(nms), np.mean(nms), np.std(nms), np.count_nonzero(nms),
                       sum(nms[0:10]), sum(nms[10:15]), sum(nms[15:20]), sum(nms[20:30])] + nms)

        y_list.append(p['label'])
        grp_list.append(pid)
        task_list.append(task)
    except: continue

# Convert
max_ch = max(x.shape[0] for x in X_sig)
X_sig_arr = np.zeros((len(X_sig), max_ch, 400), dtype=np.float32)
for i, x in enumerate(X_sig): X_sig_arr[i, :x.shape[0], :] = x

X_hc_arr = np.array(X_hc, dtype=np.float32)
df_clin = pd.DataFrame(X_clin, columns=['age','gender','task','nms_sum','nms_mean','nms_std','nms_nonzero',
                                         'nms_motor','nms_sleep','nms_mood','nms_auto']+[f'nms_{i}' for i in range(30)])
y = np.array(y_list)
groups = np.array(grp_list)
tasks = np.array(task_list)

n_pd, n_hc = np.sum(y==1), np.sum(y==0)
class_ratio = n_pd / (n_hc + 1e-10)

print(f"\n✅ Loaded: {len(y)} samples")
print(f"   PD: {n_pd}, HC: {n_hc}")
print(f"   Patients: {len(np.unique(groups))}")

del X_sig
gc.collect()

# --- GPU-ACCELERATED CV ---
print(f"\n{'='*80}")
print("🔬 10-FOLD CV (GPU + Zero Leakage)")
print(f"{'='*80}")

cv = StratifiedGroupKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)
metrics = {'bal_acc':[], 'sens':[], 'spec':[], 'f1':[], 'auc':[]}
all_true, all_pred, all_prob = [], [], []

# GPU params
xgb_params = {
    'tree_method': 'gpu_hist',  # GPU!
    'predictor': 'gpu_predictor',  # GPU!
    'n_estimators': 800,
    'learning_rate': 0.02,
    'max_depth': 9,
    'min_child_weight': 2,
    'subsample': 0.9,
    'colsample_bytree': 0.9,
    'gamma': 0.8,
    'reg_alpha': 0.2,
    'reg_lambda': 0.6,
    'scale_pos_weight': 1.0/class_ratio,
    'random_state': RANDOM_STATE
}

cat_params = {
    'task_type': 'GPU',  # GPU!
    'devices': '0',
    'iterations': 800,
    'learning_rate': 0.02,
    'depth': 9,
    'l2_leaf_reg': 2.5,
    'auto_class_weights': 'Balanced',
    'verbose': 0,
    'random_state': RANDOM_STATE
}

lgbm_params = {
    'device': 'gpu',  # GPU!
    'gpu_platform_id': 0,
    'gpu_device_id': 0,
    'n_estimators': 800,
    'learning_rate': 0.02,
    'max_depth': 9,
    'num_leaves': 80,
    'subsample': 0.9,
    'colsample_bytree': 0.9,
    'reg_alpha': 1.2,
    'reg_lambda': 1.2,
    'scale_pos_weight': 1.0/class_ratio,
    'verbosity': -1,
    'random_state': RANDOM_STATE
}

for fold, (tr_i, te_i) in enumerate(cv.split(X_sig_arr, y, groups), 1):
    print(f"\n{'─'*80}")
    print(f"📌 FOLD {fold}/10")
    print(f"{'─'*80}")

    X_sig_tr, X_sig_te = X_sig_arr[tr_i], X_sig_arr[te_i]
    X_hc_tr, X_hc_te = X_hc_arr[tr_i], X_hc_arr[te_i]
    df_c_tr, df_c_te = df_clin.iloc[tr_i], df_clin.iloc[te_i]
    y_tr, y_te = y[tr_i], y[te_i]
    g_tr, g_te = groups[tr_i], groups[te_i]

    # CRITICAL: Rocket fit on TRAINING only!
    print(f"  🚀 Rocket fit on training (n_jobs=-1)...")
    rocket = MiniRocketMultivariate(num_kernels=ROCKET_KERNELS,
                                     random_state=RANDOM_STATE,
                                     n_jobs=-1)  # Use all CPUs
    X_r_tr = rocket.fit_transform(X_sig_tr)
    X_r_te = rocket.transform(X_sig_te)

    X_r_tr = X_r_tr.values if hasattr(X_r_tr, 'values') else X_r_tr
    X_r_te = X_r_te.values if hasattr(X_r_te, 'values') else X_r_te

    # No PCA - keep all features
    print(f"  ✓ Rocket features: {X_r_tr.shape[1]}")

    # Clinical
    clin_prep = ColumnTransformer([
        ('num', RobustScaler(), ['age','nms_sum','nms_mean','nms_std','nms_nonzero',
                                 'nms_motor','nms_sleep','nms_mood','nms_auto']+[f'nms_{i}' for i in range(30)]),
        ('cat', OrdinalEncoder(handle_unknown='use_encoded_value', unknown_value=-1), ['gender','task'])
    ])
    X_c_tr = clin_prep.fit_transform(df_c_tr)
    X_c_te = clin_prep.transform(df_c_te)

    # Handcrafted
    hc_sc = RobustScaler()
    X_hc_tr_sc = hc_sc.fit_transform(X_hc_tr)
    X_hc_te_sc = hc_sc.transform(X_hc_te)

    # Combine
    X_comb_tr = np.hstack([X_r_tr, X_hc_tr_sc]).astype(np.float32)
    X_comb_te = np.hstack([X_r_te, X_hc_te_sc]).astype(np.float32)

    print(f"  🎯 Training GPU models...")

    # GPU models
    xgb = XGBClassifier(**xgb_params)
    cat = CatBoostClassifier(**cat_params, allow_writing_files=False)
    lgbm = LGBMClassifier(**lgbm_params)

    xgb.fit(X_comb_tr, y_tr)
    cat.fit(X_comb_tr, y_tr)
    lgbm.fit(X_comb_tr, y_tr)

    # Get TRAINING probs for threshold
    p_xgb_tr = xgb.predict_proba(X_comb_tr)[:,1]
    p_cat_tr = cat.predict_proba(X_comb_tr)[:,1]
    p_lgbm_tr = lgbm.predict_proba(X_comb_tr)[:,1]

    ens_tr = (p_xgb_tr + p_cat_tr + p_lgbm_tr) / 3.0

    # Patient-level TRAINING
    df_tr = pd.DataFrame({'pid': g_tr, 'true': y_tr, 'prob': ens_tr})
    pat_tr_prob, pat_tr_lab = [], []
    for pid in df_tr['pid'].unique():
        pd_data = df_tr[df_tr['pid']==pid]
        pat_tr_prob.append(np.median(pd_data['prob'].values))
        pat_tr_lab.append(pd_data['true'].iloc[0])

    # Threshold
    fpr, tpr, ths = roc_curve(pat_tr_lab, pat_tr_prob)
    best_th = ths[np.argmax(tpr - fpr)]

    # TEST probs
    p_xgb_te = xgb.predict_proba(X_comb_te)[:,1]
    p_cat_te = cat.predict_proba(X_comb_te)[:,1]
    p_lgbm_te = lgbm.predict_proba(X_comb_te)[:,1]

    ens_te = (p_xgb_te + p_cat_te + p_lgbm_te) / 3.0

    # Patient-level TEST
    df_te = pd.DataFrame({'pid': g_te, 'true': y_te, 'prob': ens_te})
    pat_te_prob, pat_te_lab = [], []
    for pid in df_te['pid'].unique():
        pd_data = df_te[df_te['pid']==pid]
        pat_te_prob.append(np.median(pd_data['prob'].values))
        pat_te_lab.append(pd_data['true'].iloc[0])

    y_true = np.array(pat_te_lab)
    y_prob = np.array(pat_te_prob)
    y_pred = (y_prob >= best_th).astype(int)

    # Metrics
    ba = balanced_accuracy_score(y_true, y_pred)
    se = recall_score(y_true, y_pred, pos_label=1)
    sp = recall_score(y_true, y_pred, pos_label=0)
    f1 = f1_score(y_true, y_pred)
    au = roc_auc_score(y_true, y_prob)

    metrics['bal_acc'].append(ba)
    metrics['sens'].append(se)
    metrics['spec'].append(sp)
    metrics['f1'].append(f1)
    metrics['auc'].append(au)

    all_true.extend(y_true)
    all_pred.extend(y_pred)
    all_prob.extend(y_prob)

    print(f"  ✓ BalAcc={ba*100:.2f}% | Sens={se*100:.2f}% | Spec={sp*100:.2f}%")

    gc.collect()

# Results
print(f"\n{'='*80}")
print("🏆 FINAL RESULTS (GPU-ACCELERATED, ZERO LEAKAGE)")
print(f"{'='*80}")

for k, v in metrics.items():
    print(f"{k.upper():12s}: {np.mean(v)*100:6.2f}% ± {np.std(v)*100:5.2f}%")

our_ba = np.mean(metrics['bal_acc'])*100
paper_ba = 91.16

print(f"\n📊 Comparison:")
print(f"  Our method: {our_ba:.2f}%")
print(f"  Paper:      {paper_ba:.2f}%")
print(f"  Difference: {our_ba-paper_ba:+.2f}%")

# Statistical test
t_stat, p_val = stats.ttest_1samp([b*100 for b in metrics['bal_acc']], paper_ba)
print(f"  p-value:    {'<0.001' if p_val < 0.001 else f'{p_val:.3f}'}")

# Save
with open(f"{OUTPUT_DIR}/results.txt", 'w') as f:
    f.write(f"Balanced Accuracy: {our_ba:.2f}%\n")
    f.write(f"vs Paper: {paper_ba:.2f}%\n")
    f.write(f"Difference: {our_ba-paper_ba:+.2f}%\n")
    f.write(f"p-value: {'<0.001' if p_val < 0.001 else f'{p_val:.3f}'}\n")

print(f"\n✅ Results saved to {OUTPUT_DIR}/")
print("="*80)

