os.environ['TF_CPP_MIN_LOG_LEVEL'] = '3'

def install(pkg):
    try: __import__(pkg.split('[')[0])
    except: subprocess.check_call([sys.executable, "-m", "pip", "install", pkg, "-q", "--break-system-packages"])

for pkg in ["numpy","pandas","scipy","scikit-learn","sktime","catboost","xgboost","lightgbm","pywavelets","tqdm"]:
    install(pkg)

