# ── FEATURE EXTRACTION ────────────────────────────────────────────────────────
def extract_features(sig):
    f = []
    f.extend([np.mean(sig), np.std(sig), np.median(sig),
              np.min(sig), np.max(sig), np.ptp(sig),
              skew(sig), kurtosis(sig),
              np.percentile(sig, 25), np.percentile(sig, 75)])
    try:
        c = pywt.wavedec(sig, 'db4', level=2)
        for cc in c: f.extend([np.mean(cc), np.std(cc), np.max(np.abs(cc))])
    except: f.extend([0]*9)
    try:
        fr, ps = welch(sig, fs=100, nperseg=min(128, len(sig)))
        f.extend([np.sum(ps), np.max(ps), float(np.argmax(ps))])
    except: f.extend([0]*3)
    d1 = np.diff(sig)
    f.extend([np.mean(np.abs(d1)), np.std(d1)])
    return np.array(f, dtype=np.float32)

# ── LOAD DATA ─────────────────────────────────────────────────────────────────
print("\n📊 Veri yükleniyor...")

# subjects.csv ara, yoksa patient_*.json
patient_info = {}
csv_candidates = [
    f"{data_path}/subjects.csv",
    *glob(f"{EXTRACT_ROOT}/**/subjects.csv", recursive=True),
    "/content/drive/MyDrive/subjects.csv",
    "/content/drive/MyDrive/Parkinson/subjects.csv",
]
csv_found = next((c for c in csv_candidates if os.path.exists(c)), None)

if csv_found:
    df_meta = pd.read_csv(csv_found)
    df_meta.columns = [c.strip().lower() for c in df_meta.columns]
    id_col  = next((c for c in df_meta.columns if c == 'id'), None)
    lbl_col = next((c for c in df_meta.columns if 'label' in c), None)
    age_col = next((c for c in df_meta.columns if 'age'   in c), None)
    sex_col = next((c for c in df_meta.columns if 'sex'   in c or 'gender' in c), None)
    if id_col and lbl_col:
        for _, r in df_meta[df_meta[lbl_col].isin([0,1])].iterrows():
            try:
                patient_info[str(r[id_col]).zfill(3)] = {
                    'label' : int(r[lbl_col]),
                    'age'   : float(r[age_col]) if age_col else 60.0,
                    'gender': str(r[sex_col])   if sex_col else 'unknown'
                }
            except: continue
        print(f"✅ subjects.csv: {csv_found} | {len(patient_info)} hasta")

if not patient_info:
    print("⚠️  subjects.csv yok, patient_*.json deneniyor...")
    for pf in glob(f"{data_path}/**/patient_*.json", recursive=True):
        try:
            d = json.load(open(pf))
            c = d.get('condition', '').lower()
            if   "parkinson" in c: lbl = 1
            elif "healthy"   in c or "control" in c: lbl = 0
            else: continue
            pid = str(d['id']).zfill(3)
            patient_info[pid] = {
                'label' : lbl,
                'age'   : float(d.get('age', 60)),
                'gender': str(d.get('gender', 'unknown'))
            }
        except: pass
    print(f"✅ patient_*.json: {len(patient_info)} hasta")

if not patient_info:
    raise FileNotFoundError("Hasta verisi bulunamadı!")

# NMS
nms_data = {}
for qf in glob(f"{data_path}/**/questionnaire_response_*.json", recursive=True):
    try:
        q   = json.load(open(qf))
        pid = str(q.get('subject_id', '')).zfill(3)
        if pid not in patient_info: continue
        ans = [0]*30
        for it in q.get('item', []):
            try:
                i = int(it.get('link_id','99')) - 1
                if 0 <= i < 30: ans[i] = 1 if it.get('answer') else 0
            except: pass
        nms_data[pid] = ans
    except: pass
print(f"✅ NMS: {len(nms_data)} hasta")

# Sinyaller
X_sig, X_hc, X_clin = [], [], []
y_list, grp_list, task_list = [], [], []

for fp in tqdm(all_txt, desc="Sinyal yükleniyor"):
    try:
        base  = os.path.basename(fp).replace('.txt','')
        parts = base.split('_')
        pid   = parts[0].zfill(3)
        task  = parts[1] if len(parts) > 1 else "Unk"
        if pid not in patient_info: continue

        raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
        if raw.shape[0] < 100: continue
        raw = raw[CROP_START:, :]
        raw = detrend(raw, axis=0)
        if raw.shape[0] > raw.shape[1]: raw = raw.T
        raw = resample(raw, SEQ_LEN, axis=1).astype(np.float32)

        X_sig.append(raw)
        hc = [feat for ch in range(raw.shape[0]) for feat in extract_features(raw[ch])]
        X_hc.append(hc)

        p   = patient_info[pid]
        nms = nms_data.get(pid, [0]*30)
        X_clin.append([
            float(p['age']), str(p['gender']), str(task),
            sum(nms), float(np.mean(nms)), float(np.std(nms)),
            int(np.count_nonzero(nms)),
            sum(nms[0:10]), sum(nms[10:15]), sum(nms[15:20]), sum(nms[20:30])
        ] + nms)

        y_list.append(p['label'])
        grp_list.append(pid)
        task_list.append(task)
    except: continue

if len(X_sig) == 0:
    raise ValueError("Hiç sinyal yüklenemedi!")

max_ch    = max(x.shape[0] for x in X_sig)
X_sig_arr = np.zeros((len(X_sig), max_ch, SEQ_LEN), dtype=np.float32)
for i, x in enumerate(X_sig): X_sig_arr[i, :x.shape[0], :] = x

X_hc_arr  = np.array(X_hc, dtype=np.float32)
clin_cols = (['age','gender','task','nms_sum','nms_mean','nms_std','nms_nonzero',
               'nms_motor','nms_sleep','nms_mood','nms_auto'] +
              [f'nms_{i}' for i in range(30)])
df_clin   = pd.DataFrame(X_clin, columns=clin_cols)
y         = np.array(y_list)
groups    = np.array(grp_list)
tasks     = np.array(task_list)

n_pd, n_hc_cnt = int(np.sum(y==1)), int(np.sum(y==0))
class_ratio     = n_pd / (n_hc_cnt + 1e-10)

print(f"\n✅ Yüklendi     : {len(y)} örnek")
print(f"   PD           : {n_pd} | HC: {n_hc_cnt}")
print(f"   Hasta        : {len(np.unique(groups))}")
print(f"   Sinyal şekli : {X_sig_arr.shape}")

del X_sig
gc.collect()

# ── MODEL PARAMETRELERİ ───────────────────────────────────────────────────────
if gpu_available:
    xgb_params = dict(
        tree_method='hist', device='cuda',
        n_estimators=1000, learning_rate=0.01, max_depth=10,
        min_child_weight=1, subsample=0.9, colsample_bytree=0.9,
        gamma=0.5, reg_alpha=0.1, reg_lambda=0.5,
        scale_pos_weight=1.0/class_ratio,
        random_state=RANDOM_STATE, eval_metric='logloss', verbosity=0)
    cat_params = dict(
        task_type='GPU', devices='0',
        iterations=1000, learning_rate=0.01, depth=10,
        l2_leaf_reg=2, random_strength=1, bagging_temperature=0.2,
        auto_class_weights='Balanced',
        verbose=0, random_state=RANDOM_STATE)
    lgbm_params = dict(
        device='gpu', gpu_platform_id=0, gpu_device_id=0,
        n_estimators=1000, learning_rate=0.01, max_depth=10,
        num_leaves=100, min_child_samples=10,
        subsample=0.9, colsample_bytree=0.9,
        reg_alpha=1.0, reg_lambda=1.0,
        scale_pos_weight=1.0/class_ratio,
        verbosity=-1, random_state=RANDOM_STATE)
    print("\n🔥 GPU modunda!")
else:
    xgb_params = dict(
        tree_method='hist',
        n_estimators=1000, learning_rate=0.01, max_depth=10,
        min_child_weight=1, subsample=0.9, colsample_bytree=0.9,
        gamma=0.5, reg_alpha=0.1, reg_lambda=0.5,
        scale_pos_weight=1.0/class_ratio,
        random_state=RANDOM_STATE, eval_metric='logloss', verbosity=0)
    cat_params = dict(
        task_type='CPU',
        iterations=1000, learning_rate=0.01, depth=10,
        l2_leaf_reg=2, random_strength=1, bagging_temperature=0.2,
        auto_class_weights='Balanced',
        verbose=0, random_state=RANDOM_STATE)
    lgbm_params = dict(
        device='cpu',
        n_estimators=1000, learning_rate=0.01, max_depth=10,
        num_leaves=100, min_child_samples=10,
        subsample=0.9, colsample_bytree=0.9,
        reg_alpha=1.0, reg_lambda=1.0,
        scale_pos_weight=1.0/class_ratio,
        verbosity=-1, random_state=RANDOM_STATE)
    print("\n⚠️  CPU modunda")

# ── 10-FOLD CV ─────────────────────────────────────────────────────────────────
print(f"\n{'='*70}")
print("🔬 10-FOLD STRATIFIED GROUP CV (Zero Leakage)")
print(f"{'='*70}")

cv      = StratifiedGroupKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)
metrics = {'bal_acc':[], 'sens':[], 'spec':[], 'f1':[], 'auc':[]}
all_true, all_pred, all_prob = [], [], []

num_cols      = (['age','nms_sum','nms_mean','nms_std','nms_nonzero',
                   'nms_motor','nms_sleep','nms_mood','nms_auto'] +
                  [f'nms_{i}' for i in range(30)])
cat_cols_clin = ['gender','task']

for fold, (tr_i, te_i) in enumerate(cv.split(X_sig_arr, y, groups), 1):
    print(f"\n{'─'*70}")
    print(f"📌 FOLD {fold}/10  |  Train: {len(tr_i)}  Test: {len(te_i)}")

    X_sig_tr, X_sig_te = X_sig_arr[tr_i], X_sig_arr[te_i]
    X_hc_tr,  X_hc_te  = X_hc_arr[tr_i],  X_hc_arr[te_i]
    df_c_tr   = df_clin.iloc[tr_i].reset_index(drop=True)
    df_c_te   = df_clin.iloc[te_i].reset_index(drop=True)
    y_tr, y_te = y[tr_i], y[te_i]
    g_tr, g_te = groups[tr_i], groups[te_i]

    # MiniRocket — SADECE train'e fit
    print(f"  🚀 MiniRocket ({ROCKET_KERNELS} kernel, train only)...")
    rocket = MiniRocketMultivariate(num_kernels=ROCKET_KERNELS,
                                    random_state=RANDOM_STATE, n_jobs=-1)
    X_r_tr = rocket.fit_transform(X_sig_tr)
    X_r_te = rocket.transform(X_sig_te)
    X_r_tr = X_r_tr.values if hasattr(X_r_tr, 'values') else np.array(X_r_tr)
    X_r_te = X_r_te.values if hasattr(X_r_te, 'values') else np.array(X_r_te)
    print(f"  ✓ Rocket features: {X_r_tr.shape[1]}")

    # Klinik — SADECE train'e fit
    clin_prep = ColumnTransformer([
        ('num', RobustScaler(), num_cols),
        ('cat', OrdinalEncoder(handle_unknown='use_encoded_value',
                               unknown_value=-1), cat_cols_clin)
    ])
    X_c_tr = clin_prep.fit_transform(df_c_tr)
    X_c_te = clin_prep.transform(df_c_te)

    # El-yapımı — SADECE train'e fit
    hc_sc      = RobustScaler()
    X_hc_sc_tr = hc_sc.fit_transform(X_hc_tr)
    X_hc_sc_te = hc_sc.transform(X_hc_te)

    # Birleştir
    X_tr = np.hstack([X_r_tr, X_hc_sc_tr, X_c_tr]).astype(np.float32)
    X_te = np.hstack([X_r_te, X_hc_sc_te, X_c_te]).astype(np.float32)
    print(f"  ✓ Toplam feature: {X_tr.shape[1]}")

    # Modelleri eğit
    print(f"  🎯 Modeller eğitiliyor...")
    xgb_m  = XGBClassifier(**xgb_params)
    cat_m  = CatBoostClassifier(**cat_params, allow_writing_files=False)
    lgbm_m = LGBMClassifier(**lgbm_params)

    xgb_m.fit(X_tr, y_tr)
    cat_m.fit(X_tr, y_tr)
    lgbm_m.fit(X_tr, y_tr)

    # Optimal eşik — SADECE train'den
    p_tr = (xgb_m.predict_proba(X_tr)[:,1] +
            cat_m.predict_proba(X_tr)[:,1] +
            lgbm_m.predict_proba(X_tr)[:,1]) / 3.0

    df_tr_agg = pd.DataFrame({'pid': g_tr, 'true': y_tr, 'prob': p_tr})
    pat_tr_p, pat_tr_l = [], []
    for pid in df_tr_agg['pid'].unique():
        sub = df_tr_agg[df_tr_agg['pid']==pid]
        pat_tr_p.append(float(np.median(sub['prob'].values)))
        pat_tr_l.append(int(sub['true'].iloc[0]))

    fpr_tr, tpr_tr, ths_tr = roc_curve(pat_tr_l, pat_tr_p)
    best_th = float(ths_tr[np.argmax(tpr_tr - fpr_tr)])

    # Test tahminleri
    p_te = (xgb_m.predict_proba(X_te)[:,1] +
            cat_m.predict_proba(X_te)[:,1] +
            lgbm_m.predict_proba(X_te)[:,1]) / 3.0

    df_te_agg = pd.DataFrame({'pid': g_te, 'true': y_te, 'prob': p_te})
    pat_te_p, pat_te_l = [], []
    for pid in df_te_agg['pid'].unique():
        sub = df_te_agg[df_te_agg['pid']==pid]
        pat_te_p.append(float(np.median(sub['prob'].values)))
        pat_te_l.append(int(sub['true'].iloc[0]))

    y_true = np.array(pat_te_l)
    y_prob = np.array(pat_te_p)
    y_pred = (y_prob >= best_th).astype(int)

    ba = balanced_accuracy_score(y_true, y_pred)
    se = recall_score(y_true, y_pred, pos_label=1, zero_division=0)
    sp = recall_score(y_true, y_pred, pos_label=0, zero_division=0)
    f1 = f1_score(y_true, y_pred, zero_division=0)
    au = roc_auc_score(y_true, y_prob)

    metrics['bal_acc'].append(ba)
    metrics['sens'].append(se)
    metrics['spec'].append(sp)
    metrics['f1'].append(f1)
    metrics['auc'].append(au)
    all_true.extend(y_true.tolist())
    all_pred.extend(y_pred.tolist())
    all_prob.extend(y_prob.tolist())

    print(f"  ✓ BalAcc={ba*100:.2f}% | Sens={se*100:.2f}% | Spec={sp*100:.2f}% | F1={f1*100:.2f}% | AUC={au:.3f}")
    gc.collect()

# ── SONUÇLAR ──────────────────────────────────────────────────────────────────
print(f"\n{'='*70}")
print("🏆 FINAL SONUÇLAR (GPU + Zero Leakage + Patient-Level)")
print(f"{'='*70}")
for k, v in metrics.items():
    print(f"  {k.upper():12s}: {np.mean(v)*100:6.2f}% ± {np.std(v)*100:5.2f}%")

our_ba   = np.mean(metrics['bal_acc']) * 100
paper_ba = 91.16
t_stat, p_val = stats.ttest_1samp([b*100 for b in metrics['bal_acc']], paper_ba)

print(f"\n{'─'*70}")
print(f"  📊 Bizim yöntem : {our_ba:.2f}%")
print(f"  📄 Makale       : {paper_ba:.2f}%")
print(f"  📈 Fark         : {our_ba - paper_ba:+.2f}%")
print(f"  📉 p-değeri     : {'<0.001' if p_val < 0.001 else f'{p_val:.3f}'}")
print(f"{'─'*70}")

results_txt = f"""PADS Parkinson Tespit Sonuçları
================================
Balanced Accuracy : {np.mean(metrics['bal_acc'])*100:.2f}% ± {np.std(metrics['bal_acc'])*100:.2f}%
Sensitivity       : {np.mean(metrics['sens'])*100:.2f}% ± {np.std(metrics['sens'])*100:.2f}%
Specificity       : {np.mean(metrics['spec'])*100:.2f}% ± {np.std(metrics['spec'])*100:.2f}%
F1 Score          : {np.mean(metrics['f1'])*100:.2f}% ± {np.std(metrics['f1'])*100:.2f}%
AUC               : {np.mean(metrics['auc'])*100:.2f}% ± {np.std(metrics['auc'])*100:.2f}%

Karşılaştırma
--------------
Bizim yöntem      : {our_ba:.2f}%
Makale (PADS)     : {paper_ba:.2f}%
Fark              : {our_ba - paper_ba:+.2f}%
p-değeri          : {'<0.001' if p_val < 0.001 else f'{p_val:.3f}'}

Fold Bazlı BalAcc : {[f'{v*100:.2f}%' for v in metrics['bal_acc']]}
"""

with open(f"{OUTPUT_DIR}/results.txt", 'w') as f:
    f.write(results_txt)

print(results_txt)
print(f"✅ Sonuçlar kaydedildi: {OUTPUT_DIR}/results.txt")
print("=" * 70)

