# ── RAM Kontrolü ──────────────────────────────────────────────────────────────
def check_ram(tag=""):
    mem = psutil.virtual_memory()
    used_gb  = (mem.total - mem.available) / 1e9
    total_gb = mem.total / 1e9
    pct      = mem.percent
    print(f"  💾 RAM [{tag}]: {used_gb:.1f}/{total_gb:.1f} GB ({pct:.0f}%)")
    if pct > 88:
        print("  ⚠️  RAM kritik! Temizleniyor...")
        gc.collect()
    return pct

def aggressive_cleanup(*arrays):
    """Belirtilen array'leri ve cache'i temizle"""
    for a in arrays:
        try: del a
        except: pass
    gc.collect()
    try:
        import ctypes
        ctypes.CDLL("libc.so.6").malloc_trim(0)
    except: pass

