import sys, subprocess, os, warnings, gc, zipfile, shutil, json, pickle
warnings.filterwarnings('ignore')
os.environ['TF_CPP_MIN_LOG_LEVEL'] = '3'

def install(pkg):
    try: __import__(pkg.split('[')[0])
    except: subprocess.check_call([sys.executable, "-m", "pip", "install", pkg, "-q", "--break-system-packages"])

for pkg in ["numpy","pandas","scipy","scikit-learn","sktime","catboost","xgboost","lightgbm","pywavelets","tqdm","psutil"]:
    install(pkg)

import numpy as np
import pandas as pd
import psutil
from glob import glob
from tqdm import tqdm
from scipy.signal import detrend, resample, welch
from scipy.stats import skew, kurtosis
from scipy import stats
import pywt
from sklearn.model_selection import StratifiedGroupKFold
from sklearn.preprocessing import RobustScaler, OrdinalEncoder
from sklearn.metrics import (balanced_accuracy_score, recall_score,
                              f1_score, roc_auc_score, roc_curve)
from sklearn.compose import ColumnTransformer
from sktime.transformations.panel.rocket import MiniRocketMultivariate
from catboost import CatBoostClassifier
from xgboost import XGBClassifier
from lightgbm import LGBMClassifier

# ── Yardımcı fonksiyonlar ─────────────────────────────────────────────────────
def check_ram(tag=""):
    mem = psutil.virtual_memory()
    pct = mem.percent
    used = (mem.total - mem.available) / 1e9
    total = mem.total / 1e9
    print(f"  💾 RAM [{tag}]: {used:.1f}/{total:.1f} GB ({pct:.0f}%)")
    return pct

def aggressive_cleanup(*arrays):
    for a in arrays:
        try: del a
        except: pass
    gc.collect()
    try:
        import ctypes
        ctypes.CDLL("libc.so.6").malloc_trim(0)
    except: pass

# ── GPU Kontrol ───────────────────────────────────────────────────────────────
gpu_available = False
try:
    r = subprocess.run(['nvidia-smi'], capture_output=True, text=True)
    if r.returncode == 0:
        gpu_available = True
        print("✅ GPU aktif!")
        # GPU belleğini göster
        lines = r.stdout.split('\n')
        for l in lines:
            if 'MiB' in l: print(" ", l.strip())
except: pass

# ── Config ────────────────────────────────────────────────────────────────────
ROCKET_KERNELS = 7000    # Düşük tut — crash önlemek için kritik
RANDOM_STATE   = 42
SEQ_LEN        = 400
CROP_START     = 50
OUTPUT_DIR     = '/content/pads_results'
