# ── ADIM 4: Data path ─────────────────────────────────────────────────────────
inner     = glob(f"{EXTRACT_ROOT}/pads-parkinsons-disease-smartwatch-dataset-1.0.0")
data_path = inner[0] if inner else EXTRACT_ROOT
all_txt   = [f for f in glob(f"{data_path}/**/*.txt", recursive=True) if "LICENSE" not in f]

if len(all_txt) == 0:
    for sd in glob(f"{EXTRACT_ROOT}/*/"):
        txts = [f for f in glob(f"{sd}/**/*.txt", recursive=True) if "LICENSE" not in f]
        if txts:
            data_path = sd.rstrip('/')
            all_txt   = txts
            break

print(f"\n✅ data_path    : {data_path}")
