import sys, subprocess, os, warnings, gc, zipfile, shutil, json, pickle
warnings.filterwarnings('ignore')
os.environ['TF_CPP_MIN_LOG_LEVEL'] = '3'

def install(pkg):
    try: __import__(pkg.split('[')[0])
    except: subprocess.check_call([sys.executable, "-m", "pip", "install", pkg, "-q", "--break-system-packages"])

for pkg in ["numpy","pandas","scipy","scikit-learn","sktime","catboost","xgboost","lightgbm","pywavelets","tqdm","psutil"]:
    install(pkg)

import numpy as np
import pandas as pd
import psutil
from glob import glob
from tqdm import tqdm
from scipy.signal import detrend, resample, welch
from scipy.stats import skew, kurtosis
from scipy import stats
import pywt
from sklearn.model_selection import StratifiedGroupKFold, StratifiedKFold
from sklearn.preprocessing import RobustScaler, OrdinalEncoder
from sklearn.metrics import (balanced_accuracy_score, recall_score,
                              f1_score, roc_auc_score, roc_curve)
from sklearn.compose import ColumnTransformer
from sklearn.linear_model import LogisticRegression
from sktime.transformations.panel.rocket import MiniRocketMultivariate
from catboost import CatBoostClassifier
from xgboost import XGBClassifier
from lightgbm import LGBMClassifier

# ── Yardımcı ─────────────────────────────────────────────────────────────────
def check_ram(tag=""):
    mem  = psutil.virtual_memory()
    used = (mem.total - mem.available) / 1e9
    tot  = mem.total / 1e9
    print(f"  💾 RAM [{tag}]: {used:.1f}/{tot:.1f} GB ({mem.percent:.0f}%)")
    return mem.percent

def cleanup(*arrays):
    for a in arrays:
        try: del a
        except: pass
    gc.collect()
    try:
        import ctypes; ctypes.CDLL("libc.so.6").malloc_trim(0)
    except: pass

# ── GPU Kontrol + Tip ─────────────────────────────────────────────────────────
gpu_available = False
gpu_type      = "none"
try:
    r = subprocess.run(['nvidia-smi', '--query-gpu=name,memory.total',
                        '--format=csv,noheader'], capture_output=True, text=True)
    if r.returncode == 0 and r.stdout.strip():
        gpu_available = True
        gpu_info = r.stdout.strip()
        print(f"✅ GPU: {gpu_info}")
        if   'A100' in gpu_info: gpu_type = 'A100'
        elif 'V100' in gpu_info: gpu_type = 'V100'
        elif 'T4'   in gpu_info: gpu_type = 'T4'
        else:                    gpu_type = 'other'
except: pass

# GPU tipine göre Rocket kernel sayısı
ROCKET_MAP = {'A100': 15000, 'V100': 12000, 'T4': 7000, 'other': 7000, 'none': 5000}
ROCKET_KERNELS = ROCKET_MAP[gpu_type]

# ── Config ────────────────────────────────────────────────────────────────────
RANDOM_STATE   = 42
SEQ_LEN        = 400
CROP_START     = 50
OUTPUT_DIR     = '/content/pads_results'
CHECKPOINT_DIR = '/content/pads_results/checkpoints'
EXTRACT_ROOT   = '/content/pads_extracted'
LOCAL_ZIP      = '/content/pads_dataset.zip'
DRIVE_ZIP      = '/content/drive/MyDrive/Parkinson/pads-parkinsons-disease-smartwatch-dataset-1.0.0.zip'
DATA_CACHE     = f'{CHECKPOINT_DIR}/data_cache.pkl'
METRICS_FILE   = f'{CHECKPOINT_DIR}/metrics.pkl'

os.makedirs(OUTPUT_DIR,     exist_ok=True)
os.makedirs(CHECKPOINT_DIR, exist_ok=True)
np.random.seed(RANDOM_STATE)

print("=" * 70)
print("🚀 PADS MAX PERFORMANCE + CRASH-PROOF")
print("=" * 70)
print(f"  GPU tipi       : {gpu_type}")
print(f"  Rocket Kernels : {ROCKET_KERNELS}")
print(f"  Checkpoint     : {CHECKPOINT_DIR}")
print("=" * 70)

