# ── Feature extraction ────────────────────────────────────────────────────────
def extract_features(sig):
    f = []
    f.extend([np.mean(sig), np.std(sig), np.median(sig), np.min(sig), np.max(sig),
              np.ptp(sig), skew(sig), kurtosis(sig),
              np.percentile(sig,25), np.percentile(sig,75),
              np.percentile(sig,10), np.percentile(sig,90)])
    # Wavelet
    try:
        for lvl in [2, 3]:
            c = pywt.wavedec(sig, 'db4', level=lvl)
            for cc in c: f.extend([np.mean(cc), np.std(cc), np.max(np.abs(cc)), np.sum(cc**2)])
    except: f.extend([0]*24)
    # Welch
    try:
        fr, ps = welch(sig, fs=100, nperseg=min(128, len(sig)))
        total  = np.sum(ps) + 1e-10
        bands  = [(0,5),(5,15),(15,30),(30,50)]
        for lo,hi in bands:
            idx = (fr>=lo)&(fr<hi)
            f.extend([np.sum(ps[idx])/total, np.max(ps[idx]) if idx.any() else 0])
        f.extend([np.sum(ps), np.max(ps), float(np.argmax(ps))])
    except: f.extend([0]*11)
    # Diff features
    d1 = np.diff(sig);  d2 = np.diff(d1)
    f.extend([np.mean(np.abs(d1)), np.std(d1), np.mean(np.abs(d2)), np.std(d2)])
    # Zero crossings
    zc = np.sum(np.diff(np.sign(sig)) != 0)
    f.append(float(zc))
    return np.array(f, dtype=np.float32)

# ── Load data ─────────────────────────────────────────────────────────────────
# Drive cache varsa oradan yükle (crash sonrası hızlı başlangıç)
DRIVE_CACHE = "/content/drive/MyDrive/Parkinson/pads_data_cache.pkl"

if os.path.exists(DATA_CACHE):
    print(f"\n♻️  Local cache yükleniyor...")
    with open(DATA_CACHE,'rb') as f: cache = pickle.load(f)
    X_sig_arr=cache['X_sig_arr']; X_hc_arr=cache['X_hc_arr']
    df_clin=cache['df_clin']; y=cache['y']
    groups=cache['groups']; tasks=cache['tasks']
    print(f"✅ {len(y)} örnek, {len(np.unique(groups))} hasta")

elif os.path.exists(DRIVE_CACHE):
    print(f"\n♻️  Drive cache yükleniyor...")
    with open(DRIVE_CACHE,'rb') as f: cache = pickle.load(f)
    X_sig_arr=cache['X_sig_arr']; X_hc_arr=cache['X_hc_arr']
    df_clin=cache['df_clin']; y=cache['y']
    groups=cache['groups']; tasks=cache['tasks']
    # Local'e de kaydet
    with open(DATA_CACHE,'wb') as f: pickle.dump(cache,f)
    print(f"✅ {len(y)} örnek, {len(np.unique(groups))} hasta")

else:
    print("\n📊 Veri ilk kez yükleniyor...")

    patient_info = {}
    csv_cands = [f"{data_path}/subjects.csv",
                 *glob(f"{EXTRACT_ROOT}/**/subjects.csv", recursive=True),
                 "/content/drive/MyDrive/subjects.csv"]
    csv_found = next((c for c in csv_cands if os.path.exists(c)), None)

    if csv_found:
        dm = pd.read_csv(csv_found)
        dm.columns = [c.strip().lower() for c in dm.columns]
        id_c  = next((c for c in dm.columns if c=='id'), None)
        lb_c  = next((c for c in dm.columns if 'label' in c), None)
        ag_c  = next((c for c in dm.columns if 'age'   in c), None)
        sx_c  = next((c for c in dm.columns if 'sex'   in c or 'gender' in c), None)
        if id_c and lb_c:
            for _,r in dm[dm[lb_c].isin([0,1])].iterrows():
                try:
                    patient_info[str(r[id_c]).zfill(3)] = {
                        'label': int(r[lb_c]),
                        'age'  : float(r[ag_c]) if ag_c else 60.0,
                        'gender': str(r[sx_c]) if sx_c else 'u'}
                except: continue
            print(f"✅ subjects.csv: {len(patient_info)} hasta")

    if not patient_info:
        print("⚠️  patient_*.json deneniyor...")
        for pf in glob(f"{data_path}/**/patient_*.json", recursive=True):
            try:
                d=json.load(open(pf)); c=d.get('condition','').lower()
                if   'parkinson' in c: lbl=1
                elif 'healthy' in c or 'control' in c: lbl=0
                else: continue
                patient_info[str(d['id']).zfill(3)]={
                    'label':lbl,'age':float(d.get('age',60)),'gender':str(d.get('gender','u'))}
            except: pass
        print(f"✅ patient_*.json: {len(patient_info)} hasta")

    if not patient_info: raise FileNotFoundError("Hasta verisi yok!")

    nms_data = {}
    for qf in glob(f"{data_path}/**/questionnaire_response_*.json", recursive=True):
        try:
            q=json.load(open(qf)); pid=str(q.get('subject_id','')).zfill(3)
            if pid not in patient_info: continue
            ans=[0]*30
            for it in q.get('item',[]):
                try:
                    i=int(it.get('link_id','99'))-1
                    if 0<=i<30: ans[i]=1 if it.get('answer') else 0
                except: pass
            nms_data[pid]=ans
        except: pass
    print(f"✅ NMS: {len(nms_data)} hasta")

    X_sig, X_hc, X_clin = [], [], []
    y_list, grp_list, task_list = [], [], []

    for fp in tqdm(all_txt, desc="Yükleniyor"):
        try:
            base=os.path.basename(fp).replace('.txt',''); parts=base.split('_')
            pid=parts[0].zfill(3); task=parts[1] if len(parts)>1 else "Unk"
            if pid not in patient_info: continue

            raw=pd.read_csv(fp,header=None).select_dtypes(include=[np.number]).values
            if raw.shape[0]<100: continue
            raw=raw[CROP_START:,:]
            raw=detrend(raw,axis=0)
            if raw.shape[0]>raw.shape[1]: raw=raw.T
            raw=resample(raw,SEQ_LEN,axis=1).astype(np.float32)

            X_sig.append(raw)
            hc=[feat for ch in range(raw.shape[0]) for feat in extract_features(raw[ch])]
            X_hc.append(hc)

            p=patient_info[pid]; nms=nms_data.get(pid,[0]*30)
            X_clin.append([float(p['age']),str(p['gender']),str(task),
                           sum(nms),float(np.mean(nms)),float(np.std(nms)),
                           int(np.count_nonzero(nms)),
                           sum(nms[0:10]),sum(nms[10:15]),sum(nms[15:20]),sum(nms[20:30])]+nms)
            y_list.append(p['label']); grp_list.append(pid); task_list.append(task)
        except: continue

    if not X_sig: raise ValueError("Sinyal yüklenemedi!")

    max_ch=max(x.shape[0] for x in X_sig)
    X_sig_arr=np.zeros((len(X_sig),max_ch,SEQ_LEN),dtype=np.float32)
    for i,x in enumerate(X_sig): X_sig_arr[i,:x.shape[0],:]=x

    X_hc_arr=np.array(X_hc,dtype=np.float32)
    clin_cols=(['age','gender','task','nms_sum','nms_mean','nms_std','nms_nonzero',
                'nms_motor','nms_sleep','nms_mood','nms_auto']+[f'nms_{i}' for i in range(30)])
    df_clin=pd.DataFrame(X_clin,columns=clin_cols)
    y=np.array(y_list); groups=np.array(grp_list); tasks=np.array(task_list)

    del X_sig,X_hc,X_clin,y_list,grp_list,task_list
    cleanup()

    print("\n💾 Cache kaydediliyor...")
    cache_data={'X_sig_arr':X_sig_arr,'X_hc_arr':X_hc_arr,
                'df_clin':df_clin,'y':y,'groups':groups,'tasks':tasks}
    with open(DATA_CACHE,'wb') as f: pickle.dump(cache_data,f)
    try:
        shutil.copy2(DATA_CACHE, DRIVE_CACHE)
        print("✅ Drive cache kaydedildi!")
    except: pass

n_pd,n_hc_cnt=int(np.sum(y==1)),int(np.sum(y==0))
class_ratio=n_pd/(n_hc_cnt+1e-10)

print(f"\n✅ Yüklendi: {len(y)} örnek | PD:{n_pd} HC:{n_hc_cnt} | Hasta:{len(np.unique(groups))}")
print(f"   Sinyal: {X_sig_arr.shape} | HC features: {X_hc_arr.shape[1]}")
check_ram("Veri hazır")

# ── Model parametreleri ───────────────────────────────────────────────────────
# XGBoost — GPU varsa cuda
xgb_params = dict(
    tree_method='hist',
    device='cuda' if gpu_available else 'cpu',
    n_estimators=800, learning_rate=0.02, max_depth=8,
    min_child_weight=2, subsample=0.85, colsample_bytree=0.85,
    gamma=0.3, reg_alpha=0.1, reg_lambda=1.0,
    scale_pos_weight=1.0/class_ratio,
    random_state=RANDOM_STATE, eval_metric='logloss', verbosity=0)

# CatBoost — HER ZAMAN CPU
cat_params = dict(
    task_type='CPU', thread_count=4,
    iterations=800, learning_rate=0.02, depth=8,
    l2_leaf_reg=3, random_strength=0.5, bagging_temperature=0.3,
    auto_class_weights='Balanced',
    verbose=0, random_state=RANDOM_STATE)

# LightGBM — GPU varsa
lgbm_params = dict(
    device='gpu' if gpu_available else 'cpu',
    gpu_platform_id=0, gpu_device_id=0,
    n_estimators=800, learning_rate=0.02, max_depth=8,
    num_leaves=80, min_child_samples=10,
    subsample=0.85, colsample_bytree=0.85,
    reg_alpha=0.5, reg_lambda=1.0,
    scale_pos_weight=1.0/class_ratio,
    verbosity=-1, random_state=RANDOM_STATE)

print(f"\n🔥 XGBoost  : {'GPU ('+gpu_type+')' if gpu_available else 'CPU'}")
print(f"   CatBoost : CPU (GPU OOM koruması)")
print(f"   LightGBM : {'GPU ('+gpu_type+')' if gpu_available else 'CPU'}")

# ── CV ────────────────────────────────────────────────────────────────────────
print(f"\n{'='*70}")
print("🔬 10-FOLD STRATIFIED GROUP CV")
print(f"{'='*70}")

cv     = StratifiedGroupKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)
splits = list(cv.split(X_sig_arr, y, groups))

if os.path.exists(METRICS_FILE):
    with open(METRICS_FILE,'rb') as f: saved=pickle.load(f)
    metrics=saved['metrics']; all_true=saved['all_true']
    all_pred=saved['all_pred']; all_prob=saved['all_prob']
    completed=saved['completed_folds']
    print(f"♻️  Kaldığı yerden devam: {completed}")
else:
    metrics={'bal_acc':[],'sens':[],'spec':[],'f1':[],'auc':[]}
    all_true,all_pred,all_prob=[],[],[]
    completed=[]
    print("🆕 Yeni çalışma")

num_cols=['age','nms_sum','nms_mean','nms_std','nms_nonzero',
          'nms_motor','nms_sleep','nms_mood','nms_auto']+[f'nms_{i}' for i in range(30)]
cat_cols_clin=['gender','task']

for fold,(tr_i,te_i) in enumerate(splits,1):
    if fold in completed:
        print(f"⏭️  FOLD {fold} atlanıyor..."); continue

    print(f"\n{'─'*70}")
    print(f"📌 FOLD {fold}/10  Train:{len(tr_i)}  Test:{len(te_i)}")
    check_ram(f"Fold {fold} başlangıç")

    X_sig_tr=X_sig_arr[tr_i].copy(); X_sig_te=X_sig_arr[te_i].copy()
    X_hc_tr=X_hc_arr[tr_i].copy();  X_hc_te=X_hc_arr[te_i].copy()
    df_c_tr=df_clin.iloc[tr_i].reset_index(drop=True)
    df_c_te=df_clin.iloc[te_i].reset_index(drop=True)
    y_tr,y_te=y[tr_i],y[te_i]
    g_tr,g_te=groups[tr_i],groups[te_i]

    # ── MiniRocket ────────────────────────────────────────────────────────────
    print(f"  🚀 MiniRocket ({ROCKET_KERNELS} kernel)...")
    rocket=MiniRocketMultivariate(num_kernels=ROCKET_KERNELS,
                                   random_state=RANDOM_STATE,n_jobs=-1)
    X_r_tr=rocket.fit_transform(X_sig_tr)
    X_r_te=rocket.transform(X_sig_te)
    X_r_tr=X_r_tr.values if hasattr(X_r_tr,'values') else np.array(X_r_tr)
    X_r_te=X_r_te.values if hasattr(X_r_te,'values') else np.array(X_r_te)
    del X_sig_tr,X_sig_te,rocket; cleanup()
    check_ram(f"Fold {fold} Rocket bitti")
    print(f"  ✓ Rocket: {X_r_tr.shape[1]} feature")

    # ── Preprocessing ─────────────────────────────────────────────────────────
    clin_prep=ColumnTransformer([
        ('num',RobustScaler(),num_cols),
        ('cat',OrdinalEncoder(handle_unknown='use_encoded_value',
                              unknown_value=-1),cat_cols_clin)])
    X_c_tr=clin_prep.fit_transform(df_c_tr)
    X_c_te=clin_prep.transform(df_c_te)

    hc_sc=RobustScaler()
    X_hc_sc_tr=hc_sc.fit_transform(X_hc_tr)
    X_hc_sc_te=hc_sc.transform(X_hc_te)
    del X_hc_tr,X_hc_te; cleanup()

    X_tr=np.hstack([X_r_tr,X_hc_sc_tr,X_c_tr]).astype(np.float32)
    X_te=np.hstack([X_r_te,X_hc_sc_te,X_c_te]).astype(np.float32)
    del X_r_tr,X_r_te,X_hc_sc_tr,X_hc_sc_te,X_c_tr,X_c_te; cleanup()
    check_ram(f"Fold {fold} feature hazır")
    print(f"  ✓ Toplam feature: {X_tr.shape[1]}")

    # ── Modeller sırayla ─────────────────────────────────────────────────────
    print("  🎯 XGBoost...")
    xgb_m=XGBClassifier(**xgb_params)
    xgb_m.fit(X_tr,y_tr)
    p_xgb_tr=xgb_m.predict_proba(X_tr)[:,1].copy()
    p_xgb_te=xgb_m.predict_proba(X_te)[:,1].copy()
    del xgb_m; cleanup()

    print("  🎯 CatBoost (CPU)...")
    cat_m=CatBoostClassifier(**cat_params,allow_writing_files=False)
    cat_m.fit(X_tr,y_tr)
    p_cat_tr=cat_m.predict_proba(X_tr)[:,1].copy()
    p_cat_te=cat_m.predict_proba(X_te)[:,1].copy()
    del cat_m; cleanup()

    print("  🎯 LightGBM...")
    lgbm_m=LGBMClassifier(**lgbm_params)
    lgbm_m.fit(X_tr,y_tr)
    p_lgbm_tr=lgbm_m.predict_proba(X_tr)[:,1].copy()
    p_lgbm_te=lgbm_m.predict_proba(X_te)[:,1].copy()
    del lgbm_m; cleanup()
    check_ram(f"Fold {fold} modeller bitti")

    # ── Stacking meta-learner ─────────────────────────────────────────────────
    # Train'deki 3 modelin çıktısını kullanarak meta-learner eğit
    # Bu threshold hack'ini ortadan kaldırır
    meta_X_tr = np.column_stack([p_xgb_tr, p_cat_tr, p_lgbm_tr])
    meta_X_te = np.column_stack([p_xgb_te, p_cat_te, p_lgbm_te])

    # Patient-level aggregation — train
    df_meta_tr=pd.DataFrame({'pid':g_tr,'true':y_tr,
                              'p0':meta_X_tr[:,0],'p1':meta_X_tr[:,1],'p2':meta_X_tr[:,2]})
    pat_agg_tr=df_meta_tr.groupby('pid').agg(
        true=('true','first'), p0=('p0','median'),
        p1=('p1','median'),    p2=('p2','median')).reset_index()

    meta_tr=pat_agg_tr[['p0','p1','p2']].values
    y_meta_tr=pat_agg_tr['true'].values.astype(int)

    # Meta-learner: Logistic Regression (lightweight, no GPU needed)
    meta_lr=LogisticRegression(C=1.0, class_weight='balanced',
                                max_iter=1000, random_state=RANDOM_STATE)
    meta_lr.fit(meta_tr, y_meta_tr)

    # Patient-level aggregation — test
    df_meta_te=pd.DataFrame({'pid':g_te,'true':y_te,
                              'p0':meta_X_te[:,0],'p1':meta_X_te[:,1],'p2':meta_X_te[:,2]})
    pat_agg_te=df_meta_te.groupby('pid').agg(
        true=('true','first'), p0=('p0','median'),
        p1=('p1','median'),    p2=('p2','median')).reset_index()

    meta_te=pat_agg_te[['p0','p1','p2']].values
    y_true =pat_agg_te['true'].values.astype(int)
    y_prob =meta_lr.predict_proba(meta_te)[:,1]

    # Threshold: 0.5 (meta-learner class_weight='balanced' ile zaten optimize)
    # Ama Youden J ile train'den bul
    fpr_m,tpr_m,ths_m=roc_curve(y_meta_tr, meta_lr.predict_proba(meta_tr)[:,1])
    best_th=float(ths_m[np.argmax(tpr_m-fpr_m)])
    y_pred=(y_prob>=best_th).astype(int)

    del X_tr,X_te,meta_X_tr,meta_X_te,meta_lr; cleanup()

    ba=balanced_accuracy_score(y_true,y_pred)
    se=recall_score(y_true,y_pred,pos_label=1,zero_division=0)
    sp=recall_score(y_true,y_pred,pos_label=0,zero_division=0)
    f1=f1_score(y_true,y_pred,zero_division=0)
    au=roc_auc_score(y_true,y_prob)

    metrics['bal_acc'].append(ba); metrics['sens'].append(se)
    metrics['spec'].append(sp);   metrics['f1'].append(f1)
    metrics['auc'].append(au)
    all_true.extend(y_true.tolist()); all_pred.extend(y_pred.tolist())
    all_prob.extend(y_prob.tolist()); completed.append(fold)

    print(f"  ✓ BalAcc={ba*100:.2f}% | Sens={se*100:.2f}% | Spec={sp*100:.2f}% | F1={f1*100:.2f}% | AUC={au:.3f}")
    print(f"  📊 Şimdiye kadar ort: {np.mean(metrics['bal_acc'])*100:.2f}%")

    ckpt={'metrics':metrics,'all_true':all_true,'all_pred':all_pred,
          'all_prob':all_prob,'completed_folds':completed}
    with open(METRICS_FILE,'wb') as f: pickle.dump(ckpt,f)
    try:
        shutil.copy2(METRICS_FILE,
                     f"/content/drive/MyDrive/Parkinson/pads_ckpt_fold{fold}.pkl")
        print(f"  💾 Drive checkpoint fold {fold}/10 ✅")
    except Exception as e:
        print(f"  ⚠️  Drive kayıt: {e}")

    cleanup()

# ── Sonuçlar ──────────────────────────────────────────────────────────────────
print(f"\n{'='*70}")
print("🏆 FINAL SONUÇLAR")
print(f"{'='*70}")
for k,v in metrics.items():
    print(f"  {k.upper():12s}: {np.mean(v)*100:6.2f}% ± {np.std(v)*100:5.2f}%")

our_ba=np.mean(metrics['bal_acc'])*100; paper_ba=91.16
t_stat,p_val=stats.ttest_1samp([b*100 for b in metrics['bal_acc']],paper_ba)

print(f"\n  📊 Bizim  : {our_ba:.2f}%")
print(f"  📄 Makale : {paper_ba:.2f}%")
print(f"  📈 Fark   : {our_ba-paper_ba:+.2f}%")
print(f"  📉 p-val  : {'<0.001' if p_val<0.001 else f'{p_val:.3f}'}")
print(f"  ✅ Foldlar: {completed}")
print(f"  📋 Fold detay: {[f'{v*100:.1f}%' for v in metrics['bal_acc']]}")

results_txt=f"""PADS Parkinson Sonuçları
=========================
GPU               : {gpu_type}
Rocket Kernels    : {ROCKET_KERNELS}
Balanced Accuracy : {np.mean(metrics['bal_acc'])*100:.2f}% ± {np.std(metrics['bal_acc'])*100:.2f}%
Sensitivity       : {np.mean(metrics['sens'])*100:.2f}% ± {np.std(metrics['sens'])*100:.2f}%
Specificity       : {np.mean(metrics['spec'])*100:.2f}% ± {np.std(metrics['spec'])*100:.2f}%
F1 Score          : {np.mean(metrics['f1'])*100:.2f}% ± {np.std(metrics['f1'])*100:.2f}%
AUC               : {np.mean(metrics['auc'])*100:.2f}% ± {np.std(metrics['auc'])*100:.2f}%
Bizim yöntem      : {our_ba:.2f}%
Makale            : {paper_ba:.2f}%
Fark              : {our_ba-paper_ba:+.2f}%
p-değeri          : {'<0.001' if p_val<0.001 else f'{p_val:.3f}'}
Foldlar           : {completed}
Fold BalAcc       : {[f'{v*100:.2f}%' for v in metrics['bal_acc']]}
"""

with open(f"{OUTPUT_DIR}/results.txt",'w') as f: f.write(results_txt)
try:
    shutil.copy2(f"{OUTPUT_DIR}/results.txt",
                 "/content/drive/MyDrive/Parkinson/pads_final_results.txt")
    print("\n✅ Sonuçlar Drive'a kaydedildi!")
except: pass

print(results_txt)
print("="*70)

# ============================================================================
# PADS - MAKALENİN YÖNTEMİNE SADIK + CRASH-PROOF + GPU
# ============================================================================
# Makalenin kritik adımları:
# 1. Hasta başına TEK örnek (segment aggregation = median)
# 2. Gender + Label ile sample weighting
