# ── Yardımcı ─────────────────────────────────────────────────────────────────
def check_ram(tag=""):
    mem = psutil.virtual_memory()
    print(f"  💾 RAM [{tag}]: {(mem.total-mem.available)/1e9:.1f}/{mem.total/1e9:.1f} GB ({mem.percent:.0f}%)")
    return mem.percent

def cleanup(*arrays):
    for a in arrays:
        try: del a
        except: pass
    gc.collect()
    try:
        import ctypes; ctypes.CDLL("libc.so.6").malloc_trim(0)
    except: pass

def get_balanced_weights(y, gender=None):
    """Makalenin sample weighting: hem label hem gender ile dengele"""
    if gender is not None:
        combined = np.array([f"{yi}_{gi}" for yi,gi in zip(y, gender)])
    else:
        combined = y.astype(str)
    weights = np.zeros(len(combined), dtype=np.float32)
    unique, counts = np.unique(combined, return_counts=True)
    for u, c in zip(unique, counts):
        weights[combined == u] = len(combined) / (len(unique) * c)
    return weights

