# ── Feature extraction (makalenin yöntemi) ───────────────────────────────────
def bandpower(x, srate=100, steps=100, cut=(1,20)):
    fs, pxx = welch(x, fs=srate, nperseg=steps, scaling="density")
    bp = pxx[cut[0]:cut[1]]
    return np.log10(bp + 1e-10)

def std_windowed(x):
    l = len(x)//4
    return [np.std(x[n*l:(n+1)*l]) for n in range(4)]

def abs_energy_windowed(x):
    l = len(x)//4
    return [np.sum(np.abs(x[n*l:(n+1)*l])) for n in range(4)]

def abs_max_windowed(x):
    l = len(x)//4
    return [np.max(np.abs(x[n*l:(n+1)*l])) for n in range(4)]

def extract_features_paper(sig):
    """Makalenin tam feature pipeline'ı"""
    f = []
    for ch in range(sig.shape[0]):
        x = sig[ch]
        f.extend(bandpower(x))        # 19 feature
        f.extend(std_windowed(x))     # 4 feature
        f.extend(abs_energy_windowed(x))  # 4 feature
        f.extend(abs_max_windowed(x))     # 4 feature
    return np.array(f, dtype=np.float32)

def extract_features_extra(sig):
    """Ek özellikler — makale üstüne"""
    f = []
    for ch in range(sig.shape[0]):
        x = sig[ch]
        f.extend([np.mean(x), np.std(x), np.median(x),
                  np.ptp(x), skew(x), kurtosis(x),
                  np.percentile(x,25), np.percentile(x,75)])
        try:
            c = pywt.wavedec(x, 'db4', level=3)
            for cc in c: f.extend([np.mean(cc), np.std(cc), np.sum(cc**2)])
        except: f.extend([0]*12)
        d1 = np.diff(x)
        f.extend([np.mean(np.abs(d1)), np.std(d1)])
    return np.array(f, dtype=np.float32)

# ── Load data ─────────────────────────────────────────────────────────────────
if os.path.exists(DATA_CACHE):
    print(f"\n♻️  Local cache yükleniyor...")
    with open(DATA_CACHE,'rb') as f: cache=pickle.load(f)
elif os.path.exists(DRIVE_CACHE):
    print(f"\n♻️  Drive cache yükleniyor...")
    with open(DRIVE_CACHE,'rb') as f: cache=pickle.load(f)
    with open(DATA_CACHE,'wb') as f: pickle.dump(cache,f)
else:
    cache = None

if cache:
    patient_df   = cache['patient_df']
    seg_features = cache['seg_features']
    seg_rocket   = cache['seg_rocket_raw']   # ham sinyal — rocket fold'da fit edilecek
    print(f"✅ Cache: {len(patient_df)} hasta")
else:
    print("\n📊 Veri yükleniyor...")

    # subjects.csv veya patient_*.json
    patient_info = {}
    csv_cands = [f"{data_path}/subjects.csv",
                 *glob(f"{EXTRACT_ROOT}/**/subjects.csv", recursive=True),
                 "/content/drive/MyDrive/subjects.csv"]
    csv_found = next((c for c in csv_cands if os.path.exists(c)), None)

    if csv_found:
        dm = pd.read_csv(csv_found)
        dm.columns = [c.strip().lower() for c in dm.columns]
        id_c  = next((c for c in dm.columns if c=='id'), None)
        lb_c  = next((c for c in dm.columns if 'label' in c), None)
        ag_c  = next((c for c in dm.columns if 'age'   in c), None)
        sx_c  = next((c for c in dm.columns if 'sex'   in c or 'gender' in c), None)
        if id_c and lb_c:
            for _,r in dm[dm[lb_c].isin([0,1])].iterrows():
                try:
                    patient_info[str(r[id_c]).zfill(3)] = {
                        'label' : int(r[lb_c]),
                        'age'   : float(r[ag_c]) if ag_c else 60.0,
                        'gender': str(r[sx_c]) if sx_c else 'u'}
                except: continue
            print(f"✅ subjects.csv: {len(patient_info)} hasta")

    if not patient_info:
        for pf in glob(f"{data_path}/**/patient_*.json", recursive=True):
            try:
                d=json.load(open(pf)); c=d.get('condition','').lower()
                if 'parkinson' in c: lbl=1
                elif 'healthy' in c or 'control' in c: lbl=0
                else: continue
                patient_info[str(d['id']).zfill(3)]={
                    'label':lbl,'age':float(d.get('age',60)),'gender':str(d.get('gender','u'))}
            except: pass
        print(f"✅ patient_*.json: {len(patient_info)} hasta")

    if not patient_info: raise FileNotFoundError("Hasta verisi yok!")

    # NMS
    nms_data = {}
    for qf in glob(f"{data_path}/**/questionnaire_response_*.json", recursive=True):
        try:
            q=json.load(open(qf)); pid=str(q.get('subject_id','')).zfill(3)
            if pid not in patient_info: continue
            ans=[0]*30
            for it in q.get('item',[]):
                try:
                    i=int(it.get('link_id','99'))-1
                    if 0<=i<30: ans[i]=1 if it.get('answer') else 0
                except: pass
            nms_data[pid]=ans
        except: pass

    # Segment bazında yükle — sonra hasta bazına aggregate edeceğiz
    seg_data = {}  # pid -> list of (raw_signal, features_paper, features_extra, task)

    for fp in tqdm(all_txt, desc="Yükleniyor"):
        try:
            base=os.path.basename(fp).replace('.txt',''); parts=base.split('_')
            pid=parts[0].zfill(3); task=parts[1] if len(parts)>1 else "Unk"
            if pid not in patient_info: continue

            raw=pd.read_csv(fp,header=None).select_dtypes(include=[np.number]).values
            if raw.shape[0]<100: continue
            raw=raw[CROP_START:,:]
            raw=detrend(raw,axis=0)
            if raw.shape[0]>raw.shape[1]: raw=raw.T
            raw=resample(raw,SEQ_LEN,axis=1).astype(np.float32)

            fp_feat = extract_features_paper(raw)
            ex_feat = extract_features_extra(raw)

            if pid not in seg_data: seg_data[pid]=[]
            seg_data[pid].append({'raw':raw, 'fp':fp_feat, 'ex':ex_feat, 'task':task})
        except: continue

    # ── Hasta bazına aggregate ────────────────────────────────────────────────
    # Her hasta için: median aggregation tüm segmentler üzerinden
    patient_rows = []
    seg_features = {}   # pid -> aggregated features
    seg_rocket   = {}   # pid -> stacked raw signals (channels x time x n_segs)

    for pid, segs in seg_data.items():
        p = patient_info[pid]
        nms = nms_data.get(pid,[0]*30)

        # Median aggregation
        fp_agg = np.median([s['fp'] for s in segs], axis=0)
        ex_agg = np.median([s['ex'] for s in segs], axis=0)

        # NMS features
        nms_feat = np.array([
            sum(nms), np.mean(nms), np.std(nms), np.count_nonzero(nms),
            sum(nms[0:10]), sum(nms[10:15]), sum(nms[15:20]), sum(nms[20:30])
        ] + nms, dtype=np.float32)

        seg_features[pid] = np.concatenate([fp_agg, ex_agg, nms_feat])

        # Raw sinyaller (rocket için) — her hastanın tüm segmentleri
        raws = np.stack([s['raw'] for s in segs])  # (n_segs, channels, time)
        seg_rocket[pid] = raws

        patient_rows.append({
            'pid'   : pid,
            'label' : p['label'],
            'age'   : p['age'],
            'gender': p['gender']
        })

    patient_df = pd.DataFrame(patient_rows).set_index('pid')
    print(f"\n✅ Hasta bazı: {len(patient_df)} hasta")
    print(f"   PD: {patient_df['label'].sum()} | HC: {(patient_df['label']==0).sum()}")
    print(f"   Feature/hasta: {list(seg_features.values())[0].shape[0]}")

    del seg_data; cleanup()

    print("\n💾 Cache kaydediliyor...")
    cache_data = {'patient_df':patient_df, 'seg_features':seg_features, 'seg_rocket_raw':seg_rocket}
    with open(DATA_CACHE,'wb') as f: pickle.dump(cache_data,f)
    try:
        shutil.copy2(DATA_CACHE, DRIVE_CACHE)
        print("✅ Drive cache kaydedildi!")
    except: pass

# ── Verileri array'e çevir ────────────────────────────────────────────────────
pids    = patient_df.index.tolist()
y       = patient_df['label'].values.astype(int)
genders = patient_df['gender'].values

# Handcrafted features — (n_hasta, n_feat)
X_feat = np.stack([seg_features[p] for p in pids]).astype(np.float32)

# Ham sinyal — her hastanın segmentleri (rocket için)
# max_segs x channels x time
max_segs = max(seg_rocket[p].shape[0] for p in pids)
max_ch   = max(seg_rocket[p].shape[1] for p in pids)
X_raw    = np.zeros((len(pids), max_segs, max_ch, SEQ_LEN), dtype=np.float32)
seg_counts = []
for i,p in enumerate(pids):
    r = seg_rocket[p]
    X_raw[i, :r.shape[0], :r.shape[1], :] = r
    seg_counts.append(r.shape[0])
seg_counts = np.array(seg_counts)

n_pd  = int(np.sum(y==1))
n_hc  = int(np.sum(y==0))
class_ratio = n_pd/(n_hc+1e-10)

print(f"\n✅ Array hazır: {X_feat.shape} feat | {X_raw.shape} raw")
print(f"   PD:{n_pd} HC:{n_hc} | Ortalama segment/hasta: {seg_counts.mean():.1f}")
check_ram("Veri hazır")

# ── Model parametreleri ───────────────────────────────────────────────────────
xgb_params = dict(
    tree_method='hist',
    device='cuda' if gpu_available else 'cpu',
    n_estimators=800, learning_rate=0.02, max_depth=7,
    min_child_weight=2, subsample=0.85, colsample_bytree=0.85,
    gamma=0.3, reg_alpha=0.2, reg_lambda=1.0,
    random_state=RANDOM_STATE, eval_metric='logloss', verbosity=0)

cat_params = dict(
    task_type='CPU', thread_count=4,
    iterations=800, learning_rate=0.02, depth=7,
    l2_leaf_reg=3, random_strength=0.5,
    auto_class_weights='Balanced',
    verbose=0, random_state=RANDOM_STATE)

lgbm_params = dict(
    device='gpu' if gpu_available else 'cpu',
    gpu_platform_id=0, gpu_device_id=0,
    n_estimators=800, learning_rate=0.02, max_depth=7,
    num_leaves=70, min_child_samples=5,
    subsample=0.85, colsample_bytree=0.85,
    reg_alpha=0.5, reg_lambda=1.0,
    verbosity=-1, random_state=RANDOM_STATE)

print(f"\n🔥 XGB:{('GPU('+gpu_type+')') if gpu_available else 'CPU'} | CAT:CPU | LGBM:{('GPU') if gpu_available else 'CPU'}")

# ── 5-FOLD CV (Makale ile aynı) ───────────────────────────────────────────────
print(f"\n{'='*70}")
print(f"🔬 {N_FOLDS}-FOLD CV — Hasta bazlı (Makale yöntemi + İyileştirmeler)")
print(f"{'='*70}")

cv     = StratifiedKFold(n_splits=N_FOLDS, shuffle=True, random_state=RANDOM_STATE)
splits = list(cv.split(X_feat, y))

if os.path.exists(METRICS_FILE):
    with open(METRICS_FILE,'rb') as f: saved=pickle.load(f)
    metrics_d=saved['metrics']; completed=saved['completed_folds']
    all_true=saved['all_true']; all_pred=saved['all_pred']; all_prob=saved['all_prob']
    print(f"♻️  Kaldığı yerden devam: {completed}")
else:
    metrics_d={'bal_acc':[],'sens':[],'spec':[],'f1':[],'auc':[]}
    all_true,all_pred,all_prob=[],[],[]
    completed=[]
    print("🆕 Yeni çalışma")

for fold,(tr_i,te_i) in enumerate(splits,1):
    if fold in completed:
        print(f"⏭️  FOLD {fold} atlanıyor..."); continue

    print(f"\n{'─'*70}")
    print(f"📌 FOLD {fold}/{N_FOLDS}  Train:{len(tr_i)} hasta  Test:{len(te_i)} hasta")
    check_ram(f"Fold {fold} başlangıç")

    # Hasta bazlı split
    y_tr,y_te       = y[tr_i],y[te_i]
    g_tr             = genders[tr_i]
    X_feat_tr        = X_feat[tr_i]; X_feat_te = X_feat[te_i]

    # Sample weights (makale: gender + label)
    sw = get_balanced_weights(y_tr, g_tr)

    # ── MiniRocket: her hastanın tüm segmentlerini kullan ────────────────────
    print(f"  🚀 MiniRocket ({ROCKET_KERNELS} kernel, hasta bazlı)...")

    # Train: tüm segmentleri stack et
    tr_segs = []; tr_seg_pids = []
    for i in tr_i:
        n = seg_counts[i]
        tr_segs.append(X_raw[i,:n,:,:])
        tr_seg_pids.extend([i]*n)
    tr_segs = np.vstack(tr_segs)  # (total_segs, channels, time)

    te_segs = []; te_seg_pids = []
    for i in te_i:
        n = seg_counts[i]
        te_segs.append(X_raw[i,:n,:,:])
        te_seg_pids.extend([i]*n)
    te_segs = np.vstack(te_segs)

    rocket = MiniRocketMultivariate(num_kernels=ROCKET_KERNELS,
                                     random_state=RANDOM_STATE, n_jobs=-1)
    X_r_tr_segs = rocket.fit_transform(tr_segs)
    X_r_te_segs = rocket.transform(te_segs)
    X_r_tr_segs = X_r_tr_segs.values if hasattr(X_r_tr_segs,'values') else np.array(X_r_tr_segs)
    X_r_te_segs = X_r_te_segs.values if hasattr(X_r_te_segs,'values') else np.array(X_r_te_segs)
    del tr_segs, te_segs, rocket; cleanup()

    # Segment → hasta bazına median aggregate
    tr_seg_pids = np.array(tr_seg_pids)
    te_seg_pids = np.array(te_seg_pids)

    X_r_tr = np.array([np.median(X_r_tr_segs[tr_seg_pids==i], axis=0) for i in tr_i])
    X_r_te = np.array([np.median(X_r_te_segs[te_seg_pids==i], axis=0) for i in te_i])
    del X_r_tr_segs, X_r_te_segs; cleanup()
    check_ram(f"Fold {fold} Rocket bitti")
    print(f"  ✓ Rocket: {X_r_tr.shape[1]} feature/hasta")

    # Handcrafted scale
    sc = RobustScaler()
    X_hc_tr = sc.fit_transform(X_feat_tr)
    X_hc_te = sc.transform(X_feat_te)

    # Rocket scale
    sc2 = RobustScaler()
    X_r_tr = sc2.fit_transform(X_r_tr)
    X_r_te = sc2.transform(X_r_te)

    # Birleştir
    X_tr = np.hstack([X_r_tr, X_hc_tr]).astype(np.float32)
    X_te = np.hstack([X_r_te, X_hc_te]).astype(np.float32)
    del X_r_tr,X_r_te,X_hc_tr,X_hc_te; cleanup()
    print(f"  ✓ Toplam feature: {X_tr.shape[1]}")
    check_ram(f"Fold {fold} feature hazır")

    # ── Modeller sırayla (sample_weight ile) ─────────────────────────────────
    print("  🎯 XGBoost...")
    xgb_m = XGBClassifier(**xgb_params)
    xgb_m.fit(X_tr, y_tr, sample_weight=sw)
    p_xgb_tr = xgb_m.predict_proba(X_tr)[:,1].copy()
    p_xgb_te = xgb_m.predict_proba(X_te)[:,1].copy()
    del xgb_m; cleanup()

    print("  🎯 CatBoost (CPU)...")
    cat_m = CatBoostClassifier(**cat_params, allow_writing_files=False)
    cat_m.fit(X_tr, y_tr, sample_weight=sw)
    p_cat_tr = cat_m.predict_proba(X_tr)[:,1].copy()
    p_cat_te = cat_m.predict_proba(X_te)[:,1].copy()
    del cat_m; cleanup()

    print("  🎯 LightGBM...")
    lgbm_m = LGBMClassifier(**lgbm_params)
    lgbm_m.fit(X_tr, y_tr, sample_weight=sw)
    p_lgbm_tr = lgbm_m.predict_proba(X_tr)[:,1].copy()
    p_lgbm_te = lgbm_m.predict_proba(X_te)[:,1].copy()
    del lgbm_m, X_tr, X_te; cleanup()
    check_ram(f"Fold {fold} modeller bitti")

    # ── Meta stacking (makale: LogisticRegression final estimator) ────────────
    meta_tr = np.column_stack([p_xgb_tr, p_cat_tr, p_lgbm_tr])
    meta_te = np.column_stack([p_xgb_te, p_cat_te, p_lgbm_te])

    meta_lr = LogisticRegression(C=1.0, class_weight='balanced',
                                  max_iter=1000, random_state=RANDOM_STATE)
    meta_lr.fit(meta_tr, y_tr, sample_weight=sw)

    y_prob = meta_lr.predict_proba(meta_te)[:,1]
    y_pred = meta_lr.predict(meta_te)   # threshold=0.5 (makale gibi)
    y_true = y_te

    del meta_tr, meta_te, meta_lr; cleanup()

    ba = balanced_accuracy_score(y_true,y_pred)
    se = recall_score(y_true,y_pred,pos_label=1,zero_division=0)
    sp = recall_score(y_true,y_pred,pos_label=0,zero_division=0)
    f1 = f1_score(y_true,y_pred,zero_division=0)
    au = roc_auc_score(y_true,y_prob)

    metrics_d['bal_acc'].append(ba); metrics_d['sens'].append(se)
    metrics_d['spec'].append(sp);   metrics_d['f1'].append(f1)
    metrics_d['auc'].append(au)
    all_true.extend(y_true.tolist()); all_pred.extend(y_pred.tolist())
    all_prob.extend(y_prob.tolist()); completed.append(fold)

    print(f"  ✓ BalAcc={ba*100:.2f}% | Sens={se*100:.2f}% | Spec={sp*100:.2f}% | F1={f1*100:.2f}% | AUC={au:.3f}")
    print(f"  📊 Şimdiye kadar ort: {np.mean(metrics_d['bal_acc'])*100:.2f}%")

    ckpt={'metrics':metrics_d,'all_true':all_true,'all_pred':all_pred,
          'all_prob':all_prob,'completed_folds':completed}
    with open(METRICS_FILE,'wb') as f: pickle.dump(ckpt,f)
    try:
        shutil.copy2(METRICS_FILE,
                     f"/content/drive/MyDrive/Parkinson/pads_ckpt_v2_fold{fold}.pkl")
        print(f"  💾 Drive checkpoint fold {fold}/{N_FOLDS} ✅")
    except Exception as e: print(f"  ⚠️  {e}")

    cleanup()

