def install(pkg, import_name=None):
    name = import_name or pkg.split('[')[0].replace('-','_')
    try:
        __import__(name)
    except ImportError:
        print(f"  Kuruluyor: {pkg}")
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", pkg, "-q", "--break-system-packages"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
        )

