# ── Feature extraction fonksiyonları ─────────────────────────────────────────
# NOT: Tüm bu fonksiyonlar SADECE numpy/scipy kullanır.
# Scaler yok — scaler her fold'da pipeline içinde train'e fit edilecek.

def bandpower(x, srate=100, steps=100, cut=(1, 20)):
    """Makalenin bandpower özelliği (1-19 Hz, log scale)."""
    fs, pxx = welch(x, fs=srate, nperseg=steps, scaling="density")
    bp = pxx[cut[0]:cut[1]]
    return np.log10(bp + 1e-10)  # +eps: log(0) önlenir

def std_windowed(x):
    """4 eşit segment, her birinin std'si."""
    l = len(x) // 4
    return [np.std(x[n*l:(n+1)*l]) for n in range(4)]

def abs_energy_windowed(x):
    """4 eşit segment, mutlak enerji toplamı."""
    l = len(x) // 4
    return [np.sum(np.abs(x[n*l:(n+1)*l])) for n in range(4)]

def abs_max_windowed(x):
    """4 eşit segment, mutlak maksimum."""
    l = len(x) // 4
    return [np.max(np.abs(x[n*l:(n+1)*l])) for n in range(4)]

def tremor_band_power(x, srate=100):
    """
    Parkinson tremoru için spesifik 3-7 Hz bandı.
    Mutlak log-güç + toplam güce normalize oran döndürür.
    """
    fs, pxx = welch(x, fs=srate, nperseg=min(100, len(x)), scaling="density")
    total   = np.sum(pxx) + 1e-12
    mask    = (fs >= 3) & (fs <= 7)
    bp      = np.sum(pxx[mask])
    return [np.log10(bp + 1e-12), float(bp / total)]

def hjorth_parameters(x):
    """
    Hjorth: activity, mobility, complexity.
    Hareket patolojilerinde yaygın kullanılır.
    """
    act  = np.var(x)
    d1   = np.diff(x)
    d2   = np.diff(d1)
    mob  = np.sqrt(np.var(d1) / (act + 1e-12))
    comp = (np.sqrt(np.var(d2) / (np.var(d1) + 1e-12))) / (mob + 1e-12)
    return [float(act), float(mob), float(comp)]

def extra_stat_features(x):
    """Skewness, kurtosis, IQR, MAD, zero-crossing rate."""
    zcr = float(np.sum(np.diff(np.sign(x)) != 0) / len(x))
    q75, q25 = np.percentile(x, [75, 25])
    return [
        float(skew(x)), float(kurtosis(x)),
        float(q75 - q25),                        # IQR
        float(np.mean(np.abs(x - np.mean(x)))),  # MAD
        zcr,
    ]

def wavelet_features(x):
    """Wavelet decomposition (db4, 3 level) — enerji + std."""
    try:
        coeffs = pywt.wavedec(x, 'db4', level=3)
        feats  = []
        for c in coeffs:
            feats.extend([np.mean(c), np.std(c), np.sum(c**2)])
        return feats
    except Exception:
        return [0.0] * 12

def dominant_freq(x, srate=100):
    """PSD'deki dominant frekans (1-20 Hz arasında)."""
    fs, pxx = welch(x, fs=srate, nperseg=min(100, len(x)), scaling="density")
    mask    = (fs >= 1) & (fs <= 20)
    if mask.sum() == 0:
        return [0.0]
    return [float(fs[mask][np.argmax(pxx[mask])])]

def extract_features_per_channel(x):
    """Tek kanal (1D array) için tüm özellikler."""
    feats = []
    feats.extend(bandpower(x))          # 19 feat (makale)
    feats.extend(std_windowed(x))       #  4 feat (makale)
    feats.extend(abs_energy_windowed(x))#  4 feat (makale)
    feats.extend(abs_max_windowed(x))   #  4 feat (makale)
    feats.extend(tremor_band_power(x))  #  2 feat (yeni)
    feats.extend(hjorth_parameters(x))  #  3 feat (yeni)
    feats.extend(extra_stat_features(x))#  5 feat (yeni)
    feats.extend(wavelet_features(x))   # 12 feat (yeni)
    feats.extend(dominant_freq(x))      #  1 feat (yeni)
    return feats  # 54 feat/kanal

def extract_features_from_segment(sig):
    """
    Tüm kanallara özellik çıkar.
    sig: (n_channels, n_timepoints)
    döndürür: (n_channels * 54,) array
    """
    feats = []
    for ch in range(sig.shape[0]):
        feats.extend(extract_features_per_channel(sig[ch]))
    return np.array(feats, dtype=np.float32)

