# Beklenen cache anahtarları
REQUIRED_CACHE_KEYS = {'patient_df', 'feat_dict', 'raw_dict', 'seg_count_dict'}

def load_cache(path):
    """
    Cache yükle. Eski/farklı formatlı cache varsa None döndür
    (yeni format gerektiriyor — yeniden işlenecek).
    """
    if not os.path.exists(path):
        return None
    try:
        with open(path, 'rb') as f:
            obj = pickle.load(f)
        if not isinstance(obj, dict):
            print(f"  ⚠️  Cache dict değil, atlanıyor: {path}")
            return None
        missing = REQUIRED_CACHE_KEYS - set(obj.keys())
        if missing:
            print(f"  ⚠️  Cache eski format (eksik: {missing}), yeniden işlenecek")
            return None
        return obj
    except Exception as e:
        print(f"  ⚠️  Cache okunamadı ({e}), yeniden işlenecek")
        return None

