# ── L1 Trend Filter (scipy ile — cvxpy gerektirmez) ──────────────────────────
def l1_trend_filter_scipy(y, vlambda=50):
    """
    Orijinal kodun cvxpy versiyonunun scipy karşılığı.
    Gravity offset'i sinyalden çıkarır (piecewise-linear smoothing).
    """
    n = len(y)
    # Second difference matrix D (n-2 x n)
    e = np.ones(n)
    diags = np.array([e, -2*e, e])
    offsets = np.array([0, 1, 2])
    from scipy.sparse import diags as sp_diags
    D = sp_diags(diags, offsets, shape=(n-2, n), format='csc')
    # L1 trend via LASSO approximation: iterative reweighted least squares
    # Bu, cvxpy çözümüne çok yakın sonuç üretir
    from scipy.sparse import eye as sp_eye
    lam = vlambda
    weights = np.ones(n-2)
    x = y.copy()
    for _ in range(20):  # IRLS iterations
        W = sp_diags(weights, 0, format='csc')
        A = sp_eye(n, format='csc') + lam * D.T @ W @ D
        x_new = spsolve(A, y)
        residuals = np.abs(D @ x_new) + 1e-6
        weights = 1.0 / residuals
        if np.max(np.abs(x_new - x)) < 1e-4:
            break
        x = x_new
    return x_new

# ── Dict handling (orijinalden kopyalandı) ────────────────────────────────────
def _flatten_dict(data_dict, tmp_fields, data_dict_flat):
    is_most_inner = True
    for key, item in data_dict.items():
        if isinstance(item, dict):
            is_most_inner = False
            data_dict, tmp_fields, data_dict_flat = _flatten_dict(item, tmp_fields.copy(), data_dict_flat.copy())
        elif isinstance(item, list):
            if len(item) > 0 and isinstance(item[0], dict):
                is_most_inner = False
                for list_item in item:
                    data_dict, tmp_fields, data_dict_flat = _flatten_dict(list_item, tmp_fields.copy(), data_dict_flat.copy())
            else:
                tmp_fields[key] = item
        else:
            tmp_fields[key] = item
    if is_most_inner:
        data_dict_flat.append(tmp_fields)
    return data_dict, tmp_fields, data_dict_flat

def flatten_dict(d):
    _, _, flat = _flatten_dict(d, {}, [])
    return flat

# ── Preprocessing (orijinal run_preprocessing.py'dan) ────────────────────────
TASKS_ORDER = ['Relaxed1','Relaxed2','RelaxedTask1','RelaxedTask2',
               'StretchHold','LiftHold','HoldWeight','PointFinger',
               'DrinkGlas','CrossArms','TouchIndex','TouchNose',
               'Entrainment1','Entrainment2']
REMOVE_TASKS = 'Time|LiftHold|PointFinger|TouchIndex'
PROCESS_SENSOR = 'Accelerometer'

def load_patient_files(patient_dir):
    """Tüm patient JSON dosyalarını yükle."""
    rows = []
    for pf in sorted(glob(f"{patient_dir}/**/*.json", recursive=True)):
        try:
            with open(pf) as f: d = json.load(f)
            flat = flatten_dict(d)
            for row in flat:
                rows.append(row)
        except Exception:
            continue
    if not rows:
        return pd.DataFrame()
    return pd.DataFrame(rows)

def load_observation_files(movement_dir, subject_id):
    """Bir hastanın tüm observation JSON'larını yükle."""
    obs_files = sorted(glob(f"{movement_dir}/**/observation_*{subject_id}*.json", recursive=True))
    if not obs_files:
        obs_files = sorted(glob(f"{movement_dir}/**/{subject_id}*.json", recursive=True))
    return obs_files

def get_signal_from_observation(obs_path):
    """Observation JSON'dan sinyal ve kanal listesi çıkar."""
    with open(obs_path) as f:
        obs = json.load(f)
    flat = flatten_dict(obs)
    if not flat:
        return None, None
    df = pd.DataFrame(flat)
    if 'file_name' not in df.columns:
        return None, None

    all_records, all_channels = [], []
    obs_dir = os.path.dirname(obs_path)

    for _, row in df.iterrows():
        try:
            fname   = row['file_name']
            fpath   = os.path.join(obs_dir, fname)
            if not os.path.exists(fpath):
                fpath = next((f for f in glob(f"{data_path}/**/{fname}", recursive=True)), None)
            if fpath is None or not os.path.exists(fpath):
                continue

            rec = pd.read_csv(fpath, header=None).select_dtypes(include=[np.number]).values
            if rec.ndim == 1:
                rec = rec.reshape(1, -1)
            elif rec.shape[0] > rec.shape[1]:
                rec = rec.T  # (channels, time)

            channels = row.get('channels', [])
            if isinstance(channels, str):
                channels = channels.strip('[]').replace("'","").split(', ')

            loc    = str(row.get('device_location', 'Unknown'))
            rname  = str(row.get('record_name', 'Unk'))
            rows_n = int(row.get('rows', rec.shape[1]))
            min_rows = rows_n  # basit

            n_splits = rec.shape[1] // min_rows if min_rows > 0 else 1
            ch_names = [f"{rname}_{loc}_{ch}" for ch in channels]

            if n_splits > 1:
                step = rec.shape[1] // n_splits
                for k in range(n_splits):
                    seg = rec[:, k*step:(k+1)*step]
                    new_names = [f"{rname}{k+1}_{loc}_{ch}" for ch in channels]
                    all_records.append(seg)
                    all_channels.extend(new_names)
            else:
                all_records.append(rec)
                all_channels.extend(ch_names)
        except Exception:
            continue

    if not all_records:
        return None, None

    # Tüm segmentleri aynı uzunluğa getir
    min_len = min(r.shape[1] for r in all_records)
    all_records = [r[:, :min_len] for r in all_records]
    try:
        data = np.concatenate(all_records, axis=0)
    except Exception:
        return None, None

    return data, all_channels

def build_channel_order(channels):
    """Orijinal preprocessing'deki sıralama."""
    ordered, ch_idx = [], {c: i for i, c in enumerate(channels)}
    for task in TASKS_ORDER:
        for wrist in ['LeftWrist','RightWrist']:
            for sensor in ['Time','Accelerometer','Gyroscope']:
                if sensor == 'Time':
                    ch = f"{task}_{wrist}_{sensor}"
                    if ch in ch_idx: ordered.append(ch_idx[ch])
                else:
                    for axis in ['X','Y','Z']:
                        ch = f"{task}_{wrist}_{sensor}_{axis}"
                        if ch in ch_idx: ordered.append(ch_idx[ch])
    # Bulamayanları sona ekle
    found = set(ordered)
    for i in range(len(channels)):
        if i not in found: ordered.append(i)
    return ordered

def preprocess_patient_movement(subject_id, movement_dir_path, out_path, overwrite=False):
    """
    Orijinal preprocess_movement() fonksiyonunun Colab uyumlu versiyonu.
    """
    out_file = os.path.join(out_path, f"{subject_id:03d}_ml.bin")
    if os.path.exists(out_file) and not overwrite:
        return True

    # Observation dosyalarını bul
    obs_files = sorted(glob(f"{movement_dir_path}/**/*{subject_id:03d}*.json", recursive=True))
    obs_files += sorted(glob(f"{movement_dir_path}/**/*{subject_id}*.json", recursive=True))
    obs_files = list(dict.fromkeys(obs_files))  # deduplicate

    if not obs_files:
        return False

    all_data, all_channels = [], []
    for obs_f in obs_files:
        d, c = get_signal_from_observation(obs_f)
        if d is not None:
            all_data.append(d)
            all_channels.extend(c)

    if not all_data:
        return False

    try:
        # Uniform zaman ekseni
        min_t = min(d.shape[1] for d in all_data)
        all_data = [d[:, :min_t] for d in all_data]
        data = np.concatenate(all_data, axis=0)
        channels = np.array(all_channels)
    except Exception:
        return False

    # Kanal sıralaması (orijinal ile aynı)
    sort_idx = build_channel_order(list(channels))
    if len(sort_idx) == len(channels):
        data     = data[sort_idx]
        channels = channels[sort_idx]

    # Zaman ve kaldırılacak görevleri filtrele
    keep_mask    = ~pd.Series(channels).str.contains(REMOVE_TASKS, na=False).values
    process_mask = pd.Series(channels[keep_mask]).str.contains(PROCESS_SENSOR, na=False).values

    data     = data[keep_mask]
    channels = channels[keep_mask]

    # L1 trend filter ile gravity offset kaldır (sadece Accelerometer kanallarında)
    for i in np.where(process_mask)[0]:
        try:
            trend = l1_trend_filter_scipy(data[i], vlambda=50)
            data[i] = data[i] - trend
        except Exception:
            pass  # hata olursa ham sinyal kullan

    # İlk 48 sample at (smartwatch titreşimi) — makale: 0.5s @ 100Hz
    data = data[:, 48:]

    # .bin'e kaydet (float32)
    data.astype(np.float32).tofile(out_file)
    return True

def preprocess_questionnaire(subject_id, quest_dir_path, out_path, overwrite=False):
    """NMS anketini 30-element float32 vektörüne çevir."""
    out_file = os.path.join(out_path, f"{subject_id:03d}_ml.bin")
    if os.path.exists(out_file) and not overwrite:
        return True

    q_files = sorted(glob(f"{quest_dir_path}/**/*{subject_id:03d}*.json", recursive=True))
    q_files += sorted(glob(f"{quest_dir_path}/**/*{subject_id}*.json", recursive=True))
    q_files = list(dict.fromkeys(q_files))

    answers = [0.0] * 30
    found = False
    for qf in q_files:
        try:
            with open(qf) as f: q = json.load(f)
            flat = flatten_dict(q)
            for row in flat:
                link = str(row.get('link_id', ''))
                ans  = row.get('answer', None)
                try:
                    i = int(link) - 1
                    if 0 <= i < 30:
                        answers[i] = 1.0 if ans else 0.0
                        found = True
                except Exception:
                    pass
        except Exception:
            continue

    if not found:
        return False

    np.array(answers, dtype=np.float32).tofile(out_file)
    return True

