# ── ML Feature extraction (makalenin Option A) ────────────────────────────────
# Orijinal feature_extraction.py

def bandpower(x, srate=100, steps=100, cut=(1,20), scale=True):
    fs, pxx = welch(x, fs=srate, nperseg=steps, scaling="density")
    bp = pxx[cut[0]:cut[1]]
    if scale:
        bp = np.log10(bp + 1e-12)
    return bp

def std_windowed(x):
    l = len(x)//4
    return [np.std(x[n*l:(n+1)*l]) for n in range(4)]

def abs_energy_windowed(x):
    l = len(x)//4
    return [np.sum(np.abs(x[n*l:(n+1)*l])) for n in range(4)]

def abs_max_windowed(x):
    l = len(x)//4
    return [np.max(np.abs(x[n*l:(n+1)*l])) for n in range(4)]

def feature_extraction_paper(x):
    """Makalenin tam feature pipeline'ı — x: (n_channels, n_time)"""
    feats = []
    for fn in [bandpower, std_windowed, abs_energy_windowed, abs_max_windowed]:
        feats.append(np.apply_along_axis(fn, 1, x))
    feats = np.concatenate(feats, axis=1).flatten()
    return feats

# ── Veri yükleme (orijinal get_dataset) ──────────────────────────────────────
SEQ_LEN_MOVEMENT = 976  # Makale: 10s @ ~100Hz = 976 samples (ilk 48 atıldıktan sonra)

def load_movement_dataset(mode=None, channel_filter=None, apply_feat_extraction=False):
    """
    Orijinal get_dataset(type='movement') karşılığı.
    channel_filter: 'Acceleration', 'Rotation', veya None (Both)
    """
    fl = file_list.copy()
    if mode == 'pd_vs_hc':
        fl = fl[fl['label'].isin([0,1])].copy()
    elif mode == 'pd_vs_dd':
        fl = fl[fl['label'].isin([1,2])].copy()
        fl['label'] = fl['label'].map({1:0, 2:1})

    # Tüm kanal isimleri (makale get_channels())
    all_channels = []
    for task in ['Relaxed1','Relaxed2','RelaxedTask1','RelaxedTask2','StretchHold',
                 'HoldWeight','DrinkGlas','CrossArms','TouchNose','Entrainment1','Entrainment2']:
        for wrist in ['LeftWrist','RightWrist']:
            for sensor in ['Acceleration','Rotation']:
                for axis in ['X','Y','Z']:
                    all_channels.append(f"{task}_{sensor}_{wrist}_{axis}")
    channels = pd.Series(all_channels)

    if channel_filter and channel_filter != 'Both':
        mask = channels.str.contains(channel_filter)
        channels = channels[mask]

    X, y_arr = [], fl['label'].values
    for sid in fl['id'].values:
        fpath = f"{PREPROCESSED}/movement/{sid:03d}_ml.bin"
        if not os.path.exists(fpath):
            X.append(np.zeros((len(channels), SEQ_LEN_MOVEMENT), dtype=np.float32))
            continue
        raw = np.fromfile(fpath, dtype=np.float32)
        # Reshape: (n_channels_total, seq_len)
        n_ch_total = len(all_channels)
        if raw.size == 0:
            X.append(np.zeros((len(channels), SEQ_LEN_MOVEMENT), dtype=np.float32))
            continue
        seq_len_actual = raw.size // n_ch_total if raw.size >= n_ch_total else raw.size // max(1, len(channels))
        try:
            data = raw.reshape((n_ch_total, -1))
        except ValueError:
            # Boyut uyumsuzluğu — en yakın şekle koy
            usable = (raw.size // n_ch_total) * n_ch_total
            data = raw[:usable].reshape((n_ch_total, -1))

        if channel_filter and channel_filter != 'Both':
            orig_ch = pd.Series(all_channels)
            fmask   = orig_ch.str.contains(channel_filter).values
            data    = data[fmask]

        # SEQ_LEN_MOVEMENT uzunluğuna kırp/pad
        t = data.shape[1]
        if t >= SEQ_LEN_MOVEMENT:
            data = data[:, :SEQ_LEN_MOVEMENT]
        else:
            data = np.pad(data, ((0,0),(0,SEQ_LEN_MOVEMENT-t)))

        if apply_feat_extraction:
            data = feature_extraction_paper(data)

        X.append(data)

    X = np.stack(X)
    c = fl['gender'].values if 'gender' in fl.columns else np.zeros(len(fl), dtype=str)
    return X, y_arr, channels.values, c

def load_questionnaire_dataset(mode=None):
    """Orijinal get_dataset(type='questionnaire') karşılığı."""
    fl = file_list.copy()
    if mode == 'pd_vs_hc':
        fl = fl[fl['label'].isin([0,1])].copy()
    elif mode == 'pd_vs_dd':
        fl = fl[fl['label'].isin([1,2])].copy()
        fl['label'] = fl['label'].map({1:0, 2:1})

    X, y_arr = [], fl['label'].values
    for sid in fl['id'].values:
        fpath = f"{PREPROCESSED}/questionnaire/{sid:03d}_ml.bin"
        if os.path.exists(fpath):
            data = np.fromfile(fpath, dtype=np.float32)
            if len(data) < 30:
                data = np.zeros(30, dtype=np.float32)
        else:
            data = np.zeros(30, dtype=np.float32)
        X.append(data[:30])

    X = np.stack(X)
    c = fl['gender'].values if 'gender' in fl.columns else np.zeros(len(fl), dtype=str)
    return X, y_arr, np.array([f"NMS_{n:02d}" for n in range(1,31)]), c

# ── Sample weighting (orijinal ile aynı) ─────────────────────────────────────
def get_balanced_weights(y, c=None):
    """Makalenin sample weighting: gender + label grupları."""
    if c is not None:
        combined = np.array([f"{yi}_{ci}" for yi,ci in zip(y.astype(str), c.astype(str))])
    else:
        combined = y.astype(str)
    weights = np.zeros(len(combined), dtype=np.float32)
    for lbl in np.unique(combined):
        cnt = np.sum(combined == lbl)
        weights[combined == lbl] = len(combined) / (len(np.unique(combined)) * cnt)
    return weights

# ── MultiBOSS (data leakage DÜZELTİLDİ: cache yok, fold'da sıfırdan fit) ─────
class MultiBOSS:
    """
    Orijinal multi_boss.py — hash cache KALDIRILDI (data leakage vardı).
    Her fold'da sıfırdan fit edilir.
    """
    def __init__(self, data_shape, window_sizes=(20,40,80), window_step=2, word_size=4, n_bins=4):
        self.data_shape   = data_shape
        self.window_sizes = window_sizes
        self.window_step  = window_step
        self.word_size    = word_size
        self.n_bins       = n_bins
        self.boss_list_   = None

    def _make_list(self):
        bl = []
        for _ in range(self.data_shape[0]):
            for ws in self.window_sizes:
                bl.append(BOSS(sparse=False, window_size=ws, window_step=self.window_step,
                               word_size=self.word_size, n_bins=self.n_bins,
                               norm_std=False, norm_mean=False, anova=False, drop_sum=False))
        return bl

    def fit(self, X, y):
        self.boss_list_ = self._make_list()
        i = 0
        for ch in range(self.data_shape[0]):
            for _ in self.window_sizes:
                self.boss_list_[i].fit(X[:,ch,:], y)
                i += 1
        return self

    def transform(self, X):
        out, i = [], 0
        for ch in range(self.data_shape[0]):
            for _ in self.window_sizes:
                out.append(self.boss_list_[i].transform(X[:,ch,:]))
                i += 1
        return np.concatenate(out, axis=1).astype(np.float32)

    def fit_transform(self, X, y):
        return self.fit(X,y).transform(X)

# ── Pipeline kurucular ────────────────────────────────────────────────────────
def make_pipeline_A_svm():
    return Pipeline([
        ('scaler', StandardScaler()),
        ('clf',    SVC(probability=False, random_state=RANDOM_STATE)),
    ])

def make_pipeline_A_cat():
    return Pipeline([
        ('scaler', 'passthrough'),
        ('clf',    CatBoostClassifier(random_state=RANDOM_STATE, verbose=False)),
    ])

def make_pipeline_D_cat():
    return Pipeline([
        ('scaler', 'passthrough'),
        ('clf',    CatBoostClassifier(random_state=RANDOM_STATE, verbose=False)),
    ])

HYPERPARAMS = {
    'svm': {'clf__C': [0.1,1.0,10.0,100.0], 'clf__gamma': ['scale']},
    'cat': {'clf__num_trees': [500], 'clf__depth': [4,5,6], 'scaler': ['passthrough']},
}

# ── Metrikler (orijinal ile aynı, roc_auc HARİÇ — SVC probability=False) ─────
def compute_metrics(y_true, y_pred):
    return {
        'balanced_accuracy': balanced_accuracy_score(y_true, y_pred),
        'f1'               : f1_score(y_true, y_pred, zero_division=0),
        'precision'        : precision_score(y_true, y_pred, zero_division=0),
        'recall'           : recall_score(y_true, y_pred, zero_division=0),
    }

def print_fold_scores(scores):
    for k,v in scores.items():
        print(f"    {k:25s}: {np.mean(v)*100:.2f}% ± {np.std(v)*100:.2f}%")

# ── ANA 5-FOLD CV (makalenin yöntemi) ────────────────────────────────────────
def run_mode(mode):
    print(f"\n{'='*70}")
    print(f"🔬 MODE: {mode.upper()}")
    print(f"{'='*70}")

    cv = StratifiedKFold(n_splits=N_FOLDS, shuffle=True, random_state=RANDOM_STATE)

    # ── Option A: Handcrafted + SVM ──────────────────────────────────────────
    print("\n[Option A] Handcrafted features + SVM")
    # Her channel_filter için en iyi sonucu al (makale: best per fold seçiyor)
    best_configs = ['Acceleration', 'Rotation', 'Both']

    X_mov_feat = {}
    for cf in best_configs:
        print(f"  Loading {cf}...", end=" ")
        X, y_mov, ch, c_mov = load_movement_dataset(mode=mode, channel_filter=cf,
                                                     apply_feat_extraction=True)
        X_mov_feat[cf] = (X, y_mov, c_mov)
        print(f"shape={X.shape}")

    scores_A = {'balanced_accuracy':[], 'f1':[], 'precision':[], 'recall':[]}
    scores_B = {'balanced_accuracy':[], 'f1':[], 'precision':[], 'recall':[]}
    scores_D = {'balanced_accuracy':[], 'f1':[], 'precision':[], 'recall':[]}
    scores_S = {'balanced_accuracy':[], 'f1':[], 'precision':[], 'recall':[]}

    # Option D (questionnaire) için veri — bir kez yükle
    print("\n[Option D] Questionnaire NMS")
    X_quest, y_quest, ch_quest, c_quest = load_questionnaire_dataset(mode=mode)
    print(f"  shape={X_quest.shape}")

    # Option B (BOSS) için veri — bir kez yükle (ham sinyal)
    print("\n[Option B] BOSS feature extraction")
    X_mov_raw = {}
    for cf in best_configs:
        X, y_r, ch_r, c_r = load_movement_dataset(mode=mode, channel_filter=cf,
                                                    apply_feat_extraction=False)
        X_mov_raw[cf] = (X, y_r, ch_r, c_r)
        print(f"  {cf}: shape={X.shape}")

    for fold_idx, (tr_i, te_i) in enumerate(cv.split(X_quest, y_quest), 1):
        print(f"\n  ── FOLD {fold_idx}/{N_FOLDS} ── RAM: {ram()}")
        y_tr = y_quest[tr_i]; y_te = y_quest[te_i]
        c_tr = c_quest[tr_i]
        sw   = get_balanced_weights(y_tr, c_tr)

        # ── Option A: Handcrafted + GridSearch ──────────────────────────────
        best_A_score, best_A_pred = -1, None
        inner_cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=RANDOM_STATE)

        for cf in best_configs:
            X_f, _, _ = X_mov_feat[cf]
            X_tr_f, X_te_f = X_f[tr_i], X_f[te_i]

            for clf_name, make_fn in [('svm', make_pipeline_A_svm), ('cat', make_pipeline_A_cat)]:
                try:
                    est = GridSearchCV(make_fn(), HYPERPARAMS[clf_name],
                                       cv=inner_cv, scoring='balanced_accuracy', n_jobs=-1)
                    est.fit(X_tr_f, y_tr, clf__sample_weight=sw if clf_name=='cat' else None)
                    pred = est.predict(X_te_f)
                    s    = balanced_accuracy_score(y_te, pred)
                    if s > best_A_score:
                        best_A_score = s
                        best_A_pred  = pred
                        best_A_proba = est.best_estimator_.predict_proba(X_te_f)[:,1] if hasattr(est.best_estimator_['clf'], 'predict_proba') else None
                except Exception as e:
                    pass
        if best_A_pred is not None:
            for k,v in compute_metrics(y_te, best_A_pred).items():
                scores_A[k].append(v)
            print(f"    Option A: BalAcc={best_A_score*100:.2f}%")

        # ── Option B: BOSS + GridSearch ──────────────────────────────────────
        best_B_score, best_B_pred = -1, None

        for cf in best_configs:
            X_r, _, ch_r, _ = X_mov_raw[cf]
            X_tr_r, X_te_r = X_r[tr_i], X_r[te_i]
            data_shape = X_tr_r.shape[1:]  # (n_ch, n_time)

            for clf_name in ['svm', 'cat']:
                try:
                    boss = MultiBOSS(data_shape=data_shape, window_sizes=(20,40,80))
                    X_tr_boss = boss.fit_transform(X_tr_r, y_tr)  # FIT sadece train!
                    X_te_boss = boss.transform(X_te_r)

                    if clf_name == 'svm':
                        inner_preds = []
                        for C in [0.1, 1.0, 10.0, 100.0]:
                            p = Pipeline([('sc', StandardScaler()),
                                           ('clf', SVC(C=C, gamma='scale', random_state=RANDOM_STATE))])
                            # Inner CV score
                            inner_scores = []
                            for ti, vi in inner_cv.split(X_tr_boss, y_tr):
                                p.fit(X_tr_boss[ti], y_tr[ti])
                                inner_scores.append(balanced_accuracy_score(y_tr[vi], p.predict(X_tr_boss[vi])))
                            inner_preds.append((np.mean(inner_scores), C))
                        best_C = max(inner_preds, key=lambda x: x[0])[1]
                        p = Pipeline([('sc', StandardScaler()),
                                       ('clf', SVC(C=best_C, gamma='scale', random_state=RANDOM_STATE))])
                        p.fit(X_tr_boss, y_tr)
                        pred = p.predict(X_te_boss)
                    else:
                        inner_scores_cat = []
                        for depth in [4,5,6]:
                            clf_tmp = CatBoostClassifier(num_trees=500, depth=depth,
                                                          random_state=RANDOM_STATE, verbose=False)
                            _s = []
                            for ti, vi in inner_cv.split(X_tr_boss, y_tr):
                                clf_tmp.fit(X_tr_boss[ti], y_tr[ti], sample_weight=sw[ti])
                                _s.append(balanced_accuracy_score(y_tr[vi], clf_tmp.predict(X_tr_boss[vi])))
                            inner_scores_cat.append((np.mean(_s), depth))
                        best_depth = max(inner_scores_cat, key=lambda x: x[0])[1]
                        clf_b = CatBoostClassifier(num_trees=500, depth=best_depth,
                                                    random_state=RANDOM_STATE, verbose=False)
                        clf_b.fit(X_tr_boss, y_tr, sample_weight=sw)
                        pred = clf_b.predict(X_te_boss)

                    s = balanced_accuracy_score(y_te, pred)
                    if s > best_B_score:
                        best_B_score = s
                        best_B_pred  = pred

                    del boss, X_tr_boss, X_te_boss
                    gc.collect()
                except Exception as e:
                    pass

        if best_B_pred is not None:
            for k,v in compute_metrics(y_te, best_B_pred).items():
                scores_B[k].append(v)
            print(f"    Option B: BalAcc={best_B_score*100:.2f}%")

        # ── Option D: NMS questionnaire + CatBoost ───────────────────────────
        X_q_tr, X_q_te = X_quest[tr_i], X_quest[te_i]
        best_D_score, best_D_pred, best_D_proba = -1, None, None
        for depth in [4,5,6]:
            try:
                clf_d = CatBoostClassifier(num_trees=500, depth=depth,
                                            random_state=RANDOM_STATE, verbose=False)
                clf_d.fit(X_q_tr, y_tr, sample_weight=sw)
                pred_d = clf_d.predict(X_q_te)
                s_d    = balanced_accuracy_score(y_te, pred_d)
                if s_d > best_D_score:
                    best_D_score = s_d
                    best_D_pred  = pred_d
                    best_D_proba = clf_d.predict_proba(X_q_te)[:,1]
            except Exception:
                pass

        if best_D_pred is not None:
            for k,v in compute_metrics(y_te, best_D_pred).items():
                scores_D[k].append(v)
            print(f"    Option D: BalAcc={best_D_score*100:.2f}%")

        # ── Stacking: Movement (best of A,B) + Quest (D) ─────────────────────
        # Orijinal: LogisticRegression meta-classifier
        # OOF üzerinde eğit (leakage yok)
        try:
            inner_cv3 = StratifiedKFold(n_splits=5, shuffle=True, random_state=RANDOM_STATE)

            # En iyi movement modeli seç (A veya B, whichever higher inner score)
            # Basit: best_B_pred kullan (makale BOSS'u genellikle seçiyor)
            mov_pred_tr  = np.zeros(len(tr_i))
            quest_pred_tr = np.zeros(len(tr_i))

            # Inner OOF — movement
            best_mov_oof_score = -1
            best_cf_for_stack  = 'Rotation'
            for cf in best_configs:
                X_r, _, _, _ = X_mov_raw[cf]
                X_tr_r = X_r[tr_i]
                oof_preds = np.zeros(len(tr_i))
                for ti, vi in inner_cv3.split(X_tr_r, y_tr):
                    b = MultiBOSS(data_shape=X_tr_r.shape[1:], window_sizes=(20,40,80))
                    Xb_tr = b.fit_transform(X_tr_r[ti], y_tr[ti])
                    Xb_val = b.transform(X_tr_r[vi])
                    sc_tmp = StandardScaler()
                    p_tmp  = Pipeline([('sc', StandardScaler()),
                                        ('clf', SVC(C=10.0, gamma='scale', random_state=RANDOM_STATE))])
                    p_tmp.fit(Xb_tr, y_tr[ti])
                    oof_preds[vi] = p_tmp.predict(Xb_val)
                s = balanced_accuracy_score(y_tr, oof_preds)
                if s > best_mov_oof_score:
                    best_mov_oof_score = s
                    mov_pred_tr = oof_preds
                    best_cf_for_stack = cf

            # Inner OOF — questionnaire
            for ti, vi in inner_cv3.split(X_q_tr, y_tr):
                c_tmp2 = CatBoostClassifier(num_trees=500, depth=5,
                                            random_state=RANDOM_STATE, verbose=False)
                c_tmp2.fit(X_q_tr[ti], y_tr[ti], sample_weight=sw[ti])
                quest_pred_tr[vi] = c_tmp2.predict(X_q_tr[vi])

            # Meta-learner eğitimi (OOF üzerinde)
            meta_tr = np.column_stack([mov_pred_tr, quest_pred_tr])
            meta_lr = LogisticRegression(C=1.0, max_iter=1000, random_state=RANDOM_STATE)
            meta_lr.fit(meta_tr, y_tr)

            # Test tahminleri — full train fold ile sub-classifiers yeniden eğitilir
            X_r_full, _, _, _ = X_mov_raw[best_cf_for_stack]
            boss_full = MultiBOSS(data_shape=X_r_full[tr_i].shape[1:], window_sizes=(20,40,80))
            Xb_full_tr = boss_full.fit_transform(X_r_full[tr_i], y_tr)
            Xb_full_te = boss_full.transform(X_r_full[te_i])
            svc_full   = Pipeline([('sc', StandardScaler()),
                                    ('clf', SVC(C=10.0, gamma='scale', random_state=RANDOM_STATE))])
            svc_full.fit(Xb_full_tr, y_tr)
            mov_pred_te = svc_full.predict(Xb_full_te)

            cat_full2 = CatBoostClassifier(num_trees=500, depth=5,
                                           random_state=RANDOM_STATE, verbose=False)
            cat_full2.fit(X_q_tr, y_tr, sample_weight=sw)
            quest_pred_te = cat_full2.predict(X_q_te)

            meta_te = np.column_stack([mov_pred_te, quest_pred_te])
            stack_pred = meta_lr.predict(meta_te)
            s_stack = balanced_accuracy_score(y_te, stack_pred)

            for k,v in compute_metrics(y_te, stack_pred).items():
                scores_S[k].append(v)
            print(f"    Stacking: BalAcc={s_stack*100:.2f}%")

            del boss_full, Xb_full_tr, Xb_full_te
            gc.collect()

        except Exception as e:
            print(f"    ⚠ Stacking hatası: {e}")

    # ── Sonuçlar ──────────────────────────────────────────────────────────────
    print(f"\n  ── {mode.upper()} SONUÇLARI ──")
    for label, sc in [("Option A (Handcrafted+SVM/CAT)", scores_A),
                       ("Option B (BOSS+SVM/CAT)",        scores_B),
                       ("Option D (NMS+CatBoost)",        scores_D),
                       ("STACKING (Mov+Quest)",           scores_S)]:
        if sc['balanced_accuracy']:
            ba = np.mean(sc['balanced_accuracy'])*100
            f1 = np.mean(sc['f1'])*100
            print(f"\n  {label}")
            print(f"    BalAcc={ba:.2f}% ± {np.std(sc['balanced_accuracy'])*100:.2f}%  "
                  f"F1={f1:.2f}%  "
                  f"Folds={[f'{v*100:.1f}%' for v in sc['balanced_accuracy']]}")

    return {'A': scores_A, 'B': scores_B, 'D': scores_D, 'S': scores_S}

# ── Çalıştır ──────────────────────────────────────────────────────────────────
all_results = {}
for mode in ['pd_vs_hc', 'pd_vs_dd']:
    all_results[mode] = run_mode(mode)

# ── Final özet ────────────────────────────────────────────────────────────────
paper = {
    'pd_vs_hc': {'A': 78.99, 'B': 78.99, 'D': 89.79, 'S': 91.16},
    'pd_vs_dd': {'A': 69.18, 'B': 69.18, 'D': 67.77, 'S': 72.42},
}

print(f"\n{'='*70}")
print("🏆 FINAL ÖZET")
print(f"{'='*70}")
print(f"{'Mode':<12} {'Option':<30} {'Bizim':>8} {'Makale':>8} {'Fark':>8}")
print(f"{'-'*70}")
for mode in ['pd_vs_hc', 'pd_vs_dd']:
    for opt, label in [('A','Handcrafted'),('B','BOSS'),('D','NMS-Quest'),('S','Stacking')]:
        sc = all_results[mode].get(opt, {})
        if sc.get('balanced_accuracy'):
            ba = np.mean(sc['balanced_accuracy'])*100
            pb = paper.get(mode,{}).get(opt, 0)
            print(f"  {mode:<12} {label:<28} {ba:>7.2f}%  {pb:>7.2f}%  {ba-pb:>+7.2f}%")

# Sonuç dosyası
try:
    lines = []
    for mode in ['pd_vs_hc','pd_vs_dd']:
        for opt, label in [('A','Handcrafted'),('B','BOSS'),('D','NMS-Quest'),('S','Stacking')]:
            sc = all_results[mode].get(opt,{})
            if sc.get('balanced_accuracy'):
                ba = np.mean(sc['balanced_accuracy'])*100
                lines.append(f"{mode} | {label}: {ba:.2f}%")
    report = "\n".join(lines)
    with open(f"{OUTPUT_DIR}/results.txt",'w') as f: f.write(report)
    shutil.copy2(f"{OUTPUT_DIR}/results.txt",
                 "/content/drive/MyDrive/Parkinson/pads_results.txt")
    print(f"\n✅ Sonuçlar kaydedildi!")
except Exception as e:
    print(f"⚠ Kayıt: {e}")

print("\n✅ Tamamlandı!")

