# ─────────────────────────────────────────────────────────────────────────────
# L1 TREND FİLTER — orijinal l1_trend_filter.py scipy ile
# ─────────────────────────────────────────────────────────────────────────────
def l1_trend_filter(y, vlambda=50):
    from scipy.sparse import diags, eye
    n = len(y)
    e = np.ones(n)
    D = diags([e, -2*e, e], [0, 1, 2], shape=(n-2, n), format='csc')
    w = np.ones(n-2); x = y.copy()
    for _ in range(30):
        W  = diags(w, 0, format='csc')
        A  = eye(n, format='csc') + vlambda * (D.T @ W @ D)
        xn = spsolve(A, y)
        w  = 1.0 / (np.abs(D @ xn) + 1e-6)
        if np.max(np.abs(xn - x)) < 1e-4: break
        x  = xn
    return xn

# ─────────────────────────────────────────────────────────────────────────────
# DICT FLATTEN — orijinal dict_handling.py birebir
# ─────────────────────────────────────────────────────────────────────────────
def _flatten_dict(data_dict, tmp_fields, data_dict_flat):
    is_most_inner = True
    for key, item in data_dict.items():
        if isinstance(item, dict):
            is_most_inner = False
            data_dict, tmp_fields, data_dict_flat = _flatten_dict(item, tmp_fields.copy(), data_dict_flat.copy())
        elif isinstance(item, list):
            if isinstance(item[0], dict) if item else False:
                is_most_inner = False
                for list_item in item:
                    data_dict, tmp_fields, data_dict_flat = _flatten_dict(list_item, tmp_fields.copy(), data_dict_flat.copy())
            else:
                tmp_fields[key] = item
        else:
            tmp_fields[key] = item
    if is_most_inner:
        data_dict_flat.append(tmp_fields)
    return data_dict, tmp_fields, data_dict_flat

def flatten_dict(data_dict):
    tmp_fields = {}
    data_dict_flat = []
    _, _, data_dict_flat = _flatten_dict(data_dict, tmp_fields, data_dict_flat)
    return data_dict_flat

