TASKS_FULL = ['Relaxed1','Relaxed2','RelaxedTask1','RelaxedTask2','StretchHold',
              'LiftHold','HoldWeight','PointFinger','DrinkGlas','CrossArms',
              'TouchIndex','TouchNose','Entrainment1','Entrainment2']
LABEL_MAP = {
    'Healthy': 0, "Parkinson's": 1,
    'Other Movement Disorders': 2, 'Essential Tremor': 2,
    'Multiple Sclerosis': 2, 'Atypical Parkinsonism': 2,
}

def get_signal_from_observation(obs_path, data_root):
    """Orijinal get_data_from_observation() karşılığı."""
    try:
        with open(obs_path) as f: obs = json.load(f)
        rows = flatten_dict(obs)
        if not rows: return None, None
        df = pd.DataFrame(rows)
        if 'file_name' not in df.columns: return None, None
        obs_dir = os.path.dirname(obs_path)

        all_records, all_channels = [], []
        min_rows = df['rows'].min() if 'rows' in df.columns else None

        for _, row in df.iterrows():
            try:
                fname = row['file_name']
                fpath = os.path.join(obs_dir, fname)
                if not os.path.exists(fpath):
                    fpath = next((f for f in glob(f"{data_root}/**/{fname}", recursive=True)), None)
                if not fpath or not os.path.exists(fpath): continue

                # Orijinal: np.loadtxt + np.swapaxes
                record = np.loadtxt(fpath, dtype=np.float32, delimiter=",")
                if record.ndim == 1: record = record.reshape(1, -1)
                record = np.swapaxes(record, 0, 1)  # (channels, time)

                channels = row.get('channels', [])
                if isinstance(channels, str):
                    channels = [c.strip().strip("'") for c in channels.strip('[]').split(',')]

                loc  = str(row.get('device_location', 'Unk'))
                rn   = str(row.get('record_name', 'Unk'))
                rows_val = int(row.get('rows', record.shape[1]))
                mr   = int(min_rows) if min_rows is not None else rows_val
                n_splits = rows_val // mr if mr > 0 else 1
                step = record.shape[1] // n_splits

                if n_splits > 1:
                    new_record = []
                    for n in range(0, record.shape[1], step):
                        new_record.append(record[:, n:n+step])
                    record = np.concatenate(new_record, axis=0)
                    new_channels = []
                    for n in range(n_splits):
                        for ch in channels:
                            new_channels.append(f'{rn}{n+1}_{loc}_{ch}')
                    channels = new_channels
                else:
                    channels = [f'{rn}_{loc}_{ch}' for ch in channels]

                all_records.append(record)
                all_channels.extend(channels)
            except Exception:
                continue

        if not all_records: return None, None
        all_records = np.concatenate(all_records, axis=0)
        return all_records, all_channels
    except Exception:
        return None, None

def preprocess_movement(subject_id, movement_dir, out_dir, overwrite=False):
    """Orijinal preprocess_movement() birebir."""
    out_file = f"{out_dir}/{subject_id:03d}_ml.bin"
    if os.path.exists(out_file) and not overwrite: return True

    obs_files = sorted(set(
        glob(f"{movement_dir}/**/*{subject_id:03d}*.json", recursive=True) +
        glob(f"{movement_dir}/**/*{subject_id:04d}*.json", recursive=True)
    ))
    if not obs_files: return False

    all_data, all_channels = [], []
    for of in obs_files:
        d, c = get_signal_from_observation(of, DATA_PATH)
        if d is not None: all_data.append(d); all_channels.extend(c)
    if not all_data: return False

    try:
        min_t = min(x.shape[1] for x in all_data)
        data  = np.concatenate([x[:, :min_t] for x in all_data], axis=0)
        channels = np.array(all_channels)
    except Exception: return False

    # Orijinal kanal sıralaması
    sort_idx = []
    ch_list  = list(channels)
    for task in TASKS_FULL:
        for wrist in ['LeftWrist', 'RightWrist']:
            for sensor in ['Time', 'Accelerometer', 'Gyroscope']:
                if sensor == 'Time':
                    ch = f"{task}_{wrist}_{sensor}"
                    if ch in ch_list: sort_idx.append(ch_list.index(ch))
                else:
                    for ax in ['X', 'Y', 'Z']:
                        ch = f"{task}_{wrist}_{sensor}_{ax}"
                        if ch in ch_list: sort_idx.append(ch_list.index(ch))
    if sort_idx: data = data[sort_idx]; channels = channels[sort_idx]

    # Kaldır: Time, LiftHold, PointFinger, TouchIndex
    keep = ~pd.Series(channels).str.contains('Time|LiftHold|PointFinger|TouchIndex', na=False).values
    data     = data[keep]
    channels = channels[keep]

    # L1 trend filter (sadece Accelerometer)
    acc_mask = pd.Series(channels).str.contains('Accelerometer', na=False).values
    for i in np.where(acc_mask)[0]:
        try: data[i] = data[i] - l1_trend_filter(data[i], vlambda=50)
        except: pass

    # İlk 48 sample at
    data = data[:, 48:]
    data.astype(np.float32).tofile(out_file)
    return True

def preprocess_questionnaire(subject_id, quest_dir, out_dir, overwrite=False):
    """Orijinal questionnaire preprocessing."""
    out_file = f"{out_dir}/{subject_id:03d}_ml.bin"
    if os.path.exists(out_file) and not overwrite: return True

    q_files = sorted(set(
        glob(f"{quest_dir}/**/*{subject_id:03d}*.json", recursive=True) +
        glob(f"{quest_dir}/**/*{subject_id:04d}*.json", recursive=True)
    ))
    answers, found = [0.0] * 30, False
    for qf in q_files:
        try:
            with open(qf) as f: q = json.load(f)
            for row in flatten_dict(q):
                try:
                    i = int(str(row.get('link_id', '99'))) - 1
                    if 0 <= i < 30:
                        answers[i] = 1.0 if row.get('answer') else 0.0
                        found = True
                except: pass
        except: continue
    if not found: return False
    np.array(answers, dtype=np.float32).tofile(out_file)
    return True

