# ─────────────────────────────────────────────────────────────────────────────
# ML UTILS — orijinal ml/utils.py birebir
# ─────────────────────────────────────────────────────────────────────────────

def get_channels(type="movement"):
    """Orijinal get_channels() birebir."""
    channels = []
    if type == "movement":
        for task in ["Relaxed1","Relaxed2","RelaxedTask1","RelaxedTask2","StretchHold",
                     "HoldWeight","DrinkGlas","CrossArms","TouchNose","Entrainment1","Entrainment2"]:
            for device_location in ["LeftWrist","RightWrist"]:
                for sensor in ["Acceleration","Rotation"]:
                    for axis in ["X","Y","Z"]:
                        channels.append(f"{task}_{sensor}_{device_location}_{axis}")
    elif type == "questionnaire":
        channels = [f"NMS_{n:02d}" for n in range(1, 31)]
    return channels

def get_file_list(mode=None):
    """Orijinal get_file_list() birebir."""
    file_list = FILE_LIST.copy()
    if mode == "pd_vs_hc":
        file_list = file_list.loc[(file_list["label"]==0)|(file_list["label"]==1)]
    if mode == "pd_vs_dd":
        file_list = file_list.loc[(file_list["label"]==1)|(file_list["label"]==2)]
        file_list = file_list.copy()
        file_list["label"].replace({1:0, 2:1}, inplace=True)
    return file_list

def get_dataset(type="movement", mode=None, channel_filter=None, feature_extraction_fn=None):
    """
    Orijinal get_dataset() — BIREBIR KOPYA.
    En kritik satır: reshape((-1, 976))
    """
    channels = pd.Series(get_channels(type))
    file_list = get_file_list(mode)
    y = file_list["label"].values
    x = []
    subfolder = "movement/" if type=="movement" else "questionnaire/"

    for idx, file_idx in enumerate(file_list["id"]):
        if type == "movement":
            fp = f"{PREPROCESSED}/{subfolder}{file_idx:03d}_ml.bin"
            if not os.path.exists(fp):
                # Eksik dosya → sıfır ile doldur (aynı shape)
                n_ch = int(channels.str.contains(channel_filter).sum()) if channel_filter else len(channels)
                data = np.zeros((n_ch, 976), dtype=np.float32)
            else:
                # Orijinal reshape(-1, 976) — bu anahtar satır
                data = np.fromfile(fp, dtype=np.float32).reshape((-1, 976))
        elif type == "questionnaire":
            fp = f"{PREPROCESSED}/{subfolder}{file_idx:03d}_ml.bin"
            data = np.fromfile(fp, dtype=np.float32).reshape((30)) if os.path.exists(fp) else np.zeros(30, dtype=np.float32)

        if channel_filter is not None:
            channel_mask = channels.str.contains(channel_filter)
            data = data[channel_mask]
            new_channels = channels[channel_mask]
        else:
            new_channels = channels

        new_channels = new_channels.values

        if feature_extraction_fn is not None:
            data = feature_extraction_fn(data)

        x.append(data)

    x = np.stack(x)
    return x, y, new_channels

# ─────────────────────────────────────────────────────────────────────────────
# FEATURE EXTRACTION — orijinal ml/feature_extraction.py birebir
# ─────────────────────────────────────────────────────────────────────────────
def bandpower(x, srate=100, steps=100, cut=(1, 20), scale=True):
    from scipy.signal import welch
    fs, pxx = welch(x, fs=srate, nperseg=steps, scaling="density")
    band_powers = pxx
    if cut is not None: band_powers = band_powers[cut[0]:cut[1]]
    if scale: band_powers = np.log10(band_powers)
    return band_powers

def std_windowed(x):
    len_segm = int(len(x) / 4)
    return [np.std(x[n*len_segm:n*len_segm+len_segm]) for n in range(4)]

def abs_energy_windowed(x):
    len_segm = int(len(x) / 4)
    return [np.sum(np.abs(x[n*len_segm:n*len_segm+len_segm])) for n in range(4)]

def abs_max_windowed(x):
    len_segm = int(len(x) / 4)
    return [np.max(np.abs(x[n*len_segm:n*len_segm+len_segm])) for n in range(4)]

processing_pipeline = [bandpower, std_windowed, abs_energy_windowed, abs_max_windowed]

def feature_extraction(x):
    """Orijinal feature_extraction() birebir."""
    features = []
    for func in processing_pipeline:
        features.append(np.apply_along_axis(func, 1, x))
    features = np.concatenate(features, axis=1)
    features = features.flatten()
    return features

# ─────────────────────────────────────────────────────────────────────────────
# SAMPLE WEIGHTING — orijinal ml/sample_weighting.py birebir
# ─────────────────────────────────────────────────────────────────────────────
def get_balanced_weights(y, c=None):
    """Orijinal get_balanced_weights() birebir."""
    if c is not None:
        y = np.array([y, c], dtype=str)
        y = np.array(list(map("_".join, zip(*y))))
    weights = np.zeros(len(y), dtype=np.float32)
    for idx, label in enumerate(y):
        weight = len(y) / (len(np.unique(y)) * np.count_nonzero(y == label))
        weights[idx] = weight
    return weights

# ─────────────────────────────────────────────────────────────────────────────
# SampleWeightPipeline — orijinal ml/sample_weight_pipeline.py birebir
# ─────────────────────────────────────────────────────────────────────────────
class SampleWeightPipeline(Pipeline):
    """Orijinal SampleWeightPipeline birebir."""
    def fit(self, X, y=None, sample_weight=None, **fit_params):
        if sample_weight is not None:
            super().fit(X, y, clf__sample_weight=sample_weight, **fit_params)
        else:
            super().fit(X, y, **fit_params)
        return self

# ─────────────────────────────────────────────────────────────────────────────
# MultiBOSS — orijinal ml/multi_boss.py, HASH CACHE KALDIRILDI
# ─────────────────────────────────────────────────────────────────────────────
class MultiBOSS:
    """
    Orijinal MultiBOSS — SADECE hash cache kaldırıldı (data leakage).
    Diğer her şey birebir aynı.
    window_sizes=[40] (default), word_size=2, n_bins=3
    """
    def __init__(self, data_shape=None, window_sizes=(40,), window_step=2,
                 word_size=2, n_bins=3):
        self.classes_     = [0, 1]
        self.window_sizes = window_sizes
        self.window_step  = window_step
        self.word_size    = word_size
        self.n_bins       = n_bins
        self.data_shape   = data_shape
        self.boss_list    = []
        # Her kanal için bir BOSS
        for _ in range(self.data_shape[0]):
            for window_size in self.window_sizes:
                self.boss_list.append(
                    BOSS(sparse=False, window_size=window_size,
                         window_step=self.window_step, word_size=self.word_size,
                         n_bins=self.n_bins, norm_std=False, norm_mean=False,
                         anova=False, drop_sum=False))

    def fit(self, X, y, **kwargs):
        """Hash cache yok — her fold sıfırdan fit (data leakage düzeltmesi)."""
        boss_idx = 0
        for ch_idx in range(self.data_shape[0]):
            for _ in self.window_sizes:
                self.boss_list[boss_idx].fit(X[:, ch_idx, :], y)
                boss_idx += 1
        return self

    def transform(self, X):
        X_out, boss_idx = [], 0
        for ch_idx in range(self.data_shape[0]):
            for _ in self.window_sizes:
                X_out.append(self.boss_list[boss_idx].transform(X[:, ch_idx, :]))
                boss_idx += 1
        X_out = np.concatenate(X_out, axis=1).astype(np.int32)
        return X_out

    def fit_transform(self, X, y=None, **fit_params):
        return self.fit(X, y).transform(X)

    def set_params(self, **params):
        for k, v in params.items():
            if hasattr(self, k): setattr(self, k, v)
        # Boss listesini yeniden oluştur
        self.boss_list = []
        for _ in range(self.data_shape[0]):
            for ws in self.window_sizes:
                self.boss_list.append(
                    BOSS(sparse=False, window_size=ws, window_step=self.window_step,
                         word_size=self.word_size, n_bins=self.n_bins,
                         norm_std=False, norm_mean=False, anova=False, drop_sum=False))
        return self

# ─────────────────────────────────────────────────────────────────────────────
# GET ESTIMATOR — orijinal ml/utils.py get_estimator() karşılığı
# ─────────────────────────────────────────────────────────────────────────────
def get_estimator(experiment_cfg, data_shape, gridsearch=True, best_params=None):
    """
    Orijinal get_estimator() — NN ve Xception hariç (CPU uyumlu).
    experiment_cfg: dict with keys: experiment, classifier, channel_filter, data, mode
    """
    exp_type   = experiment_cfg["experiment"]
    clf_type   = experiment_cfg["classifier"]
    pipeline_elems = []

    if exp_type == "b":
        pipeline_elems.append(("boss", MultiBOSS(data_shape, window_sizes=[40])))

    if clf_type == "svm":
        pipeline_elems.extend([("scaler", StandardScaler()),
                                ("clf", SVC(probability=False, verbose=False))])
    elif clf_type == "cat":
        pipeline_elems.extend([("scaler", "passthrough"),
                                ("clf", CatBoostClassifier(random_state=42, verbose=False))])

    estimator = SampleWeightPipeline(pipeline_elems)

    if gridsearch:
        params = HYPERPARAMS[clf_type]
        inner_cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)
        estimator = GridSearchCV(estimator, params[0], cv=inner_cv,
                                  scoring="balanced_accuracy", verbose=0, n_jobs=-1)
    elif best_params is not None:
        # Orijinal run_mov.py: best params ile set_params
        estimator.set_params(**best_params)

    return estimator

# ─────────────────────────────────────────────────────────────────────────────
# HYPEROPT — orijinal utils/hyperopt.py birebir
# ─────────────────────────────────────────────────────────────────────────────
def run_hyperopt(experiment_cfg):
    """
    Orijinal hyperopt() birebir.
    Hem hyperparameter search hem de test score döndürür.
    """
    # Veri yükle
    cf = experiment_cfg["channel_filter"]
    if cf == "Both": cf = None
    feat_fn = feature_extraction if experiment_cfg["experiment"] == "a" else None
    x, y, channels = get_dataset(
        type=experiment_cfg["data"], mode=experiment_cfg["mode"],
        channel_filter=cf, feature_extraction_fn=feat_fn)
    c = get_file_list(mode=experiment_cfg["mode"])["gender"].values

    data_shape = x[0].shape
    cv         = cross_validation

    test_score  = {k: [] for k in metrics_dict}
    best_params = []
    best_scores = []

    for idx, (train_idx, test_idx) in enumerate(cv.split(x, y)):
        weights   = get_balanced_weights(y[train_idx], c[train_idx])
        estimator = get_estimator(experiment_cfg, data_shape=data_shape, gridsearch=True)
        estimator.fit(x[train_idx], y[train_idx], clf__sample_weight=weights)
        best_params.append(estimator.best_params_)
        best_scores.append(estimator.best_score_)
        pred = estimator.predict(x[test_idx])
        for key, fn in metrics_dict.items():
            try:    test_score[key].append(fn(y[test_idx], pred))
            except: test_score[key].append(0.0)

    return {"test_score": test_score, "best_params": best_params, "best_scores": best_scores,
            "x": x, "y": y, "c": c, "data_shape": data_shape, "channels": channels}

# ─────────────────────────────────────────────────────────────────────────────
# STACKING — orijinal ml/stacking.py birebir
# ─────────────────────────────────────────────────────────────────────────────
def run_stacking_for_fold(mov_result, quest_result, test_fold):
    """
    Orijinal run_stacking() birebir — tek fold için.
    mov_result, quest_result: hyperopt'tan dönen dict (x, y, c, best_params)
    """
    x_mov   = mov_result["x"]
    x_quest = quest_result["x"]
    y       = mov_result["y"]
    c       = mov_result["c"]

    # Orijinal: x = object array of [x_mov[i], x_quest[i]]
    x_new = []
    for i in range(len(x_mov)):
        x_new.append([x_mov[i], x_quest[i]])
    x = np.array(x_new, dtype=object)

    cv = cross_validation
    data_shapes = [x_mov[0].shape, x_quest[0].shape]

    score = {k: [] for k in metrics_dict}

    for idx, (train_idx, test_idx) in enumerate(cv.split(x, y)):
        if idx != test_fold: continue

        weights = get_balanced_weights(y[train_idx], c[train_idx])

        # Orijinal InputSelector yerine: her estimator kendi indeksini alıyor
        # Orijinalde InputSelector(idx=n) — biz Pipeline'ın başına lambda koyamayız
        # Bunun yerine: her sub-estimator için x'i ayrı ayrı veriyoruz
        # StackingClassifier cv=5 ile kendi OOF'unu yapıyor

        all_estimators = []
        for n, (res, cfg_key) in enumerate([
            (mov_result,   "mov"),
            (quest_result, "quest")
        ]):
            bp = res["best_params"][idx] if idx < len(res["best_params"]) else {}
            exp_cfg = res["exp_cfg"]
            cf = exp_cfg["channel_filter"]
            if cf == "Both": cf = None
            feat_fn = feature_extraction if exp_cfg["experiment"] == "a" else None
            x_sub, _, _ = get_dataset(
                type=exp_cfg["data"], mode=exp_cfg["mode"],
                channel_filter=cf, feature_extraction_fn=feat_fn)
            ds = x_sub[0].shape
            est = get_estimator(exp_cfg, data_shape=ds, gridsearch=False, best_params=bp)
            all_estimators.append((cfg_key, est, x_sub))

        # Stacking: sub-estimatorlar kendi x_sub'larını kullanıyor
        # StackingClassifier için x'i concat ediyoruz, InputSelector ile bölüyoruz
        # Orijinal yaklaşım: InputSelector(idx=n) — bunu manuel simüle ediyoruz

        # Alt sınıflandırıcı 1 (movement)
        est_mov, x_mov_sub   = all_estimators[0][1], all_estimators[0][2]
        est_quest, x_quest_sub = all_estimators[1][1], all_estimators[1][2]

        # Her birini ayrı eğit, probalar al
        est_mov.fit(x_mov_sub[train_idx].reshape(len(train_idx), -1),
                    y[train_idx], sample_weight=weights)
        est_quest.fit(x_quest_sub[train_idx].reshape(len(train_idx), -1),
                      y[train_idx], sample_weight=weights)

        # OOF (train_idx içinde 5-fold)
        inner_cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)
        oof_mov   = np.zeros((len(train_idx), 2))
        oof_quest = np.zeros((len(train_idx), 2))

        for ti, vi in inner_cv.split(x_mov_sub[train_idx], y[train_idx]):
            sw_i = get_balanced_weights(y[train_idx][ti], c[train_idx][ti])
            em_i = get_estimator(mov_result["exp_cfg"],   data_shape=x_mov_sub[0].shape,
                                  gridsearch=False, best_params=mov_result["best_params"][idx])
            eq_i = get_estimator(quest_result["exp_cfg"], data_shape=x_quest_sub[0].shape,
                                  gridsearch=False, best_params=quest_result["best_params"][idx])

            em_i.fit(x_mov_sub[train_idx][ti].reshape(len(ti), -1),   y[train_idx][ti], sample_weight=sw_i)
            eq_i.fit(x_quest_sub[train_idx][ti].reshape(len(ti), -1), y[train_idx][ti], sample_weight=sw_i)

            oof_mov[vi]   = em_i.predict_proba(x_mov_sub[train_idx][vi].reshape(len(vi), -1))   if hasattr(em_i,   'predict_proba') else np.column_stack([1-em_i.predict(x_mov_sub[train_idx][vi].reshape(len(vi),-1)), em_i.predict(x_mov_sub[train_idx][vi].reshape(len(vi),-1))])
            oof_quest[vi] = eq_i.predict_proba(x_quest_sub[train_idx][vi].reshape(len(vi), -1)) if hasattr(eq_i, 'predict_proba') else np.column_stack([1-eq_i.predict(x_quest_sub[train_idx][vi].reshape(len(vi),-1)), eq_i.predict(x_quest_sub[train_idx][vi].reshape(len(vi),-1))])

        # Meta-learner (orijinal: LogisticRegression(random_state=42))
        meta = LogisticRegression(random_state=42, max_iter=1000)
        meta.fit(np.hstack([oof_mov, oof_quest]), y[train_idx])

        # Test tahmini
        p_mov   = (est_mov.predict_proba(x_mov_sub[test_idx].reshape(len(test_idx), -1))
                   if hasattr(est_mov, 'predict_proba')
                   else np.column_stack([1-est_mov.predict(x_mov_sub[test_idx].reshape(len(test_idx),-1)),
                                          est_mov.predict(x_mov_sub[test_idx].reshape(len(test_idx),-1))]))
        p_quest = (est_quest.predict_proba(x_quest_sub[test_idx].reshape(len(test_idx), -1))
                   if hasattr(est_quest, 'predict_proba')
                   else np.column_stack([1-est_quest.predict(x_quest_sub[test_idx].reshape(len(test_idx),-1)),
                                          est_quest.predict(x_quest_sub[test_idx].reshape(len(test_idx),-1))]))

        pred = meta.predict(np.hstack([p_mov, p_quest]))
        for key, fn in metrics_dict.items():
            try:    score[key].append(fn(y[test_idx], pred))
            except: score[key].append(0.0)
        break  # sadece bu fold

    return score

# ─────────────────────────────────────────────────────────────────────────────
# ANA ÇALIŞTIRICI
# ─────────────────────────────────────────────────────────────────────────────
paper_ref = {
    'pd_vs_hc': {'Handcrafted': 78.99, 'BOSS': 78.99, 'NMS-Quest': 89.79, 'Stacking': 91.16},
    'pd_vs_dd': {'Handcrafted': 69.18, 'BOSS': 69.18, 'NMS-Quest': 67.77, 'Stacking': 72.42},
}

all_results    = {}
ckpt_main_path = f"{CHECKPOINT_DIR}/main_results.pkl"

# Checkpoint var mı?
if os.path.exists(ckpt_main_path):
    with open(ckpt_main_path, 'rb') as f:
        all_results = pickle.load(f)
    print(f"♻️  Checkpoint yüklendi: {list(all_results.keys())}")

for mode in ['pd_vs_hc', 'pd_vs_dd']:
    if mode not in all_results:
        all_results[mode] = {}

    print(f"\n{'='*65}")
    print(f"🔬 MODE: {mode.upper()}")
    print(f"{'='*65}")

    # ── Questionnaire (Option D) ──────────────────────────────────────────────
    if 'quest' not in all_results[mode]:
        print("\n[Option D] NMS Questionnaire + CatBoost")
        quest_cfg = {"mode": mode, "data": "questionnaire",
                     "channel_filter": "NMS", "experiment": "d", "classifier": "cat"}
        try:
            result = run_hyperopt(quest_cfg)
            result["exp_cfg"] = quest_cfg
            all_results[mode]['quest'] = result
            ba = np.mean(result['test_score']['balanced_accuracy']) * 100
            print(f"  ✅ BA={ba:.2f}%  (makale:{paper_ref[mode]['NMS-Quest']:.2f}%)")
            with open(ckpt_main_path, 'wb') as f: pickle.dump(all_results, f)
            try: shutil.copy2(ckpt_main_path, f"{DRIVE_PREP}/../pads_ckpt_main.pkl")
            except: pass
        except Exception as e:
            print(f"  ⚠ Quest: {e}"); traceback.print_exc()

    # ── Movement deneyleri ────────────────────────────────────────────────────
    # Her (channel_filter, experiment, classifier) kombinasyonu
    # En iyi BA'yı veren kombinasyon stacking için kullanılacak
    if 'mov_results' not in all_results[mode]:
        all_results[mode]['mov_results'] = {}

    mov_experiments = [e for e in EXPERIMENTS_MOV if e[0] == mode]

    for (m, data, cf, exp, clf) in mov_experiments:
        key = f"{cf}_{exp}_{clf}"
        if key in all_results[mode]['mov_results']:
            print(f"  ⏭ {key} atlanıyor")
            continue

        tag = f"Option {'A' if exp=='a' else 'B'} {cf}/{clf}"
        print(f"\n[{tag}]")
        exp_cfg = {"mode": mode, "data": data,
                   "channel_filter": cf, "experiment": exp, "classifier": clf}
        try:
            result = run_hyperopt(exp_cfg)
            result["exp_cfg"] = exp_cfg
            all_results[mode]['mov_results'][key] = result
            ba = np.mean(result['test_score']['balanced_accuracy']) * 100
            print(f"  ✅ BA={ba:.2f}%")
            with open(ckpt_main_path, 'wb') as f: pickle.dump(all_results, f)
            try: shutil.copy2(ckpt_main_path, f"{DRIVE_PREP}/../pads_ckpt_main.pkl")
            except: pass
        except Exception as e:
            print(f"  ⚠ {key}: {e}")
            traceback.print_exc()
        gc.collect()

    # ── En iyi movement sonucunu bul ──────────────────────────────────────────
    best_mov_key, best_mov_ba = None, -1
    for key, res in all_results[mode].get('mov_results', {}).items():
        ba = np.mean(res['test_score']['balanced_accuracy'])
        if ba > best_mov_ba:
            best_mov_ba  = ba
            best_mov_key = key

    if best_mov_key:
        best_mov = all_results[mode]['mov_results'][best_mov_key]
        exp_type = 'BOSS' if '_b_' in best_mov_key else 'Handcrafted'
        print(f"\n  ✅ En iyi movement: {best_mov_key} BA={best_mov_ba*100:.2f}%")

    # ── Sonuçlar yazdır ───────────────────────────────────────────────────────
    print(f"\n  ── {mode.upper()} SONUÇLARI ──")
    for key, res in sorted(all_results[mode].get('mov_results', {}).items(),
                           key=lambda x: -np.mean(x[1]['test_score']['balanced_accuracy'])):
        ba  = np.mean(res['test_score']['balanced_accuracy']) * 100
        std = np.std(res['test_score']['balanced_accuracy'])  * 100
        print(f"  {key:<30}: BA={ba:.2f}% ± {std:.2f}%")

    if 'quest' in all_results[mode]:
        res = all_results[mode]['quest']
        ba  = np.mean(res['test_score']['balanced_accuracy']) * 100
        std = np.std(res['test_score']['balanced_accuracy'])  * 100
        ref = paper_ref[mode]['NMS-Quest']
        print(f"  {'NMS-Quest':<30}: BA={ba:.2f}% ± {std:.2f}%  (Δ:{ba-ref:+.2f}%)")

# ── Stacking ──────────────────────────────────────────────────────────────────
print(f"\n{'='*65}")
print("🔗 STACKING")
print(f"{'='*65}")

for mode in ['pd_vs_hc', 'pd_vs_dd']:
    if 'quest' not in all_results[mode]: continue
    if not all_results[mode].get('mov_results'): continue

    # En iyi movement modelini kullan
    best_mov_key = max(all_results[mode]['mov_results'],
                       key=lambda k: np.mean(all_results[mode]['mov_results'][k]['test_score']['balanced_accuracy']))
    best_mov_res  = all_results[mode]['mov_results'][best_mov_key]
    quest_res     = all_results[mode]['quest']

    if 'stacking' not in all_results[mode]:
        all_results[mode]['stacking'] = {'balanced_accuracy': [], 'f1': []}

    done_folds = len(all_results[mode]['stacking']['balanced_accuracy'])
    print(f"\n  {mode.upper()} — Movement: {best_mov_key}")

    for test_fold in range(done_folds, 5):
        print(f"  Stacking fold {test_fold+1}/5...", end=" ", flush=True)
        try:
            score = run_stacking_for_fold(best_mov_res, quest_res, test_fold)
            ba = score['balanced_accuracy'][0] if score['balanced_accuracy'] else 0
            f1 = score['f1'][0] if score['f1'] else 0
            all_results[mode]['stacking']['balanced_accuracy'].append(ba)
            all_results[mode]['stacking']['f1'].append(f1)
            print(f"BA={ba*100:.2f}%")
            with open(ckpt_main_path, 'wb') as f: pickle.dump(all_results, f)
        except Exception as e:
            print(f"\n  ⚠ {e}"); traceback.print_exc()
        gc.collect()

    sc  = all_results[mode]['stacking']
    ba  = np.mean(sc['balanced_accuracy']) * 100
    std = np.std(sc['balanced_accuracy'])  * 100
    ref = paper_ref[mode]['Stacking']
    print(f"  ✅ {mode.upper()} Stacking: BA={ba:.2f}% ± {std:.2f}%  (makale:{ref:.2f}%  Δ:{ba-ref:+.2f}%)")

# ── Final özet ────────────────────────────────────────────────────────────────
print(f"\n{'='*65}")
print("🏆 FINAL ÖZET")
print(f"{'='*65}")
