# ─── L1 Trend Filter ─────────────────────────────────────────────────────────
def l1_trend_filter(y, vlambda=50):
    from scipy.sparse import diags, eye
    n=len(y); e=np.ones(n)
    D=diags([e,-2*e,e],[0,1,2],shape=(n-2,n),format='csc')
    w=np.ones(n-2); x=y.copy()
    for _ in range(30):
        W=diags(w,0,format='csc'); A=eye(n,format='csc')+vlambda*(D.T@W@D)
        xn=spsolve(A,y) if False else __import__('scipy.sparse.linalg',fromlist=['spsolve']).spsolve(A,y)
        w=1.0/(np.abs(D@xn)+1e-6)
        if np.max(np.abs(xn-x))<1e-4: break
        x=xn
    return xn

from scipy.sparse.linalg import spsolve
def l1tf(y, vlambda=50):
    from scipy.sparse import diags, eye
    n=len(y); e=np.ones(n)
    D=diags([e,-2*e,e],[0,1,2],shape=(n-2,n),format='csc')
    w=np.ones(n-2); x=y.copy()
    for _ in range(30):
        W=diags(w,0,format='csc'); A=eye(n,format='csc')+vlambda*(D.T@W@D)
        xn=spsolve(A,y); w=1.0/(np.abs(D@xn)+1e-6)
        if np.max(np.abs(xn-x))<1e-4: break
        x=xn
    return xn

# ─── PREPROCESSING — run_preprocessing.py BİREBİR ───────────────────────────
# JSON yapısı (diagnostic'ten):
# {resource_type, subject_id, session: [
#   {record_name, rows, records: [
#     {device_location, channels:[...], file_name}
#   ]}
# ]}

TASKS_ORDER = ['Relaxed1','Relaxed2','RelaxedTask1','RelaxedTask2','StretchHold',
               'LiftHold','HoldWeight','PointFinger','DrinkGlas','CrossArms',
               'TouchIndex','TouchNose','Entrainment1','Entrainment2']
LABEL_MAP = {'Healthy':0,"Parkinson's":1,
             'Other Movement Disorders':2,'Essential Tremor':2,
             'Multiple Sclerosis':2,'Atypical Parkinsonism':2}

def read_obs_json(obs_path):
    """
    Observation JSON'dan (rows, channels, file_name) içeren DataFrame döndür.
    Orijinal load_all_files() + flatten_dict() kombinasyonunun karşılığı.
    JSON yapısı: {session: [{record_name, rows, records: [{device_location, channels, file_name}]}]}
    """
    with open(obs_path) as f: obs = json.load(f)
    rows_list = []
    for session in obs.get('session', []):
        rn   = session['record_name']   # ör: 'Relaxed', 'Relaxed1', vb.
        rows = session['rows']           # toplam sample sayısı
        for rec in session.get('records', []):
            rows_list.append({
                'record_name':     rn,
                'rows':            rows,
                'device_location': rec['device_location'],
                'channels':        rec['channels'],
                'file_name':       rec['file_name'],
            })
    return pd.DataFrame(rows_list) if rows_list else None

def get_data_from_observation(df):
    """
    Orijinal get_data_from_observation() BİREBİR.
    df: bir hastanın tüm observation satırları (tüm session records)
    """
    all_records = []
    all_channels = []
    min_rows = int(df['rows'].min())

    for _, meta in df.iterrows():
        n_splits = int(meta['rows']) // min_rows
        fname    = meta['file_name']
        fpath    = os.path.join(TS_DIR, fname)
        if not os.path.exists(fpath):
            fpath = next((f for f in glob(f"{DATA}/**/{fname}", recursive=True)), None)
        if not fpath or not os.path.exists(fpath): continue

        # Orijinal: np.loadtxt + swapaxes
        try:
            record = np.loadtxt(fpath, dtype=np.float32, delimiter=",")
        except Exception:
            continue
        if record.ndim == 1: record = record.reshape(1,-1)
        record = np.swapaxes(record, 0, 1)   # → (channels, time)

        chs = meta['channels']
        if isinstance(chs, str):
            chs = [c.strip().strip("'\"") for c in chs.strip('[]').split(',')]

        loc = str(meta['device_location'])
        rn  = str(meta['record_name'])

        # Orijinal kanal isimlendirmesi:
        # channels = ['_'.join([device_location, ch]) for ch in channels]
        # Sonra: channels = ['_'.join([record_name, ch]) for ch in channels]
        channels_named = [f"{rn}_{loc}_{ch}" for ch in chs]

        step = record.shape[1] // n_splits
        if n_splits > 1:
            new_recs = []
            for n in range(n_splits):
                new_recs.append(record[:, n*step:(n+1)*step])
            record = np.concatenate(new_recs, axis=0)
            new_chs = []
            for n in range(n_splits):
                for ch in channels_named:
                    # Orijinal: f'{record_name}{n+1}_{location}_{axis}'
                    # Ama channels_named zaten record_name içeriyor
                    # Orijinalde record_name'i sonradan ekliyordu, burada zaten var
                    # Düzelt: n+1 suffix'ini record_name'e ekle
                    parts = ch.split('_', 1)  # record_name | rest
                    new_chs.append(f"{parts[0]}{n+1}_{parts[1]}")
            channels_named = new_chs
        # Else: tek split → isim değişmiyor

        all_records.append(record)
        all_channels.extend(channels_named)

    if not all_records: return None, None
    # Orijinal: all_records = np.concatenate → tüm satırları birleştir
    # Ama farklı time uzunlukları olabilir → min_rows'a göre kırp
    min_t = min(r.shape[1] for r in all_records)
    all_records = np.concatenate([r[:,:min_t] for r in all_records], axis=0)
    return all_records, all_channels

def preprocess_movement(subject_id, obs_df, out_dir, overwrite=False):
    """Orijinal preprocess_movement() BİREBİR."""
    out = os.path.join(out_dir, f"{int(subject_id):03d}_ml.bin")
    if os.path.exists(out) and not overwrite: return True

    data, channels = get_data_from_observation(obs_df)
    if data is None or len(channels)==0: return False
    channels = np.array(channels)

    # Orijinal kanal sıralaması
    channels_sorted = []
    for task in TASKS_ORDER:
        for wrist in ['LeftWrist','RightWrist']:
            for sensor in ['Time','Accelerometer','Gyroscope']:
                if sensor=='Time':
                    channels_sorted.append(f"{task}_{wrist}_{sensor}")
                else:
                    for ax in ['X','Y','Z']:
                        channels_sorted.append(f"{task}_{wrist}_{sensor}_{ax}")

    # sorting_indices = [channels.index(ch) for ch in channels_sorted]
    # Orijinal bunu yaparken KeyError olabilir — sadece var olanları al
    ch_list = list(channels)
    sorting_indices = []
    for ch_name in channels_sorted:
        # Tam eşleşme dene, yoksa suffix eşleşmesi
        found = None
        for i, c in enumerate(ch_list):
            if c == ch_name:
                found = i; break
        if found is None:
            # Session'da record_name'ler farklı olabilir (ör: 'Relaxed' vs 'Relaxed1')
            # Suffix eşleştir: task_wrist_sensor[_ax] kısmı
            suffix = '_'.join(ch_name.split('_')[0:])  # tüm isim
            for i, c in enumerate(ch_list):
                if c.endswith(suffix) or suffix in c:
                    found = i; break
        if found is not None:
            sorting_indices.append(found)

    if not sorting_indices: return False
    data     = data[sorting_indices]
    channels = channels[sorting_indices]

    # Kaldır: Time, LiftHold, PointFinger, TouchIndex
    to_remove  = 'Time|LiftHold|PointFinger|TouchIndex'
    keep_mask  = ~pd.Series(channels).str.contains(to_remove, na=False).values
    data       = data[keep_mask]
    channels   = channels[keep_mask]

    # L1 trend filter (sadece Accelerometer)
    acc_mask = pd.Series(channels).str.contains('Accelerometer', na=False).values
    data[acc_mask, :] = np.apply_along_axis(
        lambda x: x - l1tf(x, vlambda=50), 1, data[acc_mask, :])

    # İlk 48 sample at → 1024-48=976 ✅
    data = data[:, 48:]
    data.astype(np.float32).tofile(out)
    return True

def preprocess_questionnaire(subject_id, q_path, out_dir, overwrite=False):
    """Orijinal questionnaire preprocessing."""
    out = os.path.join(out_dir, f"{int(subject_id):03d}_ml.bin")
    if os.path.exists(out) and not overwrite: return True
    if not os.path.exists(q_path): return False
    with open(q_path) as f: q = json.load(f)
    answers = [0.0]*30
    for item in q.get('item', []):
        try:
            i = int(str(item['link_id'])) - 1
            if 0 <= i < 30:
                answers[i] = 1.0 if item.get('answer') else 0.0
        except: pass
    np.array(answers, dtype=np.float32).tofile(out)
    return True

