# ─── ML UTILS ────────────────────────────────────────────────────────────────
def get_channels(type="movement"):
    chs=[]
    if type=="movement":
        for task in ["Relaxed1","Relaxed2","RelaxedTask1","RelaxedTask2","StretchHold",
                     "HoldWeight","DrinkGlas","CrossArms","TouchNose","Entrainment1","Entrainment2"]:
            for loc in ["LeftWrist","RightWrist"]:
                for sensor in ["Acceleration","Rotation"]:
                    for ax in ["X","Y","Z"]:
                        chs.append(f"{task}_{sensor}_{loc}_{ax}")
    elif type=="questionnaire":
        chs=[f"NMS_{n:02d}" for n in range(1,31)]
    return chs

def get_file_list(mode=None):
    fl=FILE_LIST.copy()
    if mode=="pd_vs_hc": fl=fl[(fl["label"]==0)|(fl["label"]==1)].copy()
    elif mode=="pd_vs_dd":
        fl=fl[(fl["label"]==1)|(fl["label"]==2)].copy()
        fl["label"].replace({1:0,2:1},inplace=True)
    return fl

def get_dataset(type="movement", mode=None, channel_filter=None, feature_extraction_fn=None):
    """Orijinal get_dataset() — reshape((-1, 976)) ile."""
    channels  = pd.Series(get_channels(type))
    file_list = get_file_list(mode)
    y         = file_list["label"].values
    subfolder = "movement/" if type=="movement" else "questionnaire/"
    x         = []
    new_channels = channels

    for fid in file_list["id"]:
        fp = f"{MY_PREP}/{subfolder}{int(fid):03d}_ml.bin"
        if type=="movement":
            if not os.path.exists(fp):
                n_ch = int(channels.str.contains(channel_filter).sum()) if channel_filter else len(channels)
                data = np.zeros((n_ch,976),dtype=np.float32)
            else:
                raw = np.fromfile(fp,dtype=np.float32)
                data = raw.reshape((-1,976))   # ← orijinal birebir
        else:
            data = (np.fromfile(fp,dtype=np.float32).reshape((30))
                    if os.path.exists(fp) else np.zeros(30,dtype=np.float32))

        if channel_filter is not None and type=="movement":
            mask = channels.str.contains(channel_filter)
            # data: (n_ch_in_bin, 976) — n_ch_in_bin ile mask boyutu eşleşmeli
            if len(mask)==data.shape[0]:
                data = data[mask]; new_channels=channels[mask]
            elif data.shape[0] > len(mask):
                data = data[:len(mask)]; data=data[mask]; new_channels=channels[mask]
            else:
                # Eksik kanallar var — pad
                pad = np.zeros((len(mask)-data.shape[0],976),dtype=np.float32)
                data = np.vstack([data,pad]); data=data[mask]; new_channels=channels[mask]
        elif type=="movement":
            new_channels=channels

        if feature_extraction_fn and type=="movement":
            data=feature_extraction_fn(data)
        x.append(data)

    try: x=np.stack(x)
    except ValueError:
        min_t=min(a.shape[-1] for a in x) if x[0].ndim>1 else None
        x=np.stack([a[...,:min_t] for a in x]) if min_t else np.stack([a for a in x])

    return x,y,(new_channels.values if hasattr(new_channels,'values') else new_channels)

# ─── Feature Extraction ───────────────────────────────────────────────────────
def bandpower(x,srate=100,steps=100,cut=(1,20),scale=True):
    from scipy.signal import welch
    fs,pxx=welch(x,fs=srate,nperseg=steps,scaling="density")
    bp=pxx[cut[0]:cut[1]]
    return np.log10(bp) if scale else bp

def std_windowed(x):
    l=int(len(x)/4); return [np.std(x[n*l:n*l+l]) for n in range(4)]
def abs_energy_windowed(x):
    l=int(len(x)/4); return [np.sum(np.abs(x[n*l:n*l+l])) for n in range(4)]
def abs_max_windowed(x):
    l=int(len(x)/4); return [np.max(np.abs(x[n*l:n*l+l])) for n in range(4)]

def feature_extraction(x):
    feats=[]
    for fn in [bandpower,std_windowed,abs_energy_windowed,abs_max_windowed]:
        feats.append(np.apply_along_axis(fn,1,x))
    return np.concatenate(feats,axis=1).flatten()

# ─── Sample Weighting ─────────────────────────────────────────────────────────
def get_balanced_weights(y,c=None):
    if c is not None:
        y=np.array(list(map("_".join,zip(y.astype(str),c.astype(str)))))
    w=np.zeros(len(y),dtype=np.float32)
    for idx,lbl in enumerate(y):
        w[idx]=len(y)/(len(np.unique(y))*np.count_nonzero(y==lbl))
    return w

# ─── Pipeline ─────────────────────────────────────────────────────────────────
class SampleWeightPipeline(Pipeline):
    def fit(self,X,y=None,sample_weight=None,**kw):
        if sample_weight is not None: super().fit(X,y,clf__sample_weight=sample_weight,**kw)
        else: super().fit(X,y,**kw)
        return self

class MultiBOSS:
    def __init__(self,data_shape=None,window_sizes=(40,),window_step=2,word_size=2,n_bins=3):
        self.window_sizes=window_sizes; self.window_step=window_step
        self.word_size=word_size; self.n_bins=n_bins; self.data_shape=data_shape
        self.classes_=[0,1]; self.boss_list=self._build()
    def _build(self):
        return [BOSS(sparse=False,window_size=ws,window_step=self.window_step,
                     word_size=self.word_size,n_bins=self.n_bins,
                     norm_std=False,norm_mean=False,anova=False,drop_sum=False)
                for _ in range(self.data_shape[0]) for ws in self.window_sizes]
    def fit(self,X,y,**kw):
        bi=0
        for ch in range(self.data_shape[0]):
            for _ in self.window_sizes: self.boss_list[bi].fit(X[:,ch,:],y); bi+=1
        return self
    def transform(self,X):
        out,bi=[],0
        for ch in range(self.data_shape[0]):
            for _ in self.window_sizes: out.append(self.boss_list[bi].transform(X[:,ch,:])); bi+=1
        return np.concatenate(out,axis=1).astype(np.int32)
    def fit_transform(self,X,y=None,**kw): return self.fit(X,y).transform(X)
    def set_params(self,**p):
        for k,v in p.items():
            if hasattr(self,k): setattr(self,k,v)
        self.boss_list=self._build(); return self

def get_estimator(exp_cfg,data_shape,gridsearch=True,best_params=None):
    elems=[]
    if exp_cfg["experiment"]=="b":
        elems.append(("boss",MultiBOSS(data_shape,window_sizes=[40])))
    if exp_cfg["classifier"]=="svm":
        elems+=[("scaler",StandardScaler()),("clf",SVC(probability=False,verbose=False))]
    elif exp_cfg["classifier"]=="cat":
        elems+=[("scaler","passthrough"),("clf",CatBoostClassifier(random_state=42,verbose=False))]
    est=SampleWeightPipeline(elems)
    if gridsearch:
        icv=StratifiedKFold(n_splits=5,shuffle=True,random_state=42)
        est=GridSearchCV(est,HYPERPARAMS[exp_cfg["classifier"]],cv=icv,
                         scoring="balanced_accuracy",verbose=0,n_jobs=-1)
    elif best_params: est.set_params(**best_params)
    return est

# ─── Hyperopt ─────────────────────────────────────────────────────────────────
def run_hyperopt(exp_cfg):
    cf=None if exp_cfg["channel_filter"]=="Both" else exp_cfg["channel_filter"]
    fn=feature_extraction if exp_cfg["experiment"]=="a" else None
    x,y,_=get_dataset(type=exp_cfg["data"],mode=exp_cfg["mode"],
                       channel_filter=cf,feature_extraction_fn=fn)
    fl=get_file_list(mode=exp_cfg["mode"])
    c=fl["gender"].values if "gender" in fl.columns else np.zeros(len(y),dtype='U1')
    ds=x[0].shape; cv=cross_validation
    ts={k:[] for k in metrics_dict}; bp=[]; bs=[]
    for tr,te in cv.split(x,y):
        w=get_balanced_weights(y[tr],c[tr])
        est=get_estimator(exp_cfg,data_shape=ds,gridsearch=True)
        est.fit(x[tr],y[tr],clf__sample_weight=w)
        bp.append(est.best_params_); bs.append(est.best_score_)
        pred=est.predict(x[te])
        for k,fn2 in metrics_dict.items():
            try: ts[k].append(fn2(y[te],pred))
            except: ts[k].append(0.0)
    return {"test_score":ts,"best_params":bp,"best_scores":bs,
            "x":x,"y":y,"c":c,"data_shape":ds,"exp_cfg":exp_cfg}

# ─── Stacking ─────────────────────────────────────────────────────────────────
def run_stacking_fold(mov_res,quest_res,fold_idx):
    mc=mov_res["exp_cfg"]; qc=quest_res["exp_cfg"]
    cf=None if mc["channel_filter"]=="Both" else mc["channel_filter"]
    fn=feature_extraction if mc["experiment"]=="a" else None
    x_m,y,_=get_dataset(type=mc["data"],mode=mc["mode"],channel_filter=cf,feature_extraction_fn=fn)
    x_q,_,_=get_dataset(type=qc["data"],mode=qc["mode"])
    fl=get_file_list(mode=mc["mode"])
    c=fl["gender"].values if "gender" in fl.columns else np.zeros(len(y),dtype='U1')
    cv=cross_validation; score={k:[] for k in metrics_dict}
    for idx,(tr,te) in enumerate(cv.split(x_m,y)):
        if idx!=fold_idx: continue
        w=get_balanced_weights(y[tr],c[tr])
        bpm=mov_res["best_params"][idx] if idx<len(mov_res["best_params"]) else {}
        bpq=quest_res["best_params"][idx] if idx<len(quest_res["best_params"]) else {}
        inner=StratifiedKFold(n_splits=5,shuffle=True,random_state=42)
        oof_m=np.zeros((len(tr),2)); oof_q=np.zeros((len(tr),2))
        for ti,vi in inner.split(x_m[tr],y[tr]):
            sw=get_balanced_weights(y[tr][ti],c[tr][ti])
            em=get_estimator(mc,x_m[0].shape,gridsearch=False,best_params=bpm)
            eq=get_estimator(qc,x_q[0].shape,gridsearch=False,best_params=bpq)
            em.fit(x_m[tr][ti].reshape(len(ti),-1),y[tr][ti],sample_weight=sw)
            eq.fit(x_q[tr][ti],y[tr][ti],sample_weight=sw)
            pm=em.predict(x_m[tr][vi].reshape(len(vi),-1))
            pq=eq.predict(x_q[tr][vi])
            oof_m[vi]=np.c_[1-pm,pm]; oof_q[vi]=np.c_[1-pq,pq]
        meta=LogisticRegression(random_state=42,max_iter=1000)
        meta.fit(np.hstack([oof_m,oof_q]),y[tr])
        emf=get_estimator(mc,x_m[0].shape,gridsearch=False,best_params=bpm)
        eqf=get_estimator(qc,x_q[0].shape,gridsearch=False,best_params=bpq)
        emf.fit(x_m[tr].reshape(len(tr),-1),y[tr],sample_weight=w)
        eqf.fit(x_q[tr],y[tr],sample_weight=w)
        pm_te=emf.predict(x_m[te].reshape(len(te),-1))
        pq_te=eqf.predict(x_q[te])
        pred=meta.predict(np.hstack([np.c_[1-pm_te,pm_te],np.c_[1-pq_te,pq_te]]))
        for k,fn2 in metrics_dict.items():
            try: score[k].append(fn2(y[te],pred))
            except: score[k].append(0.0)
        break
    return score

