# ─── BOSS MONKEY-PATCH ────────────────────────────────────────────────────────
# pyts'nin yeni scipy ile uyumsuzluğu: X_boss.A → .toarray() gerekiyor
try:
    import pyts.transformation.boss as _boss_module
    import scipy.sparse as _sp
    _orig_transform = _boss_module.BOSS.transform

    def _patched_transform(self, X):
        result = _orig_transform(self, X)
        if _sp.issparse(result):
            return result.toarray()
        if hasattr(result, 'A'):
            return np.asarray(result.A)
        return np.asarray(result)

    _boss_module.BOSS.transform = _patched_transform
    print("✅ BOSS sparse patch uygulandı")
except Exception as e:
    print(f"⚠ BOSS patch: {e}")

