def ensure(*pkgs):
    for p in pkgs:
        mod = p.split('[')[0].replace('-','_')
        try: __import__(mod)
        except ImportError:
            print(f"  Installing {p}...")
            subprocess.check_call(
                [sys.executable,"-m","pip","install",p,"-q","--break-system-packages"],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

print("📦 Paketler kontrol ediliyor...")
ensure("numpy","pandas","scipy","scikit-learn","catboost","tqdm","psutil","matplotlib","seaborn")
