assert sample.size == 132*976, f"❌ Format hatası: beklenen {132*976}, alınan {sample.size}"
print(f"✅ .bin format: 132×976")

FILE_LIST = pd.read_csv(f"{PREP_DIR}/file_list.csv")
n_pd = (FILE_LIST['label']==1).sum()
