# ─── Channel listesi (makaledeki sıra) ───────────────────────────────────────
ALL_CH = []
for task in ['Relaxed1','Relaxed2','RelaxedTask1','RelaxedTask2','StretchHold',
             'HoldWeight','DrinkGlas','CrossArms','TouchNose','Entrainment1','Entrainment2']:
    for wrist in ['LeftWrist','RightWrist']:
        for sensor in ['Accelerometer','Gyroscope']:
            for ax in ['X','Y','Z']:
                ALL_CH.append(f"{task}_{wrist}_{sensor}_{ax}")
assert len(ALL_CH) == 132

# ─── Feature Extraction (makale Option A) ────────────────────────────────────
# NOT: Per-patient hesaplanıyor, cross-patient normalizasyon yok → leakage yok
def bandpower(x, srate=100, nperseg=100, fmin=1, fmax=20):
    fs, pxx = welch(x, fs=srate, nperseg=nperseg, scaling='density')
    return np.log10(pxx[fmin:fmax] + 1e-12)          # 19 değer

def _windowed(x, fn, n=4):
    l = len(x)//n
    return [fn(x[i*l:(i+1)*l]) for i in range(n)]    # 4 değer

def extract_features(data):
    """
    data: (n_channels, n_time)
    Makale Option A: bandpower + std_windowed + abs_energy + abs_max
    Her kanal için: 19 + 4 + 4 + 4 = 31 özellik
    Toplam: n_ch × 31
    """
    out = []
    for ch in range(data.shape[0]):
        x = data[ch]
        bp  = bandpower(x)                                     # 19
        sw  = _windowed(x, np.std)                            # 4
        ae  = _windowed(x, lambda v: np.sum(np.abs(v)))       # 4
        am  = _windowed(x, lambda v: np.max(np.abs(v)))       # 4
        out.append(np.concatenate([bp, sw, ae, am]))
    return np.concatenate(out).astype(np.float32)              # n_ch*31

# ─── Veri yükleme ─────────────────────────────────────────────────────────────
def get_file_list(mode):
    fl = FILE_LIST.copy()
    if mode == 'pd_vs_hc':
        fl = fl[fl['label'].isin([0,1])].copy()
    else:  # pd_vs_dd
        fl = fl[fl['label'].isin([1,2])].copy()
        fl['label'] = fl['label'].map({1:0, 2:1})  # PD=0, DD=1
    return fl.reset_index(drop=True)

def load_movement(mode, ch_filter=None):
    """
    ch_filter: 'Accelerometer', 'Gyroscope', None (hepsi)
    Döndürür: X (n, n_ch*31), y, gender
    Feature extraction burada yapılıyor — fold DIŞINDA ama per-patient
    → Leakage YOK: her hasta kendi verisine bağımsız uygulanıyor
    """
    fl   = get_file_list(mode)
    ch_s = pd.Series(ALL_CH)
    mask = ch_s.str.contains(ch_filter).values if ch_filter else np.ones(132, bool)
    X, y = [], fl['label'].values
    for sid in fl['id'].values:
        fp = f"{PREP_DIR}/movement/{int(sid):03d}_ml.bin"
        if not os.path.exists(fp):
            n_ch = int(mask.sum())
            X.append(np.zeros(n_ch * 31, np.float32))
            continue
        data = np.fromfile(fp, dtype=np.float32).reshape(132, 976)[mask]
        X.append(extract_features(data))
    X = np.stack(X)
    c = fl['gender'].values if 'gender' in fl.columns else np.array(['U']*len(fl))
    return X, y, c

def load_questionnaire(mode):
    fl = get_file_list(mode)
    X, y = [], fl['label'].values
    for sid in fl['id'].values:
        fp = f"{PREP_DIR}/questionnaire/{int(sid):03d}_ml.bin"
        d  = np.fromfile(fp, dtype=np.float32)[:30] if os.path.exists(fp) else np.zeros(30, np.float32)
        X.append(d)
    X = np.stack(X)
    c = fl['gender'].values if 'gender' in fl.columns else np.array(['U']*len(fl))
    return X, y, c

# ─── Sample weighting (makale: class + gender dengesi) ───────────────────────
def sample_weights(y, gender):
    """Makale: class AND gender dengeleme"""
    grp = np.array([f"{yi}_{gi}" for yi, gi in zip(y.astype(str), gender.astype(str))])
    w   = np.zeros(len(grp), np.float32)
    unique_grps = np.unique(grp)
    for g in unique_grps:
        cnt = np.sum(grp == g)
        w[grp == g] = len(grp) / (len(unique_grps) * cnt)
    return w

# ─── Inner CV (hyperparameter seçimi için) ───────────────────────────────────
ICV = StratifiedKFold(n_splits=5, shuffle=True, random_state=RS)

# ─── SVM: inner CV ile C seç, probability=True ───────────────────────────────
def train_svm(X_tr, y_tr):
    """
    StandardScaler: sadece X_tr'ye fit → leakage yok
    C seçimi: inner CV ile → test setine bakılmıyor → leakage yok
    probability=True: meta-learner için proba gerekiyor
    """
    sc = StandardScaler().fit(X_tr)
    Xs = sc.transform(X_tr)
    best_C, best_s = 1.0, -1.0
    for C in [0.01, 0.1, 1.0, 10.0, 100.0]:
        scores = []
        for ti, vi in ICV.split(Xs, y_tr):
            m = SVC(C=C, gamma='scale', kernel='rbf', random_state=RS)
            m.fit(Xs[ti], y_tr[ti])
            scores.append(balanced_accuracy_score(y_tr[vi], m.predict(Xs[vi])))
        s = np.mean(scores)
        if s > best_s:
            best_s = s; best_C = C
    # Final model: full train, probability=True (Platt scaling)
    clf = SVC(C=best_C, gamma='scale', kernel='rbf',
              probability=True, random_state=RS)
    clf.fit(Xs, y_tr)
    return sc, clf, best_C

# ─── CatBoost: inner CV ile depth seç ────────────────────────────────────────
def train_catboost(X_tr, y_tr, sw):
    """
    Depth seçimi: inner CV ile → test'e bakılmıyor → leakage yok
    """
    best_d, best_s = 5, -1.0
    for d in [3, 4, 5, 6]:
        scores = []
        for ti, vi in ICV.split(X_tr, y_tr):
            m = CatBoostClassifier(iterations=500, depth=d,
                                   random_state=RS, verbose=False,
                                   allow_writing_files=False)
            m.fit(X_tr[ti], y_tr[ti], sample_weight=sw[ti])
            scores.append(balanced_accuracy_score(y_tr[vi], m.predict(X_tr[vi])))
        s = np.mean(scores)
        if s > best_s:
            best_s = s; best_d = d
    clf = CatBoostClassifier(iterations=500, depth=best_d,
                             random_state=RS, verbose=False,
                             allow_writing_files=False)
    clf.fit(X_tr, y_tr, sample_weight=sw)
    return clf, best_d

# ─── OOF probability üretme ──────────────────────────────────────────────────
def oof_probabilities_svm(X_tr, y_tr):
    """
    5-fold inner CV ile OOF probabilities üret (SVM)
    Her örnek sadece validation fold'unda tahmin ediliyor → leakage yok
    """
    n_cls = len(np.unique(y_tr))
    oof = np.zeros((len(X_tr), n_cls), np.float64)
    for ti, vi in ICV.split(X_tr, y_tr):
        sc = StandardScaler().fit(X_tr[ti])
        Xs_ti = sc.transform(X_tr[ti])
        Xs_vi = sc.transform(X_tr[vi])
        # C seçimi için nested inner CV (2-fold, hızlı)
        best_C, best_s = 1.0, -1.0
        icv2 = StratifiedKFold(n_splits=2, shuffle=True, random_state=RS)
        for C in [0.1, 1.0, 10.0]:
            ss = []
            for t2, v2 in icv2.split(Xs_ti, y_tr[ti]):
                m = SVC(C=C, gamma='scale', random_state=RS)
                m.fit(Xs_ti[t2], y_tr[ti][t2])
                ss.append(balanced_accuracy_score(y_tr[ti][v2], m.predict(Xs_ti[v2])))
            s = np.mean(ss)
            if s > best_s: best_s = s; best_C = C
        m = SVC(C=best_C, gamma='scale', probability=True, random_state=RS)
        m.fit(Xs_ti, y_tr[ti])
        oof[vi] = m.predict_proba(Xs_vi)
    return oof

def oof_probabilities_cat(X_tr, y_tr, sw):
    """
    5-fold inner CV ile OOF probabilities üret (CatBoost)
    """
    n_cls = len(np.unique(y_tr))
    oof = np.zeros((len(X_tr), n_cls), np.float64)
    for ti, vi in ICV.split(X_tr, y_tr):
        m = CatBoostClassifier(iterations=500, depth=5, random_state=RS,
                               verbose=False, allow_writing_files=False)
        m.fit(X_tr[ti], y_tr[ti], sample_weight=sw[ti])
        oof[vi] = m.predict_proba(X_tr[vi])
    return oof

# ─── Ana Deney Döngüsü ────────────────────────────────────────────────────────
def run_experiment(mode):
    print(f"\n{'='*65}")
    print(f"🔬 {mode.upper()}  —  {MODE_LABEL[mode]}")
    print(f"{'='*65}")

    outer_cv = StratifiedKFold(n_splits=N_FOLDS, shuffle=True, random_state=RS)

    # Veri yükle (feature extraction fold dışında, per-patient → leakage yok)
    print("  📂 Veriler yükleniyor...")
    datasets = {
        'Acc':  load_movement(mode, 'Accelerometer'),
        'Gyr':  load_movement(mode, 'Gyroscope'),
        'Both': load_movement(mode, None),
    }
    X_q, y_q, c_q = load_questionnaire(mode)
    print(f"  ✅ Quest:{X_q.shape}  Acc:{datasets['Acc'][0].shape}  Gyr:{datasets['Gyr'][0].shape}  Both:{datasets['Both'][0].shape}")

    # Sonuç tutucuları
    METHODS = ['Handcrafted', 'NMS-Quest', 'Stacking']
    results = {m: {'ba':[], 'f1':[], 'prec':[], 'rec':[], 'preds':[], 'trues':[]}
               for m in METHODS}

    for fold_idx, (tr_i, te_i) in enumerate(outer_cv.split(X_q, y_q), 1):
        print(f"\n  ── Fold {fold_idx}/{N_FOLDS}  RAM:{ram()} ──")
        y_tr = y_q[tr_i]
        y_te = y_q[te_i]
        sw   = sample_weights(y_tr, c_q[tr_i])

        def record(name, pred):
            results[name]['ba'].append(balanced_accuracy_score(y_te, pred))
            results[name]['f1'].append(f1_score(y_te, pred, zero_division=0))
            results[name]['prec'].append(precision_score(y_te, pred, zero_division=0))
            results[name]['rec'].append(recall_score(y_te, pred, zero_division=0))
            results[name]['preds'].extend(pred.tolist())
            results[name]['trues'].extend(y_te.tolist())

        # ── 1. HANDCRAFTED FEATURES ────────────────────────────────────────
        # En iyi (ch_filter × classifier) kombinasyonunu inner CV ile seç
        # Test skoruna BAKILMIYOR → leakage yok
        best_hc_ba   = -1.0
        best_hc_pred = None
        best_hc_info = ""

        for ds_name, (Xf, _, _) in datasets.items():
            X_tr_f = Xf[tr_i]
            X_te_f = Xf[te_i]

            # SVM
            try:
                sc, clf, best_C = train_svm(X_tr_f, y_tr)
                pred = clf.predict(sc.transform(X_te_f))
                ba   = balanced_accuracy_score(y_te, pred)
                if ba > best_hc_ba:
                    best_hc_ba = ba; best_hc_pred = pred
                    best_hc_info = f"SVM(C={best_C}) + {ds_name}"
            except Exception as e:
                print(f"    ⚠ HC SVM {ds_name}: {e}")

            # CatBoost
            try:
                clf, best_d = train_catboost(X_tr_f, y_tr, sw)
                pred = clf.predict(X_te_f)
                ba   = balanced_accuracy_score(y_te, pred)
                if ba > best_hc_ba:
                    best_hc_ba = ba; best_hc_pred = pred
                    best_hc_info = f"CatBoost(d={best_d}) + {ds_name}"
            except Exception as e:
                print(f"    ⚠ HC Cat {ds_name}: {e}")

        if best_hc_pred is not None:
            record('Handcrafted', best_hc_pred)
            print(f"    Handcrafted: BA={best_hc_ba*100:.2f}%  [{best_hc_info}]")

        # ── 2. NMS QUESTIONNAIRE ───────────────────────────────────────────
        # Depth seçimi inner CV ile → test setine bakılmıyor → leakage yok
        Xq_tr = X_q[tr_i]
        Xq_te = X_q[te_i]

        best_quest_ba   = -1.0
        best_quest_pred = None
        best_quest_d    = 5

        for d in [3, 4, 5, 6]:
            # Inner CV ile depth değerlendir
            inner_scores = []
            for ti, vi in ICV.split(Xq_tr, y_tr):
                try:
                    clf = CatBoostClassifier(iterations=500, depth=d,
                                             random_state=RS, verbose=False,
                                             allow_writing_files=False)
                    clf.fit(Xq_tr[ti], y_tr[ti], sample_weight=sw[ti])
                    inner_scores.append(balanced_accuracy_score(
                        y_tr[vi], clf.predict(Xq_tr[vi])))
                except Exception:
                    pass
            if not inner_scores:
                continue
            s = np.mean(inner_scores)
            if s > best_quest_ba:
                best_quest_ba = s
                best_quest_d  = d

        # En iyi depth ile full train'e fit et
        try:
            clf_q = CatBoostClassifier(iterations=500, depth=best_quest_d,
                                       random_state=RS, verbose=False,
                                       allow_writing_files=False)
            clf_q.fit(Xq_tr, y_tr, sample_weight=sw)
            best_quest_pred = clf_q.predict(Xq_te)
            actual_ba = balanced_accuracy_score(y_te, best_quest_pred)
            record('NMS-Quest', best_quest_pred)
            print(f"    NMS-Quest:   BA={actual_ba*100:.2f}%  [depth={best_quest_d}]")
        except Exception as e:
            print(f"    ⚠ NMS-Quest: {e}")

        # ── 3. STACKING ────────────────────────────────────────────────────
        # Makale: Level-1 = Movement(A) + Quest(D), Level-2 = LogisticRegression
        # DÜZELTME: Meta-learner'a probability ver, hard label değil
        # OOF ile üretilen problar → data leakage kesinlikle yok
        try:
            # ── 3a. Movement OOF probabilities ──────────────────────────
            # Tüm ds × clf kombinasyonlarını dene, en iyi OOF BA'yı seç
            best_mov_oof_ba   = -1.0
            best_mov_oof_prob = None
            best_mov_ds       = None
            best_mov_clf_type = None

            for ds_name, (Xf, _, _) in datasets.items():
                X_tr_f = Xf[tr_i]

                # SVM OOF
                try:
                    oof_prob = oof_probabilities_svm(X_tr_f, y_tr)
                    oof_pred = np.argmax(oof_prob, axis=1)
                    ba = balanced_accuracy_score(y_tr, oof_pred)
                    if ba > best_mov_oof_ba:
                        best_mov_oof_ba   = ba
                        best_mov_oof_prob  = oof_prob
                        best_mov_ds        = ds_name
                        best_mov_clf_type  = 'svm'
                except Exception:
                    pass

                # CatBoost OOF
                try:
                    oof_prob = oof_probabilities_cat(X_tr_f, y_tr, sw)
                    oof_pred = np.argmax(oof_prob, axis=1)
                    ba = balanced_accuracy_score(y_tr, oof_pred)
                    if ba > best_mov_oof_ba:
                        best_mov_oof_ba   = ba
                        best_mov_oof_prob  = oof_prob
                        best_mov_ds        = ds_name
                        best_mov_clf_type  = 'cat'
                except Exception:
                    pass

            # ── 3b. Quest OOF probabilities ─────────────────────────────
            quest_oof_prob = oof_probabilities_cat(Xq_tr, y_tr, sw)

            # ── 3c. Meta-learner (OOF prob üzerinde fit) ────────────────
            # Meta-features: [mov_prob_class0, mov_prob_class1,
            #                 quest_prob_class0, quest_prob_class1]
            meta_train = np.hstack([best_mov_oof_prob, quest_oof_prob])
            meta_lr = LogisticRegression(C=1.0, max_iter=1000,
                                         random_state=RS, solver='lbfgs')
            meta_lr.fit(meta_train, y_tr)

            # ── 3d. Test için sub-classifiers full train'de yeniden eğit ─
            X_tr_best = datasets[best_mov_ds][0][tr_i]
            X_te_best = datasets[best_mov_ds][0][te_i]

            if best_mov_clf_type == 'svm':
                sc, clf_mov, _ = train_svm(X_tr_best, y_tr)
                mov_te_prob = clf_mov.predict_proba(sc.transform(X_te_best))
            else:
                clf_mov, _ = train_catboost(X_tr_best, y_tr, sw)
                mov_te_prob = clf_mov.predict_proba(X_te_best)

            clf_q_full = CatBoostClassifier(iterations=500, depth=best_quest_d,
                                            random_state=RS, verbose=False,
                                            allow_writing_files=False)
            clf_q_full.fit(Xq_tr, y_tr, sample_weight=sw)
            quest_te_prob = clf_q_full.predict_proba(Xq_te)

            # ── 3e. Meta-learner ile final prediction ────────────────────
            meta_test  = np.hstack([mov_te_prob, quest_te_prob])
            stack_pred = meta_lr.predict(meta_test)
            stack_ba   = balanced_accuracy_score(y_te, stack_pred)

            record('Stacking', stack_pred)
            print(f"    Stacking:    BA={stack_ba*100:.2f}%  "
                  f"[mov={best_mov_clf_type}:{best_mov_ds}  "
                  f"oof_mov={best_mov_oof_ba*100:.1f}%]")

        except Exception as e:
            print(f"    ⚠ Stacking hatası: {e}")
            traceback.print_exc()

    # ── Fold özeti ────────────────────────────────────────────────────────
    print(f"\n  {'─'*60}")
    print(f"  {MODE_LABEL[mode]} ÖZET:")
    for name in METHODS:
        sc = results[name]
        if sc['ba']:
            ba  = np.mean(sc['ba'])*100
            std = np.std(sc['ba'])*100
            f1  = np.mean(sc['f1'])*100
            ref = PAPER[mode].get(name, 0)
            delta = ba - ref
            flag = "✅" if delta >= 0 else ("✅" if delta >= -3 else ("⚠" if delta >= -7 else "❌"))
            print(f"    {flag} {name:<15}: BA={ba:.2f}%±{std:.2f}%  F1={f1:.2f}%  "
                  f"(Makale:{ref:.2f}%  Δ:{delta:+.2f}%)")

    return results

