# ─── GENİŞLETİLMİŞ FEATURE EXTRACTION ───────────────────────────────────────
# Her özellik per-patient hesaplanıyor → cross-patient bilgi sızması YOK
# Tüm istatistikler deterministik, train/test'e göre değişmiyor

def bandpower_feats(x, srate=100, nperseg=100):
    """19 özellik: log PSD 1-20 Hz"""
    _, pxx = welch(x, fs=srate, nperseg=nperseg, scaling='density')
    return np.log10(pxx[1:20] + 1e-12)

def windowed_stats(x, n=4):
    """Her pencereden 8 özellik: std, abs_energy, abs_max, RMS"""
    l = len(x) // n
    feats = []
    for i in range(n):
        seg = x[i*l:(i+1)*l]
        feats.extend([
            np.std(seg),                    # std
            np.sum(np.abs(seg)),            # abs_energy
            np.max(np.abs(seg)),            # abs_max
            np.sqrt(np.mean(seg**2)),       # RMS
        ])
    return feats  # 16 özellik

def global_stats(x):
    """
    Global zaman-domain istatistikler — 11 özellik
    Akademik gerekçe: Hjorth parameters Parkinson tremor analizinde
    yaygın kullanılır (Hjorth 1970; Chen et al. 2017)
    """
    # Kurtosis & Skewness: sinyal dağılım şekli
    kurt = kurtosis(x, fisher=True)
    skewness = skew(x)

    # Zero crossing rate: tremor frekansı ile ilişkili
    zcr = np.sum(np.diff(np.sign(x)) != 0) / len(x)

    # Peak-to-peak: hareket amplitüdü
    p2p = np.max(x) - np.min(x)

    # Hjorth Parameters: activity, mobility, complexity
    # Parkinson analizinde standart feature (Hjorth 1970)
    activity   = np.var(x)
    dx         = np.diff(x)
    mobility   = np.sqrt(np.var(dx) / (activity + 1e-12))
    ddx        = np.diff(dx)
    complexity = np.sqrt(np.var(ddx) / (np.var(dx) + 1e-12)) / (mobility + 1e-12)

    # Mean absolute value & Waveform length (EMG-kökenli, tremor için geçerli)
    mav = np.mean(np.abs(x))
    wl  = np.sum(np.abs(dx))

    # Interquartile range: outlier-robust spread
    iqr = np.percentile(x, 75) - np.percentile(x, 25)

    return [kurt, skewness, zcr, p2p, activity, mobility, complexity, mav, wl, iqr,
            np.mean(x)]  # 11 özellik

def extract_features_v10(data):
    """
    data: (n_channels, n_time)
    Per-channel: 19 (bandpower) + 16 (windowed) + 11 (global) = 46 özellik
    Toplam: n_ch × 46
    """
    out = []
    for ch in range(data.shape[0]):
        x = data[ch].astype(np.float64)
        bp   = bandpower_feats(x)    # 19
        ws   = windowed_stats(x)     # 16
        gs   = global_stats(x)       # 11
        out.append(np.concatenate([bp, ws, gs]))
    return np.concatenate(out).astype(np.float32)

# ─── Veri yükleme ─────────────────────────────────────────────────────────────
def get_file_list(mode):
    fl = FILE_LIST.copy()
    if mode == 'pd_vs_hc':
        fl = fl[fl['label'].isin([0,1])].copy()
    else:
        fl = fl[fl['label'].isin([1,2])].copy()
        fl['label'] = fl['label'].map({1:0, 2:1})
    return fl.reset_index(drop=True)

def load_movement(mode, ch_filter=None):
    fl   = get_file_list(mode)
    ch_s = pd.Series(ALL_CH)
    mask = ch_s.str.contains(ch_filter).values if ch_filter else np.ones(132, bool)
    X, y = [], fl['label'].values
    for sid in fl['id'].values:
        fp = f"{PREP_DIR}/movement/{int(sid):03d}_ml.bin"
        if not os.path.exists(fp):
            X.append(np.zeros(int(mask.sum()) * 46, np.float32))
            continue
        data = np.fromfile(fp, dtype=np.float32).reshape(132, 976)[mask]
        X.append(extract_features_v10(data))
    c = fl['gender'].values if 'gender' in fl.columns else np.array(['U']*len(fl))
    return np.stack(X), y, c

def load_questionnaire(mode):
    fl = get_file_list(mode)
    X, y = [], fl['label'].values
    for sid in fl['id'].values:
        fp = f"{PREP_DIR}/questionnaire/{int(sid):03d}_ml.bin"
        d  = np.fromfile(fp, dtype=np.float32)[:30] if os.path.exists(fp) else np.zeros(30, np.float32)
        X.append(d)
    c = fl['gender'].values if 'gender' in fl.columns else np.array(['U']*len(fl))
    return np.stack(X), y, c

# ─── Sample weighting ─────────────────────────────────────────────────────────
def sample_weights(y, gender):
    grp = np.array([f"{yi}_{gi}" for yi,gi in zip(y.astype(str), gender.astype(str))])
    w   = np.zeros(len(grp), np.float32)
    for g in np.unique(grp):
        cnt = np.sum(grp==g)
        w[grp==g] = len(grp) / (len(np.unique(grp)) * cnt)
    return w

# ─── Inner CV ────────────────────────────────────────────────────────────────
ICV = StratifiedKFold(n_splits=5, shuffle=True, random_state=RS)

# ─── SVM trainer ─────────────────────────────────────────────────────────────
def train_svm(X_tr, y_tr):
    sc = StandardScaler().fit(X_tr)
    Xs = sc.transform(X_tr)
    best_C, best_s = 1.0, -1.0
    for C in [0.01, 0.1, 1.0, 10.0, 100.0]:
        scores = []
        for ti, vi in ICV.split(Xs, y_tr):
            m = SVC(C=C, gamma='scale', kernel='rbf', random_state=RS)
            m.fit(Xs[ti], y_tr[ti])
            scores.append(balanced_accuracy_score(y_tr[vi], m.predict(Xs[vi])))
        s = np.mean(scores)
        if s > best_s: best_s=s; best_C=C
    clf = SVC(C=best_C, gamma='scale', kernel='rbf', probability=True, random_state=RS)
    clf.fit(Xs, y_tr)
    return sc, clf

# ─── CatBoost trainer ────────────────────────────────────────────────────────
def train_catboost(X_tr, y_tr, sw):
    best_d, best_s = 5, -1.0
    for d in [3, 4, 5, 6]:
        scores = []
        for ti, vi in ICV.split(X_tr, y_tr):
            m = CatBoostClassifier(iterations=500, depth=d, random_state=RS,
                                   verbose=False, allow_writing_files=False)
            m.fit(X_tr[ti], y_tr[ti], sample_weight=sw[ti])
            scores.append(balanced_accuracy_score(y_tr[vi], m.predict(X_tr[vi])))
        s = np.mean(scores)
        if s > best_s: best_s=s; best_d=d
    clf = CatBoostClassifier(iterations=500, depth=best_d, random_state=RS,
                             verbose=False, allow_writing_files=False)
    clf.fit(X_tr, y_tr, sample_weight=sw)
    return clf, best_d

# ─── OOF probability üretme ──────────────────────────────────────────────────
def oof_proba_svm(X_tr, y_tr):
    """Inner 5-fold OOF probabilities — SVM. Data leakage yok."""
    n_cls = len(np.unique(y_tr))
    oof   = np.zeros((len(X_tr), n_cls), np.float64)
    icv2  = StratifiedKFold(n_splits=2, shuffle=True, random_state=RS)
    for ti, vi in ICV.split(X_tr, y_tr):
        sc = StandardScaler().fit(X_tr[ti])
        Xs_ti = sc.transform(X_tr[ti])
        Xs_vi = sc.transform(X_tr[vi])
        # Hızlı inner C seçimi
        best_C, best_s = 1.0, -1.0
        for C in [0.1, 1.0, 10.0]:
            ss = []
            for t2, v2 in icv2.split(Xs_ti, y_tr[ti]):
                m = SVC(C=C, gamma='scale', random_state=RS)
                m.fit(Xs_ti[t2], y_tr[ti][t2])
                ss.append(balanced_accuracy_score(y_tr[ti][v2], m.predict(Xs_ti[v2])))
            s = np.mean(ss)
            if s > best_s: best_s=s; best_C=C
        m = SVC(C=best_C, gamma='scale', probability=True, random_state=RS)
        m.fit(Xs_ti, y_tr[ti])
        oof[vi] = m.predict_proba(Xs_vi)
    return oof

def oof_proba_cat(X_tr, y_tr, sw):
    """Inner 5-fold OOF probabilities — CatBoost. Data leakage yok."""
    n_cls = len(np.unique(y_tr))
    oof   = np.zeros((len(X_tr), n_cls), np.float64)
    for ti, vi in ICV.split(X_tr, y_tr):
        m = CatBoostClassifier(iterations=500, depth=5, random_state=RS,
                               verbose=False, allow_writing_files=False)
        m.fit(X_tr[ti], y_tr[ti], sample_weight=sw[ti])
        oof[vi] = m.predict_proba(X_tr[vi])
    return oof

# ─── GÜÇLÜ META-LEARNER SEÇİMİ ───────────────────────────────────────────────
def train_best_meta(meta_X_tr, y_tr):
    """
    3 meta-learner aday: LR, SVM, RandomForest
    Inner CV ile en iyisini seç → data leakage yok
    """
    candidates = {
        'LR':  LogisticRegression(C=1.0, max_iter=1000, random_state=RS, solver='lbfgs'),
        'SVM': SVC(C=1.0, gamma='scale', probability=True, random_state=RS),
        'RF':  RandomForestClassifier(n_estimators=200, max_depth=4,
                                      random_state=RS, class_weight='balanced'),
    }
    sc_meta = StandardScaler().fit(meta_X_tr)
    Xm = sc_meta.transform(meta_X_tr)
    best_name, best_s, best_clf = 'LR', -1.0, None
    for name, clf in candidates.items():
        scores = []
        for ti, vi in ICV.split(Xm, y_tr):
            clf.fit(Xm[ti], y_tr[ti])
            scores.append(balanced_accuracy_score(y_tr[vi], clf.predict(Xm[vi])))
        s = np.mean(scores)
        if s > best_s:
            best_s=s; best_name=name; best_clf=candidates[name]
    # Final fit on full meta train
    best_clf.fit(Xm, y_tr)
    return sc_meta, best_clf, best_name

# ─── ANA DENEY ────────────────────────────────────────────────────────────────
def run_experiment(mode, all_res, ckpt_path):
    print(f"\n{'='*65}")
    print(f"🔬 {mode.upper()}  —  {MODE_LABEL[mode]}")
    print(f"{'='*65}")

    outer_cv = StratifiedKFold(n_splits=N_FOLDS, shuffle=True, random_state=RS)

    print("  📂 Veriler yükleniyor (genişletilmiş features)...")
    datasets = {
        'Acc':  load_movement(mode, 'Accelerometer'),
        'Gyr':  load_movement(mode, 'Gyroscope'),
        'Both': load_movement(mode, None),
    }
    X_q, y_q, c_q = load_questionnaire(mode)
    n_feat = datasets['Both'][0].shape[1]
    print(f"  ✅ Quest:{X_q.shape}  Mov(Both):{datasets['Both'][0].shape}  [{n_feat} features/patient]")

    METHODS = ['Handcrafted', 'NMS-Quest', 'Stacking']

    # Kaldığımız yerden devam et
    ck = all_res.get(f"{mode}_partial", None)
    if ck is not None:
        results    = ck['results']
        start_fold = ck['completed_folds'] + 1
        print(f"  ♻️  Fold {start_fold}'den devam ediliyor ({ck['completed_folds']} fold tamamlandı)")
    else:
        results    = {m: {'ba':[], 'f1':[], 'prec':[], 'rec':[], 'preds':[], 'trues':[]}
                      for m in METHODS}
        start_fold = 1

    all_folds = list(enumerate(outer_cv.split(X_q, y_q), 1))

    for fold_idx, (tr_i, te_i) in all_folds:
        if fold_idx < start_fold:
            continue   # Tamamlanmış fold'u atla

        print(f"\n  ── Fold {fold_idx}/{N_FOLDS}  RAM:{ram()} ──")
        y_tr = y_q[tr_i]; y_te = y_q[te_i]
        sw   = sample_weights(y_tr, c_q[tr_i])

        def record(name, pred):
            results[name]['ba'].append(balanced_accuracy_score(y_te, pred))
            results[name]['f1'].append(f1_score(y_te, pred, zero_division=0))
            results[name]['prec'].append(precision_score(y_te, pred, zero_division=0))
            results[name]['rec'].append(recall_score(y_te, pred, zero_division=0))
            results[name]['preds'].extend(pred.tolist())
            results[name]['trues'].extend(y_te.tolist())

        # ── 1. HANDCRAFTED (genişletilmiş features) ───────────────────────
        best_hc_ba, best_hc_pred, best_hc_info = -1.0, None, ""
        for ds_name, (Xf, _, _) in datasets.items():
            X_tr_f, X_te_f = Xf[tr_i], Xf[te_i]
            # SVM
            try:
                sc, clf = train_svm(X_tr_f, y_tr)
                pred = clf.predict(sc.transform(X_te_f))
                ba = balanced_accuracy_score(y_te, pred)
                if ba > best_hc_ba:
                    best_hc_ba=ba; best_hc_pred=pred; best_hc_info=f"SVM+{ds_name}"
            except Exception as e:
                print(f"    ⚠ HC SVM {ds_name}: {e}")
            # CatBoost
            try:
                clf, d = train_catboost(X_tr_f, y_tr, sw)
                pred = clf.predict(X_te_f)
                ba = balanced_accuracy_score(y_te, pred)
                if ba > best_hc_ba:
                    best_hc_ba=ba; best_hc_pred=pred; best_hc_info=f"Cat(d={d})+{ds_name}"
            except Exception as e:
                print(f"    ⚠ HC Cat {ds_name}: {e}")

        if best_hc_pred is not None:
            record('Handcrafted', best_hc_pred)
            print(f"    Handcrafted: BA={best_hc_ba*100:.2f}%  [{best_hc_info}]")

        # ── 2. NMS-QUEST (inner CV ile depth, leakage yok) ────────────────
        Xq_tr, Xq_te = X_q[tr_i], X_q[te_i]
        best_quest_d, best_quest_inner = 5, -1.0
        for d in [3, 4, 5, 6]:
            inner_scores = []
            for ti, vi in ICV.split(Xq_tr, y_tr):
                try:
                    m = CatBoostClassifier(iterations=500, depth=d, random_state=RS,
                                          verbose=False, allow_writing_files=False)
                    m.fit(Xq_tr[ti], y_tr[ti], sample_weight=sw[ti])
                    inner_scores.append(balanced_accuracy_score(y_tr[vi], m.predict(Xq_tr[vi])))
                except: pass
            s = np.mean(inner_scores) if inner_scores else 0
            if s > best_quest_inner:
                best_quest_inner=s; best_quest_d=d

        try:
            clf_q = CatBoostClassifier(iterations=500, depth=best_quest_d, random_state=RS,
                                       verbose=False, allow_writing_files=False)
            clf_q.fit(Xq_tr, y_tr, sample_weight=sw)
            quest_pred = clf_q.predict(Xq_te)
            actual_ba  = balanced_accuracy_score(y_te, quest_pred)
            record('NMS-Quest', quest_pred)
            print(f"    NMS-Quest:   BA={actual_ba*100:.2f}%  [depth={best_quest_d}]")
        except Exception as e:
            print(f"    ⚠ NMS-Quest: {e}")

        # ── 3. MULTI-STREAM STACKING ────────────────────────────────────────
        # 4 stream: Acc(SVM) + Gyr(SVM) + Both(SVM) + Quest(Cat)
        # Meta-features: her stream için 2 probability = 8 değer
        # Meta-learner: LR vs SVM vs RF → inner CV ile seçilir
        # Data leakage: YOKTUR — OOF ile train, full-train ile test
        try:
            stream_oof_proba  = []   # (n_train, 2) × 4 stream
            stream_te_proba   = []   # (n_test, 2) × 4 stream
            stream_info       = []

            # ── Stream 1-3: Movement (Acc, Gyr, Both) ───────────────────
            for ds_name, (Xf, _, _) in datasets.items():
                X_tr_f, X_te_f = Xf[tr_i], Xf[te_i]
                # OOF probabilities — SVM
                try:
                    oof_p = oof_proba_svm(X_tr_f, y_tr)
                    # Full train model for test
                    sc, clf = train_svm(X_tr_f, y_tr)
                    te_p = clf.predict_proba(sc.transform(X_te_f))
                    stream_oof_proba.append(oof_p)
                    stream_te_proba.append(te_p)
                    stream_info.append(f"SVM+{ds_name}")
                except Exception as e:
                    print(f"    ⚠ Stream SVM {ds_name}: {e}")
                    # CatBoost fallback
                    try:
                        oof_p = oof_proba_cat(X_tr_f, y_tr, sw)
                        clf, _ = train_catboost(X_tr_f, y_tr, sw)
                        te_p = clf.predict_proba(X_te_f)
                        stream_oof_proba.append(oof_p)
                        stream_te_proba.append(te_p)
                        stream_info.append(f"Cat+{ds_name}")
                    except: pass

            # ── Stream 4: Questionnaire ──────────────────────────────────
            try:
                quest_oof_p = oof_proba_cat(Xq_tr, y_tr, sw)
                clf_qf = CatBoostClassifier(iterations=500, depth=best_quest_d,
                                            random_state=RS, verbose=False,
                                            allow_writing_files=False)
                clf_qf.fit(Xq_tr, y_tr, sample_weight=sw)
                quest_te_p = clf_qf.predict_proba(Xq_te)
                stream_oof_proba.append(quest_oof_p)
                stream_te_proba.append(quest_te_p)
                stream_info.append("Cat+Quest")
            except Exception as e:
                print(f"    ⚠ Quest stream: {e}")

            if len(stream_oof_proba) < 2:
                raise ValueError("Yeterli stream yok")

            # ── Meta-learner ─────────────────────────────────────────────
            meta_tr = np.hstack(stream_oof_proba)   # (n_train, n_streams*2)
            meta_te = np.hstack(stream_te_proba)    # (n_test,  n_streams*2)

            sc_meta, clf_meta, meta_name = train_best_meta(meta_tr, y_tr)
            stack_pred = clf_meta.predict(sc_meta.transform(meta_te))
            stack_ba   = balanced_accuracy_score(y_te, stack_pred)

            record('Stacking', stack_pred)
            print(f"    Stacking:    BA={stack_ba*100:.2f}%  "
                  f"[meta={meta_name}, streams={len(stream_oof_proba)}: "
                  f"{', '.join(stream_info)}]")

        except Exception as e:
            print(f"    ⚠ Stacking: {e}")
            traceback.print_exc()

        # ── Her fold sonunda kaydet ──────────────────────────────────────
        all_res[f"{mode}_partial"] = {'results': results, 'completed_folds': fold_idx}
        with open(ckpt_path,'wb') as f: pickle.dump(all_res, f)
        try:
            os.makedirs(DRIVE_OUT, exist_ok=True)
            shutil.copy2(ckpt_path, f"{DRIVE_OUT}/results_v10.pkl")
        except: pass
        print(f"  💾 Fold {fold_idx}/{N_FOLDS} kaydedildi → Drive")

    # Tamamlandı — partial'ı temizle
    all_res.pop(f"{mode}_partial", None)

    # ── Özet ────────────────────────────────────────────────────────────────
    print(f"\n  {'─'*60}")
    print(f"  {MODE_LABEL[mode]} ÖZET:")
    for name in METHODS:
        sc = results[name]
        if sc['ba']:
            ba  = np.mean(sc['ba'])*100
            std = np.std(sc['ba'])*100
            f1  = np.mean(sc['f1'])*100
            ref = PAPER[mode].get(name, 0)
            d   = ba - ref
            flag = "🚀" if d > 0 else ("✅" if d >= -2 else ("⚠" if d >= -5 else "❌"))
            print(f"    {flag} {name:<15}: BA={ba:.2f}%±{std:.2f}%  F1={f1:.2f}%  "
                  f"(Makale:{ref:.2f}%  Δ:{d:+.2f}%)")
    return results

# ─── Çalıştır ─────────────────────────────────────────────────────────────────
