    if mode in all_res:
        print(f"\n♻️  {mode} zaten tamamlanmış, atlanıyor.")
        continue
    # Partial varsa (fold ortasında kesilmiş) veya hiç yoksa çalıştır
    all_res[mode] = run_experiment(mode, all_res, CKPT)
    with open(CKPT,'wb') as f: pickle.dump(all_res, f)
    try:
        os.makedirs(DRIVE_OUT, exist_ok=True)
        shutil.copy2(CKPT, f"{DRIVE_OUT}/results_v10.pkl")
        print(f"  💾 {mode} tamamlandı → Drive")
    except Exception as e:
        print(f"  ⚠ Drive: {e}")

