np.random.seed(RS)

PAPER = {
    'pd_vs_hc': {'Handcrafted':78.99,'NMS-Quest':89.79,'Stacking':91.16},
    'pd_vs_dd': {'Handcrafted':69.18,'NMS-Quest':67.77,'Stacking':72.42},
}
MODE_LABEL = {'pd_vs_hc':'PD vs HC','pd_vs_dd':'PD vs DD'}
def ram(): m=psutil.virtual_memory(); return f"{(m.total-m.available)/1e9:.1f}/{m.total/1e9:.1f}GB"

