# ─── Preprocessed veriler — robust kopya ──────────────────────────────────────
def robust_copy(src_dir, dst_dir):
    """Drive okuma hatalarına karşı dayanıklı dosya kopyalama."""
    os.makedirs(dst_dir, exist_ok=True)
    files = glob(f"{src_dir}/*.bin") + glob(f"{src_dir}/*.csv")
    ok = 0
    for fp in files:
        dst = os.path.join(dst_dir, os.path.basename(fp))
        if os.path.exists(dst) and os.path.getsize(dst) > 0:
            ok += 1; continue
        for attempt in range(3):
            try:
                shutil.copy2(fp, dst)
                ok += 1; break
            except Exception as e:
                if attempt == 2:
                    print(f"  ⚠ Atlandı: {os.path.basename(fp)} ({e})")
                else:
                    time.sleep(2)
    return ok

