# ─── Feature extraction ───────────────────────────────────────────────────────
def extract_features(data):
    """Per-patient, deterministik. Leakage yok."""
    out = []
    for ch in range(data.shape[0]):
        x = data[ch].astype(np.float64)
        _, pxx = welch(x, fs=100, nperseg=100, scaling='density')
        bp = np.log10(pxx[1:20] + 1e-12)
        l = len(x) // 4
        ws = []
        for i in range(4):
            seg = x[i*l:(i+1)*l]
            ws.extend([np.std(seg), np.sum(np.abs(seg)),
                       np.max(np.abs(seg)), np.sqrt(np.mean(seg**2))])
        dx = np.diff(x); ddx = np.diff(dx); act = np.var(x)
        mob = np.sqrt(np.var(dx) / (act + 1e-12))
        cmp = np.sqrt(np.var(ddx) / (np.var(dx) + 1e-12)) / (mob + 1e-12)
        gs = [kurtosis(x, fisher=True), skew(x),
              np.sum(np.diff(np.sign(x)) != 0) / len(x),
              np.max(x) - np.min(x), act, mob, cmp,
              np.mean(np.abs(x)), np.sum(np.abs(dx)),
              np.percentile(x, 75) - np.percentile(x, 25), np.mean(x)]
        out.append(np.concatenate([bp, ws, gs]))
    return np.concatenate(out).astype(np.float32)

