# ─── Channels ─────────────────────────────────────────────────────────────────
ALL_CH = [f"{t}_{w}_{s}_{a}"
          for t in ['Relaxed1','Relaxed2','RelaxedTask1','RelaxedTask2','StretchHold',
                    'HoldWeight','DrinkGlas','CrossArms','TouchNose','Entrainment1','Entrainment2']
          for w in ['LeftWrist','RightWrist']
          for s in ['Accelerometer','Gyroscope']
          for a in ['X','Y','Z']]
assert len(ALL_CH) == 132

# ─── Feature extraction — per-patient, deterministik ─────────────────────────
# LEAKAGE KONTROLÜ 1: Her hasta bağımsız hesaplanıyor.
# Diğer hastaların verisi kullanılmıyor.
def extract_features(data):
    out = []
    for ch in range(data.shape[0]):
        x = data[ch].astype(np.float64)
        _, pxx = welch(x, fs=100, nperseg=100, scaling='density')
        bp = np.log10(pxx[1:20] + 1e-12)
        l  = len(x) // 4
        ws = []
        for i in range(4):
            seg = x[i*l:(i+1)*l]
            ws.extend([np.std(seg), np.sum(np.abs(seg)),
                       np.max(np.abs(seg)), np.sqrt(np.mean(seg**2))])
        dx = np.diff(x); ddx = np.diff(dx); act = np.var(x)
        mob = np.sqrt(np.var(dx) / (act + 1e-12))
        cmp = np.sqrt(np.var(ddx) / (np.var(dx) + 1e-12)) / (mob + 1e-12)
        gs  = [kurtosis(x,fisher=True), skew(x),
               np.sum(np.diff(np.sign(x))!=0)/len(x),
               np.max(x)-np.min(x), act, mob, cmp,
               np.mean(np.abs(x)), np.sum(np.abs(dx)),
               np.percentile(x,75)-np.percentile(x,25), np.mean(x)]
        out.append(np.concatenate([bp, ws, gs]))
    return np.concatenate(out).astype(np.float32)

def get_fl(mode):
    fl = FILE_LIST.copy()
    if mode == 'pd_vs_hc':
        fl = fl[fl['label'].isin([0,1])].copy()
    else:
        fl = fl[fl['label'].isin([1,2])].copy()
        fl['label'] = fl['label'].map({1:0, 2:1})
    return fl.reset_index(drop=True)

def load_mov(mode, ch_filter=None):
    fl   = get_fl(mode)
    mask = (pd.Series(ALL_CH).str.contains(ch_filter).values
            if ch_filter else np.ones(132, bool))
    X = []
    for sid in fl['id'].values:
        fp = f"{PREP_DIR}/movement/{int(sid):03d}_ml.bin"
        X.append(extract_features(
            np.fromfile(fp, dtype=np.float32).reshape(132,976)[mask])
            if os.path.exists(fp) else
            np.zeros(int(mask.sum())*46, np.float32))
    c = fl['gender'].values if 'gender' in fl.columns else np.array(['U']*len(fl))
    return np.stack(X), fl['label'].values, c

def load_quest(mode):
    fl = get_fl(mode); X = []
    for sid in fl['id'].values:
        fp = f"{PREP_DIR}/questionnaire/{int(sid):03d}_ml.bin"
        X.append(np.fromfile(fp,dtype=np.float32)[:30]
                 if os.path.exists(fp) else np.zeros(30,np.float32))
    c = fl['gender'].values if 'gender' in fl.columns else np.array(['U']*len(fl))
    return np.stack(X), fl['label'].values, c

def sample_weights(y, gender):
    grp = np.array([f"{yi}_{gi}" for yi,gi in zip(y.astype(str),gender.astype(str))])
    w   = np.zeros(len(grp), np.float32)
    for g in np.unique(grp):
        n = np.sum(grp==g)
        w[grp==g] = len(grp)/(len(np.unique(grp))*n)
    return w

ICV = StratifiedKFold(n_splits=5, shuffle=True, random_state=RS)

# ─── Modeller — sadece Cat+LGB GPU ───────────────────────────────────────────
# LEAKAGE KONTROLÜ 2: fit() sadece train slice üzerinde çağrılıyor.
def cat(X_tr, y_tr, sw, depth=6, iters=300):
    m = CatBoostClassifier(iterations=iters, depth=depth,
                           random_seed=RS, verbose=False,
                           allow_writing_files=False,
                           task_type=CAT_DEVICE,
                           **({'devices':'0'} if HAS_GPU else {}))
    m.fit(X_tr, y_tr, sample_weight=sw)
    return m

def lgb_m(X_tr, y_tr, sw, depth=6, iters=300):
    n = len(np.unique(y_tr))
    p = dict(n_estimators=iters, max_depth=depth, learning_rate=0.05,
             num_leaves=63, random_state=RS, verbose=-1,
             class_weight='balanced', n_jobs=1 if HAS_GPU else -1,
             device=LGB_DEVICE,
             objective='binary' if n==2 else 'multiclass')
    if n > 2: p['num_class'] = n
    m = lgb.LGBMClassifier(**p)
    m.fit(X_tr, y_tr, sample_weight=sw)
    return m

def cat_lgb_proba(X_tr, y_tr, sw, X_te, depth=6, iters=300):
    """Cat+LGB soft voting proba. Leakage yok."""
    pc = cat(X_tr,y_tr,sw,depth,iters).predict_proba(X_te)
    pl = lgb_m(X_tr,y_tr,sw,depth,iters).predict_proba(X_te)
    return (pc+pl)/2

# LEAKAGE KONTROLÜ 3: innerCV sadece X_tr[ti] kullanıyor, X_te hiç görülmüyor.
def depth_cv_cat(X_tr, y_tr, sw, depths, iters):
    best_d, best_s = depths[0], -1.0
    for d in depths:
        sc = [balanced_accuracy_score(y_tr[vi],
              cat(X_tr[ti],y_tr[ti],sw[ti],d,iters).predict(X_tr[vi]))
              for ti,vi in ICV.split(X_tr,y_tr)]
        if np.mean(sc) > best_s:
            best_s = np.mean(sc); best_d = d
    return best_d

# LEAKAGE KONTROLÜ 4: OOF — her örnek sadece kendi val fold'unda tahmin ediliyor.
def oof_proba(X_tr, y_tr, sw, depth=6, iters=300):
    n   = len(np.unique(y_tr))
    oof = np.zeros((len(X_tr), n), np.float64)
    for ti, vi in ICV.split(X_tr, y_tr):
        oof[vi] = cat_lgb_proba(X_tr[ti],y_tr[ti],sw[ti],X_tr[vi],depth,iters)
    return oof

# LEAKAGE KONTROLÜ 5: Meta scaler sadece OOF_train'e fit ediliyor.
# LEAKAGE KONTROLÜ 6: Meta model seçimi inner CV ile, test'e bakılmıyor.
def train_meta(meta_tr, y_tr):
    sc = StandardScaler().fit(meta_tr)
    Xm = sc.transform(meta_tr)
    best_name, best_s, best_clf = 'LR', -1.0, None
    for name, clf in [
        ('LR',  LogisticRegression(C=1.0, max_iter=2000, random_state=RS)),
        ('SVM', SVC(C=1.0, gamma='scale', probability=True, random_state=RS)),
        ('RF',  RandomForestClassifier(n_estimators=200, random_state=RS,
                                        class_weight='balanced')),
    ]:
        ss = [balanced_accuracy_score(y_tr[vi],
              clf.fit(Xm[ti],y_tr[ti]).predict(Xm[vi]))
              for ti,vi in ICV.split(Xm,y_tr)]
        s = np.mean(ss)
        if s > best_s:
            best_s = s; best_name = name
            best_clf = (LogisticRegression(C=1.0,max_iter=2000,random_state=RS)
                        if name=='LR' else
                        SVC(C=1.0,gamma='scale',probability=True,random_state=RS)
                        if name=='SVM' else
                        RandomForestClassifier(n_estimators=200,random_state=RS,
                                               class_weight='balanced'))
    best_clf.fit(Xm, y_tr)
    return sc, best_clf, best_name

# ─── ANA DENEY ────────────────────────────────────────────────────────────────
def run_experiment(mode, all_res, ckpt_path):
    print(f"\n{'='*65}")
    print(f"🔬 {mode.upper()}  —  {MODE_LABEL[mode]}")
    print(f"{'='*65}")

    outer_cv = StratifiedKFold(n_splits=N_FOLDS, shuffle=True, random_state=RS)

    print("  📂 Veriler yükleniyor...")
    X_both, y_all, c_all = load_mov(mode, None)
    X_gyr,  _,     _     = load_mov(mode, 'Gyroscope')
    X_q,    _,     _     = load_quest(mode)
    print(f"  ✅ Both:{X_both.shape}  Gyr:{X_gyr.shape}  Quest:{X_q.shape}")

    ck = all_res.get(f"{mode}_partial")
    if ck:
        results    = ck['results']
        start_fold = ck['completed_folds'] + 1
        print(f"  ♻️  Fold {start_fold}'den devam ({ck['completed_folds']} tamamlandı)")
    else:
        results = {m: {'ba':[],'f1':[],'prec':[],'rec':[],
                       'preds':[],'trues':[],'proba':[]}
                   for m in METHODS}
        start_fold = 1

    for fold_idx, (tr_i, te_i) in enumerate(outer_cv.split(X_both, y_all), 1):
        if fold_idx < start_fold:
            continue
        t0 = time.time()
        print(f"\n  ── Fold {fold_idx}/{N_FOLDS}  RAM:{ram()} ──")
        y_tr = y_all[tr_i]; y_te = y_all[te_i]
        sw   = sample_weights(y_tr, c_all[tr_i])

        def record(name, pred, proba=None):
            results[name]['ba'].append(balanced_accuracy_score(y_te, pred))
            results[name]['f1'].append(f1_score(y_te, pred, zero_division=0))
            results[name]['prec'].append(precision_score(y_te, pred, zero_division=0))
            results[name]['rec'].append(recall_score(y_te, pred, zero_division=0))
            results[name]['preds'].extend(pred.tolist())
            results[name]['trues'].extend(y_te.tolist())
            if proba is not None:
                results[name]['proba'].extend(proba.tolist())

        # ── 1. HANDCRAFTED ────────────────────────────────────────────────
        # Cat+LGB GPU, iter=500, innerCV depth(5,6)
        # Both ve Gyr dene → en iyi BA'yı al
        # v10: 84.48%🚀 (iter=500)  v9: DD=70.63%🚀
        best_ba, best_pred, best_proba, best_info = -1.0, None, None, ""
        for ds_name, Xf in [('Both', X_both), ('Gyr', X_gyr)]:
            try:
                d    = depth_cv_cat(Xf[tr_i], y_tr, sw,
                                    depths=(5,6), iters=ITERS_HC)
                prob = cat_lgb_proba(Xf[tr_i], y_tr, sw,
                                     Xf[te_i], depth=d, iters=ITERS_HC)
                pred = np.argmax(prob, axis=1)
                ba   = balanced_accuracy_score(y_te, pred)
                if ba > best_ba:
                    best_ba = ba; best_pred = pred
                    best_proba = prob; best_info = f"Cat+LGB(d={d})+{ds_name}"
            except Exception as e:
                print(f"    ⚠ HC {ds_name}: {e}")

        if best_pred is not None:
            record('Handcrafted', best_pred, best_proba)
            print(f"    Handcrafted: BA={best_ba*100:.2f}%  "
                  f"[{best_info}]  ({time.time()-t0:.0f}s)")

        # ── 2. NMS-QUEST ──────────────────────────────────────────────────
        # Cat+LGB GPU, iter=500, innerCV depth(3,4,5,6)
        # v16: 89.96%🚀
        Xq_tr, Xq_te = X_q[tr_i], X_q[te_i]
        best_d_q = 5
        try:
            best_d_q = depth_cv_cat(Xq_tr, y_tr, sw,
                                     depths=(3,4,5,6), iters=ITERS_QUEST)
            prob = cat_lgb_proba(Xq_tr, y_tr, sw, Xq_te,
                                  depth=best_d_q, iters=ITERS_QUEST)
            pred = np.argmax(prob, axis=1)
            record('NMS-Quest', pred, prob)
            print(f"    NMS-Quest:   BA={balanced_accuracy_score(y_te,pred)*100:.2f}%  "
                  f"[Cat+LGB(d={best_d_q})]  ({time.time()-t0:.0f}s)")
        except Exception as e:
            print(f"    ⚠ NMS-Quest: {e}")

        # ── 3. STACKING ───────────────────────────────────────────────────
        # HAM feature, iter=300, depth=6 SABİT
        # Both + Gyr + Quest → OOF → meta
        # innerCV YOK stacking'de → hız
        # v13: 74.43%🚀 (aynı mantık)
        try:
            oof_list = []; te_list = []
            for ds_name, Xf in [('Both', X_both), ('Gyr', X_gyr)]:
                oof_list.append(oof_proba(Xf[tr_i], y_tr, sw,
                                          depth=STACK_DEPTH, iters=ITERS_STACK))
                te_list.append(cat_lgb_proba(Xf[tr_i], y_tr, sw, Xf[te_i],
                                              depth=STACK_DEPTH, iters=ITERS_STACK))
                print(f"      [{ds_name}] stream OK  ({time.time()-t0:.0f}s)")

            oof_list.append(oof_proba(Xq_tr, y_tr, sw,
                                       depth=best_d_q, iters=ITERS_STACK))
            te_list.append(cat_lgb_proba(Xq_tr, y_tr, sw, Xq_te,
                                          depth=best_d_q, iters=ITERS_STACK))

            meta_tr_feat = np.hstack(oof_list)
            meta_te_feat = np.hstack(te_list)
            sc_m, clf_m, meta_name = train_meta(meta_tr_feat, y_tr)
            # LEAKAGE KONTROLÜ 7: transform sadece test meta feature'a uygulanıyor
            meta_te_sc = sc_m.transform(meta_te_feat)
            stack_pred = clf_m.predict(meta_te_sc)
            stack_prob = (clf_m.predict_proba(meta_te_sc)
                          if hasattr(clf_m,'predict_proba') else None)
            record('Stacking', stack_pred, stack_prob)
            print(f"    Stacking:    BA={balanced_accuracy_score(y_te,stack_pred)*100:.2f}%  "
                  f"[meta={meta_name}]  ({time.time()-t0:.0f}s)")
        except Exception as e:
            print(f"    ⚠ Stacking: {e}"); traceback.print_exc()

        # ── Checkpoint ───────────────────────────────────────────────────
        all_res[f"{mode}_partial"] = {'results':results, 'completed_folds':fold_idx}
        with open(ckpt_path,'wb') as f: pickle.dump(all_res,f)
        try:
            os.makedirs(DRIVE_OUT, exist_ok=True)
            shutil.copy2(ckpt_path, f"{DRIVE_OUT}/results_v18.pkl")
        except: pass
        elapsed = time.time()-t0
        remaining = (N_FOLDS-fold_idx) * elapsed
        print(f"  💾 Fold {fold_idx}/{N_FOLDS} → Drive  "
              f"({elapsed:.0f}s)  Kalan:~{remaining/3600:.1f}h")

    all_res.pop(f"{mode}_partial", None)
    print(f"\n  {'─'*60}")
    print(f"  {MODE_LABEL[mode]} ÖZET:")
    for name in METHODS:
        sc = results[name]
        if sc['ba']:
            ba  = np.mean(sc['ba'])*100; std = np.std(sc['ba'])*100
            f1  = np.mean(sc['f1'])*100
            ref = PAPER[mode].get(name,0); d = ba-ref
            flag = "🚀" if d>0 else ("✅" if d>=-2 else ("⚠" if d>=-5 else "❌"))
            print(f"    {flag} {name:<15}: BA={ba:.2f}%±{std:.2f}%  "
                  f"F1={f1:.2f}%  (Makale:{ref:.2f}%  Δ:{d:+.2f}%)")
    return results

