print('🎨 Fig 9: Feature importance heatmap...')
try:
    import sys, os
    sys.path.insert(0, '/content/pads_my_preprocessed')
    from scipy.signal import welch
    from scipy.stats import kurtosis, skew
    from sklearn.model_selection import StratifiedKFold
    from catboost import CatBoostClassifier
    import pandas as pd

    PREP_DIR = '/content/pads_my_preprocessed'
    ALL_CH = [f'{t}_{w}_{s}_{a}'
              for t in ['Relaxed1','Relaxed2','RelaxedTask1','RelaxedTask2',
                        'StretchHold','HoldWeight','DrinkGlas','CrossArms',
                        'TouchNose','Entrainment1','Entrainment2']
              for w in ['LeftWrist','RightWrist']
              for s in ['Accelerometer','Gyroscope']
              for a in ['X','Y','Z']]
    TASKS   = ['Relaxed1','Relaxed2','RelaxedTask1','RelaxedTask2',
               'StretchHold','HoldWeight','DrinkGlas','CrossArms',
               'TouchNose','Entrainment1','Entrainment2']
    SENSORS = ['Accelerometer','Gyroscope']
    FEAT_NAMES = ['BP1','BP2','BP3','BP4','BP5','BP6','BP7','BP8',
                  'BP9','BP10','BP11','BP12','BP13','BP14','BP15',
                  'BP16','BP17','BP18','BP19',
                  'Std_1','AbsSum_1','MaxAbs_1','RMS_1',
                  'Std_2','AbsSum_2','MaxAbs_2','RMS_2',
                  'Std_3','AbsSum_3','MaxAbs_3','RMS_3',
                  'Std_4','AbsSum_4','MaxAbs_4','RMS_4',
                  'Kurtosis','Skewness','ZCR','Range',
                  'Activity','Mobility','Complexity',
                  'MAV','WaveLen','IQR','Mean']

    def extract_features_imp(data):
        out = []
        for ch in range(data.shape[0]):
            x = data[ch].astype(np.float64)
            _, pxx = welch(x,fs=100,nperseg=100,scaling='density')
            bp = np.log10(pxx[1:20]+1e-12)
            l  = len(x)//4; ws = []
            for i in range(4):
                seg = x[i*l:(i+1)*l]
                ws.extend([np.std(seg),np.sum(np.abs(seg)),
                            np.max(np.abs(seg)),np.sqrt(np.mean(seg**2))])
            dx = np.diff(x); ddx = np.diff(dx); act = np.var(x)
            mob = np.sqrt(np.var(dx)/(act+1e-12))
            cmp = np.sqrt(np.var(ddx)/(np.var(dx)+1e-12))/(mob+1e-12)
            gs  = [kurtosis(x,fisher=True),skew(x),
                   np.sum(np.diff(np.sign(x))!=0)/len(x),
                   np.max(x)-np.min(x),act,mob,cmp,
                   np.mean(np.abs(x)),np.sum(np.abs(dx)),
                   np.percentile(x,75)-np.percentile(x,25),np.mean(x)]
            out.append(np.concatenate([bp,ws,gs]))
        return np.concatenate(out).astype(np.float32)

    FL    = pd.read_csv(f'{PREP_DIR}/file_list.csv')
    FL_hc = FL[FL['label'].isin([0,1])].reset_index(drop=True)
    X_imp, y_imp = [], []
    for _, row in FL_hc.iterrows():
        fp = f"{PREP_DIR}/movement/{int(row['id']):03d}_ml.bin"
        if os.path.exists(fp):
            X_imp.append(extract_features_imp(
                np.fromfile(fp,dtype=np.float32).reshape(132,976)))
            y_imp.append(int(row['label']))
    X_imp = np.stack(X_imp); y_imp = np.array(y_imp)

    # CatBoost feature importance (tüm veri)
    cat_imp = CatBoostClassifier(iterations=200,depth=6,
                                  random_seed=42,verbose=False,
                                  allow_writing_files=False)
    cat_imp.fit(X_imp, y_imp)
    importances = cat_imp.get_feature_importance()

    # 132 ch × 46 feat → görev × sensör heatmap
    n_feat = 46
    imp_matrix = importances.reshape(132, n_feat)
    # Her task için ortalama importance
    task_sensor_imp = np.zeros((len(TASKS), len(SENSORS)))
    for t_idx, task in enumerate(TASKS):
        for s_idx, sensor in enumerate(SENSORS):
            ch_idx = [i for i,ch in enumerate(ALL_CH)
                      if task in ch and sensor in ch]
            if ch_idx:
                task_sensor_imp[t_idx,s_idx] = imp_matrix[ch_idx,:].mean()

    # Normalize per sensor
    task_sensor_norm = task_sensor_imp / (task_sensor_imp.max()+1e-12) * 100

    fig, axes = plt.subplots(1,2,figsize=(14,7))
    fig.suptitle('Feature Importance: Task × Sensor (PD vs HC)\nCatBoost Gain Importance',
                 fontsize=13, fontweight='bold')
    task_labels = ['Relaxed1','Relaxed2','RelaxedTask1','RelaxedTask2',
                   'StretchHold','HoldWeight','DrinkGlass','CrossArms',
                   'TouchNose','Entrainment1','Entrainment2']
    sns.heatmap(task_sensor_norm,
                xticklabels=SENSORS, yticklabels=task_labels,
                ax=axes[0], cmap='YlOrRd', annot=True, fmt='.1f',
                linewidths=0.5, cbar_kws={'label':'Normalized Importance (%)'},
                annot_kws={'size':10})
    axes[0].set_title('PD vs HC', fontsize=11, fontweight='bold')
    axes[0].set_xlabel('Sensor'); axes[0].set_ylabel('Task')

    # DD için de hesapla
    FL_dd = FL[FL['label'].isin([1,2])].reset_index(drop=True)
    FL_dd['label'] = FL_dd['label'].map({1:0,2:1})
    X_dd, y_dd = [], []
    for _, row in FL_dd.iterrows():
        fp = f"{PREP_DIR}/movement/{int(row['id']):03d}_ml.bin"
        if os.path.exists(fp):
            X_dd.append(extract_features_imp(
                np.fromfile(fp,dtype=np.float32).reshape(132,976)))
            y_dd.append(int(row['label']))
    if X_dd:
        X_dd = np.stack(X_dd); y_dd = np.array(y_dd)
        cat_dd = CatBoostClassifier(iterations=200,depth=6,
                                     random_seed=42,verbose=False,
                                     allow_writing_files=False)
        cat_dd.fit(X_dd, y_dd)
        imp_dd = cat_dd.get_feature_importance()
        imp_dd_mat = imp_dd.reshape(132,n_feat)
        ts_dd = np.zeros((len(TASKS),len(SENSORS)))
        for t_idx,task in enumerate(TASKS):
            for s_idx,sensor in enumerate(SENSORS):
                ch_idx=[i for i,ch in enumerate(ALL_CH)
                        if task in ch and sensor in ch]
                if ch_idx:
                    ts_dd[t_idx,s_idx]=imp_dd_mat[ch_idx,:].mean()
        ts_dd_norm = ts_dd/(ts_dd.max()+1e-12)*100
        sns.heatmap(ts_dd_norm,
                    xticklabels=SENSORS, yticklabels=task_labels,
                    ax=axes[1], cmap='YlOrRd', annot=True, fmt='.1f',
                    linewidths=0.5, cbar_kws={'label':'Normalized Importance (%)'},
                    annot_kws={'size':10})
        axes[1].set_title('PD vs DD', fontsize=11, fontweight='bold')
        axes[1].set_xlabel('Sensor'); axes[1].set_ylabel('Task')
    plt.tight_layout()
    plt.savefig(f'{OUT_DIR}/fig9_feature_importance.png',
                dpi=200, bbox_inches='tight')
    plt.close(); print('  ✅ Fig 9: Feature importance')
except Exception as e:
    print(f'  ⚠ Fig 9 atlandı: {e}')

