import sys, subprocess, os, warnings, shutil, pickle, time
warnings.filterwarnings('ignore')

def ensure(*pkgs):
    for p in pkgs:
        try: __import__(p.split('[')[0].replace('-','_'))
        except ImportError:
            subprocess.check_call([sys.executable,'-m','pip','install',p,'-q',
                                   '--break-system-packages'],
                                  stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)

print('📦 Paketler...')
ensure('numpy','pandas','scipy','scikit-learn','catboost','lightgbm',
       'matplotlib','seaborn','psutil')
