# ─── Yardımcı fonksiyonlar ────────────────────────────────────────────────────
def sens_spec(trues, preds):
    """Sensitivity (Recall for positive) ve Specificity."""
    trues = np.array(trues); preds = np.array(preds)
    cm    = confusion_matrix(trues, preds)
    if cm.shape == (2,2):
        tn,fp,fn,tp = cm.ravel()
        sens = tp/(tp+fn) if (tp+fn)>0 else 0
        spec = tn/(tn+fp) if (tn+fp)>0 else 0
    else:
        # Multi-class: macro average
        sens = recall_score(trues, preds, average='macro', zero_division=0)
        spec = np.mean([confusion_matrix(trues==i, preds==i).ravel()[0] /
                        max(1, np.sum(trues!=i))
                        for i in np.unique(trues)])
    return sens*100, spec*100

def bootstrap_ci(trues, preds, metric_fn, n_boot=1000, ci=95):
    """Bootstrap 95% CI."""
    trues = np.array(trues); preds = np.array(preds)
    scores = []
    rng    = np.random.RandomState(42)
    for _ in range(n_boot):
        idx = rng.choice(len(trues), len(trues), replace=True)
        try:
            scores.append(metric_fn(trues[idx], preds[idx]))
        except: pass
    if not scores: return 0, 0
    lo = np.percentile(scores, (100-ci)/2)
    hi = np.percentile(scores, 100-(100-ci)/2)
    return lo*100, hi*100

def mcnemar_test(trues, preds1, preds2):
    """
    McNemar testi: iki classifier arasındaki fark istatistiksel anlamlı mı?
    Döner: p-value, b (clf1 doğru clf2 yanlış), c (clf1 yanlış clf2 doğru)
    """
    trues  = np.array(trues)
    preds1 = np.array(preds1)
    preds2 = np.array(preds2)
    correct1 = (preds1 == trues)
    correct2 = (preds2 == trues)
    b = np.sum( correct1 & ~correct2)   # clf1 doğru, clf2 yanlış
    c = np.sum(~correct1 &  correct2)   # clf1 yanlış, clf2 doğru
    if b+c == 0: return 1.0, 0, 0
    # McNemar exact (küçük örnekler için) veya chi2
    if b+c < 25:
        from scipy.stats import binom
        p = 2 * min(binom.cdf(min(b,c), b+c, 0.5),
                    1 - binom.cdf(min(b,c)-1, b+c, 0.5))
    else:
        chi2 = (abs(b-c)-1)**2 / (b+c)
        from scipy.stats import chi2 as chi2dist
        p = 1 - chi2dist.cdf(chi2, df=1)
    return p, b, c

def roc_auc_safe(trues, proba):
    """Binary ROC AUC. Proba yok veya multi-class ise None döner."""
    if not proba or len(proba) == 0: return None, None, None
    try:
        t = np.array(trues); p = np.array(proba)
        if p.ndim == 2: p = p[:,1]
        fpr, tpr, _ = roc_curve(t, p)
        return fpr, tpr, auc(fpr, tpr)
    except: return None, None, None

