# TABLO 3: McNEMAR TESTİ
# ════════════════════════════════════════════════════════════════════
print('📊 Tablo 3: McNemar testi...')
table3_rows = []
for mode in MODES:
    preds_dict = {m: np.array(all_res[mode][m]['preds'])
                  for m in METHODS if all_res[mode][m]['preds']}
    trues      = np.array(all_res[mode][METHODS[0]]['trues'])
    method_list = list(preds_dict.keys())
    for i in range(len(method_list)):
        for j in range(i+1, len(method_list)):
            m1, m2 = method_list[i], method_list[j]
            p_val, b, c = mcnemar_test(trues, preds_dict[m1], preds_dict[m2])
            sig = '***' if p_val<0.001 else ('**' if p_val<0.01 else
                  ('*' if p_val<0.05 else 'ns'))
            table3_rows.append({
                'Mode':        MODE_LABEL[mode],
                'Method A':    m1,
                'Method B':    m2,
                'b (A✓,B✗)':  b,
                'c (A✗,B✓)':  c,
                'p-value':     f'{p_val:.4f}',
                'Significance':sig,
            })

table3 = pd.DataFrame(table3_rows)
table3.to_csv(f'{OUT_DIR}/table3_mcnemar.csv', index=False)
tex3 = table3.to_latex(index=False, escape=False,
                        caption='McNemar Test: Pairwise Statistical Significance',
                        label='tab:mcnemar')
with open(f'{OUT_DIR}/table3_mcnemar.tex','w') as f: f.write(tex3)
print('✅ Tablo 3: McNemar')

