print('🎨 Fig 8: Bootstrap 95% CI...')
fig, axes = plt.subplots(1,2,figsize=(14,6))
fig.suptitle('Balanced Accuracy with 95% Bootstrap Confidence Intervals',
             fontsize=14, fontweight='bold')
for ai, mode in enumerate(MODES):
    ax = axes[ai]
    methods_ok = [m for m in METHODS if all_res[mode][m]['preds']]
    means  = []; lo_errs = []; hi_errs = []
    for m in methods_ok:
        p   = all_res[mode][m]
        ba  = np.mean(p['ba'])*100
        lo, hi = bootstrap_ci(p['trues'], p['preds'],
                               lambda t,pr: balanced_accuracy_score(t,pr))
        means.append(ba); lo_errs.append(ba-lo); hi_errs.append(hi-ba)
    x    = np.arange(len(methods_ok))
    cols = [COLORS_M[m] for m in methods_ok]
    ax.bar(x, means, color=cols, alpha=0.8, width=0.5)
    ax.errorbar(x, means,
                yerr=[lo_errs, hi_errs],
                fmt='none', color='#222', capsize=8,
                capthick=2.5, elinewidth=2.5)
    # Paper benchmark çizgisi
    for i, m in enumerate(methods_ok):
        ref = PAPER[mode][m]
