# ─── Preprocessed veriler ─────────────────────────────────────────────────────
def robust_copy(src, dst):
    os.makedirs(dst, exist_ok=True)
    files = glob(f'{src}/*.bin') + glob(f'{src}/*.csv')
    ok = 0
    for fp in files:
        d = os.path.join(dst, os.path.basename(fp))
        if os.path.exists(d) and os.path.getsize(d) > 0:
            ok += 1; continue
        for a in range(3):
            try: shutil.copy2(fp, d); ok += 1; break
            except:
                if a < 2: time.sleep(2)
    return ok

