# ─── Feature extraction — per-patient, deterministik ─────────────────────────
def extract_features(data):
    out = []
    for ch in range(data.shape[0]):
        x = data[ch].astype(np.float64)
        _, pxx = welch(x, fs=100, nperseg=100, scaling='density')
        bp = np.log10(pxx[1:20] + 1e-12)
        l  = len(x) // 4; ws = []
        for i in range(4):
            seg = x[i*l:(i+1)*l]
            ws.extend([np.std(seg), np.sum(np.abs(seg)),
                       np.max(np.abs(seg)), np.sqrt(np.mean(seg**2))])
        dx = np.diff(x); ddx = np.diff(dx); act = np.var(x)
        mob = np.sqrt(np.var(dx) / (act + 1e-12))
        cmp = np.sqrt(np.var(ddx) / (np.var(dx) + 1e-12)) / (mob + 1e-12)
        gs  = [kurtosis(x,fisher=True), skew(x),
               np.sum(np.diff(np.sign(x)) != 0) / len(x),
               np.max(x)-np.min(x), act, mob, cmp,
               np.mean(np.abs(x)), np.sum(np.abs(dx)),
               np.percentile(x,75)-np.percentile(x,25), np.mean(x)]
        out.append(np.concatenate([bp, ws, gs]))
    return np.concatenate(out).astype(np.float32)

# ─── Veri yükleme ─────────────────────────────────────────────────────────────
def get_fl(mode):
    fl = FILE_LIST.copy()
    if mode == 'pd_vs_hc':
        fl = fl[fl['label'].isin([0,1])].copy()
    else:
        fl = fl[fl['label'].isin([1,2])].copy()
        fl['label'] = fl['label'].map({1:0,2:1})
    return fl.reset_index(drop=True)

def load_mov(mode, ch_filter=None):
    fl   = get_fl(mode)
    mask = (pd.Series(ALL_CH).str.contains(ch_filter).values
            if ch_filter else np.ones(132, bool))
    X = []
    for sid in fl['id'].values:
        fp = f'{PREP_DIR}/movement/{int(sid):03d}_ml.bin'
        X.append(extract_features(
            np.fromfile(fp,dtype=np.float32).reshape(132,976)[mask])
            if os.path.exists(fp) else
            np.zeros(int(mask.sum())*46, np.float32))
    c = fl['gender'].values if 'gender' in fl.columns else np.array(['U']*len(fl))
    return np.stack(X), fl['label'].values, c

def load_quest(mode):
    fl = get_fl(mode); X = []
    for sid in fl['id'].values:
        fp = f'{PREP_DIR}/questionnaire/{int(sid):03d}_ml.bin'
        X.append(np.fromfile(fp,dtype=np.float32)[:30]
                 if os.path.exists(fp) else np.zeros(30,np.float32))
    c = fl['gender'].values if 'gender' in fl.columns else np.array(['U']*len(fl))
    return np.stack(X), fl['label'].values, c

ICV = StratifiedKFold(n_splits=5, shuffle=True, random_state=RS)

# ─── SMOTE — leakage yok ──────────────────────────────────────────────────────
def apply_smote(X_tr, y_tr):
    """
    SMOTE sadece train set'e uygulanır.
    Test set'e dokunulmaz → leakage yok.
    k_neighbors: en az sınıf boyutuna göre ayarlanır.
    """
    min_class = np.min(np.bincount(y_tr))
    k = min(5, min_class - 1)
    if k < 1:
        return X_tr, y_tr   # Çok az örnek, SMOTE uygulanamaz
    try:
        sm = SMOTE(random_state=RS, k_neighbors=k)
        X_res, y_res = sm.fit_resample(X_tr, y_tr)
        return X_res, y_res
    except Exception as e:
        print(f'      ⚠ SMOTE: {e}')
        return X_tr, y_tr

# ─── Optuna Bayesian Hyperparameter Opt — leakage yok ────────────────────────
def optuna_tune(X_tr, y_tr, n_trials=OPTUNA_TRIALS, iters=300):
    """
    Optuna ile CatBoost hyperparameter arama.
    Leakage yok: sadece X_tr üzerinde inner CV kullanır.
    X_te hiç görülmez.
    """
    def objective(trial):
        params = {
            'iterations':   iters,
            'depth':        trial.suggest_int('depth', 4, 6),  # max 6 → OOM yok
            'learning_rate':trial.suggest_float('lr', 0.01, 0.15, log=True),
            'l2_leaf_reg':  trial.suggest_float('l2', 1e-3, 10.0, log=True),
            'random_seed':  RS,
            'verbose':      False,
            'allow_writing_files': False,
            # GPU OOM FIX: border_count=32, max_ctr_complexity=2
            # T4=15GB: 6072feat×depth6×border32×ctr2 ≈ 5GB → sığar
            'task_type':    CAT_DEVICE,
            'border_count': 32,            # default 128 → VRAM 4x azalır
            'max_ctr_complexity': 2,       # default 4  → VRAM 2x azalır
            **({'devices':'0'} if HAS_GPU else {}),
        }
        scores = []
        for ti, vi in ICV.split(X_tr, y_tr):
            m = CatBoostClassifier(**params)
            m.fit(X_tr[ti], y_tr[ti])
            scores.append(balanced_accuracy_score(
                y_tr[vi], m.predict(X_tr[vi])))
        return np.mean(scores)

    study = optuna.create_study(direction='maximize',
                                 sampler=optuna.samplers.TPESampler(seed=RS))
    study.optimize(objective, n_trials=n_trials, show_progress_bar=False)
    return study.best_params

# ─── Model fonksiyonları ──────────────────────────────────────────────────────
def cat_fit(X_tr, y_tr, depth=6, lr=0.05, l2=3.0, iters=300):
    m = CatBoostClassifier(
        iterations=iters, depth=depth,
        learning_rate=lr, l2_leaf_reg=l2,
        random_seed=RS, verbose=False,
        allow_writing_files=False,
        task_type=CAT_DEVICE,
        border_count=32,         # T4 OOM fix: 128→32 = 4x VRAM azalır
        max_ctr_complexity=2,    # T4 OOM fix: 4→2  = 2x VRAM azalır
        **({'devices':'0'} if HAS_GPU else {}))
    m.fit(X_tr, y_tr)
    return m

def lgb_fit(X_tr, y_tr, depth=6, lr=0.05, iters=300):
    n = len(np.unique(y_tr))
    p = dict(n_estimators=iters, max_depth=depth, learning_rate=lr,
             num_leaves=63, random_state=RS, verbose=-1,
             class_weight='balanced', n_jobs=1 if HAS_GPU else -1,
             device=LGB_DEVICE,
             objective='binary' if n==2 else 'multiclass')
    if n > 2: p['num_class'] = n
    m = lgb.LGBMClassifier(**p)
    m.fit(X_tr, y_tr)
    return m

def xgb_fit(X_tr, y_tr, depth=6, lr=0.05, iters=300):
    n = len(np.unique(y_tr))
    scale = np.sum(y_tr==0)/max(1,np.sum(y_tr==1))
    params = dict(n_estimators=iters, max_depth=depth,
                  learning_rate=lr, tree_method='hist',
                  device=XGB_DEVICE, random_state=RS,
                  eval_metric='logloss', verbosity=0)
    if n == 2:
        params['scale_pos_weight'] = scale
        m = xgb.XGBClassifier(**params)
    else:
        params['objective'] = 'multi:softprob'
        params['num_class'] = n
        m = xgb.XGBClassifier(**params)
    m.fit(X_tr, y_tr)
    return m

def ensemble_proba(X_tr, y_tr, X_te, depth=6, lr=0.05, l2=3.0, iters=300):
    """Cat + LGB + XGB soft voting. Leakage yok."""
    pc = cat_fit(X_tr,y_tr,depth,lr,l2,iters).predict_proba(X_te)
    pl = lgb_fit(X_tr,y_tr,depth,lr,iters).predict_proba(X_te)
    px = xgb_fit(X_tr,y_tr,depth,lr,iters).predict_proba(X_te)
    return (pc + pl + px) / 3

def oof_ensemble(X_tr, y_tr, depth=6, lr=0.05, l2=3.0, iters=300):
    """
    OOF ensemble proba.
    Leakage yok: her örnek sadece kendi val fold'unda tahmin ediliyor.
    SMOTE sadece inner train'e uygulanır — val leak yok.
    """
    n   = len(np.unique(y_tr))
    oof = np.zeros((len(X_tr), n), np.float64)
    for ti, vi in ICV.split(X_tr, y_tr):
        # SMOTE sadece inner train'e (ti) — val (vi) dokunulmaz
        Xs, ys = apply_smote(X_tr[ti], y_tr[ti])
        pc = cat_fit(Xs,ys,depth,lr,l2,iters).predict_proba(X_tr[vi])
        pl = lgb_fit(Xs,ys,depth,lr,iters).predict_proba(X_tr[vi])
        px = xgb_fit(Xs,ys,depth,lr,iters).predict_proba(X_tr[vi])
        oof[vi] = (pc + pl + px) / 3
    return oof

def train_meta(meta_tr, y_tr):
    """Meta-learner: LR/SVM/RF inner CV ile seç. Leakage yok."""
    sc = StandardScaler().fit(meta_tr)
    Xm = sc.transform(meta_tr)
    best_name, best_s, best_clf = 'LR', -1.0, None
    for name, clf in [
        ('LR',  LogisticRegression(C=1.0, max_iter=2000, random_state=RS)),
        ('SVM', SVC(C=1.0, gamma='scale', probability=True, random_state=RS)),
        ('RF',  RandomForestClassifier(n_estimators=200, random_state=RS,
                                        class_weight='balanced')),
    ]:
        ss = [balanced_accuracy_score(y_tr[vi],
              clf.fit(Xm[ti],y_tr[ti]).predict(Xm[vi]))
              for ti,vi in ICV.split(Xm,y_tr)]
        s = np.mean(ss)
        if s > best_s:
            best_s = s; best_name = name
            best_clf = (LogisticRegression(C=1.0,max_iter=2000,random_state=RS)
                        if name=='LR' else
                        SVC(C=1.0,gamma='scale',probability=True,random_state=RS)
                        if name=='SVM' else
                        RandomForestClassifier(n_estimators=200,random_state=RS,
                                               class_weight='balanced'))
    best_clf.fit(Xm, y_tr)
    return sc, best_clf, best_name

# ─── ANA DENEY ────────────────────────────────────────────────────────────────
def run_experiment(mode, all_res, ckpt_path):
    print(f'\n{"="*65}')
    print(f'🔬 {mode.upper()}  —  {MODE_LABEL[mode]}')
    print(f'{"="*65}')

    outer_cv = StratifiedKFold(n_splits=N_FOLDS, shuffle=True, random_state=RS)

    print('  📂 Veriler yükleniyor...')
    X_both, y_all, c_all = load_mov(mode, None)
    X_gyr,  _,     _     = load_mov(mode, 'Gyroscope')
    X_q,    _,     _     = load_quest(mode)
    n_cls = len(np.unique(y_all))
    print(f'  ✅ Both:{X_both.shape}  Gyr:{X_gyr.shape}  Quest:{X_q.shape}')
    print(f'  Sınıf dağılımı: {np.bincount(y_all)}')

    ck = all_res.get(f'{mode}_partial')
    if ck:
        results    = ck['results']
        start_fold = ck['completed_folds'] + 1
        opt_cache  = ck.get('opt_cache', {})
        print(f'  ♻️  Fold {start_fold}\'den devam ({ck["completed_folds"]} tamamlandı)')
    else:
        results   = {m: {'ba':[],'f1':[],'prec':[],'rec':[],'preds':[],'trues':[]}
                     for m in METHODS}
        opt_cache = {}   # Optuna sonuçlarını cache'le (fold'lar arası tekrar arama)
        start_fold = 1

    for fold_idx, (tr_i, te_i) in enumerate(outer_cv.split(X_both, y_all), 1):
        if fold_idx < start_fold:
            continue

        t0 = time.time()
        print(f'\n  ── Fold {fold_idx}/{N_FOLDS}  RAM:{ram()} ──')
        y_tr = y_all[tr_i]; y_te = y_all[te_i]

        def record(name, pred):
            results[name]['ba'].append(balanced_accuracy_score(y_te, pred))
            results[name]['f1'].append(f1_score(y_te, pred, zero_division=0))
            results[name]['prec'].append(precision_score(y_te, pred, zero_division=0))
            results[name]['rec'].append(recall_score(y_te, pred, zero_division=0))
            results[name]['preds'].extend(pred.tolist())
            results[name]['trues'].extend(y_te.tolist())

        # ── Optuna: SMOTE + Handcrafted için hyperparameter search ───────
        # Cache: ilk fold'da hesapla, sonrakilerde tekrar aramaya gerek yok
        # Leakage yok: sadece X_both[tr_i] ve inner CV kullanılıyor
        cache_key = f'{mode}_hc'
        if cache_key not in opt_cache:
            print(f'    🔍 Optuna hyperparameter search ({OPTUNA_TRIALS} trial)...')
            # SMOTE uygulanmış train üzerinde optimize et
            X_sm, y_sm = apply_smote(X_both[tr_i], y_tr)
            best_p = optuna_tune(X_sm, y_sm, n_trials=OPTUNA_TRIALS, iters=ITERS_HC)
            opt_cache[cache_key] = best_p
            print(f'    ✅ Best: depth={best_p["depth"]} '
                  f'lr={best_p["lr"]:.4f} l2={best_p["l2"]:.3f}  '
                  f'({time.time()-t0:.0f}s)')
        else:
            best_p = opt_cache[cache_key]
            print(f'    ♻️  Optuna cache: depth={best_p["depth"]} '
                  f'lr={best_p["lr"]:.4f} l2={best_p["l2"]:.3f}')

        depth_hc = best_p['depth']
        lr_hc    = best_p['lr']
        l2_hc    = best_p['l2']

        # ── 1. HANDCRAFTED ────────────────────────────────────────────────
        # SMOTE + Optuna params + Cat+LGB+XGB ensemble
        # Both ve Gyr dene → en iyi al
        best_ba, best_pred, best_info = -1.0, None, ''
        for ds_name, Xf in [('Both', X_both), ('Gyr', X_gyr)]:
            try:
                # LEAKAGE: SMOTE sadece train'e, test dokunulmaz
                X_sm, y_sm = apply_smote(Xf[tr_i], y_tr)
                prob = ensemble_proba(X_sm, y_sm, Xf[te_i],
                                      depth=depth_hc, lr=lr_hc, l2=l2_hc,
                                      iters=ITERS_HC)
                pred = np.argmax(prob, axis=1)
                ba   = balanced_accuracy_score(y_te, pred)
                if ba > best_ba:
                    best_ba = ba; best_pred = pred
                    best_info = f'SMOTE+Cat+LGB+XGB(d={depth_hc})+{ds_name}'
            except Exception as e:
                print(f'    ⚠ HC {ds_name}: {e}')

        if best_pred is not None:
            record('Handcrafted', best_pred)
            print(f'    Handcrafted: BA={best_ba*100:.2f}%  '
                  f'[{best_info}]  ({time.time()-t0:.0f}s)')

        # ── 2. NMS-QUEST ──────────────────────────────────────────────────
        # 30 feature, Optuna tune, SMOTE, Cat+LGB+XGB
        Xq_tr, Xq_te = X_q[tr_i], X_q[te_i]
        try:
            cache_key_q = f'{mode}_quest'
            if cache_key_q not in opt_cache:
                Xq_sm, yq_sm = apply_smote(Xq_tr, y_tr)
                best_q = optuna_tune(Xq_sm, yq_sm,
                                      n_trials=OPTUNA_TRIALS, iters=ITERS_QUEST)
                opt_cache[cache_key_q] = best_q
            else:
                best_q = opt_cache[cache_key_q]

            Xq_sm, yq_sm = apply_smote(Xq_tr, y_tr)
            prob = ensemble_proba(Xq_sm, yq_sm, Xq_te,
                                   depth=best_q['depth'], lr=best_q['lr'],
                                   l2=best_q['l2'], iters=ITERS_QUEST)
            pred = np.argmax(prob, axis=1)
            record('NMS-Quest', pred)
            print(f'    NMS-Quest:   BA={balanced_accuracy_score(y_te,pred)*100:.2f}%  '
                  f'[SMOTE+Cat+LGB+XGB d={best_q["depth"]}]  ({time.time()-t0:.0f}s)')
        except Exception as e:
            print(f'    ⚠ NMS-Quest: {e}')

        # ── 3. STACKING ───────────────────────────────────────────────────
        # HAM 6072 feature, SMOTE inner train'de, Cat+LGB+XGB OOF
        # depth=STACK_DEPTH sabit (v12/v13 kanıtladı)
        # SMOTE: OOF inner train'de uygulanır → oof_ensemble içinde
        try:
            oof_list = []; te_list = []
            for ds_name, Xf in [('Both', X_both), ('Gyr', X_gyr)]:
                oof_list.append(oof_ensemble(Xf[tr_i], y_tr,
                                              depth=STACK_DEPTH, lr=0.05,
                                              l2=l2_hc, iters=ITERS_STACK))
                # Full train SMOTE + ensemble → test proba
                X_sm, y_sm = apply_smote(Xf[tr_i], y_tr)
                te_list.append(ensemble_proba(X_sm, y_sm, Xf[te_i],
                                               depth=STACK_DEPTH, lr=0.05,
                                               l2=l2_hc, iters=ITERS_STACK))
                print(f'      [{ds_name}] stream OK  ({time.time()-t0:.0f}s)')

            # Quest stream
            Xq_sm, yq_sm = apply_smote(Xq_tr, y_tr)
            oof_list.append(oof_ensemble(Xq_tr, y_tr,
                                          depth=best_q.get('depth', STACK_DEPTH),
                                          lr=best_q.get('lr', 0.05),
                                          l2=best_q.get('l2', 3.0),
                                          iters=ITERS_STACK))
            te_list.append(ensemble_proba(Xq_sm, yq_sm, Xq_te,
                                           depth=best_q.get('depth', STACK_DEPTH),
                                           lr=best_q.get('lr', 0.05),
                                           l2=best_q.get('l2', 3.0),
                                           iters=ITERS_STACK))

            meta_tr_feat = np.hstack(oof_list)   # (n_train, 6)
            meta_te_feat = np.hstack(te_list)     # (n_test, 6)
            sc_m, clf_m, meta_name = train_meta(meta_tr_feat, y_tr)
            stack_pred = clf_m.predict(sc_m.transform(meta_te_feat))
            record('Stacking', stack_pred)
            print(f'    Stacking:    BA={balanced_accuracy_score(y_te,stack_pred)*100:.2f}%  '
                  f'[meta={meta_name}]  ({time.time()-t0:.0f}s)')
        except Exception as e:
            print(f'    ⚠ Stacking: {e}'); traceback.print_exc()

        # ── Checkpoint ───────────────────────────────────────────────────
        all_res[f'{mode}_partial'] = {
            'results': results, 'completed_folds': fold_idx,
            'opt_cache': opt_cache}
        with open(ckpt_path,'wb') as f: pickle.dump(all_res,f)
        try:
            os.makedirs(DRIVE_OUT, exist_ok=True)
            shutil.copy2(ckpt_path, f'{DRIVE_OUT}/results_v19.pkl')
        except: pass
        elapsed   = time.time()-t0
        remaining = (N_FOLDS-fold_idx)*elapsed
        print(f'  💾 Fold {fold_idx}/{N_FOLDS} → Drive  '
              f'({elapsed:.0f}s)  Kalan:~{remaining/3600:.1f}h')

    all_res.pop(f'{mode}_partial', None)
    print(f'\n  {"─"*60}')
    print(f'  {MODE_LABEL[mode]} ÖZET:')
    for name in METHODS:
        sc = results[name]
        if sc['ba']:
            ba  = np.mean(sc['ba'])*100; std = np.std(sc['ba'])*100
            f1  = np.mean(sc['f1'])*100
            ref = PAPER[mode][name]; d = ba-ref
            flag = '🚀' if d>0 else ('✅' if d>=-2 else ('⚠' if d>=-5 else '❌'))
            print(f'    {flag} {name:<15}: BA={ba:.2f}%±{std:.2f}%  '
                  f'F1={f1:.2f}%  (Makale:{ref:.2f}%  Δ:{d:+.2f}%)')
    return results

# ─── Çalıştır ─────────────────────────────────────────────────────────────────
CKPT = f'{OUT_DIR}/results_v19.pkl'
