for mode in ['pd_vs_hc','pd_vs_dd']:
    if mode in all_res:
        print(f'\n♻️  {mode} tamamlanmış, atlanıyor.')
        continue
    all_res[mode] = run_experiment(mode, all_res, CKPT)
    with open(CKPT,'wb') as f: pickle.dump(all_res,f)
    try:
        os.makedirs(DRIVE_OUT, exist_ok=True)
        shutil.copy2(CKPT, f'{DRIVE_OUT}/results_v19.pkl')
    except Exception as e:
        print(f'  ⚠ Drive: {e}')

