# ── Yardımcı fonksiyonlar ──────────────────────────────────────────────────
def sens_spec(trues, preds):
    cm = confusion_matrix(np.array(trues), np.array(preds))
    if cm.shape == (2,2):
        tn,fp,fn,tp = cm.ravel()
        return tp/(tp+fn+1e-9)*100, tn/(tn+fp+1e-9)*100
    return (recall_score(trues,preds,average='macro',zero_division=0)*100,
            np.mean([confusion_matrix(np.array(trues)==i,
                     np.array(preds)==i).ravel()[0]/max(1,np.sum(np.array(trues)!=i))
                     for i in np.unique(trues)])*100)

def bootstrap_ci(trues, preds, n=1000):
    rng = np.random.RandomState(42)
    t,p = np.array(trues), np.array(preds)
    sc = [balanced_accuracy_score(t[idx:=rng.choice(len(t),len(t),replace=True)],
                                   p[idx]) for _ in range(n)]
    return np.percentile(sc,2.5)*100, np.percentile(sc,97.5)*100

def mcnemar_pval(trues, p1, p2):
    t,a,b = np.array(trues),np.array(p1),np.array(p2)
    bc = np.sum((a==t)&(b!=t)); cb = np.sum((a!=t)&(b==t))
    if bc+cb==0: return 1.0
    if bc+cb<25:
        from scipy.stats import binom
        return 2*min(binom.cdf(min(bc,cb),bc+cb,0.5),
                     1-binom.cdf(min(bc,cb)-1,bc+cb,0.5))
    from scipy.stats import chi2
    return 1-chi2.cdf((abs(bc-cb)-1)**2/(bc+cb), df=1)

# ── Tablo 2: Tam Metrikler ─────────────────────────────────────────────────
print('\n📊 Tablo 2: Metrikler hesaplanıyor...')
t2rows = []
for mode in MODES:
    for m in METHODS:
        p = all_res[mode][m]
        if not p['ba']: continue
        t,pr = np.array(p['trues']), np.array(p['preds'])
        ba   = np.mean(p['ba'])*100
        ci_lo,ci_hi = bootstrap_ci(p['trues'],p['preds'])
        s,sp = sens_spec(p['trues'],p['preds'])
        # AUC
        proba = p.get('proba',[])
        auc_v = 'N/A'
        if proba and len(proba):
            try:
                pr2 = np.array(proba); pr2 = pr2[:,1] if pr2.ndim==2 else pr2
                _,_,auc_v = roc_curve(t,pr2); auc_v = f'{auc(auc_v[0],auc_v[1]):.3f}'
            except: pass
        t2rows.append({
            'Mode':        MODE_LABEL[mode],
            'Method':      m,
            'BA (%)':      f'{ba:.2f}',
            '95% CI':      f'[{ci_lo:.1f}, {ci_hi:.1f}]',
            'Sensitivity': f'{s:.2f}',
            'Specificity': f'{sp:.2f}',
            'F1 (%)':      f'{np.mean(p["f1"])*100:.2f}',
            'Precision':   f'{np.mean(p["prec"])*100:.2f}',
            'Recall':      f'{np.mean(p["rec"])*100:.2f}',
            'AUC':          auc_v,
            'Paper BA':    f'{PAPER[mode][m]:.2f}',
            'Δ':           f'{ba-PAPER[mode][m]:+.2f}',
        })
t2 = pd.DataFrame(t2rows)
t2.to_csv(f'{OUT_DIR}/table2_full_metrics.csv', index=False)
with open(f'{OUT_DIR}/table2_full_metrics.tex','w') as f:
    f.write(t2.to_latex(index=False,escape=False,
            caption='Complete Performance Metrics — v19 (5-Fold CV)',
            label='tab:results'))
print('✅ Tablo 2')

# ── Tablo 3: McNemar ──────────────────────────────────────────────────────
print('📊 Tablo 3: McNemar...')
t3rows = []
for mode in MODES:
    pdict = {m:np.array(all_res[mode][m]['preds']) for m in METHODS if all_res[mode][m]['preds']}
    trues = np.array(all_res[mode][METHODS[0]]['trues'])
    mlist = list(pdict.keys())
    for i in range(len(mlist)):
        for j in range(i+1,len(mlist)):
            p = mcnemar_pval(trues, pdict[mlist[i]], pdict[mlist[j]])
            sig = '***' if p<0.001 else ('**' if p<0.01 else ('*' if p<0.05 else 'ns'))
            t3rows.append({'Mode':MODE_LABEL[mode],'A':mlist[i],'B':mlist[j],
                           'p-value':f'{p:.4f}','Significance':sig})
t3 = pd.DataFrame(t3rows)
t3.to_csv(f'{OUT_DIR}/table3_mcnemar.csv', index=False)
with open(f'{OUT_DIR}/table3_mcnemar.tex','w') as f:
    f.write(t3.to_latex(index=False,escape=False,
            caption='McNemar Test: Pairwise Statistical Significance',
            label='tab:mcnemar'))
print('✅ Tablo 3')

