# ── Fig 3: Confusion Matrices ─────────────────────────────────────────────
fig, axes = plt.subplots(2,3,figsize=(16,10))
fig.suptitle('Aggregated Confusion Matrices (5-Fold CV)',fontsize=14,fontweight='bold')
cls_n = {'pd_vs_hc':['HC','PD'],'pd_vs_dd':['PD','DD']}
for row,mode in enumerate(MODES):
    for col,m in enumerate(METHODS):
        ax=axes[row][col]; p=all_res[mode][m]
        cm=confusion_matrix(p['trues'],p['preds'])
        cmn=cm.astype(float)/cm.sum(axis=1,keepdims=True)*100
        sns.heatmap(cmn,annot=False,ax=ax,cmap='Blues',vmin=0,vmax=100,
                    xticklabels=cls_n[mode],yticklabels=cls_n[mode],
                    cbar_kws={'label':'%'},linewidths=2,linecolor='white')
        for i in range(cm.shape[0]):
            for j in range(cm.shape[1]):
                c='white' if cmn[i,j]>60 else '#1a1a1a'
                ax.text(j+0.5,i+0.4,f'{cmn[i,j]:.1f}%',ha='center',va='center',
                        fontsize=14,fontweight='bold',color=c)
                ax.text(j+0.5,i+0.65,f'n={cm[i,j]}',ha='center',va='center',
                        fontsize=9,color=c)
        ba=np.mean(p['ba'])*100; d=ba-PAPER[mode][m]
        ax.set_title(f'{MODE_LABEL[mode]} — {m}\nBA={ba:.1f}% (Δ{d:+.1f}%)',
                     fontsize=10,fontweight='bold')
        ax.set_xlabel('Predicted'); ax.set_ylabel('True')
