def extract_handcrafted_features(sig):
    """Extract features similar to Varghese et al. Option A"""
    features = []

    # Basic stats (11)
    features.extend([
        np.mean(sig), np.std(sig), np.median(sig),
        np.min(sig), np.max(sig), np.ptp(sig),
        skew(sig), kurtosis(sig),
        np.percentile(sig, 25), np.percentile(sig, 75),
        np.var(sig)
    ])

    # Wavelet (12) - 3 levels like paper
    try:
        coeffs = pywt.wavedec(sig, 'db4', level=3)
        for c in coeffs:
            features.extend([np.mean(c), np.std(c), np.max(np.abs(c))])
    except:
        features.extend([0] * 12)

    # Frequency domain (19) - Welch PSD like paper
    try:
        freqs, psd = welch(sig, fs=100, nperseg=min(256, len(sig)))
        # 0 Hz and >19 Hz discarded like paper
        psd_log = np.log10(psd[1:20] + 1e-12)
        features.extend(psd_log.tolist())
    except:
        features.extend([0] * 19)

    # Temporal (4)
    diff1 = np.diff(sig)
    features.extend([
        np.mean(np.abs(diff1)),
        np.std(diff1),
        np.sum(np.abs(diff1)),  # Total variation
        np.max(np.abs(diff1))
    ])

    # Zero crossing (1)
    zc = np.sum(np.diff(np.sign(sig)) != 0) / len(sig)
    features.append(zc)

    # Energy (1)
    features.append(np.sum(sig**2))

    return np.array(features)

