print(f"\n📡 Loading signals from {data_path}...")
s_files = [f for f in glob(f"{data_path}/**/*.txt", recursive=True)
           if "LICENSE" not in f and "README" not in f]

print(f"Found {len(s_files)} signal files")

X_signals = []
X_handcrafted = []
X_clinical = []
y_list = []
group_list = []
task_list = []

for fp in tqdm(s_files, desc="Processing"):
    try:
        fname = os.path.basename(fp)
        parts = fname.replace('.txt', '').split('_')

        if len(parts) < 1:
            continue

        pid = parts[0]
        if pid not in patient_info:
            continue

        task = parts[1] if len(parts) > 1 else "Unknown"

        # Read signal
        df = pd.read_csv(fp, header=None)
        raw = df.select_dtypes(include=[np.number]).values

        if raw.shape[0] < 100:
            continue

        # Preprocessing (like paper)
        if raw.shape[0] > 50:
            raw = raw[50:, :]  # Remove first 0.5s

        raw = detrend(raw, axis=0)

        if raw.shape[0] > raw.shape[1]:
            raw = raw.T

        raw = resample(raw, 400, axis=1)

        X_signals.append(raw)

        # Handcrafted features
        hc_features = []
        for ch in range(raw.shape[0]):
            hc_features.extend(extract_handcrafted_features(raw[ch, :]))
        X_handcrafted.append(hc_features)

        # Clinical + NMS
        p = patient_info[pid]
        nms = nms_data.get(pid, [0] * 30)

        clin_vec = [
            float(p['age']),
            str(p['gender']),
            str(task),
            sum(nms), np.mean(nms), np.std(nms), np.count_nonzero(nms),
            sum(nms[0:10]),   # Motor symptoms domain
            sum(nms[10:15]),  # Sleep domain
            sum(nms[15:20]),  # Mood domain
            sum(nms[20:30])   # Autonomic domain
        ] + nms

        X_clinical.append(clin_vec)
        y_list.append(p['label'])
        group_list.append(pid)
        task_list.append(task)

    except:
        continue

print(f"\n✅ Processed {len(y_list)} samples")

# Convert to arrays
max_ch = max([x.shape[0] for x in X_signals])
X_sig_arr = np.zeros((len(X_signals), max_ch, 400), dtype=np.float32)
for i, x in enumerate(X_signals):
    X_sig_arr[i, :x.shape[0], :] = x

X_hc_arr = np.array(X_handcrafted, dtype=np.float32)

feat_cols = ['age', 'gender', 'task', 'nms_sum', 'nms_mean', 'nms_std',
             'nms_nonzero', 'nms_motor', 'nms_sleep', 'nms_mood', 'nms_auto'] + \
            [f'nms_{i}' for i in range(30)]

df_clinical = pd.DataFrame(X_clinical, columns=feat_cols)
y = np.array(y_list)
groups = np.array(group_list)

n_pd = np.sum(y == 1)
n_hc = np.sum(y == 0)
class_ratio = n_pd / (n_hc + 1e-10)

unique_patients = len(np.unique(groups))
unique_hc = len(set([g for g, label in zip(groups, y) if label == 0]))
unique_pd = len(set([g for g, label in zip(groups, y) if label == 1]))

print(f"\n{'=' * 80}")
print("📊 DATASET SUMMARY")
print(f"{'=' * 80}")
print(f"Total samples: {len(y)}")
print(f"PD: {n_pd} ({n_pd/len(y)*100:.1f}%)")
print(f"HC: {n_hc} ({n_hc/len(y)*100:.1f}%)")
print(f"Unique patients: {unique_patients} ({unique_pd} PD, {unique_hc} HC)")
print(f"Class ratio (PD/HC): 1:{class_ratio:.2f}")
print(f"{'=' * 80}")

del X_signals
gc.collect()

# ============================================================================
# ULTIMATE CV - ZERO DATA LEAKAGE
# ============================================================================

print(f"\n{'=' * 80}")
print("🔬 10-FOLD CV - ULTIMATE PIPELINE (ZERO LEAKAGE)")
print(f"{'=' * 80}")
print("Pipeline: BOSS + MiniRocket + Handcrafted + NMS → Stacking")
print(f"{'=' * 80}")

cv = StratifiedGroupKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)

metrics = {
    'bal_acc': [], 'sens': [], 'spec': [], 'f1': [],
    'auc': [], 'precision': [], 'recall': []
}

fold_results = []
all_true, all_pred, all_prob = [], [], []

# Model params
cat_params = {
    'iterations': 800, 'learning_rate': 0.02, 'depth': 5,
    'l2_leaf_reg': 3, 'random_strength': 1.5,
    'auto_class_weights': 'Balanced',
    'verbose': 0, 'random_state': RANDOM_STATE,
    'allow_writing_files': False
}

for fold, (train_idx, test_idx) in enumerate(cv.split(X_sig_arr, y, groups), 1):
    print(f"\n{'─' * 80}")
    print(f"📌 FOLD {fold}/10")
    print(f"{'─' * 80}")

    # Split data
    X_sig_tr, X_sig_te = X_sig_arr[train_idx], X_sig_arr[test_idx]
    X_hc_tr, X_hc_te = X_hc_arr[train_idx], X_hc_arr[test_idx]
    df_c_tr, df_c_te = df_clinical.iloc[train_idx], df_clinical.iloc[test_idx]
    y_tr, y_te = y[train_idx], y[test_idx]
    g_tr, g_te = groups[train_idx], groups[test_idx]

    # ========================================================================
    # STREAM 1: BOSS FEATURES (Like Varghese et al. Option B)
    # ========================================================================
    print("  🎯 Stream 1: BOSS (multi-scale)...")

    boss_features_tr = []
    boss_features_te = []

    # Multi-scale BOSS like paper
    for window_size in BOSS_WINDOW_SIZES:
        boss = BOSS(
            word_size=BOSS_WORD_SIZE,
            n_bins=BOSS_N_BINS,
            window_size=window_size,
            sparse=False
        )

        # Reshape for BOSS: (n_samples, n_channels, n_timepoints)
        # BOSS expects (n_samples, n_timepoints) per channel
        # So we process each channel separately

        # For each channel, fit BOSS on TRAINING only
        boss_tr_all = []
        boss_te_all = []

        for ch in range(X_sig_tr.shape[1]):
            try:
                sig_tr_ch = X_sig_tr[:, ch, :]  # (n_train, 400)
                sig_te_ch = X_sig_te[:, ch, :]  # (n_test, 400)

                # Fit on training ONLY
                boss_tr_ch = boss.fit_transform(sig_tr_ch)
                boss_te_ch = boss.transform(sig_te_ch)

                boss_tr_all.append(boss_tr_ch)
                boss_te_all.append(boss_te_ch)
            except:
                # If BOSS fails on a channel, skip it
                pass

        if boss_tr_all:
            boss_features_tr.append(np.hstack(boss_tr_all))
            boss_features_te.append(np.hstack(boss_te_all))

    if boss_features_tr:
        X_boss_tr = np.hstack(boss_features_tr)
        X_boss_te = np.hstack(boss_features_te)
    else:
        # Fallback if BOSS fails
        X_boss_tr = np.zeros((len(y_tr), 1))
        X_boss_te = np.zeros((len(y_te), 1))

    print(f"    ✓ BOSS features: {X_boss_tr.shape[1]}")

    # ========================================================================
    # STREAM 2: MINIROCKET FEATURES
    # ========================================================================
    print(f"  🚀 Stream 2: MiniRocket ({ROCKET_KERNELS} kernels)...")

    rocket = MiniRocketMultivariate(
        num_kernels=ROCKET_KERNELS,
        random_state=RANDOM_STATE,
        n_jobs=-1
    )

    # FIT ON TRAINING ONLY!
    X_rocket_tr = rocket.fit_transform(X_sig_tr)
    X_rocket_te = rocket.transform(X_sig_te)

    X_rocket_tr = X_rocket_tr.values if hasattr(X_rocket_tr, 'values') else X_rocket_tr
    X_rocket_te = X_rocket_te.values if hasattr(X_rocket_te, 'values') else X_rocket_te

    print(f"    ✓ Rocket features: {X_rocket_tr.shape[1]}")

    # ========================================================================
    # STREAM 3: HANDCRAFTED FEATURES
    # ========================================================================
    print("  📐 Stream 3: Handcrafted features...")

    hc_scaler = RobustScaler()
    X_hc_tr_scaled = hc_scaler.fit_transform(X_hc_tr)
    X_hc_te_scaled = hc_scaler.transform(X_hc_te)

    print(f"    ✓ Handcrafted features: {X_hc_tr_scaled.shape[1]}")

    # ========================================================================
    # STREAM 4: NMS QUESTIONNAIRE (CRITICAL!)
    # ========================================================================
    print("  📋 Stream 4: NMS Questionnaire...")

    # Only use NMS questions (30 features)
    nms_cols = [f'nms_{i}' for i in range(30)]
    X_nms_tr = df_c_tr[nms_cols].values.astype(np.float32)
    X_nms_te = df_c_te[nms_cols].values.astype(np.float32)

    print(f"    ✓ NMS features: {X_nms_tr.shape[1]}")

    # ========================================================================
    # COMBINE ALL STREAMS
    # ========================================================================

    # Movement stream: BOSS + Rocket + Handcrafted
    X_movement_tr = np.hstack([X_boss_tr, X_rocket_tr, X_hc_tr_scaled]).astype(np.float32)
    X_movement_te = np.hstack([X_boss_te, X_rocket_te, X_hc_te_scaled]).astype(np.float32)

    print(f"\n  🔗 Combined movement features: {X_movement_tr.shape[1]}")

    # ========================================================================
    # STACKING CLASSIFIER (Like Varghese et al.)
    # ========================================================================
    print("  🎯 Training stacking ensemble...")

    # Base estimators
    movement_estimator = CatBoostClassifier(**cat_params)
    nms_estimator = CatBoostClassifier(**cat_params)

    # Stacking with Logistic Regression meta-learner (like paper)
    stacking_clf = StackingClassifier(
        estimators=[
            ('movement', movement_estimator),
            ('nms', nms_estimator)
        ],
        final_estimator=LogisticRegression(
            C=1.0,
            class_weight='balanced',
            random_state=RANDOM_STATE,
            max_iter=1000
        ),
        cv=3,  # Internal CV for meta-features (prevents overfitting)
        n_jobs=-1
    )

    # Prepare data for stacking
    # Movement model gets movement features
    # NMS model gets NMS features
    # We need to create a custom approach since StackingClassifier
    # expects same input for all estimators

    # Train movement model
    movement_estimator.fit(X_movement_tr, y_tr)

    # Train NMS model
    nms_estimator.fit(X_nms_tr, y_tr)

    # Get predictions on TRAINING for threshold (via CV to avoid leakage)
    from sklearn.model_selection import cross_val_predict

    movement_tr_proba = cross_val_predict(
        movement_estimator, X_movement_tr, y_tr,
        cv=3, method='predict_proba', n_jobs=-1
    )[:, 1]

    nms_tr_proba = cross_val_predict(
        nms_estimator, X_nms_tr, y_tr,
        cv=3, method='predict_proba', n_jobs=-1
    )[:, 1]

    # Stack predictions for meta-learner
    meta_features_tr = np.column_stack([movement_tr_proba, nms_tr_proba])

    # Train meta-learner
    meta_clf = LogisticRegression(
        C=1.0,
        class_weight='balanced',
        random_state=RANDOM_STATE,
        max_iter=1000
    )
    meta_clf.fit(meta_features_tr, y_tr)

    # Patient-level aggregation for TRAINING (for threshold)
    df_tr = pd.DataFrame({
        'pid': g_tr,
        'true': y_tr,
        'prob': meta_features_tr.mean(axis=1)  # Simple average for now
    })

    pat_tr_prob, pat_tr_lab = [], []
    for pid in df_tr['pid'].unique():
        pd_data = df_tr[df_tr['pid'] == pid]
        pat_tr_prob.append(np.median(pd_data['prob'].values))
        pat_tr_lab.append(pd_data['true'].iloc[0])

    # Calculate threshold on TRAINING
    fpr_tr, tpr_tr, ths_tr = roc_curve(pat_tr_lab, pat_tr_prob)
    best_th = ths_tr[np.argmax(tpr_tr - fpr_tr)]

    # ========================================================================
    # TEST PREDICTIONS
    # ========================================================================

    # Refit movement model on full training
    movement_estimator_full = CatBoostClassifier(**cat_params)
    movement_estimator_full.fit(X_movement_tr, y_tr)

    # Refit NMS model on full training
    nms_estimator_full = CatBoostClassifier(**cat_params)
    nms_estimator_full.fit(X_nms_tr, y_tr)

    # Get TEST predictions
    movement_te_proba = movement_estimator_full.predict_proba(X_movement_te)[:, 1]
    nms_te_proba = nms_estimator_full.predict_proba(X_nms_te)[:, 1]

    # Stack for meta-learner
    meta_features_te = np.column_stack([movement_te_proba, nms_te_proba])

    # Meta-learner prediction
    final_proba_te = meta_clf.predict_proba(meta_features_te)[:, 1]

    # Patient-level aggregation for TEST
    df_te = pd.DataFrame({
        'pid': g_te,
        'true': y_te,
        'prob': final_proba_te
    })

    pat_te_prob, pat_te_lab = [], []
    for pid in df_te['pid'].unique():
        pd_data = df_te[df_te['pid'] == pid]
        pat_te_prob.append(np.median(pd_data['prob'].values))
        pat_te_lab.append(pd_data['true'].iloc[0])

    y_true_pat = np.array(pat_te_lab)
    y_prob_pat = np.array(pat_te_prob)
    y_pred_pat = (y_prob_pat >= best_th).astype(int)

    # Calculate metrics
    ba = balanced_accuracy_score(y_true_pat, y_pred_pat)
    se = recall_score(y_true_pat, y_pred_pat, pos_label=1)
    sp = recall_score(y_true_pat, y_pred_pat, pos_label=0)
    f1 = f1_score(y_true_pat, y_pred_pat)
    au = roc_auc_score(y_true_pat, y_prob_pat)
    pr = precision_score(y_true_pat, y_pred_pat)

    metrics['bal_acc'].append(ba)
    metrics['sens'].append(se)
    metrics['spec'].append(sp)
    metrics['f1'].append(f1)
    metrics['auc'].append(au)
    metrics['precision'].append(pr)
    metrics['recall'].append(se)

    fold_results.append({
        'fold': fold,
        'bal_acc': ba,
        'sens': se,
        'spec': sp,
        'f1': f1,
        'auc': au,
        'threshold': best_th
    })

    all_true.extend(y_true_pat)
    all_pred.extend(y_pred_pat)
    all_prob.extend(y_prob_pat)

    print(f"\n  ✅ Results:")
    print(f"     BalAcc={ba*100:.2f}% | Sens={se*100:.2f}% | Spec={sp*100:.2f}% | F1={f1*100:.2f}%")

    gc.collect()

# ============================================================================
# FINAL RESULTS & COMPARISON
# ============================================================================

print(f"\n{'=' * 80}")
print("🏆 FINAL RESULTS")
print(f"{'=' * 80}")

our_ba = np.mean(metrics['bal_acc']) * 100
our_sens = np.mean(metrics['sens']) * 100
our_spec = np.mean(metrics['spec']) * 100
our_f1 = np.mean(metrics['f1']) * 100
our_auc = np.mean(metrics['auc']) * 100

std_ba = np.std(metrics['bal_acc']) * 100
std_sens = np.std(metrics['sens']) * 100
std_spec = np.std(metrics['spec']) * 100
std_f1 = np.std(metrics['f1']) * 100

print(f"\nOur Method:")
print(f"  Balanced Accuracy: {our_ba:.2f}% ± {std_ba:.2f}%")
print(f"  Sensitivity:       {our_sens:.2f}% ± {std_sens:.2f}%")
print(f"  Specificity:       {our_spec:.2f}% ± {std_spec:.2f}%")
print(f"  F1-Score:          {our_f1:.2f}% ± {std_f1:.2f}%")
print(f"  AUC:               {our_auc:.2f}%")

# Paper comparison
paper_ba = 91.16
paper_sens = 92.40
paper_spec = 92.00
paper_f1 = 94.62

print(f"\nVarghese et al. (2024):")
print(f"  Balanced Accuracy: {paper_ba:.2f}%")
print(f"  Sensitivity:       {paper_sens:.2f}%")
print(f"  Specificity:       {paper_spec:.2f}%")
print(f"  F1-Score:          {paper_f1:.2f}%")

print(f"\n{'─' * 80}")
print("COMPARISON:")
print(f"{'─' * 80}")
print(f"  ΔBalanced Accuracy: {our_ba - paper_ba:+.2f}%")
print(f"  ΔSensitivity:       {our_sens - paper_sens:+.2f}%")
print(f"  ΔSpecificity:       {our_spec - paper_spec:+.2f}%")
print(f"  ΔF1-Score:          {our_f1 - paper_f1:+.2f}%")

# Statistical test
t_stat, p_val = ttest_1samp([b*100 for b in metrics['bal_acc']], paper_ba)
print(f"\nStatistical Significance:")
print(f"  t-statistic: {t_stat:.3f}")
print(f"  p-value: {'<0.001' if p_val < 0.001 else f'{p_val:.3f}'}")

if our_ba > paper_ba:
    print(f"\n🎉 SUCCESS! We BEAT the paper by {our_ba - paper_ba:.2f}%!")
elif our_ba > paper_ba - 1:
    print(f"\n✅ VERY CLOSE! Within 1% of paper ({paper_ba - our_ba:.2f}% gap)")
else:
    print(f"\n⚠️ Below paper by {paper_ba - our_ba:.2f}% - try increasing kernels or adding features")

# Save results
results_dict = {
    'our_balanced_accuracy': our_ba,
    'paper_balanced_accuracy': paper_ba,
    'delta': our_ba - paper_ba,
    'all_metrics': metrics,
    'fold_results': fold_results,
    'statistical_test': {'t_stat': t_stat, 'p_value': p_val}
}

import pickle
with open(f'{OUTPUT_DIR}/results_ultimate.pkl', 'wb') as f:
    pickle.dump(results_dict, f)

print(f"\n✅ Results saved to {OUTPUT_DIR}/results_ultimate.pkl")
print("=" * 80)

