def install(pkg):
    try: __import__(pkg.split('[')[0].replace('-','_'))
    except:
        subprocess.check_call([sys.executable, "-m", "pip", "install", pkg, "-q", "--break-system-packages"],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

print("📦 Installing packages (silent)...")
