def save_checkpoint(fold, data, output_dir=OUTPUT_DIR):
    """Save fold results to disk"""
    checkpoint_file = f'{output_dir}/checkpoint_fold_{fold}.pkl'
    with open(checkpoint_file, 'wb') as f:
        pickle.dump(data, f)
    print(f"    💾 Checkpoint saved: fold {fold}")

def load_checkpoints(output_dir=OUTPUT_DIR):
    """Load all existing checkpoints"""
    checkpoints = []
    for i in range(1, 11):
        checkpoint_file = f'{output_dir}/checkpoint_fold_{i}.pkl'
        if os.path.exists(checkpoint_file):
            with open(checkpoint_file, 'rb') as f:
                checkpoints.append(pickle.load(f))
    return checkpoints

def save_final_results(results, output_dir=OUTPUT_DIR):
    """Save final results"""
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    final_file = f'{output_dir}/FINAL_RESULTS_{timestamp}.pkl'
    with open(final_file, 'wb') as f:
        pickle.dump(results, f)
    print(f"\n💾 FINAL RESULTS SAVED: {final_file}")
    return final_file

