def find_file(name):
    """Find file anywhere in drive"""
    paths = [f"/content/{name}", f"/content/drive/MyDrive/{name}",
             f"/content/drive/MyDrive/Parkinson/{name}", f"./{name}"]
    for p in paths:
        if os.path.exists(p): return p
    if os.path.exists("/content/drive"):
        r = subprocess.getoutput(f"find /content/drive -name '{name}' -type f 2>/dev/null | head -1")
        if r.strip(): return r.strip()
    return None

def find_data_dir():
    """Find data directory"""
    dirs = ["./pads_data_extracted", "/content/pads_data_extracted",
            "/content/pads_extracted", "/content/drive/MyDrive/Parkinson/pads_data_extracted"]
    for d in dirs:
        if os.path.exists(d) and len(glob(f"{d}/**/*.txt", recursive=True)) > 10:
            return d
    return None

def find_data():
    """Smart data finding like 25-hour code"""
    # First check if already extracted
    data_path = find_data_dir()
    if data_path:
        return data_path

    # If not, find and extract zip
    zp = find_file("pads-parkinsons-disease-smartwatch-dataset-1.0.0.zip")
    if zp:
        print(f"📦 Extracting from {zp}...")
        with zf.ZipFile(zp, 'r') as z:
            z.extractall("./pads_data_extracted")
        return "./pads_data_extracted"

    raise FileNotFoundError("❌ PADS data not found!")

data_path = find_data()
print(f"✅ Data: {data_path}")

# ============================================================================
# FAST FEATURE EXTRACTION
# ============================================================================

def extract_features_fast(sig):
    """Fast handcrafted features - 28 per channel"""
    f = []

    # Stats (8)
    f.extend([np.mean(sig), np.std(sig), np.min(sig), np.max(sig),
              skew(sig), kurtosis(sig), np.percentile(sig,25), np.percentile(sig,75)])

    # Wavelet (9) - 2 levels
    try:
        c = pywt.wavedec(sig, 'db4', level=2)
        for cc in c: f.extend([np.mean(cc), np.std(cc), np.max(np.abs(cc))])
    except: f.extend([0]*9)

    # Frequency (8)
    try:
        fr, ps = welch(sig, fs=100, nperseg=128)
        f.extend([np.sum(ps), np.max(ps), np.argmax(ps), np.mean(ps),
                  np.sum(ps[fr<5]), np.sum(ps[(fr>=5)&(fr<10)]),
                  np.sum(ps[(fr>=10)&(fr<20)]), np.sum(ps[fr>=20])])
    except: f.extend([0]*8)

    # Temporal (3)
    d = np.diff(sig)
    f.extend([np.mean(np.abs(d)), np.std(d), np.sum(np.abs(d))])

    return np.array(f)

# ============================================================================
# LOAD DATA
# ============================================================================

print("\n📊 Loading data...")

# Patient info
patient_info = {}
meta_path = find_file("subjects.csv")

if meta_path and os.path.exists(meta_path):
    print(f"   Loading from: {meta_path}")
    df = pd.read_csv(meta_path)
    df_filtered = df[df['label'].isin([0, 1])]  # Only HC and PD

    for _, r in df_filtered.iterrows():
        pid = str(r['id']).zfill(3)
        patient_info[pid] = {
            'label': int(r['label']),
            'age': r['age'],
            'gender': str(r['gender'])
        }
    print(f"   ✅ Loaded {len(patient_info)} patients from CSV")
else:
    # Fallback: load from JSON files
    print("   CSV not found, loading from JSON...")
    p_files = glob(f"{data_path}/**/patient_*.json", recursive=True)
    for pf in p_files:
        try:
            with open(pf) as f:
                d = json.load(f)
            pid = str(d.get('id', ''))
            cond = d.get('condition', '').lower()

            if "parkinson" in cond:
                lbl = 1
            elif "healthy" in cond or "control" in cond:
                lbl = 0
            else:
                continue

            if pid:
                patient_info[pid] = {
                    'label': lbl,
                    'age': d.get('age', 60),
                    'gender': str(d.get('gender', 'unknown'))
                }
        except:
            continue
    print(f"   ✅ Loaded {len(patient_info)} patients from JSON")

# NMS
nms_data = {}
for qf in glob(f"{data_path}/**/questionnaire_response_*.json", recursive=True):
    try:
        q = json.load(open(qf))
        pid = str(q.get('subject_id',''))
        if pid not in patient_info: continue
        ans = [0]*30
        for it in q.get('item',[]):
            try:
                i = int(it.get('link_id','99'))-1
                if 0<=i<30: ans[i] = 1 if it.get('answer') else 0
            except: pass
        nms_data[pid] = ans
    except: pass

# Signals
s_files = [f for f in glob(f"{data_path}/**/*.txt", recursive=True)
           if "LICENSE" not in f and "README" not in f]

X_sig, X_hc, X_nms, y_list, groups = [], [], [], [], []

print(f"Processing {len(s_files)} files...")
for fp in tqdm(s_files, desc="Loading"):
    try:
        pid = os.path.basename(fp).split('_')[0]
        if pid not in patient_info: continue

        raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
        if len(raw) < 100: continue

        if len(raw) > 50: raw = raw[50:,:]
        raw = detrend(raw, axis=0)
        if raw.shape[0] > raw.shape[1]: raw = raw.T
        raw = resample(raw, 400, axis=1)

        X_sig.append(raw)

        # Handcrafted (FAST)
        hc = [f for ch in range(raw.shape[0]) for f in extract_features_fast(raw[ch])]
        X_hc.append(hc)

        # NMS
        X_nms.append(nms_data.get(pid, [0]*30))

        y_list.append(patient_info[pid]['label'])
        groups.append(pid)
    except: continue

print(f"\n✅ Loaded {len(y_list)} samples from {len(np.unique(groups))} patients")

# SAFETY CHECK
if len(y_list) == 0:
    print("\n❌ ERROR: No samples loaded!")
    print("\nDEBUG INFO:")
    print(f"  Data path: {data_path}")
    print(f"  Signal files found: {len(s_files)}")
    print(f"  Patient info loaded: {len(patient_info)}")
    print(f"\nFirst 3 signal files:")
    for i, f in enumerate(s_files[:3]):
        print(f"    {i+1}. {f}")
    print(f"\nFirst 3 patient IDs:")
    for i, pid in enumerate(list(patient_info.keys())[:3]):
        print(f"    {i+1}. {pid}")
    raise ValueError("No data loaded - check patient_info matching!")

# Convert
max_ch = max(x.shape[0] for x in X_sig)
X_sig_arr = np.zeros((len(X_sig), max_ch, 400), dtype=np.float32)
for i, x in enumerate(X_sig): X_sig_arr[i, :x.shape[0], :] = x

X_hc_arr = np.array(X_hc, dtype=np.float32)
X_nms_arr = np.array(X_nms, dtype=np.float32)
y = np.array(y_list)
groups = np.array(groups)

del X_sig
gc.collect()

print(f"PD: {np.sum(y==1)}, HC: {np.sum(y==0)}")

# ============================================================================
# CROSS-VALIDATION WITH CHECKPOINTS
# ============================================================================

print(f"\n{'='*80}")
print("🔬 10-FOLD CV - ZERO LEAKAGE + CHECKPOINTS")
print(f"{'='*80}")

cv = StratifiedGroupKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)
metrics = {'bal_acc':[], 'sens':[], 'spec':[], 'f1':[], 'auc':[]}
fold_results = []

for fold, (tr_i, te_i) in enumerate(cv.split(X_sig_arr, y, groups), 1):

    # Check if this fold already processed
    checkpoint_exists = os.path.exists(f'{OUTPUT_DIR}/checkpoint_fold_{fold}.pkl')
    if checkpoint_exists:
        print(f"\n✅ FOLD {fold}/10 - LOADING FROM CHECKPOINT")
        with open(f'{OUTPUT_DIR}/checkpoint_fold_{fold}.pkl', 'rb') as f:
            checkpoint_data = pickle.load(f)

        metrics['bal_acc'].append(checkpoint_data['bal_acc'])
        metrics['sens'].append(checkpoint_data['sens'])
        metrics['spec'].append(checkpoint_data['spec'])
        metrics['f1'].append(checkpoint_data['f1'])
        metrics['auc'].append(checkpoint_data['auc'])
        fold_results.append(checkpoint_data)

        print(f"  ✅ BalAcc={checkpoint_data['bal_acc']*100:.2f}%")
        continue

    print(f"\n📌 FOLD {fold}/10 - PROCESSING")

    X_sig_tr, X_sig_te = X_sig_arr[tr_i], X_sig_arr[te_i]
    X_hc_tr, X_hc_te = X_hc_arr[tr_i], X_hc_arr[te_i]
    X_nms_tr, X_nms_te = X_nms_arr[tr_i], X_nms_arr[te_i]
    y_tr, y_te = y[tr_i], y[te_i]
    g_tr, g_te = groups[tr_i], groups[te_i]

    # ROCKET - FIT ON TRAINING ONLY
    print("  🚀 Rocket (15K)...")
    rocket = MiniRocketMultivariate(num_kernels=15000, random_state=RANDOM_STATE, n_jobs=-1)
    X_r_tr = rocket.fit_transform(X_sig_tr)
    X_r_te = rocket.transform(X_sig_te)

    X_r_tr = X_r_tr.values if hasattr(X_r_tr, 'values') else X_r_tr
    X_r_te = X_r_te.values if hasattr(X_r_te, 'values') else X_r_te

    # Scale handcrafted - FIT ON TRAINING ONLY
    hc_sc = RobustScaler()
    X_hc_tr_sc = hc_sc.fit_transform(X_hc_tr)
    X_hc_te_sc = hc_sc.transform(X_hc_te)

    # Combine
    X_mov_tr = np.hstack([X_r_tr, X_hc_tr_sc]).astype(np.float32)
    X_mov_te = np.hstack([X_r_te, X_hc_te_sc]).astype(np.float32)

    print(f"  ✓ Features: Rocket={X_r_tr.shape[1]}, Handcrafted={X_hc_tr_sc.shape[1]}, NMS=30")

    # STACKING - ZERO LEAKAGE
    print("  🎯 Stacking...")

    # Movement model
    mov_model = CatBoostClassifier(
        iterations=600, learning_rate=0.02, depth=5,
        auto_class_weights='Balanced', verbose=0,
        random_state=RANDOM_STATE, allow_writing_files=False
    )
    mov_model.fit(X_mov_tr, y_tr)

    # NMS model
    nms_model = CatBoostClassifier(
        iterations=600, learning_rate=0.02, depth=5,
        auto_class_weights='Balanced', verbose=0,
        random_state=RANDOM_STATE, allow_writing_files=False
    )
    nms_model.fit(X_nms_tr, y_tr)

    # CV predictions on TRAINING (prevent leakage)
    mov_tr_proba = cross_val_predict(mov_model, X_mov_tr, y_tr, cv=3,
                                      method='predict_proba', n_jobs=-1)[:,1]
    nms_tr_proba = cross_val_predict(nms_model, X_nms_tr, y_tr, cv=3,
                                      method='predict_proba', n_jobs=-1)[:,1]

    # Meta-learner - FIT ON TRAINING ONLY
    meta = LogisticRegression(C=1.0, class_weight='balanced',
                               random_state=RANDOM_STATE, max_iter=1000)
    meta.fit(np.column_stack([mov_tr_proba, nms_tr_proba]), y_tr)

    # Patient-level TRAINING for threshold
    ens_tr = (mov_tr_proba + nms_tr_proba) / 2.0
    df_tr = pd.DataFrame({'pid':g_tr, 'true':y_tr, 'prob':ens_tr})

    pat_tr_prob, pat_tr_lab = [], []
    for pid in df_tr['pid'].unique():
        pd = df_tr[df_tr['pid']==pid]
        pat_tr_prob.append(np.median(pd['prob']))
        pat_tr_lab.append(pd['true'].iloc[0])

    # Threshold on TRAINING
    fpr, tpr, ths = roc_curve(pat_tr_lab, pat_tr_prob)
    best_th = ths[np.argmax(tpr-fpr)]

    # TEST predictions
    mov_te_proba = mov_model.predict_proba(X_mov_te)[:,1]
    nms_te_proba = nms_model.predict_proba(X_nms_te)[:,1]
    ens_te = (mov_te_proba + nms_te_proba) / 2.0

    # Patient-level TEST
    df_te = pd.DataFrame({'pid':g_te, 'true':y_te, 'prob':ens_te})

    pat_te_prob, pat_te_lab = [], []
    for pid in df_te['pid'].unique():
        pd = df_te[df_te['pid']==pid]
        pat_te_prob.append(np.median(pd['prob']))
        pat_te_lab.append(pd['true'].iloc[0])

    y_true = np.array(pat_te_lab)
    y_prob = np.array(pat_te_prob)
    y_pred = (y_prob >= best_th).astype(int)

    # Metrics
    ba = balanced_accuracy_score(y_true, y_pred)
    se = recall_score(y_true, y_pred, pos_label=1)
    sp = recall_score(y_true, y_pred, pos_label=0)
    f1 = f1_score(y_true, y_pred)
    au = roc_auc_score(y_true, y_prob)

    metrics['bal_acc'].append(ba)
    metrics['sens'].append(se)
    metrics['spec'].append(sp)
    metrics['f1'].append(f1)
    metrics['auc'].append(au)

    fold_data = {
        'fold': fold, 'bal_acc': ba, 'sens': se, 'spec': sp,
        'f1': f1, 'auc': au, 'threshold': best_th
    }
    fold_results.append(fold_data)

    # SAVE CHECKPOINT
    save_checkpoint(fold, fold_data)

    print(f"  ✅ BalAcc={ba*100:.2f}% | Sens={se*100:.2f}% | Spec={sp*100:.2f}%")

    gc.collect()

# ============================================================================
# FINAL RESULTS
# ============================================================================

print(f"\n{'='*80}")
print("🏆 PLAN A - FINAL RESULTS")
print(f"{'='*80}")

our_ba = np.mean(metrics['bal_acc'])*100
std_ba = np.std(metrics['bal_acc'])*100
paper_ba = 91.16

print(f"\nOur Method:  {our_ba:.2f}% ± {std_ba:.2f}%")
print(f"Paper:       {paper_ba:.2f}%")
print(f"Difference:  {our_ba-paper_ba:+.2f}%")

t_stat, p_val = ttest_1samp([b*100 for b in metrics['bal_acc']], paper_ba)
print(f"\nStatistical test: t={t_stat:.3f}, p={'<0.001' if p_val<0.001 else f'{p_val:.3f}'}")

# Save final
results_dict = {
    'plan': 'A_FAST_30MIN',
    'our_balanced_accuracy': our_ba,
    'paper_balanced_accuracy': paper_ba,
    'delta': our_ba - paper_ba,
    'all_metrics': metrics,
    'fold_results': fold_results,
    'statistical_test': {'t_stat': t_stat, 'p_value': p_val}
}

final_file = save_final_results(results_dict)

# Verdict
print("\n" + "="*80)
if our_ba > paper_ba:
    print(f"🎉 PLAN A SUCCESS! Beat paper by {our_ba-paper_ba:.2f}%!")
    print("✅ NO NEED FOR PLAN B!")
elif our_ba > 90:
    print(f"✅ EXCELLENT! {our_ba:.2f}% - Within {paper_ba-our_ba:.2f}% of paper")
    print("💡 Consider PLAN B (BOSS) to close the gap")
elif our_ba > 88:
    print(f"✅ GOOD! {our_ba:.2f}% - Gap: {paper_ba-our_ba:.2f}%")
    print("💡 RECOMMENDED: Try PLAN B (Optimized BOSS)")
else:
    print(f"⚠️  {our_ba:.2f}% - Below target")
    print("💡 MUST TRY: PLAN B (Optimized BOSS)")
print("="*80)
print(f"\n📁 Results: {final_file}")

# ============================================================================
# PLAN A TURBO: ULTRA FAST (15 minutes) - EMERGENCY VERSION
# ============================================================================
# 🎯 TARGET: 87-90% balanced accuracy
# ⚡ TIME: 15 minutes on Colab CPU
# ✅ ZERO DATA LEAKAGE
# 💾 CHECKPOINT: Every fold saved
# 🔥 OPTIMIZED: 8K Rocket (instead of 15K)
# ============================================================================

import os, sys, subprocess, warnings, gc, zipfile as zf, pickle, json
from glob import glob
from tqdm import tqdm
import numpy as np
import pandas as pd
from datetime import datetime

warnings.filterwarnings('ignore')

def install(pkg):
    try: __import__(pkg.split('[')[0].replace('-','_'))
    except:
        subprocess.check_call([sys.executable, "-m", "pip", "install", pkg, "-q", "--break-system-packages"],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

print("📦 Installing packages...")
for pkg in ["numpy", "pandas", "scipy", "scikit-learn", "sktime", "catboost"]:
    install(pkg)

from scipy.signal import detrend, resample
from scipy.stats import ttest_1samp
from sklearn.model_selection import StratifiedGroupKFold, cross_val_predict
from sklearn.preprocessing import RobustScaler
from sklearn.metrics import *
from sklearn.linear_model import LogisticRegression
from sktime.transformations.panel.rocket import MiniRocketMultivariate
from catboost import CatBoostClassifier

RANDOM_STATE = 42
np.random.seed(RANDOM_STATE)

print("=" * 80)
print("🚀 PLAN A TURBO: ULTRA FAST (15 MIN)")
print("=" * 80)
print("Strategy: Rocket 8K + NMS + Stacking")
print("Target: 87-90% balanced accuracy")
print("=" * 80)

OUTPUT_DIR = './plan_a_turbo'
os.makedirs(OUTPUT_DIR, exist_ok=True)

# ============================================================================
# CHECKPOINT
# ============================================================================

def save_checkpoint(fold, data):
    with open(f'{OUTPUT_DIR}/checkpoint_fold_{fold}.pkl', 'wb') as f:
        pickle.dump(data, f)

def save_final(results):
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    final_file = f'{OUTPUT_DIR}/FINAL_RESULTS_{timestamp}.pkl'
    with open(final_file, 'wb') as f:
        pickle.dump(results, f)
    return final_file

# ============================================================================
# FIND DATA
# ============================================================================

print("\n📁 Finding data...")
try:
    if not os.path.exists('/content/drive'):
        from google.colab import drive
        drive.mount('/content/drive')
except: pass

def find_file(name):
    paths = [f"/content/{name}", f"/content/drive/MyDrive/{name}",
             f"/content/drive/MyDrive/Parkinson/{name}", f"./{name}"]
    for p in paths:
        if os.path.exists(p): return p
    if os.path.exists("/content/drive"):
        r = subprocess.getoutput(f"find /content/drive -name '{name}' -type f 2>/dev/null | head -1")
        if r.strip(): return r.strip()
    return None

def find_data_dir():
    dirs = ["./pads_data_extracted", "/content/pads_data_extracted",
            "/content/pads_extracted", "/content/drive/MyDrive/Parkinson/pads_data_extracted"]
    for d in dirs:
        if os.path.exists(d) and len(glob(f"{d}/**/*.txt", recursive=True)) > 10:
            return d
    return None

def find_data():
    data_path = find_data_dir()
    if data_path:
        return data_path

    zp = find_file("pads-parkinsons-disease-smartwatch-dataset-1.0.0.zip")
    if zp:
        print(f"📦 Extracting...")
        with zf.ZipFile(zp, 'r') as z:
            z.extractall("./pads_data_extracted")
        return "./pads_data_extracted"

    raise FileNotFoundError("❌ PADS data not found!")

data_path = find_data()
print(f"✅ Data: {data_path}")

# ============================================================================
# LOAD DATA
# ============================================================================

print("\n📊 Loading data...")

patient_info = {}
meta_path = find_file("subjects.csv")

if meta_path and os.path.exists(meta_path):
    df = pd.read_csv(meta_path)
    for _, r in df[df['label'].isin([0,1])].iterrows():
        patient_info[str(r['id']).zfill(3)] = {
            'label': int(r['label']), 'age': r['age'], 'gender': str(r['gender'])
        }
else:
    p_files = glob(f"{data_path}/**/patient_*.json", recursive=True)
    for pf in p_files:
        try:
            d = json.load(open(pf))
            pid = str(d.get('id',''))
            cond = d.get('condition','').lower()
            lbl = 1 if "parkinson" in cond else (0 if "healthy" in cond or "control" in cond else -1)
            if lbl >= 0 and pid:
                patient_info[pid] = {'label': lbl, 'age': d.get('age',60), 'gender': str(d.get('gender','unknown'))}
        except: pass

print(f"   ✅ {len(patient_info)} patients")

nms_data = {}
for qf in glob(f"{data_path}/**/questionnaire_response_*.json", recursive=True):
    try:
        q = json.load(open(qf))
        pid = str(q.get('subject_id',''))
        if pid not in patient_info: continue
        ans = [0]*30
        for it in q.get('item',[]):
            try:
                i = int(it.get('link_id','99'))-1
                if 0<=i<30: ans[i] = 1 if it.get('answer') else 0
            except: pass
        nms_data[pid] = ans
    except: pass

s_files = [f for f in glob(f"{data_path}/**/*.txt", recursive=True)
           if "LICENSE" not in f and "README" not in f]

X_sig, X_nms, y_list, groups = [], [], [], []

print(f"   Processing {len(s_files)} files...")
for fp in tqdm(s_files, desc="   Loading", ncols=70):
    try:
        pid = os.path.basename(fp).split('_')[0]
        if pid not in patient_info: continue

        raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
        if len(raw) < 100: continue

        if len(raw) > 50: raw = raw[50:,:]
        raw = detrend(raw, axis=0)
        if raw.shape[0] > raw.shape[1]: raw = raw.T
        raw = resample(raw, 400, axis=1)

        X_sig.append(raw)
        X_nms.append(nms_data.get(pid, [0]*30))
        y_list.append(patient_info[pid]['label'])
        groups.append(pid)
    except: continue

max_ch = max(x.shape[0] for x in X_sig)
X_sig_arr = np.zeros((len(X_sig), max_ch, 400), dtype=np.float32)
for i, x in enumerate(X_sig): X_sig_arr[i, :x.shape[0], :] = x

X_nms_arr = np.array(X_nms, dtype=np.float32)
y = np.array(y_list)
groups = np.array(groups)

del X_sig
gc.collect()

print(f"   ✅ {len(y)} samples ({np.sum(y==1)} PD, {np.sum(y==0)} HC)")

# ============================================================================
# FAST CV
# ============================================================================

print(f"\n{'='*80}")
print("🔬 10-FOLD CV - TURBO MODE")
print(f"{'='*80}")

cv = StratifiedGroupKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)
metrics = {'bal_acc':[], 'sens':[], 'spec':[], 'f1':[], 'auc':[]}
fold_results = []

for fold, (tr_i, te_i) in enumerate(cv.split(X_sig_arr, y, groups), 1):

    # Check checkpoint
    if os.path.exists(f'{OUTPUT_DIR}/checkpoint_fold_{fold}.pkl'):
        print(f"\n✅ FOLD {fold}/10 - FROM CHECKPOINT")
        with open(f'{OUTPUT_DIR}/checkpoint_fold_{fold}.pkl', 'rb') as f:
            checkpoint_data = pickle.load(f)

        for k in metrics.keys():
            metrics[k].append(checkpoint_data[k])
        fold_results.append(checkpoint_data)
        print(f"   BalAcc={checkpoint_data['bal_acc']*100:.2f}%")
        continue

    print(f"\n📌 FOLD {fold}/10")

    X_sig_tr, X_sig_te = X_sig_arr[tr_i], X_sig_arr[te_i]
    X_nms_tr, X_nms_te = X_nms_arr[tr_i], X_nms_arr[te_i]
    y_tr, y_te = y[tr_i], y[te_i]
    g_tr, g_te = groups[tr_i], groups[te_i]

    # ROCKET 8K (FAST!)
    print("   🚀 Rocket 8K...")
    rocket = MiniRocketMultivariate(num_kernels=8000, random_state=RANDOM_STATE, n_jobs=-1)
    X_r_tr = rocket.fit_transform(X_sig_tr)
    X_r_te = rocket.transform(X_sig_te)

    X_r_tr = X_r_tr.values if hasattr(X_r_tr, 'values') else X_r_tr
    X_r_te = X_r_te.values if hasattr(X_r_te, 'values') else X_r_te

    # STACKING
    print("   🔗 Stacking...")

    mov_model = CatBoostClassifier(
        iterations=400, learning_rate=0.03, depth=4,
        auto_class_weights='Balanced', verbose=0,
        random_state=RANDOM_STATE, allow_writing_files=False
    )
    mov_model.fit(X_r_tr, y_tr)

    nms_model = CatBoostClassifier(
        iterations=400, learning_rate=0.03, depth=4,
        auto_class_weights='Balanced', verbose=0,
        random_state=RANDOM_STATE, allow_writing_files=False
    )
    nms_model.fit(X_nms_tr, y_tr)

    # CV on training
    mov_tr_proba = cross_val_predict(mov_model, X_r_tr, y_tr, cv=3,
                                      method='predict_proba', n_jobs=-1)[:,1]
    nms_tr_proba = cross_val_predict(nms_model, X_nms_tr, y_tr, cv=3,
                                      method='predict_proba', n_jobs=-1)[:,1]

    # Threshold on training
    ens_tr = (mov_tr_proba + nms_tr_proba) / 2.0
    df_tr = pd.DataFrame({'pid':g_tr, 'true':y_tr, 'prob':ens_tr})

    pat_tr_prob, pat_tr_lab = [], []
    for pid in df_tr['pid'].unique():
        pid_data = df_tr[df_tr['pid']==pid]
        pat_tr_prob.append(np.median(pid_data['prob']))
        pat_tr_lab.append(pid_data['true'].iloc[0])

    fpr, tpr, ths = roc_curve(pat_tr_lab, pat_tr_prob)
    best_th = ths[np.argmax(tpr-fpr)]

    # Test
    mov_te_proba = mov_model.predict_proba(X_r_te)[:,1]
    nms_te_proba = nms_model.predict_proba(X_nms_te)[:,1]
    ens_te = (mov_te_proba + nms_te_proba) / 2.0

    df_te = pd.DataFrame({'pid':g_te, 'true':y_te, 'prob':ens_te})

    pat_te_prob, pat_te_lab = [], []
    for pid in df_te['pid'].unique():
        pid_data = df_te[df_te['pid']==pid]
        pat_te_prob.append(np.median(pid_data['prob']))
        pat_te_lab.append(pid_data['true'].iloc[0])

    y_true = np.array(pat_te_lab)
    y_prob = np.array(pat_te_prob)
    y_pred = (y_prob >= best_th).astype(int)

    ba = balanced_accuracy_score(y_true, y_pred)
    se = recall_score(y_true, y_pred, pos_label=1)
    sp = recall_score(y_true, y_pred, pos_label=0)
    f1 = f1_score(y_true, y_pred)
    au = roc_auc_score(y_true, y_prob)

    metrics['bal_acc'].append(ba)
    metrics['sens'].append(se)
    metrics['spec'].append(sp)
    metrics['f1'].append(f1)
    metrics['auc'].append(au)

    fold_data = {
        'fold': fold, 'bal_acc': ba, 'sens': se, 'spec': sp,
        'f1': f1, 'auc': au, 'threshold': best_th
    }
    fold_results.append(fold_data)

    save_checkpoint(fold, fold_data)

    print(f"   ✅ BalAcc={ba*100:.2f}% | Sens={se*100:.2f}% | Spec={sp*100:.2f}%")

    gc.collect()

