import os, sys, subprocess, warnings, gc, zipfile as zf, pickle, json
from glob import glob
from tqdm import tqdm
import numpy as np
import pandas as pd
from datetime import datetime

warnings.filterwarnings('ignore')

def install(pkg):
    try: __import__(pkg.split('[')[0].replace('-','_'))
    except:
        subprocess.check_call([sys.executable, "-m", "pip", "install", pkg, "-q", "--break-system-packages"],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

print("📦 Installing packages...")
for pkg in ["numpy", "pandas", "scipy", "scikit-learn", "sktime", "catboost"]:
    install(pkg)

from scipy.signal import detrend, resample
from scipy.stats import ttest_1samp
from sklearn.model_selection import StratifiedGroupKFold
from sklearn.metrics import *
from sktime.transformations.panel.rocket import MiniRocketMultivariate
from catboost import CatBoostClassifier

RANDOM_STATE = 42
np.random.seed(RANDOM_STATE)

print("=" * 80)
print("🚀 SUPER TURBO: 10 MINUTES MAX")
print("=" * 80)
print("Strategy: Rocket 8K + NMS (NO nested CV)")
print("Target: 87-90% balanced accuracy")
print("=" * 80)

