# ── Helper: patient-level aggregation ─────────────────────────────────────
def patient_aggregate(pids, labels, probs):
    """Median aggregation per patient → (pat_probs, pat_labels, pat_ids)"""
    df = pd.DataFrame({'pid': pids, 'true': labels, 'prob': probs})
    grp = df.groupby('pid')
    pat_prob  = grp['prob'].median().values
    pat_label = grp['true'].first().values
    pat_ids   = grp['prob'].median().index.values
    return pat_prob, pat_label, pat_ids

