print("🔬 10-FOLD CV — PLAN B")
print(f"{'='*70}")

for fold, (tr_i, te_i) in enumerate(cv.split(X_sig_arr, y, groups), 1):

    if os.path.exists(f'{OUTPUT_DIR}/ckpt_fold_{fold}.pkl'):
        print(f"\n✅ FOLD {fold}/10 — CHECKPOINT")
        with open(f'{OUTPUT_DIR}/ckpt_fold_{fold}.pkl', 'rb') as f:
            ck = pickle.load(f)
        for k in metrics: metrics[k].append(ck[k])
        fold_results.append(ck)
        print(f"   BalAcc={ck['bal_acc']*100:.2f}%")
        continue

    print(f"\n📌 FOLD {fold}/10")

    X_sig_tr_all = X_sig_arr[tr_i]
    X_nms_tr_all = X_nms_arr[tr_i]
    y_tr_all     = y[tr_i]
    g_tr_all     = groups[tr_i]
    X_sig_te     = X_sig_arr[te_i]
    X_nms_te     = X_nms_arr[te_i]
    y_te         = y[te_i]
    g_te         = groups[te_i]

    # ── Inner val split for threshold (patient-grouped) ──────────────────
    # Split unique patients: 80% train_model, 20% val_threshold
    unique_pats = np.unique(g_tr_all)
    pat_labels  = np.array([patient_info[p]['label'] for p in unique_pats])

    sss = StratifiedShuffleSplit(n_splits=1, test_size=0.2, random_state=fold)
    for model_idx, val_idx in sss.split(unique_pats, pat_labels):
        pats_model = set(unique_pats[model_idx])
        pats_val   = set(unique_pats[val_idx])

    mask_model = np.array([g in pats_model for g in g_tr_all])
    mask_val   = np.array([g in pats_val   for g in g_tr_all])

    X_sig_m, X_nms_m, y_m, g_m = (X_sig_tr_all[mask_model], X_nms_tr_all[mask_model],
                                    y_tr_all[mask_model],    g_tr_all[mask_model])
    X_sig_v, X_nms_v, y_v, g_v = (X_sig_tr_all[mask_val],  X_nms_tr_all[mask_val],
                                    y_tr_all[mask_val],      g_tr_all[mask_val])

    # ── MiniRocket (8K kernels) ─────────────────────────────────────────
    print("   🚀 MiniRocket 8K...")
    rocket = MiniRocketMultivariate(num_kernels=8000, random_state=RANDOM_STATE, n_jobs=-1)
    X_r_m = rocket.fit_transform(X_sig_m)
    X_r_v = rocket.transform(X_sig_v)
    X_r_te_raw = rocket.transform(X_sig_te)

    X_r_m  = X_r_m.values  if hasattr(X_r_m,  'values') else np.array(X_r_m)
    X_r_v  = X_r_v.values  if hasattr(X_r_v,  'values') else np.array(X_r_v)
    X_r_te_raw = X_r_te_raw.values if hasattr(X_r_te_raw, 'values') else np.array(X_r_te_raw)

    # ── Signal model: RidgeClassifierCV ────────────────────────────────
    # RidgeClassifierCV is the standard, high-performing pairing for Rocket
    print("   📐 Ridge (signal)...")
    ridge = RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced')
    ridge.fit(X_r_m, y_m)

    # Decision function → calibrate to probability via Logistic
    df_m_ridge = ridge.decision_function(X_r_m).reshape(-1, 1)
    df_v_ridge = ridge.decision_function(X_r_v).reshape(-1, 1)
    df_te_ridge = ridge.decision_function(X_r_te_raw).reshape(-1, 1)

    cal_sig = LogisticRegression(C=1.0, max_iter=1000, random_state=RANDOM_STATE)
    cal_sig.fit(df_m_ridge, y_m)
    sig_v_prob  = cal_sig.predict_proba(df_v_ridge)[:, 1]
    sig_te_prob = cal_sig.predict_proba(df_te_ridge)[:, 1]

    # ── NMS model: Logistic Regression ─────────────────────────────────
    print("   📋 LR (NMS)...")
    nms_model = Pipeline([
        ('scaler', StandardScaler()),
        ('lr', LogisticRegression(C=1.0, class_weight='balanced',
                                   max_iter=1000, random_state=RANDOM_STATE))
    ])
    nms_model.fit(X_nms_m, y_m)
    nms_v_prob  = nms_model.predict_proba(X_nms_v)[:, 1]
    nms_te_prob = nms_model.predict_proba(X_nms_te)[:, 1]

    # ── Ensemble (equal weight) ─────────────────────────────────────────
    ens_v  = (sig_v_prob  + nms_v_prob)  / 2.0
    ens_te = (sig_te_prob + nms_te_prob) / 2.0

    # ── Threshold on VAL set (patient-level) ───────────────────────────
    val_pat_prob, val_pat_lab, _ = patient_aggregate(g_v, y_v, ens_v)

    fpr, tpr, ths = roc_curve(val_pat_lab, val_pat_prob)
    best_th = float(ths[np.argmax(tpr - fpr)])

    # ── Evaluate on TEST set (patient-level) ───────────────────────────
    te_pat_prob, te_pat_lab, _ = patient_aggregate(g_te, y_te, ens_te)

    y_true = np.array(te_pat_lab)
    y_prob = np.array(te_pat_prob)
    y_pred = (y_prob >= best_th).astype(int)

    ba = balanced_accuracy_score(y_true, y_pred)
    se = recall_score(y_true, y_pred, pos_label=1, zero_division=0)
    sp = recall_score(y_true, y_pred, pos_label=0, zero_division=0)
    f1 = f1_score(y_true, y_pred, zero_division=0)
    au = roc_auc_score(y_true, y_prob)

    for k, v in zip(['bal_acc','sens','spec','f1','auc'], [ba, se, sp, f1, au]):
        metrics[k].append(v)

    fd = {'fold': fold, 'bal_acc': ba, 'sens': se, 'spec': sp,
          'f1': f1, 'auc': au, 'threshold': best_th,
          'n_val_patients': len(val_pat_lab), 'n_te_patients': len(y_true)}
    fold_results.append(fd)
    save_checkpoint(fold, fd)

    print(f"   ✅ BalAcc={ba*100:.2f}% | Sens={se*100:.2f}% | Spec={sp*100:.2f}%"
          f" | AUC={au:.3f} | th={best_th:.3f}")
    gc.collect()

# ── Final Report ─────────────────────────────────────────────────────────
print(f"\n{'='*70}")
print("🏆 PLAN B — FINAL RESULTS")
print(f"{'='*70}")

our_ba   = np.mean(metrics['bal_acc']) * 100
std_ba   = np.std(metrics['bal_acc'])  * 100
paper_ba = 91.16

print(f"\nMetric        Mean ± Std")
print(f"-" * 35)
for k, label in [('bal_acc','Balanced Acc'), ('sens','Sensitivity'),
                  ('spec','Specificity'), ('f1','F1'), ('auc','AUC')]:
    m = np.mean(metrics[k])*100
    s = np.std(metrics[k])*100
    print(f"{label:<14}  {m:.2f}% ± {s:.2f}%")

print(f"\nOur:   {our_ba:.2f}% ± {std_ba:.2f}%")
print(f"Paper: {paper_ba:.2f}%")
print(f"Delta: {our_ba - paper_ba:+.2f}%")

t_stat, p_val = ttest_1samp([b * 100 for b in metrics['bal_acc']], paper_ba)
print(f"\nStats: t={t_stat:.3f}, p={'<0.001' if p_val < 0.001 else f'{p_val:.3f}'}")

results = {
    'plan': 'PLAN_B_RIDGE',
    'our_balanced_accuracy': our_ba,
    'paper_balanced_accuracy': paper_ba,
    'delta': our_ba - paper_ba,
    'all_metrics': metrics,
    'fold_results': fold_results,
    'statistical_test': {'t_stat': t_stat, 'p_value': p_val}
}

fp = save_final(results)
print(f"\n📁 {fp}")

print("\n" + "=" * 70)
if our_ba > paper_ba:
    print(f"🎉 PAPER BEATEN! +{our_ba - paper_ba:.2f}%")
elif our_ba > 89:
    print(f"✅ EXCELLENT! {our_ba:.2f}%")
elif our_ba > 87:
    print(f"🟡 GOOD. {our_ba:.2f}%")
else:
    print(f"⚠️  {our_ba:.2f}% — Consider Plan C")
print("=" * 70)

# ============================================================================
# PLAN C: MiniRocket + Ridge.predict() + NMS — NO calibration, NO threshold
# ============================================================================
# Root cause of Plan B failure:
#   1. Calibration LR fitted on Ridge's own training data → leakage (Fold1=100%)
#   2. Threshold via Youden-J on ~12 HC patients → unstable (Fold3 spec=40%)
# Fix: Ridge.predict() uses its own balanced decision boundary → no threshold needed
# ============================================================================

import os, sys, subprocess, warnings, gc, zipfile as zf, pickle, json
from glob import glob
from tqdm import tqdm
import numpy as np
import pandas as pd
from datetime import datetime

warnings.filterwarnings('ignore')

def install(pkg):
    try: __import__(pkg.split('[')[0].replace('-','_'))
    except:
        subprocess.check_call([sys.executable, "-m", "pip", "install", pkg, "-q",
                               "--break-system-packages"],
                              stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

print("📦 Installing...")
for pkg in ["numpy", "pandas", "scipy", "scikit-learn", "sktime"]:
    install(pkg)

from scipy.signal import detrend, resample
from scipy.stats import ttest_1samp
from sklearn.model_selection import StratifiedGroupKFold
from sklearn.linear_model import RidgeClassifierCV, LogisticRegression
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import Pipeline
from sklearn.metrics import (balanced_accuracy_score, recall_score,
                             f1_score, roc_auc_score, roc_curve)
from sktime.transformations.panel.rocket import MiniRocketMultivariate

RANDOM_STATE = 42
np.random.seed(RANDOM_STATE)

OUTPUT_DIR = './plan_c'
os.makedirs(OUTPUT_DIR, exist_ok=True)

def save_checkpoint(fold, data):
    with open(f'{OUTPUT_DIR}/ckpt_fold_{fold}.pkl', 'wb') as f:
        pickle.dump(data, f)

def save_final(results):
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    fp = f'{OUTPUT_DIR}/FINAL_{ts}.pkl'
    with open(fp, 'wb') as f: pickle.dump(results, f)
    return fp

print("=" * 70)
print("🟢 PLAN C: Ridge.predict() — no calibration, no threshold tuning")
print("=" * 70)

# ── Data Discovery ────────────────────────────────────────────────────────
try:
    if not os.path.exists('/content/drive'):
        from google.colab import drive; drive.mount('/content/drive')
except: pass

def find_file(name):
    for p in [f"/content/{name}", f"/content/drive/MyDrive/{name}",
              f"/content/drive/MyDrive/Parkinson/{name}", f"./{name}"]:
        if os.path.exists(p): return p
    if os.path.exists("/content/drive"):
        r = subprocess.getoutput(
            f"find /content/drive -name '{name}' -type f 2>/dev/null | head -1")
        if r.strip(): return r.strip()
    return None

def find_data():
    dirs = ["./pads_data_extracted", "/content/pads_data_extracted",
            "/content/pads_extracted",
            "/content/drive/MyDrive/Parkinson/pads_data_extracted"]
    for d in dirs:
        if os.path.exists(d) and len(glob(f"{d}/**/*.txt", recursive=True)) > 10:
            return d
    zp = find_file("pads-parkinsons-disease-smartwatch-dataset-1.0.0.zip")
    if zp:
        print("📦 Extracting...")
        with zf.ZipFile(zp, 'r') as z: z.extractall("./pads_data_extracted")
        return "./pads_data_extracted"
    raise FileNotFoundError("❌ PADS data not found!")

data_path = find_data()
print(f"✅ Data: {data_path}")

# ── Patient Labels ────────────────────────────────────────────────────────
patient_info = {}
meta_path = find_file("subjects.csv")

if meta_path and os.path.exists(meta_path):
    df_meta = pd.read_csv(meta_path)
    for _, r in df_meta[df_meta['label'].isin([0, 1])].iterrows():
        patient_info[str(r['id']).zfill(3)] = {
            'label': int(r['label']), 'age': r['age'], 'gender': str(r['gender'])
        }
else:
    for pf in glob(f"{data_path}/**/patient_*.json", recursive=True):
        try:
            d = json.load(open(pf))
            pid = str(d.get('id', ''))
            cond = d.get('condition', '').lower()
            lbl = (1 if "parkinson" in cond else
                   0 if any(k in cond for k in ["healthy", "control"]) else -1)
            if lbl >= 0 and pid:
                patient_info[pid] = {'label': lbl, 'age': d.get('age', 60),
                                     'gender': str(d.get('gender', 'unknown'))}
        except: pass

print(f"   {len(patient_info)} patients")

# ── NMS Questionnaire ─────────────────────────────────────────────────────
nms_data = {}
for qf in glob(f"{data_path}/**/questionnaire_response_*.json", recursive=True):
    try:
        q = json.load(open(qf))
        pid = str(q.get('subject_id', ''))
        if pid not in patient_info: continue
        ans = [0] * 30
        for it in q.get('item', []):
            try:
                i = int(it.get('link_id', '99')) - 1
                if 0 <= i < 30: ans[i] = 1 if it.get('answer') else 0
            except: pass
        nms_data[pid] = ans
    except: pass

print(f"   {len(nms_data)} NMS records")

# ── Signal Loading ────────────────────────────────────────────────────────
s_files = [f for f in glob(f"{data_path}/**/*.txt", recursive=True)
           if "LICENSE" not in f and "README" not in f]

X_sig, X_nms, y_list, groups = [], [], [], []

for fp in tqdm(s_files, desc="   Loading", ncols=70):
    try:
        pid = os.path.basename(fp).split('_')[0]
        if pid not in patient_info: continue
        raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
        if len(raw) < 100: continue
        if len(raw) > 50: raw = raw[50:, :]
        raw = detrend(raw, axis=0)
        if raw.shape[0] > raw.shape[1]: raw = raw.T
        raw = resample(raw, 400, axis=1)
        X_sig.append(raw)
        X_nms.append(nms_data.get(pid, [0] * 30))
        y_list.append(patient_info[pid]['label'])
        groups.append(pid)
    except: continue

max_ch = max(x.shape[0] for x in X_sig)
X_sig_arr = np.zeros((len(X_sig), max_ch, 400), dtype=np.float32)
for i, x in enumerate(X_sig): X_sig_arr[i, :x.shape[0], :] = x

X_nms_arr = np.array(X_nms, dtype=np.float32)
y = np.array(y_list)
groups = np.array(groups)
del X_sig; gc.collect()

print(f"   ✅ {len(y)} samples | PD={np.sum(y==1)} HC={np.sum(y==0)}")

# ── Patient-level majority vote ───────────────────────────────────────────
def patient_majority_vote(pids, labels, preds, probs=None):
    """Majority vote per patient. Returns (pat_preds, pat_labels, pat_probs)"""
    df = pd.DataFrame({'pid': pids, 'true': labels, 'pred': preds,
                       'prob': probs if probs is not None else preds.astype(float)})
    grp = df.groupby('pid')
    pat_pred  = (grp['pred'].mean() >= 0.5).astype(int).values   # majority vote
    pat_label = grp['true'].first().values
    pat_prob  = grp['prob'].mean().values                          # avg prob for AUC
    return pat_pred, pat_label, pat_prob

# ── Cross-validation ──────────────────────────────────────────────────────
cv = StratifiedGroupKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)
metrics = {'bal_acc': [], 'sens': [], 'spec': [], 'f1': [], 'auc': []}
fold_results = []

print(f"\n{'='*70}")
print("🔬 10-FOLD CV — PLAN C")
print(f"{'='*70}")

for fold, (tr_i, te_i) in enumerate(cv.split(X_sig_arr, y, groups), 1):

    if os.path.exists(f'{OUTPUT_DIR}/ckpt_fold_{fold}.pkl'):
        print(f"\n✅ FOLD {fold}/10 — CHECKPOINT")
        with open(f'{OUTPUT_DIR}/ckpt_fold_{fold}.pkl', 'rb') as f:
            ck = pickle.load(f)
        for k in metrics: metrics[k].append(ck[k])
        fold_results.append(ck)
        print(f"   BalAcc={ck['bal_acc']*100:.2f}%")
        continue

    print(f"\n📌 FOLD {fold}/10")

    X_sig_tr = X_sig_arr[tr_i];  X_sig_te = X_sig_arr[te_i]
    X_nms_tr = X_nms_arr[tr_i];  X_nms_te = X_nms_arr[te_i]
    y_tr     = y[tr_i];          y_te     = y[te_i]
    g_tr     = groups[tr_i];     g_te     = groups[te_i]

    # ── MiniRocket ───────────────────────────────────────────────────────
    print("   🚀 MiniRocket 8K...")
    rocket = MiniRocketMultivariate(num_kernels=8000, random_state=RANDOM_STATE, n_jobs=-1)
    X_r_tr = rocket.fit_transform(X_sig_tr)
    X_r_te = rocket.transform(X_sig_te)

    X_r_tr = X_r_tr.values if hasattr(X_r_tr, 'values') else np.array(X_r_tr)
    X_r_te = X_r_te.values if hasattr(X_r_te, 'values') else np.array(X_r_te)

    # ── Signal model: Ridge → .predict() directly (NO calibration) ──────
    print("   📐 Ridge (signal)...")
    ridge = RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced')
    ridge.fit(X_r_tr, y_tr)
    sig_pred_te = ridge.predict(X_r_te)                  # hard labels
    # Decision function (for AUC only — NOT used for classification)
    sig_df_te = ridge.decision_function(X_r_te)

    # ── NMS model: Logistic Regression → .predict() ──────────────────────
    print("   📋 LR (NMS)...")
    nms_pipe = Pipeline([
        ('sc', StandardScaler()),
        ('lr', LogisticRegression(C=1.0, class_weight='balanced',
                                   max_iter=1000, random_state=RANDOM_STATE))
    ])
    nms_pipe.fit(X_nms_tr, y_tr)
    nms_pred_te = nms_pipe.predict(X_nms_te)              # hard labels
    nms_prob_te = nms_pipe.predict_proba(X_nms_te)[:, 1]  # for AUC

    # ── Segment-level ensemble: majority vote of two models ──────────────
    # Each model votes; ties → signal model wins (higher quality)
    seg_vote = np.where(sig_pred_te == nms_pred_te,
                        sig_pred_te,           # agree → that label
                        sig_pred_te)           # disagree → trust signal

    # Soft prob for AUC (normalize decision function to [0,1])
    sig_prob_te = 1 / (1 + np.exp(-sig_df_te))  # sigmoid of decision function
    ens_prob_te = (sig_prob_te + nms_prob_te) / 2.0

    # ── Patient-level aggregation ─────────────────────────────────────────
    y_pred, y_true, y_prob = patient_majority_vote(g_te, y_te, seg_vote, ens_prob_te)

    ba = balanced_accuracy_score(y_true, y_pred)
    se = recall_score(y_true, y_pred, pos_label=1, zero_division=0)
    sp = recall_score(y_true, y_pred, pos_label=0, zero_division=0)
    f1 = f1_score(y_true, y_pred, zero_division=0)
    au = roc_auc_score(y_true, y_prob)

    for k, v in zip(['bal_acc','sens','spec','f1','auc'], [ba, se, sp, f1, au]):
        metrics[k].append(v)

    fd = {'fold': fold, 'bal_acc': ba, 'sens': se, 'spec': sp, 'f1': f1, 'auc': au,
          'n_test_patients': len(y_true)}
    fold_results.append(fd)
    save_checkpoint(fold, fd)

    print(f"   ✅ BalAcc={ba*100:.2f}% | Sens={se*100:.2f}% | Spec={sp*100:.2f}%"
          f" | AUC={au:.3f}")
    gc.collect()

# ── Final Report ──────────────────────────────────────────────────────────
print(f"\n{'='*70}")
print("🏆 PLAN C — FINAL RESULTS")
print(f"{'='*70}")

our_ba   = np.mean(metrics['bal_acc']) * 100
std_ba   = np.std(metrics['bal_acc'])  * 100
paper_ba = 91.16

print(f"\nMetric          Mean ± Std")
print(f"-" * 35)
for k, label in [('bal_acc','Balanced Acc'), ('sens','Sensitivity'),
                  ('spec','Specificity'), ('f1','F1'), ('auc','AUC')]:
    m = np.mean(metrics[k]) * 100
    s = np.std(metrics[k])  * 100
    print(f"{label:<16}  {m:.2f}% ± {s:.2f}%")

print(f"\nOur:   {our_ba:.2f}% ± {std_ba:.2f}%")
print(f"Paper: {paper_ba:.2f}%")
print(f"Delta: {our_ba - paper_ba:+.2f}%")

t_stat, p_val = ttest_1samp([b * 100 for b in metrics['bal_acc']], paper_ba)
sig_str = '<0.001' if p_val < 0.001 else f'{p_val:.3f}'
print(f"\nStats: t={t_stat:.3f}, p={sig_str}")

results = {
    'plan': 'PLAN_C_RIDGE_PREDICT',
    'our_balanced_accuracy': our_ba,
    'paper_balanced_accuracy': paper_ba,
    'delta': our_ba - paper_ba,
    'all_metrics': metrics,
    'fold_results': fold_results,
    'statistical_test': {'t_stat': t_stat, 'p_value': p_val}
}

fp = save_final(results)
print(f"\n📁 {fp}")

print("\n" + "=" * 70)
if our_ba > paper_ba:
    print(f"🎉 PAPER BEATEN! +{our_ba - paper_ba:.2f}%")
elif our_ba > 90:
    print(f"🟡 CLOSE. {our_ba:.2f}% — try Plan D (concat features)")
elif our_ba > 87:
    print(f"🟡 GOOD. {our_ba:.2f}%")
else:
    print(f"⚠️  {our_ba:.2f}% — check fold-level results for pattern")
print("=" * 70)

# ============================================================================
# PLAN D: Patient-level aggregation BEFORE classification
# ============================================================================
# Root cause of Plans A/B/C failure:
#   Segment-level clf → patient aggregation → too few test patients (~12 HC/fold)
#   1 wrong HC = -8% specificity → high variance (std ~9-10%)
#
# Fix: MiniRocket per segment → mean+std per patient → 355 patient vectors
#   Then Ridge on PATIENT level. No aggregation needed after prediction.
#   Fold başına ~35 test hasta, ~12 HC → hala az ama segment-level'den iyi
# ============================================================================

import os, sys, subprocess, warnings, gc, zipfile as zf, pickle, json
from glob import glob
from tqdm import tqdm
import numpy as np
import pandas as pd
from datetime import datetime

warnings.filterwarnings('ignore')

def install(pkg):
    try: __import__(pkg.split('[')[0].replace('-','_'))
    except:
        subprocess.check_call([sys.executable, "-m", "pip", "install", pkg, "-q",
                               "--break-system-packages"],
                              stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

print("📦 Installing...")
for pkg in ["numpy", "pandas", "scipy", "scikit-learn", "sktime"]:
    install(pkg)

from scipy.signal import detrend, resample
from scipy.stats import ttest_1samp
from sklearn.model_selection import StratifiedKFold
from sklearn.linear_model import RidgeClassifierCV, LogisticRegression
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import Pipeline
from sklearn.metrics import (balanced_accuracy_score, recall_score,
                             f1_score, roc_auc_score, roc_curve)
from sktime.transformations.panel.rocket import MiniRocketMultivariate

RANDOM_STATE = 42
np.random.seed(RANDOM_STATE)

OUTPUT_DIR = './plan_d'
os.makedirs(OUTPUT_DIR, exist_ok=True)

def save_checkpoint(fold, data):
    with open(f'{OUTPUT_DIR}/ckpt_fold_{fold}.pkl', 'wb') as f:
        pickle.dump(data, f)

def save_final(results):
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    fp = f'{OUTPUT_DIR}/FINAL_{ts}.pkl'
    with open(fp, 'wb') as f: pickle.dump(results, f)
    return fp

print("=" * 70)
print("🟣 PLAN D: Patient-level aggregation BEFORE classification")
print("   Architecture: Rocket(segments) → mean+std per patient → Ridge(patients)")
print("=" * 70)

# ── Data Discovery ────────────────────────────────────────────────────────
try:
    if not os.path.exists('/content/drive'):
        from google.colab import drive; drive.mount('/content/drive')
except: pass

def find_file(name):
    for p in [f"/content/{name}", f"/content/drive/MyDrive/{name}",
              f"/content/drive/MyDrive/Parkinson/{name}", f"./{name}"]:
        if os.path.exists(p): return p
