def find_data():
    dirs = ["./pads_data_extracted", "/content/pads_data_extracted",
            "/content/pads_extracted",
            "/content/drive/MyDrive/Parkinson/pads_data_extracted"]
    for d in dirs:
        if os.path.exists(d) and len(glob(f"{d}/**/*.txt", recursive=True)) > 10:
            return d
    zp = find_file("pads-parkinsons-disease-smartwatch-dataset-1.0.0.zip")
    if zp:
        print("📦 Extracting...")
        with zf.ZipFile(zp, 'r') as z: z.extractall("./pads_data_extracted")
        return "./pads_data_extracted"
    raise FileNotFoundError("❌ PADS data not found!")

data_path = find_data()
print(f"✅ Data: {data_path}")

# ── Patient Labels ────────────────────────────────────────────────────────
patient_info = {}
meta_path = find_file("subjects.csv")

if meta_path and os.path.exists(meta_path):
    df_meta = pd.read_csv(meta_path)
    for _, r in df_meta[df_meta['label'].isin([0, 1])].iterrows():
        patient_info[str(r['id']).zfill(3)] = {
            'label': int(r['label']), 'age': r['age'], 'gender': str(r['gender'])
        }
else:
    for pf in glob(f"{data_path}/**/patient_*.json", recursive=True):
        try:
            d = json.load(open(pf))
            pid = str(d.get('id', ''))
            cond = d.get('condition', '').lower()
            lbl = (1 if "parkinson" in cond else
                   0 if any(k in cond for k in ["healthy", "control"]) else -1)
            if lbl >= 0 and pid:
                patient_info[pid] = {'label': lbl, 'age': d.get('age', 60),
                                     'gender': str(d.get('gender', 'unknown'))}
        except: pass

print(f"   {len(patient_info)} patients loaded")

# ── NMS Questionnaire ─────────────────────────────────────────────────────
nms_data = {}
for qf in glob(f"{data_path}/**/questionnaire_response_*.json", recursive=True):
    try:
        q = json.load(open(qf))
        pid = str(q.get('subject_id', ''))
        if pid not in patient_info: continue
        ans = [0] * 30
        for it in q.get('item', []):
            try:
                i = int(it.get('link_id', '99')) - 1
                if 0 <= i < 30: ans[i] = 1 if it.get('answer') else 0
            except: pass
        nms_data[pid] = ans
    except: pass

print(f"   {len(nms_data)} NMS records")

# ── Load segments grouped by patient ─────────────────────────────────────
# patient_segments[pid] = list of (C, 400) arrays
s_files = [f for f in glob(f"{data_path}/**/*.txt", recursive=True)
           if "LICENSE" not in f and "README" not in f]

patient_segments = {}  # pid → list of arrays

for fp in tqdm(s_files, desc="   Loading", ncols=70):
    try:
        pid = os.path.basename(fp).split('_')[0]
        if pid not in patient_info: continue
        raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
        if len(raw) < 100: continue
        if len(raw) > 50: raw = raw[50:, :]
        raw = detrend(raw, axis=0)
        if raw.shape[0] > raw.shape[1]: raw = raw.T
        raw = resample(raw, 400, axis=1)
        if pid not in patient_segments:
            patient_segments[pid] = []
        patient_segments[pid].append(raw)
    except: continue

# Keep only patients that appear in patient_info
valid_pids = [p for p in patient_segments if p in patient_info]
print(f"   ✅ {len(valid_pids)} patients with segments")
print(f"   Segments per patient: min={min(len(patient_segments[p]) for p in valid_pids)} "
      f"max={max(len(patient_segments[p]) for p in valid_pids)} "
      f"median={int(np.median([len(patient_segments[p]) for p in valid_pids]))}")

# ── Build patient-level signal array (raw segments) ───────────────────────
# We'll run MiniRocket globally (fit on train patients' segments, transform all)
# But for patient-level CV, we need to be careful:
# → Rocket will be fit on training patients' segments only
# → Then transform all segments and aggregate per patient

max_ch = max(s.shape[0] for p in valid_pids for s in patient_segments[p])

# patient-level labels and NMS
pat_labels = np.array([patient_info[p]['label'] for p in valid_pids])
pat_nms    = np.array([nms_data.get(p, [0]*30) for p in valid_pids], dtype=np.float32)
valid_pids_arr = np.array(valid_pids)

print(f"\n   Patient-level: PD={np.sum(pat_labels==1)} HC={np.sum(pat_labels==0)}")

# ── Cross-validation (patient-level, NO groups needed) ───────────────────
# StratifiedKFold since each row = 1 patient (no leakage risk)
cv = StratifiedKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)
metrics = {'bal_acc': [], 'sens': [], 'spec': [], 'f1': [], 'auc': []}
fold_results = []

print(f"\n{'='*70}")
print("🔬 10-FOLD CV — PLAN D  (patient-level)")
print(f"{'='*70}")

for fold, (tr_idx, te_idx) in enumerate(cv.split(valid_pids_arr, pat_labels), 1):

    ck_path = f'{OUTPUT_DIR}/ckpt_fold_{fold}.pkl'
    if os.path.exists(ck_path):
        print(f"\n✅ FOLD {fold}/10 — CHECKPOINT")
        with open(ck_path, 'rb') as f: ck = pickle.load(f)
        for k in metrics: metrics[k].append(ck[k])
        fold_results.append(ck)
        print(f"   BalAcc={ck['bal_acc']*100:.2f}%")
        continue

    print(f"\n📌 FOLD {fold}/10")

    tr_pids = valid_pids_arr[tr_idx]
    te_pids = valid_pids_arr[te_idx]
    y_tr    = pat_labels[tr_idx]
    y_te    = pat_labels[te_idx]
    nms_tr  = pat_nms[tr_idx]
    nms_te  = pat_nms[te_idx]

    # ── Build segment arrays for Rocket fit ──────────────────────────────
    # Flatten training patients' segments
    tr_segs, tr_seg_labels = [], []
    for pid, lbl in zip(tr_pids, y_tr):
        for seg in patient_segments[pid]:
            padded = np.zeros((max_ch, 400), dtype=np.float32)
            padded[:seg.shape[0], :] = seg
            tr_segs.append(padded)
            tr_seg_labels.append(lbl)

    X_tr_segs = np.array(tr_segs, dtype=np.float32)
    del tr_segs; gc.collect()

    # ── Fit MiniRocket on training segments ──────────────────────────────
    print(f"   🚀 MiniRocket 8K ({len(X_tr_segs)} train segments)...")
    rocket = MiniRocketMultivariate(num_kernels=8000, random_state=RANDOM_STATE, n_jobs=-1)
    X_rocket_tr_segs = rocket.fit_transform(X_tr_segs)
    X_rocket_tr_segs = (X_rocket_tr_segs.values
                        if hasattr(X_rocket_tr_segs, 'values')
                        else np.array(X_rocket_tr_segs))
    del X_tr_segs; gc.collect()

    # ── Aggregate: mean+std of rocket features → patient vector ──────────
    print("   📊 Aggregating per patient...")
    seg_counts_tr = [len(patient_segments[p]) for p in tr_pids]
    seg_counts_te = [len(patient_segments[p]) for p in te_pids]

    # Training patients
    X_pat_tr = np.zeros((len(tr_pids), X_rocket_tr_segs.shape[1] * 2), dtype=np.float32)
    idx = 0
    for i, cnt in enumerate(seg_counts_tr):
        segs = X_rocket_tr_segs[idx:idx+cnt]
        X_pat_tr[i, :X_rocket_tr_segs.shape[1]] = segs.mean(axis=0)
        X_pat_tr[i, X_rocket_tr_segs.shape[1]:] = segs.std(axis=0)
        idx += cnt

    del X_rocket_tr_segs; gc.collect()

    # Test patients: transform their segments
    te_segs = []
    for pid in te_pids:
        for seg in patient_segments[pid]:
            padded = np.zeros((max_ch, 400), dtype=np.float32)
            padded[:seg.shape[0], :] = seg
            te_segs.append(padded)

    X_te_segs_arr = np.array(te_segs, dtype=np.float32)
    del te_segs; gc.collect()

    X_rocket_te_segs = rocket.transform(X_te_segs_arr)
    X_rocket_te_segs = (X_rocket_te_segs.values
                        if hasattr(X_rocket_te_segs, 'values')
                        else np.array(X_rocket_te_segs))
    del X_te_segs_arr; gc.collect()

    feat_dim = X_rocket_te_segs.shape[1]
    X_pat_te = np.zeros((len(te_pids), feat_dim * 2), dtype=np.float32)
    idx = 0
    for i, cnt in enumerate(seg_counts_te):
        segs = X_rocket_te_segs[idx:idx+cnt]
        X_pat_te[i, :feat_dim] = segs.mean(axis=0)
        X_pat_te[i, feat_dim:] = segs.std(axis=0)
        idx += cnt

    del X_rocket_te_segs; gc.collect()

    # ── Signal model: Ridge on patient vectors ────────────────────────────
    print("   📐 Ridge (patient-level signal)...")
    ridge = RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced')
    ridge.fit(X_pat_tr, y_tr)
    sig_pred = ridge.predict(X_pat_te)
    sig_df   = ridge.decision_function(X_pat_te)
    sig_prob = 1 / (1 + np.exp(-sig_df))   # sigmoid for AUC only

    # ── NMS model: Logistic Regression ───────────────────────────────────
    print("   📋 LR (NMS)...")
    nms_pipe = Pipeline([
        ('sc', StandardScaler()),
        ('lr', LogisticRegression(C=1.0, class_weight='balanced',
                                   max_iter=1000, random_state=RANDOM_STATE))
    ])
    nms_pipe.fit(nms_tr, y_tr)
    nms_pred = nms_pipe.predict(nms_te)
    nms_prob = nms_pipe.predict_proba(nms_te)[:, 1]

    # ── Ensemble: signal wins ties ────────────────────────────────────────
    y_pred = np.where(sig_pred == nms_pred, sig_pred, sig_pred)
    y_prob = (sig_prob + nms_prob) / 2.0
    y_true = y_te

    ba = balanced_accuracy_score(y_true, y_pred)
    se = recall_score(y_true, y_pred, pos_label=1, zero_division=0)
    sp = recall_score(y_true, y_pred, pos_label=0, zero_division=0)
    f1 = f1_score(y_true, y_pred, zero_division=0)
    au = roc_auc_score(y_true, y_prob)

    for k, v in zip(['bal_acc','sens','spec','f1','auc'], [ba, se, sp, f1, au]):
        metrics[k].append(v)

    fd = {'fold': fold, 'bal_acc': ba, 'sens': se, 'spec': sp, 'f1': f1,
          'auc': au, 'n_test': len(y_true)}
    fold_results.append(fd)
    save_checkpoint(fold, fd)

    print(f"   ✅ BalAcc={ba*100:.2f}% | Sens={se*100:.2f}% | Spec={sp*100:.2f}%"
          f" | AUC={au:.3f}")
    gc.collect()

# ── Final Report ──────────────────────────────────────────────────────────
print(f"\n{'='*70}")
print("🏆 PLAN D — FINAL RESULTS")
print(f"{'='*70}")

our_ba   = np.mean(metrics['bal_acc']) * 100
std_ba   = np.std(metrics['bal_acc'])  * 100
paper_ba = 91.16

print(f"\nMetric          Mean ± Std")
print("-" * 35)
for k, label in [('bal_acc','Balanced Acc'), ('sens','Sensitivity'),
                  ('spec','Specificity'), ('f1','F1'), ('auc','AUC')]:
    m = np.mean(metrics[k]) * 100
    s = np.std(metrics[k]) * 100
    print(f"{label:<16}  {m:.2f}% ± {s:.2f}%")

print(f"\nOur:   {our_ba:.2f}% ± {std_ba:.2f}%")
print(f"Paper: {paper_ba:.2f}%")
print(f"Delta: {our_ba - paper_ba:+.2f}%")

t_stat, p_val = ttest_1samp([b * 100 for b in metrics['bal_acc']], paper_ba)
print(f"\nStats: t={t_stat:.3f}, p={'<0.001' if p_val < 0.001 else f'{p_val:.3f}'}")

results = {
    'plan': 'PLAN_D_PATIENT_LEVEL',
    'our_balanced_accuracy': our_ba,
    'paper_balanced_accuracy': paper_ba,
    'delta': our_ba - paper_ba,
    'all_metrics': metrics,
    'fold_results': fold_results,
    'statistical_test': {'t_stat': t_stat, 'p_value': p_val}
}

fp = save_final(results)
print(f"\n📁 {fp}")

print("\n" + "=" * 70)
if our_ba > paper_ba:
    print(f"🎉 PAPER BEATEN! +{our_ba - paper_ba:.2f}%")
elif our_ba > 90:
    print(f"🟡 CLOSE! {our_ba:.2f}%")
elif our_ba > 87:
    print(f"🟡 GOOD. {our_ba:.2f}%")
else:
    print(f"⚠️  {our_ba:.2f}% — std düştü mü? Fold sonuçlarına bak.")
print("=" * 70)

# ============================================================================
# PLAN E: Plan D + OOF threshold tuning on training patients
# ============================================================================
# Diagnosis: AUC=96.72% (model ranks perfectly) but BalAcc=81% → wrong threshold
# Fix: cross_val_predict on training patients → OOF decision scores →
#      Youden-J threshold → apply to test
# NO leakage: test patients never seen during threshold search
# ============================================================================

import os, sys, subprocess, warnings, gc, zipfile as zf, pickle, json
from glob import glob
from tqdm import tqdm
import numpy as np
import pandas as pd
from datetime import datetime

warnings.filterwarnings('ignore')

def install(pkg):
    try: __import__(pkg.split('[')[0].replace('-','_'))
    except:
        subprocess.check_call([sys.executable, "-m", "pip", "install", pkg, "-q",
                               "--break-system-packages"],
                              stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

print("📦 Installing...")
for pkg in ["numpy", "pandas", "scipy", "scikit-learn", "sktime"]:
    install(pkg)

from scipy.signal import detrend, resample
from scipy.stats import ttest_1samp
from sklearn.model_selection import StratifiedKFold, cross_val_predict
from sklearn.linear_model import RidgeClassifierCV, LogisticRegression
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import Pipeline
from sklearn.metrics import (balanced_accuracy_score, recall_score,
                             f1_score, roc_auc_score, roc_curve)
from sktime.transformations.panel.rocket import MiniRocketMultivariate

RANDOM_STATE = 42
np.random.seed(RANDOM_STATE)

OUTPUT_DIR = './plan_e'
os.makedirs(OUTPUT_DIR, exist_ok=True)

def save_checkpoint(fold, data):
    with open(f'{OUTPUT_DIR}/ckpt_fold_{fold}.pkl', 'wb') as f:
        pickle.dump(data, f)

def save_final(results):
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    fp = f'{OUTPUT_DIR}/FINAL_{ts}.pkl'
    with open(fp, 'wb') as f: pickle.dump(results, f)
    return fp

def youden_threshold(y_true, scores):
    """Optimal threshold via Youden-J on given OOF scores."""
    fpr, tpr, ths = roc_curve(y_true, scores)
    j = tpr - fpr
    best = ths[np.argmax(j)]
    return float(best)

print("=" * 70)
print("🟠 PLAN E: Patient-level + OOF threshold (Youden-J, training only)")
print("=" * 70)

# ── Data Discovery ────────────────────────────────────────────────────────
