print("📦 Installing...")
for pkg in ["numpy", "pandas", "scipy", "scikit-learn", "sktime"]:
    install(pkg)

from scipy.signal import detrend, resample
from scipy.stats import ttest_1samp
from sklearn.model_selection import StratifiedKFold, cross_val_predict, GridSearchCV
from sklearn.svm import LinearSVC
from sklearn.linear_model import LogisticRegression, RidgeClassifierCV
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import Pipeline
from sklearn.calibration import CalibratedClassifierCV
from sklearn.metrics import (balanced_accuracy_score, recall_score,
                             f1_score, roc_auc_score, roc_curve)
from sktime.transformations.panel.rocket import MiniRocketMultivariate

RANDOM_STATE = 42
np.random.seed(RANDOM_STATE)

OUTPUT_DIR = './plan_g'
os.makedirs(OUTPUT_DIR, exist_ok=True)

def save_checkpoint(fold, data):
    with open(f'{OUTPUT_DIR}/ckpt_fold_{fold}.pkl', 'wb') as f:
        pickle.dump(data, f)

def save_final(results):
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    fp = f'{OUTPUT_DIR}/FINAL_{ts}.pkl'
    with open(fp, 'wb') as f: pickle.dump(results, f)
    return fp

def youden_threshold(y_true, scores):
    fpr, tpr, ths = roc_curve(y_true, scores)
    return float(ths[np.argmax(tpr - fpr)])

print("=" * 70)
print("🟤 PLAN G: MiniRocket + LinearSVC + OOF Threshold")
print("=" * 70)

# ── Data Discovery ────────────────────────────────────────────────────────
try:
    if not os.path.exists('/content/drive'):
        from google.colab import drive; drive.mount('/content/drive')
except: pass

def find_file(name):
    for p in [f"/content/{name}", f"/content/drive/MyDrive/{name}",
              f"/content/drive/MyDrive/Parkinson/{name}", f"./{name}"]:
        if os.path.exists(p): return p
    if os.path.exists("/content/drive"):
        r = subprocess.getoutput(
            f"find /content/drive -name '{name}' -type f 2>/dev/null | head -1")
        if r.strip(): return r.strip()
    return None

def find_data():
    dirs = ["./pads_data_extracted", "/content/pads_data_extracted",
            "/content/pads_extracted",
            "/content/drive/MyDrive/Parkinson/pads_data_extracted"]
    for d in dirs:
        if os.path.exists(d) and len(glob(f"{d}/**/*.txt", recursive=True)) > 10:
            return d
    zp = find_file("pads-parkinsons-disease-smartwatch-dataset-1.0.0.zip")
    if zp:
        print("📦 Extracting...")
        with zf.ZipFile(zp, 'r') as z: z.extractall("./pads_data_extracted")
        return "./pads_data_extracted"
    raise FileNotFoundError("❌ PADS data not found!")

data_path = find_data()
print(f"✅ Data: {data_path}")

# ── Patient Labels ────────────────────────────────────────────────────────
patient_info = {}
meta_path = find_file("subjects.csv")

if meta_path and os.path.exists(meta_path):
    df_meta = pd.read_csv(meta_path)
    for _, r in df_meta[df_meta['label'].isin([0, 1])].iterrows():
        patient_info[str(r['id']).zfill(3)] = {
            'label': int(r['label']), 'age': r['age'], 'gender': str(r['gender'])
        }
else:
    for pf in glob(f"{data_path}/**/patient_*.json", recursive=True):
        try:
            d = json.load(open(pf))
            pid = str(d.get('id', ''))
            cond = d.get('condition', '').lower()
            lbl = (1 if "parkinson" in cond else
                   0 if any(k in cond for k in ["healthy", "control"]) else -1)
            if lbl >= 0 and pid:
                patient_info[pid] = {'label': lbl, 'age': d.get('age', 60),
                                     'gender': str(d.get('gender', 'unknown'))}
        except: pass

print(f"   {len(patient_info)} patients")

# ── NMS ───────────────────────────────────────────────────────────────────
nms_data = {}
for qf in glob(f"{data_path}/**/questionnaire_response_*.json", recursive=True):
    try:
        q = json.load(open(qf))
        pid = str(q.get('subject_id', ''))
        if pid not in patient_info: continue
        ans = [0] * 30
        for it in q.get('item', []):
            try:
                i = int(it.get('link_id', '99')) - 1
                if 0 <= i < 30: ans[i] = 1 if it.get('answer') else 0
            except: pass
        nms_data[pid] = ans
    except: pass

# ── Load segments ─────────────────────────────────────────────────────────
s_files = [f for f in glob(f"{data_path}/**/*.txt", recursive=True)
           if "LICENSE" not in f and "README" not in f]

patient_segments = {}
for fp in tqdm(s_files, desc="   Loading", ncols=70):
    try:
        pid = os.path.basename(fp).split('_')[0]
        if pid not in patient_info: continue
        raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
        if len(raw) < 100: continue
        if len(raw) > 50: raw = raw[50:, :]
        raw = detrend(raw, axis=0)
        if raw.shape[0] > raw.shape[1]: raw = raw.T
        raw = resample(raw, 400, axis=1)
        if pid not in patient_segments: patient_segments[pid] = []
        patient_segments[pid].append(raw)
    except: continue

valid_pids = np.array([p for p in patient_segments if p in patient_info])
pat_labels = np.array([patient_info[p]['label'] for p in valid_pids])
pat_nms    = np.array([nms_data.get(p, [0]*30) for p in valid_pids], dtype=np.float32)
max_ch     = max(s.shape[0] for p in valid_pids for s in patient_segments[p])

print(f"   ✅ {len(valid_pids)} patients | PD={np.sum(pat_labels==1)} HC={np.sum(pat_labels==0)}")

def segments_array(pids):
    segs, counts = [], []
    for pid in pids:
        cnt = len(patient_segments[pid])
        for seg in patient_segments[pid]:
            padded = np.zeros((max_ch, 400), dtype=np.float32)
            padded[:seg.shape[0], :] = seg
            segs.append(padded)
        counts.append(cnt)
    return np.array(segs, dtype=np.float32), counts

def build_patient_features(rocket_segs, seg_counts):
    feat_dim = rocket_segs.shape[1]
    X = np.zeros((len(seg_counts), feat_dim * 2), dtype=np.float32)
    idx = 0
    for i, cnt in enumerate(seg_counts):
        segs = rocket_segs[idx:idx+cnt]
        X[i, :feat_dim] = segs.mean(axis=0)
        X[i, feat_dim:] = segs.std(axis=0)
        idx += cnt
    return X

# ── Outer CV ──────────────────────────────────────────────────────────────
outer_cv = StratifiedKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)
metrics  = {'bal_acc': [], 'sens': [], 'spec': [], 'f1': [], 'auc': []}
fold_results = []

# C values to search in inner CV
C_GRID = [0.0001, 0.001, 0.01, 0.1, 1.0]

print(f"\n{'='*70}")
print("🔬 10-FOLD CV — PLAN G  (LinearSVC, C grid search in inner CV)")
print(f"{'='*70}")

for fold, (tr_idx, te_idx) in enumerate(outer_cv.split(valid_pids, pat_labels), 1):

    ck_path = f'{OUTPUT_DIR}/ckpt_fold_{fold}.pkl'
    if os.path.exists(ck_path):
        print(f"\n✅ FOLD {fold}/10 — CHECKPOINT")
        with open(ck_path, 'rb') as f: ck = pickle.load(f)
        for k in metrics: metrics[k].append(ck[k])
        fold_results.append(ck)
        print(f"   BalAcc={ck['bal_acc']*100:.2f}% | C={ck['best_C']:.4f} | th={ck['th_ens']:.3f}")
        continue

    print(f"\n📌 FOLD {fold}/10")

    tr_pids = valid_pids[tr_idx];  te_pids = valid_pids[te_idx]
    y_tr    = pat_labels[tr_idx];  y_te    = pat_labels[te_idx]
    nms_tr  = pat_nms[tr_idx];    nms_te  = pat_nms[te_idx]

    # ── Rocket ────────────────────────────────────────────────────────────
    print(f"   🚀 MiniRocket 8K...")
    tr_segs_arr, tr_counts = segments_array(tr_pids)
    te_segs_arr, te_counts = segments_array(te_pids)

    rocket = MiniRocketMultivariate(num_kernels=8000, random_state=RANDOM_STATE, n_jobs=-1)
    X_r_tr = rocket.fit_transform(tr_segs_arr)
    X_r_tr = X_r_tr.values if hasattr(X_r_tr, 'values') else np.array(X_r_tr)
    del tr_segs_arr; gc.collect()

    X_r_te = rocket.transform(te_segs_arr)
    X_r_te = X_r_te.values if hasattr(X_r_te, 'values') else np.array(X_r_te)
    del te_segs_arr; gc.collect()

    print("   📊 Patient aggregation...")
    X_pat_tr = build_patient_features(X_r_tr, tr_counts)
    X_pat_te = build_patient_features(X_r_te, te_counts)
    del X_r_tr, X_r_te; gc.collect()

    # ── StandardScaler (required for SVM) ────────────────────────────────
    scaler = StandardScaler()
    X_pat_tr_sc = scaler.fit_transform(X_pat_tr)
    X_pat_te_sc = scaler.transform(X_pat_te)

    # ── LinearSVC: C selection via inner CV (balanced accuracy) ──────────
    print("   ⚡ LinearSVC C search (inner 5-fold)...")
    inner_cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=RANDOM_STATE)

    best_C, best_inner_ba = C_GRID[0], -1
    for C in C_GRID:
        svc = LinearSVC(C=C, class_weight='balanced', max_iter=5000,
                        random_state=RANDOM_STATE)
        oof_df = cross_val_predict(svc, X_pat_tr_sc, y_tr,
                                   cv=inner_cv, method='decision_function')
        th = youden_threshold(y_tr, oof_df)
        oof_pred = (oof_df >= th).astype(int)
        ba = balanced_accuracy_score(y_tr, oof_pred)
        if ba > best_inner_ba:
            best_inner_ba = ba
            best_C = C

    print(f"   Best C={best_C} (inner BalAcc={best_inner_ba*100:.2f}%)")

    # ── Fit final SVC with best C ─────────────────────────────────────────
    svc_final = LinearSVC(C=best_C, class_weight='balanced', max_iter=5000,
                          random_state=RANDOM_STATE)
    svc_final.fit(X_pat_tr_sc, y_tr)

    # OOF decision scores with best C (for threshold + AUC)
    oof_sig = cross_val_predict(
        LinearSVC(C=best_C, class_weight='balanced', max_iter=5000,
                  random_state=RANDOM_STATE),
        X_pat_tr_sc, y_tr, cv=inner_cv, method='decision_function'
    )

    sig_df_te   = svc_final.decision_function(X_pat_te_sc)
    sig_prob_te = 1 / (1 + np.exp(-sig_df_te))   # sigmoid for ensemble

    # ── NMS: Logistic Regression + OOF ───────────────────────────────────
    print("   📋 LR (NMS)...")
    nms_pipe = Pipeline([
        ('sc', StandardScaler()),
        ('lr', LogisticRegression(C=1.0, class_weight='balanced',
                                   max_iter=1000, random_state=RANDOM_STATE))
    ])
    nms_pipe.fit(nms_tr, y_tr)

    oof_nms = cross_val_predict(
        Pipeline([('sc', StandardScaler()),
                  ('lr', LogisticRegression(C=1.0, class_weight='balanced',
                                             max_iter=1000, random_state=RANDOM_STATE))]),
        nms_tr, y_tr, cv=inner_cv, method='predict_proba'
    )[:, 1]

    nms_prob_te = nms_pipe.predict_proba(nms_te)[:, 1]

    # ── Ensemble OOF threshold ────────────────────────────────────────────
    oof_sig_prob = 1 / (1 + np.exp(-oof_sig))
    oof_ens      = (oof_sig_prob + oof_nms) / 2.0
    th_ens       = youden_threshold(y_tr, oof_ens)

    ens_prob_te = (sig_prob_te + nms_prob_te) / 2.0
    y_pred      = (ens_prob_te >= th_ens).astype(int)
    y_true      = y_te
    y_prob      = ens_prob_te

    ba = balanced_accuracy_score(y_true, y_pred)
    se = recall_score(y_true, y_pred, pos_label=1, zero_division=0)
    sp = recall_score(y_true, y_pred, pos_label=0, zero_division=0)
    f1 = f1_score(y_true, y_pred, zero_division=0)
    au = roc_auc_score(y_true, y_prob)

    for k, v in zip(['bal_acc','sens','spec','f1','auc'], [ba, se, sp, f1, au]):
        metrics[k].append(v)

    fd = {'fold': fold, 'bal_acc': ba, 'sens': se, 'spec': sp, 'f1': f1,
          'auc': au, 'th_ens': th_ens, 'best_C': best_C, 'n_test': len(y_true)}
    fold_results.append(fd)
    save_checkpoint(fold, fd)

    print(f"   ✅ BalAcc={ba*100:.2f}% | Sens={se*100:.2f}% | Spec={sp*100:.2f}%"
          f" | AUC={au:.3f} | th={th_ens:.3f}")
    gc.collect()

# ── Final Report ──────────────────────────────────────────────────────────
print(f"\n{'='*70}")
print("🏆 PLAN G — FINAL RESULTS")
print(f"{'='*70}")

our_ba   = np.mean(metrics['bal_acc']) * 100
std_ba   = np.std(metrics['bal_acc'])  * 100
paper_ba = 91.16

print(f"\nMetric          Mean ± Std")
print("-" * 35)
for k, label in [('bal_acc','Balanced Acc'), ('sens','Sensitivity'),
                  ('spec','Specificity'), ('f1','F1'), ('auc','AUC')]:
    m = np.mean(metrics[k]) * 100
    s = np.std(metrics[k]) * 100
    print(f"{label:<16}  {m:.2f}% ± {s:.2f}%")

print(f"\nOur:   {our_ba:.2f}% ± {std_ba:.2f}%")
print(f"Paper: {paper_ba:.2f}%")
print(f"Delta: {our_ba - paper_ba:+.2f}%")

t_stat, p_val = ttest_1samp([b * 100 for b in metrics['bal_acc']], paper_ba)
print(f"\nStats: t={t_stat:.3f}, p={'<0.001' if p_val < 0.001 else f'{p_val:.3f}'}")

print(f"\nFold details:")
print(f"{'Fold':>4} {'BalAcc':>8} {'Sens':>8} {'Spec':>8} {'C':>8} {'th':>8}")
for fd in fold_results:
    print(f"{fd['fold']:>4} {fd['bal_acc']*100:>7.2f}% "
          f"{fd['sens']*100:>7.2f}% {fd['spec']*100:>7.2f}% "
          f"{fd['best_C']:>8.4f} {fd['th_ens']:>8.3f}")

results = {
    'plan': 'PLAN_G_LINEARSVC',
    'our_balanced_accuracy': our_ba,
    'paper_balanced_accuracy': paper_ba,
    'delta': our_ba - paper_ba,
    'all_metrics': metrics,
    'fold_results': fold_results,
    'statistical_test': {'t_stat': t_stat, 'p_value': p_val}
}
fp = save_final(results)
print(f"\n📁 {fp}")

print("\n" + "=" * 70)
if our_ba > paper_ba:
    print(f"🎉 PAPER BEATEN! +{our_ba - paper_ba:.2f}%")
elif our_ba > 90:
    print(f"🟡 CLOSE! {our_ba:.2f}%")
elif our_ba >= 89:
    print(f"🟡 Similar to Plan E. Consider LOSO-CV or larger kernel.")
else:
    print(f"⚠️  {our_ba:.2f}%")
print("=" * 70)

# ============================================================================
# PLAN H: LOSO-CV (Leave-One-Subject-Out) + Patient-level Rocket + Ridge
# ============================================================================
# Problem with Plans E/F/G: 10-fold CV, ~12 HC per fold → noise ceiling
# Fold 1 & 6 always bad → those patients are atypical, not model failure
#
# LOSO: 355 iterations, 1 test patient each → stable estimate, no fold luck
# Standard for clinical ML with small N (Varghese et al. likely used this)
#
# Architecture (same as Plan E, best performer):
#   MiniRocket(8K) segments → mean+std per patient → Ridge + OOF threshold
#   Threshold: inner 5-fold CV on 354 training patients → Youden-J
#
# LOSO NOTE: Rocket re-fit per fold is 355x expensive.
# Optimization: fit Rocket ONCE on ALL data (labels not used → no leakage)
#   MiniRocket is a random feature extractor, no label dependency.
#   Then per fold: Ridge fit on 354 patients, predict 1 test patient.
# ============================================================================

