# ============================================================================
# ABLATION + BASELINE COMPARISON PIPELINE
# ============================================================================
# Built on Plan E (best result: 89.10% ± 4.48%)
# Architecture: Patient-level MiniRocket (8K) + OOF Youden-J threshold
#
# ABLATION STUDY (4 conditions):
#   A1: Full system (Signal + NMS ensemble)       ← Plan E replicated
#   A2: Signal only (no NMS)
#   A3: NMS only (no MiniRocket)
#   A4: No aggregation std (mean only, no std)
#
# BASELINE COMPARISON (5 classifiers, same features as A1):
#   B1: Logistic Regression
#   B2: Random Forest
#   B3: XGBoost
#   B4: SVM (RBF kernel)
#   B5: Ridge (our method, for reference)
#
# All: 10-fold stratified CV, patient-level, OOF threshold
# Statistics: Wilcoxon signed-rank test vs our method (B5/A1)
# ============================================================================

import os, sys, subprocess, warnings, gc, zipfile as zf, pickle, json
from glob import glob
from tqdm import tqdm
import numpy as np
import pandas as pd
from datetime import datetime

warnings.filterwarnings('ignore')

def install(pkg):
    try: __import__(pkg.split('[')[0].replace('-','_'))
    except:
        subprocess.check_call([sys.executable,"-m","pip","install",pkg,"-q",
                               "--break-system-packages"],
                              stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)

print("📦 Installing...")
for pkg in ["numpy","pandas","scipy","scikit-learn","sktime","xgboost"]:
    install(pkg)

from scipy.signal import detrend, resample
from scipy.stats import wilcoxon, ttest_rel
from sklearn.model_selection import StratifiedKFold, cross_val_predict
from sklearn.linear_model import RidgeClassifierCV, LogisticRegression
from sklearn.ensemble import RandomForestClassifier
from sklearn.svm import SVC
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import Pipeline
from sklearn.metrics import (balanced_accuracy_score, recall_score,
                             f1_score, roc_auc_score, roc_curve)
from xgboost import XGBClassifier
from sktime.transformations.panel.rocket import MiniRocketMultivariate

RANDOM_STATE = 42
np.random.seed(RANDOM_STATE)

OUTPUT_DIR = './ablation_baseline'
os.makedirs(OUTPUT_DIR, exist_ok=True)

def youden_threshold(y_true, scores):
    fpr, tpr, ths = roc_curve(y_true, scores)
    return float(ths[np.argmax(tpr - fpr)])

def save_result(name, data):
    with open(f'{OUTPUT_DIR}/{name}.pkl','wb') as f: pickle.dump(data,f)

print("="*70)
print("🔬 ABLATION + BASELINE PIPELINE")
print("="*70)

# ── Data ──────────────────────────────────────────────────────────────────
try:
    if not os.path.exists('/content/drive'):
        from google.colab import drive; drive.mount('/content/drive')
except: pass

def find_file(name):
    for p in [f"/content/{name}",f"/content/drive/MyDrive/{name}",
              f"/content/drive/MyDrive/Parkinson/{name}",f"./{name}"]:
        if os.path.exists(p): return p
    if os.path.exists("/content/drive"):
        r = subprocess.getoutput(
            f"find /content/drive -name '{name}' -type f 2>/dev/null | head -1")
        if r.strip(): return r.strip()
    return None

def find_data():
    dirs = ["./pads_data_extracted","/content/pads_data_extracted",
            "/content/pads_extracted",
            "/content/drive/MyDrive/Parkinson/pads_data_extracted"]
    for d in dirs:
        if os.path.exists(d) and len(glob(f"{d}/**/*.txt",recursive=True))>10:
            return d
    zp = find_file("pads-parkinsons-disease-smartwatch-dataset-1.0.0.zip")
    if zp:
        with zf.ZipFile(zp,'r') as z: z.extractall("./pads_data_extracted")
        return "./pads_data_extracted"
    raise FileNotFoundError("❌ PADS data not found!")

data_path = find_data()

patient_info = {}
meta_path = find_file("subjects.csv")
if meta_path and os.path.exists(meta_path):
    df_meta = pd.read_csv(meta_path)
    for _, r in df_meta[df_meta['label'].isin([0,1])].iterrows():
        patient_info[str(r['id']).zfill(3)] = {
            'label':int(r['label']),'age':r['age'],'gender':str(r['gender'])}
else:
    for pf in glob(f"{data_path}/**/patient_*.json",recursive=True):
        try:
            d = json.load(open(pf))
            pid = str(d.get('id',''))
            cond = d.get('condition','').lower()
            lbl = (1 if "parkinson" in cond else
                   0 if any(k in cond for k in ["healthy","control"]) else -1)
            if lbl>=0 and pid:
                patient_info[pid]={'label':lbl,'age':d.get('age',60),
                                   'gender':str(d.get('gender','unknown'))}
        except: pass

nms_data = {}
for qf in glob(f"{data_path}/**/questionnaire_response_*.json",recursive=True):
    try:
        q = json.load(open(qf))
        pid = str(q.get('subject_id',''))
        if pid not in patient_info: continue
        ans = [0]*30
        for it in q.get('item',[]):
            try:
                i = int(it.get('link_id','99'))-1
                if 0<=i<30: ans[i]=1 if it.get('answer') else 0
            except: pass
        nms_data[pid] = ans
    except: pass

s_files = [f for f in glob(f"{data_path}/**/*.txt",recursive=True)
           if "LICENSE" not in f and "README" not in f]

patient_segments = {}
for fp in tqdm(s_files, desc="   Loading", ncols=70):
    try:
        pid = os.path.basename(fp).split('_')[0]
        if pid not in patient_info: continue
        raw = pd.read_csv(fp,header=None).select_dtypes(include=[np.number]).values
        if len(raw)<100: continue
        if len(raw)>50: raw=raw[50:,:]
        raw = detrend(raw,axis=0)
        if raw.shape[0]>raw.shape[1]: raw=raw.T
        raw = resample(raw,400,axis=1)
        if pid not in patient_segments: patient_segments[pid]=[]
        patient_segments[pid].append(raw)
    except: continue

valid_pids = np.array([p for p in patient_segments if p in patient_info])
pat_labels = np.array([patient_info[p]['label'] for p in valid_pids])
pat_nms    = np.array([nms_data.get(p,[0]*30) for p in valid_pids],dtype=np.float32)
max_ch     = max(s.shape[0] for p in valid_pids for s in patient_segments[p])
N          = len(valid_pids)

print(f"   ✅ {N} patients | PD={np.sum(pat_labels==1)} HC={np.sum(pat_labels==0)}")

# ── Rocket cache ──────────────────────────────────────────────────────────
ROCKET_CACHE  = f'{OUTPUT_DIR}/rocket_features.npy'
COUNTS_CACHE  = f'{OUTPUT_DIR}/seg_counts.npy'

if os.path.exists(ROCKET_CACHE) and os.path.exists(COUNTS_CACHE):
    print("✅ Loading cached Rocket features...")
    all_rocket = np.load(ROCKET_CACHE)
    seg_counts = np.load(COUNTS_CACHE)
else:
    print("🚀 Fitting MiniRocket on all segments (once)...")
    all_segs, seg_counts = [], []
    for pid in tqdm(valid_pids, desc="   Stacking", ncols=70):
        cnt = len(patient_segments[pid])
        for seg in patient_segments[pid]:
            padded = np.zeros((max_ch,400),dtype=np.float32)
            padded[:seg.shape[0],:] = seg
            all_segs.append(padded)
        seg_counts.append(cnt)
    all_segs_arr = np.array(all_segs,dtype=np.float32)
    seg_counts   = np.array(seg_counts)
    del all_segs; gc.collect()

    rocket = MiniRocketMultivariate(num_kernels=8000,random_state=RANDOM_STATE,n_jobs=-1)
    all_rocket = rocket.fit_transform(all_segs_arr)
    all_rocket = all_rocket.values if hasattr(all_rocket,'values') else np.array(all_rocket)
    del all_segs_arr; gc.collect()
    np.save(ROCKET_CACHE, all_rocket)
    np.save(COUNTS_CACHE, seg_counts)
    print(f"   ✅ Cached: {all_rocket.shape}")

# ── Patient feature matrices ──────────────────────────────────────────────
print("📊 Building patient matrices...")
feat_dim = all_rocket.shape[1]

# Full: mean + std  (used by A1, A2, baselines)
X_full = np.zeros((N, feat_dim*2), dtype=np.float32)
# Mean only (A4 ablation)
X_mean = np.zeros((N, feat_dim),   dtype=np.float32)

idx = 0
for i, cnt in enumerate(seg_counts):
    segs = all_rocket[idx:idx+cnt]
    X_full[i, :feat_dim]  = segs.mean(axis=0)
    X_full[i, feat_dim:]  = segs.std(axis=0)
    X_mean[i]             = segs.mean(axis=0)
    idx += cnt

del all_rocket; gc.collect()
print(f"   X_full: {X_full.shape} | X_mean: {X_mean.shape} | NMS: {pat_nms.shape}")

# ── CV + OOF threshold runner ─────────────────────────────────────────────
outer_cv = StratifiedKFold(n_splits=10, shuffle=True, random_state=RANDOM_STATE)
inner_cv = StratifiedKFold(n_splits=5,  shuffle=True, random_state=RANDOM_STATE)

def run_experiment(name, get_model_fn, X_sig, X_nms_feat, use_nms=True):
    """
    get_model_fn() → sklearn estimator (must support decision_function or predict_proba)
    X_sig:      patient-level signal features
    X_nms_feat: patient-level NMS features (ignored if use_nms=False)
    """
    ck_path = f'{OUTPUT_DIR}/ck_{name}.pkl'
    if os.path.exists(ck_path):
        print(f"   ✅ {name} — checkpoint")
        with open(ck_path,'rb') as f: return pickle.load(f)

    metrics = {'bal_acc':[],'sens':[],'spec':[],'f1':[],'auc':[]}

    for fold,(tr_idx,te_idx) in enumerate(outer_cv.split(X_sig, pat_labels),1):
        X_sig_tr, X_sig_te = X_sig[tr_idx], X_sig[te_idx]
        y_tr, y_te         = pat_labels[tr_idx], pat_labels[te_idx]

        # ── Signal model ──────────────────────────────────────────────
        sc_sig = StandardScaler()
        Xs_tr  = sc_sig.fit_transform(X_sig_tr)
        Xs_te  = sc_sig.transform(X_sig_te)

        model = get_model_fn()
        model.fit(Xs_tr, y_tr)

        # OOF scores for threshold
        if hasattr(model,'decision_function'):
            oof_sig = cross_val_predict(get_model_fn(), Xs_tr, y_tr,
                                        cv=inner_cv, method='decision_function')
            sig_score_te = model.decision_function(Xs_te)
            sig_prob_te  = 1/(1+np.exp(-sig_score_te))
            oof_sig_prob = 1/(1+np.exp(-oof_sig))
        else:
            oof_sig_prob = cross_val_predict(get_model_fn(), Xs_tr, y_tr,
                                             cv=inner_cv, method='predict_proba')[:,1]
            sig_prob_te  = model.predict_proba(Xs_te)[:,1]

        if use_nms:
            # ── NMS model ─────────────────────────────────────────────
            nms_tr, nms_te = X_nms_feat[tr_idx], X_nms_feat[te_idx]
            nms_pipe = Pipeline([
                ('sc', StandardScaler()),
                ('lr', LogisticRegression(C=1.0, class_weight='balanced',
                                          max_iter=1000, random_state=RANDOM_STATE))
            ])
            nms_pipe.fit(nms_tr, y_tr)
            oof_nms    = cross_val_predict(
                Pipeline([('sc',StandardScaler()),
                          ('lr',LogisticRegression(C=1.0,class_weight='balanced',
                                                    max_iter=1000,random_state=RANDOM_STATE))]),
                nms_tr, y_tr, cv=inner_cv, method='predict_proba')[:,1]
            nms_prob_te = nms_pipe.predict_proba(nms_te)[:,1]

            oof_ens     = (oof_sig_prob + oof_nms) / 2.0
            ens_prob_te = (sig_prob_te  + nms_prob_te) / 2.0
        else:
            oof_ens     = oof_sig_prob
            ens_prob_te = sig_prob_te

        th  = youden_threshold(y_tr, oof_ens)
        y_pred = (ens_prob_te >= th).astype(int)

        metrics['bal_acc'].append(balanced_accuracy_score(y_te, y_pred))
        metrics['sens'].append(recall_score(y_te, y_pred, pos_label=1, zero_division=0))
        metrics['spec'].append(recall_score(y_te, y_pred, pos_label=0, zero_division=0))
        metrics['f1'].append(f1_score(y_te, y_pred, zero_division=0))
        metrics['auc'].append(roc_auc_score(y_te, ens_prob_te))

        gc.collect()

    result = {k: (np.mean(v)*100, np.std(v)*100) for k,v in metrics.items()}
    result['_folds'] = {k:[x*100 for x in v] for k,v in metrics.items()}
    result['name'] = name

    with open(ck_path,'wb') as f: pickle.dump(result,f)
    m,s = result['bal_acc']
    print(f"   {name:<30} BA={m:.2f}%±{s:.2f}%")
    return result

# ── ABLATION STUDY ────────────────────────────────────────────────────────
print(f"\n{'='*70}")
print("🔬 ABLATION STUDY")
print(f"{'='*70}")

def ridge_fn():
    return RidgeClassifierCV(alphas=np.logspace(-3,3,10), class_weight='balanced')

A1 = run_experiment("A1_Full_Signal+NMS",   ridge_fn, X_full, pat_nms,  use_nms=True)
A2 = run_experiment("A2_Signal_Only",        ridge_fn, X_full, pat_nms,  use_nms=False)
A3_name = "A3_NMS_Only"
ck3 = f'{OUTPUT_DIR}/ck_{A3_name}.pkl'
if os.path.exists(ck3):
    print(f"   ✅ {A3_name} — checkpoint")
    with open(ck3,'rb') as f: A3 = pickle.load(f)
else:
    # NMS-only: just run LR on NMS, no signal
    metrics3 = {'bal_acc':[],'sens':[],'spec':[],'f1':[],'auc':[]}
    for fold,(tr_idx,te_idx) in enumerate(outer_cv.split(pat_nms, pat_labels),1):
        nms_tr,nms_te = pat_nms[tr_idx],pat_nms[te_idx]
        y_tr,y_te     = pat_labels[tr_idx],pat_labels[te_idx]
        pipe = Pipeline([('sc',StandardScaler()),
                         ('lr',LogisticRegression(C=1.0,class_weight='balanced',
                                                   max_iter=1000,random_state=RANDOM_STATE))])
        pipe.fit(nms_tr,y_tr)
        oof = cross_val_predict(
            Pipeline([('sc',StandardScaler()),
                      ('lr',LogisticRegression(C=1.0,class_weight='balanced',
                                                max_iter=1000,random_state=RANDOM_STATE))]),
            nms_tr,y_tr,cv=inner_cv,method='predict_proba')[:,1]
        prob_te = pipe.predict_proba(nms_te)[:,1]
        th  = youden_threshold(y_tr,oof)
        y_pred = (prob_te>=th).astype(int)
        metrics3['bal_acc'].append(balanced_accuracy_score(y_te,y_pred))
        metrics3['sens'].append(recall_score(y_te,y_pred,pos_label=1,zero_division=0))
        metrics3['spec'].append(recall_score(y_te,y_pred,pos_label=0,zero_division=0))
        metrics3['f1'].append(f1_score(y_te,y_pred,zero_division=0))
        metrics3['auc'].append(roc_auc_score(y_te,prob_te))
    A3 = {k:(np.mean(v)*100,np.std(v)*100) for k,v in metrics3.items()}
    A3['_folds'] = {k:[x*100 for x in v] for k,v in metrics3.items()}
    A3['name'] = A3_name
    with open(ck3,'wb') as f: pickle.dump(A3,f)
    m,s = A3['bal_acc']
