# ── STATISTICAL TESTS ─────────────────────────────────────────────────────
print(f"\n{'='*70}")
print("📊 STATISTICAL TESTS (Wilcoxon signed-rank vs Our Method)")
print(f"{'='*70}")

ref_folds = np.array(A1['_folds']['bal_acc'])

def wilcox_test(result):
    other = np.array(result['_folds']['bal_acc'])
    try:
        stat, p = wilcoxon(ref_folds, other)
        return stat, p
    except:
        return None, 1.0

print(f"\n{'Method':<30} {'BA Mean':>9} {'BA Std':>8} {'W':>8} {'p':>8}")
