def load_checkpoint(fold):
    path = f'{OUTPUT_DIR}/ckpt_fold_{fold}.pkl'
    if os.path.exists(path):
        with open(path, 'rb') as f: return pickle.load(f)
    return None

def youden_threshold(y_true, scores):
    """Derive optimal classification threshold from OOF scores using Youden-J."""
    fpr, tpr, ths = roc_curve(y_true, scores)
    return float(ths[np.argmax(tpr - fpr)])

