# ── Patient labels (PD=1, HC=0; DD excluded) ─────────────────────────────
patient_info = {}
meta_path = find_file("subjects.csv")

if meta_path and os.path.exists(meta_path):
    df_meta = pd.read_csv(meta_path)
    for _, r in df_meta[df_meta['label'].isin([0, 1])].iterrows():
        patient_info[str(r['id']).zfill(3)] = {
            'label': int(r['label']), 'age': r['age'], 'gender': str(r['gender'])
        }
else:
    for pf in glob(f"{data_path}/**/patient_*.json", recursive=True):
        try:
            d = json.load(open(pf))
            pid = str(d.get('id', ''))
            cond = d.get('condition', '').lower()
            lbl = (1 if "parkinson" in cond else
                   0 if any(k in cond for k in ["healthy", "control"]) else -1)
            if lbl >= 0 and pid:
                patient_info[pid] = {'label': lbl, 'age': d.get('age', 60),
                                     'gender': str(d.get('gender', 'unknown'))}
        except: pass

print(f"   {len(patient_info)} patients (PD + HC only; DD excluded)")

# ── NMS questionnaire (30-item binary) ───────────────────────────────────
nms_data = {}
for qf in glob(f"{data_path}/**/questionnaire_response_*.json", recursive=True):
    try:
        q = json.load(open(qf))
        pid = str(q.get('subject_id', ''))
        if pid not in patient_info: continue
        ans = [0] * 30
        for it in q.get('item', []):
            try:
                i = int(it.get('link_id', '99')) - 1
                if 0 <= i < 30: ans[i] = 1 if it.get('answer') else 0
            except: pass
        nms_data[pid] = ans
    except: pass
print(f"   {len(nms_data)} NMS questionnaire records")

# ── Signal loading and preprocessing ─────────────────────────────────────
# Preprocessing per segment:
#   1. Remove first 50 samples (transient artefact at recording onset)
#   2. Linear detrending (remove low-frequency postural drift)
#   3. Resample to 400 time steps (uniform length)
s_files = [f for f in glob(f"{data_path}/**/*.txt", recursive=True)
           if "LICENSE" not in f and "README" not in f]

patient_segments = {}
for fp in tqdm(s_files, desc="   Loading segments", ncols=70):
    try:
        pid = os.path.basename(fp).split('_')[0]
        if pid not in patient_info: continue
        raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
        if len(raw) < 100: continue
        if len(raw) > 50: raw = raw[50:, :]         # remove transient artefact
        raw = detrend(raw, axis=0)                   # linear detrend
        if raw.shape[0] > raw.shape[1]: raw = raw.T  # ensure (channels, time)
        raw = resample(raw, 400, axis=1)              # uniform length
        if pid not in patient_segments: patient_segments[pid] = []
        patient_segments[pid].append(raw)
    except: continue

valid_pids = np.array([p for p in patient_segments if p in patient_info])
pat_labels = np.array([patient_info[p]['label'] for p in valid_pids])
pat_nms    = np.array([nms_data.get(p, [0]*30) for p in valid_pids], dtype=np.float32)
max_ch     = max(s.shape[0] for p in valid_pids for s in patient_segments[p])
N          = len(valid_pids)

n_pd = int(np.sum(pat_labels == 1))
n_hc = int(np.sum(pat_labels == 0))
print(f"   ✅ {N} patients | PD={n_pd} | HC={n_hc}")

# ── Helper functions ──────────────────────────────────────────────────────
def segments_array(pids):
    """Stack all segments for given patients into (n_segs, C, T) array."""
    segs, counts = [], []
    for pid in pids:
        cnt = len(patient_segments[pid])
        for seg in patient_segments[pid]:
            padded = np.zeros((max_ch, 400), dtype=np.float32)
            padded[:seg.shape[0], :] = seg
            segs.append(padded)
        counts.append(cnt)
    return np.array(segs, dtype=np.float32), counts

def build_patient_features(rocket_segs, seg_counts):
    """
    Aggregate segment-level Rocket features to patient level.
    Concatenates channel-wise mean and std → (n_patients, 2 * feat_dim).
    The std component captures within-session motor variability,
    which is clinically meaningful in PD (irregular/inconsistent movement).
    """
    feat_dim = rocket_segs.shape[1]
    X = np.zeros((len(seg_counts), feat_dim * 2), dtype=np.float32)
    idx = 0
    for i, cnt in enumerate(seg_counts):
        segs = rocket_segs[idx:idx + cnt]
        X[i, :feat_dim] = segs.mean(axis=0)
        X[i, feat_dim:] = segs.std(axis=0)
        idx += cnt
    return X

# ── 10-fold stratified cross-validation ──────────────────────────────────
outer_cv = StratifiedKFold(n_splits=N_FOLDS, shuffle=True, random_state=RANDOM_STATE)
inner_cv = StratifiedKFold(n_splits=5,       shuffle=True, random_state=RANDOM_STATE)

metrics        = {'bal_acc': [], 'sens': [], 'spec': [], 'f1': [], 'auc': []}
fold_results   = []
all_true_pat   = []   # pooled ground truth across all folds
all_prob_pat   = []   # pooled ensemble probabilities
all_pred_pat   = []   # pooled binary predictions
all_thresholds = []

print(f"\n{'='*70}")
print("🔬 10-FOLD STRATIFIED CV (LEAKAGE-FREE)")
print(f"{'='*70}")

for fold, (tr_idx, te_idx) in enumerate(outer_cv.split(valid_pids, pat_labels), 1):

    # Resume from checkpoint if available
    ck = load_checkpoint(fold)
    if ck:
        print(f"\n✅ FOLD {fold}/{N_FOLDS} — loaded from checkpoint | "
              f"BalAcc={ck['bal_acc']*100:.2f}%")
        for k in metrics: metrics[k].append(ck[k])
        fold_results.append(ck)
        all_true_pat.extend(ck['y_true'])
        all_prob_pat.extend(ck['y_prob'])
        all_pred_pat.extend(ck['y_pred'])
        all_thresholds.append(ck['th_ens'])
        continue

    print(f"\n📌 FOLD {fold}/{N_FOLDS}")

    tr_pids = valid_pids[tr_idx];  te_pids = valid_pids[te_idx]
    y_tr    = pat_labels[tr_idx];  y_te    = pat_labels[te_idx]
    nms_tr  = pat_nms[tr_idx];    nms_te  = pat_nms[te_idx]

    # ── [LEAKAGE POINT 1] MiniRocket: fit on training segments only ───────
    print(f"   🚀 MiniRocket {N_KERNELS//1000}K kernels (training segments only)...")
    tr_segs_arr, tr_counts = segments_array(tr_pids)
    te_segs_arr, te_counts = segments_array(te_pids)

    rocket = MiniRocketMultivariate(num_kernels=N_KERNELS,
                                    random_state=RANDOM_STATE, n_jobs=-1)
    X_r_tr = rocket.fit_transform(tr_segs_arr)   # fit + transform on TRAIN
    X_r_tr = X_r_tr.values if hasattr(X_r_tr, 'values') else np.array(X_r_tr)
    del tr_segs_arr; gc.collect()

    X_r_te = rocket.transform(te_segs_arr)        # transform only on TEST
    X_r_te = X_r_te.values if hasattr(X_r_te, 'values') else np.array(X_r_te)
    del te_segs_arr; gc.collect()

    # ── Patient-level aggregation (mean + std) ────────────────────────────
    X_pat_tr = build_patient_features(X_r_tr, tr_counts)
    X_pat_te = build_patient_features(X_r_te, te_counts)
    del X_r_tr, X_r_te; gc.collect()

    # ── Signal branch: RidgeClassifierCV ─────────────────────────────────
    print("   📐 RidgeClassifierCV + OOF decision scores...")
    ridge = RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced')
    ridge.fit(X_pat_tr, y_tr)

    # OOF decision scores for threshold calibration (training only)
    oof_sig = cross_val_predict(
        RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced'),
        X_pat_tr, y_tr, cv=inner_cv, method='decision_function')

    sig_df_te   = ridge.decision_function(X_pat_te)
    sig_prob_te = 1 / (1 + np.exp(-sig_df_te))    # sigmoid for ensemble

    # ── NMS branch: Logistic Regression ──────────────────────────────────
    print("   📋 LR (NMS) + OOF probabilities...")
    nms_pipe = Pipeline([
        ('sc', StandardScaler()),
        ('lr', LogisticRegression(C=1.0, class_weight='balanced',
                                   max_iter=1000, random_state=RANDOM_STATE))
    ])
    nms_pipe.fit(nms_tr, y_tr)

    oof_nms = cross_val_predict(
        Pipeline([('sc', StandardScaler()),
                  ('lr', LogisticRegression(C=1.0, class_weight='balanced',
                                             max_iter=1000, random_state=RANDOM_STATE))]),
        nms_tr, y_tr, cv=inner_cv, method='predict_proba')[:, 1]
    nms_prob_te = nms_pipe.predict_proba(nms_te)[:, 1]

    # ── [LEAKAGE POINT 2] Ensemble threshold: derived from OOF only ───────
    oof_sig_prob = 1 / (1 + np.exp(-oof_sig))
    oof_ens      = (oof_sig_prob + oof_nms) / 2.0
    th_ens       = youden_threshold(y_tr, oof_ens)  # uses y_tr only — no test leakage

    # ── Test-set evaluation ───────────────────────────────────────────────
    ens_prob_te = (sig_prob_te + nms_prob_te) / 2.0
    y_pred      = (ens_prob_te >= th_ens).astype(int)
    y_true      = y_te

    ba = balanced_accuracy_score(y_true, y_pred)
    se = recall_score(y_true, y_pred, pos_label=1, zero_division=0)
    sp = recall_score(y_true, y_pred, pos_label=0, zero_division=0)
    f1 = f1_score(y_true, y_pred, zero_division=0)
    au = roc_auc_score(y_true, ens_prob_te)

    for k, v in zip(['bal_acc', 'sens', 'spec', 'f1', 'auc'], [ba, se, sp, f1, au]):
        metrics[k].append(v)

    fd = {'fold': fold, 'bal_acc': ba, 'sens': se, 'spec': sp,
          'f1': f1, 'auc': au, 'th_ens': th_ens, 'n_test': len(y_true),
          'y_true': list(y_true), 'y_prob': list(ens_prob_te), 'y_pred': list(y_pred)}
    fold_results.append(fd)
    save_checkpoint(fold, fd)

    all_true_pat.extend(list(y_true))
    all_prob_pat.extend(list(ens_prob_te))
    all_pred_pat.extend(list(y_pred))
    all_thresholds.append(th_ens)

    print(f"   ✅ BalAcc={ba*100:.2f}%  Se={se*100:.2f}%  "
          f"Sp={sp*100:.2f}%  F1={f1*100:.2f}%  AUC={au:.3f}  τ*={th_ens:.3f}")
    gc.collect()

all_true_pat = np.array(all_true_pat)
all_prob_pat = np.array(all_prob_pat)
all_pred_pat = np.array(all_pred_pat)

# ── Summary metrics ───────────────────────────────────────────────────────
our_ba  = np.mean(metrics['bal_acc']) * 100;  std_ba  = np.std(metrics['bal_acc']) * 100
our_se  = np.mean(metrics['sens'])    * 100;  std_se  = np.std(metrics['sens'])    * 100
our_sp  = np.mean(metrics['spec'])    * 100;  std_sp  = np.std(metrics['spec'])    * 100
our_f1  = np.mean(metrics['f1'])      * 100;  std_f1  = np.std(metrics['f1'])      * 100
our_auc = np.mean(metrics['auc'])     * 100;  std_auc = np.std(metrics['auc'])     * 100

print(f"\n{'='*70}")
print("🏆 FINAL RESULTS")
print(f"{'='*70}")
print(f"\n{'Metric':<18} {'Mean':>9} {'±SD':>8}")
print("-" * 37)
for k, label in [('bal_acc', 'Balanced Acc'), ('sens', 'Sensitivity'),
                  ('spec', 'Specificity'), ('f1', 'F1-Score'), ('auc', 'AUC-ROC')]:
    m = np.mean(metrics[k]) * 100; s = np.std(metrics[k]) * 100
    print(f"{label:<18} {m:>8.2f}%  ±{s:.2f}%")

print(f"\nBenchmark [C1]:  {BENCHMARK['BA']:.2f}% ± {BENCHMARK['BA_sd']:.2f}%  (5-fold nested CV)")
print(f"Proposed method: {our_ba:.2f}% ± {std_ba:.2f}%  (10-fold CV)")
print(f"Gender-matched benchmark: {BENCHMARK['BA_matched']:.2f}%  |  "
      f"Difference: {our_ba - BENCHMARK['BA_matched']:+.2f} pp")
print(f"\nImplied Varghese specificity: "
      f"(2×{BENCHMARK['BA']:.2f}) − {BENCHMARK['Se']:.2f} = "
      f"{2*BENCHMARK['BA'] - BENCHMARK['Se']:.2f}%  (derived, interpreted cautiously)")
print(f"Proposed specificity: {our_sp:.2f}%  "
      f"(+{our_sp - (2*BENCHMARK['BA'] - BENCHMARK['Se']):.2f} pp)")

# ── Bootstrap 95% CI (patient-level, paired indices) ─────────────────────
print("\nComputing 95% bootstrap CI...")
np.random.seed(RANDOM_STATE)
boot_ba = []
for _ in range(2000):
    idx = np.random.choice(len(all_true_pat), len(all_true_pat), replace=True)
    if len(np.unique(all_true_pat[idx])) < 2: continue
    boot_ba.append(balanced_accuracy_score(all_true_pat[idx], all_pred_pat[idx]) * 100)
ci_lo, ci_hi = np.percentile(boot_ba, [2.5, 97.5])
print(f"95% CI: [{ci_lo:.2f}%, {ci_hi:.2f}%]")
print(f"Benchmark ({BENCHMARK['BA']:.2f}%) within CI: "
      f"{'YES ✅' if ci_lo <= BENCHMARK['BA'] <= ci_hi else 'NO'}")

# ── Fold-level detail ─────────────────────────────────────────────────────
print(f"\n{'Fold':>4}  {'BA':>8}  {'Se':>8}  {'Sp':>8}  {'F1':>8}  "
      f"{'AUC':>8}  {'τ*':>7}")
print("-" * 60)
for fd in fold_results:
    print(f"{fd['fold']:>4}  {fd['bal_acc']*100:>7.2f}%  "
          f"{fd['sens']*100:>7.2f}%  {fd['spec']*100:>7.2f}%  "
          f"{fd['f1']*100:>7.2f}%  {fd['auc']*100:>7.2f}%  "
          f"{fd['th_ens']:>7.3f}")
mean_th = np.mean(all_thresholds)
print(f"\nMean τ*: {mean_th:.3f}")

# ============================================================================
# FIGURES (publication quality, 600 DPI)
# ============================================================================
print(f"\n{'='*70}")
print("📊 Generating figures...")
print(f"{'='*70}")

fold_ba   = [fd['bal_acc']*100 for fd in fold_results]
fold_se   = [fd['sens']*100    for fd in fold_results]
fold_sp   = [fd['spec']*100    for fd in fold_results]
fold_auc  = [fd['auc']*100     for fd in fold_results]
fold_nums = [fd['fold']        for fd in fold_results]

# ── Fig 1: ROC Curve ──────────────────────────────────────────────────────
# Pooled ROC from actual OOF ensemble probabilities across all 10 folds.
