# ============================================================================
# FINAL PIPELINE — MiniRocket + Ridge + NMS Ensemble
# ============================================================================
# Paper: "Leakage-Free Multimodal Parkinson's Disease Detection Using
#         MiniRocket and Non-Motor Symptom Questionnaires on the PADS Dataset"
# Target Journal: Journal of Medical Systems (Springer)
#
# RESULTS (10-fold stratified CV, patient-level):
#   Balanced Accuracy : 89.10% ± 4.48%   [95% CI: 85.40%, 92.12%]
#   Sensitivity       : 84.46% ± 9.57%
#   Specificity       : 93.75% ± 6.25%
#   F1-Score          : 90.39% ± 5.47%
#   AUC-ROC           : 96.72% ± 3.08%
#   Mean threshold τ* : 0.558
#
# ARCHITECTURE:
#   1. MiniRocket (8K kernels) fitted on training segments only [per fold]
#   2. Patient aggregation: channel-wise mean + std → 16K-dim feature vector
#   3. RidgeClassifierCV (signal branch) + LR (NMS branch) → ensemble mean
#   4. OOF Youden-J threshold derived from training partition → zero leakage
#
# LEAKAGE PREVENTION (dual-level):
#   • MiniRocket: fit_transform on tr_segs only; transform on te_segs only
#   • Threshold: youden_threshold(y_tr, oof_ens) — no test data used
#   • Patient split: all segments of a patient are in either train or test
#
# REQUIREMENTS: numpy, pandas, scipy, scikit-learn, sktime, matplotlib
# HARDWARE    : CPU only (no GPU required)
# ============================================================================

import os, sys, subprocess, warnings, gc, zipfile as zf, pickle, json
from glob import glob
from tqdm import tqdm
import numpy as np
import pandas as pd
from datetime import datetime

warnings.filterwarnings('ignore')

# ── Package installation ──────────────────────────────────────────────────
def install(pkg):
    try: __import__(pkg.split('[')[0].replace('-', '_'))
    except:
        subprocess.check_call([sys.executable, '-m', 'pip', 'install', pkg, '-q',
                               '--break-system-packages'],
                              stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

print("📦 Installing packages...")
for pkg in ['numpy', 'pandas', 'scipy', 'scikit-learn', 'sktime', 'matplotlib']:
    install(pkg)

from scipy.signal import detrend, resample
from sklearn.model_selection import StratifiedKFold, cross_val_predict
from sklearn.linear_model import RidgeClassifierCV, LogisticRegression
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import Pipeline
from sklearn.metrics import (balanced_accuracy_score, recall_score, f1_score,
                             roc_auc_score, roc_curve, confusion_matrix)
from sktime.transformations.panel.rocket import MiniRocketMultivariate

import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker

# ── Configuration ─────────────────────────────────────────────────────────
RANDOM_STATE = 42
N_KERNELS    = 8000
N_FOLDS      = 10
np.random.seed(RANDOM_STATE)

# Benchmark values from Varghese et al. (2024), npj Parkinson's Disease
BENCHMARK = {
    'label':   'Varghese et al. [C1]',
    'BA':  91.16, 'BA_sd':  4.92,   # 5-fold nested CV, complete dataset
    'Se':  92.40, 'Se_sd':  2.64,   # = reported PD recall
    'F1':  94.62, 'F1_sd':  2.21,
    'BA_matched': 89.25,            # gender-matched subset
}

OUTPUT_DIR = './final_results'
FIGURE_DIR = f'{OUTPUT_DIR}/figures'
os.makedirs(FIGURE_DIR, exist_ok=True)
DPI = 600

# ── Matplotlib style ───────────────────────────────────────────────────────
plt.rcParams.update({
    'font.family': 'DejaVu Sans', 'font.size': 9,
    'axes.titlesize': 10, 'axes.labelsize': 9,
    'xtick.labelsize': 8, 'ytick.labelsize': 8,
    'legend.fontsize': 8, 'figure.dpi': DPI, 'savefig.dpi': DPI,
    'axes.linewidth': 0.8, 'axes.spines.top': False, 'axes.spines.right': False,
    'lines.linewidth': 1.5, 'grid.linewidth': 0.5, 'grid.alpha': 0.4,
})
C = {'blue': '#2563EB', 'red': '#DC2626', 'green': '#16A34A', 'amber': '#D97706'}

def save_fig(fig, name):
    path = f'{FIGURE_DIR}/{name}.png'
    fig.savefig(path, dpi=DPI, bbox_inches='tight', facecolor='white')
    plt.close(fig)
    print(f"   💾 {path}")

def save_checkpoint(fold, data):
    with open(f'{OUTPUT_DIR}/ckpt_fold_{fold}.pkl', 'wb') as f:
        pickle.dump(data, f)

def load_checkpoint(fold):
    path = f'{OUTPUT_DIR}/ckpt_fold_{fold}.pkl'
    if os.path.exists(path):
        with open(path, 'rb') as f: return pickle.load(f)
    return None

def youden_threshold(y_true, scores):
    """Derive optimal classification threshold from OOF scores using Youden-J."""
    fpr, tpr, ths = roc_curve(y_true, scores)
    return float(ths[np.argmax(tpr - fpr)])


print("=" * 70)
print("🏁 FINAL PIPELINE — MiniRocket + Ridge + NMS (Leakage-Free)")
print("=" * 70)

# ── Data discovery ────────────────────────────────────────────────────────
try:
    if not os.path.exists('/content/drive'):
        from google.colab import drive; drive.mount('/content/drive')
except: pass

def find_file(name):
    for p in [f"/content/{name}", f"/content/drive/MyDrive/{name}",
              f"/content/drive/MyDrive/Parkinson/{name}", f"./{name}"]:
        if os.path.exists(p): return p
    if os.path.exists("/content/drive"):
        r = subprocess.getoutput(
            f"find /content/drive -name '{name}' -type f 2>/dev/null | head -1")
        if r.strip(): return r.strip()
    return None

def find_data():
    dirs = ["./pads_data_extracted", "/content/pads_data_extracted",
            "/content/pads_extracted",
            "/content/drive/MyDrive/Parkinson/pads_data_extracted"]
    for d in dirs:
        if os.path.exists(d) and len(glob(f"{d}/**/*.txt", recursive=True)) > 10:
            return d
    zp = find_file("pads-parkinsons-disease-smartwatch-dataset-1.0.0.zip")
    if zp:
        print("📦 Extracting PADS dataset...")
        with zf.ZipFile(zp, 'r') as z: z.extractall("./pads_data_extracted")
        return "./pads_data_extracted"
    raise FileNotFoundError("❌ PADS dataset not found. Upload the zip file to Colab.")

data_path = find_data()
print(f"✅ Data: {data_path}")

# ── Patient labels (PD=1, HC=0; DD excluded) ─────────────────────────────
patient_info = {}
meta_path = find_file("subjects.csv")

if meta_path and os.path.exists(meta_path):
    df_meta = pd.read_csv(meta_path)
    for _, r in df_meta[df_meta['label'].isin([0, 1])].iterrows():
        patient_info[str(r['id']).zfill(3)] = {
            'label': int(r['label']), 'age': r['age'], 'gender': str(r['gender'])
        }
else:
    for pf in glob(f"{data_path}/**/patient_*.json", recursive=True):
        try:
            d = json.load(open(pf))
            pid = str(d.get('id', ''))
            cond = d.get('condition', '').lower()
            lbl = (1 if "parkinson" in cond else
                   0 if any(k in cond for k in ["healthy", "control"]) else -1)
            if lbl >= 0 and pid:
                patient_info[pid] = {'label': lbl, 'age': d.get('age', 60),
                                     'gender': str(d.get('gender', 'unknown'))}
        except: pass

print(f"   {len(patient_info)} patients (PD + HC only; DD excluded)")

# ── NMS questionnaire (30-item binary) ───────────────────────────────────
nms_data = {}
for qf in glob(f"{data_path}/**/questionnaire_response_*.json", recursive=True):
    try:
        q = json.load(open(qf))
        pid = str(q.get('subject_id', ''))
        if pid not in patient_info: continue
        ans = [0] * 30
        for it in q.get('item', []):
            try:
                i = int(it.get('link_id', '99')) - 1
                if 0 <= i < 30: ans[i] = 1 if it.get('answer') else 0
            except: pass
        nms_data[pid] = ans
    except: pass
print(f"   {len(nms_data)} NMS questionnaire records")

# ── Signal loading and preprocessing ─────────────────────────────────────
# Preprocessing per segment:
#   1. Remove first 50 samples (transient artefact at recording onset)
#   2. Linear detrending (remove low-frequency postural drift)
#   3. Resample to 400 time steps (uniform length)
s_files = sorted([f for f in glob(f"{data_path}/**/*.txt", recursive=True)
                  if "LICENSE" not in f and "README" not in f])  # sorted for reproducibility

patient_segments = {}
for fp in tqdm(s_files, desc="   Loading segments", ncols=70):
    try:
        pid = os.path.basename(fp).split('_')[0]
        if pid not in patient_info: continue
        raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
        if len(raw) < 100: continue
        if len(raw) > 50: raw = raw[50:, :]         # remove transient artefact
        raw = detrend(raw, axis=0)                   # linear detrend
        if raw.shape[0] > raw.shape[1]: raw = raw.T  # ensure (channels, time)
        raw = resample(raw, 400, axis=1)              # uniform length
        if pid not in patient_segments: patient_segments[pid] = []
        patient_segments[pid].append(raw)
    except: continue

valid_pids = np.array(sorted([p for p in patient_segments if p in patient_info]))  # sorted for reproducibility
pat_labels = np.array([patient_info[p]['label'] for p in valid_pids])
pat_nms    = np.array([nms_data.get(p, [0]*30) for p in valid_pids], dtype=np.float32)
max_ch     = max(s.shape[0] for p in valid_pids for s in patient_segments[p])
N          = len(valid_pids)

n_pd = int(np.sum(pat_labels == 1))
n_hc = int(np.sum(pat_labels == 0))
print(f"   ✅ {N} patients | PD={n_pd} | HC={n_hc}")

# ── Helper functions ──────────────────────────────────────────────────────
def segments_array(pids):
    """Stack all segments for given patients into (n_segs, C, T) array."""
    segs, counts = [], []
    for pid in pids:
        cnt = len(patient_segments[pid])
        for seg in patient_segments[pid]:
            padded = np.zeros((max_ch, 400), dtype=np.float32)
            padded[:seg.shape[0], :] = seg
            segs.append(padded)
        counts.append(cnt)
    return np.array(segs, dtype=np.float32), counts

def build_patient_features(rocket_segs, seg_counts):
    """
    Aggregate segment-level Rocket features to patient level.
    Concatenates channel-wise mean and std → (n_patients, 2 * feat_dim).
    The std component captures within-session motor variability,
    which is clinically meaningful in PD (irregular/inconsistent movement).
    """
    feat_dim = rocket_segs.shape[1]
    X = np.zeros((len(seg_counts), feat_dim * 2), dtype=np.float32)
    idx = 0
    for i, cnt in enumerate(seg_counts):
        segs = rocket_segs[idx:idx + cnt]
        X[i, :feat_dim] = segs.mean(axis=0)
        X[i, feat_dim:] = segs.std(axis=0)
        idx += cnt
    return X

# ── 10-fold stratified cross-validation ──────────────────────────────────
outer_cv = StratifiedKFold(n_splits=N_FOLDS, shuffle=True, random_state=RANDOM_STATE)
inner_cv = StratifiedKFold(n_splits=5,       shuffle=True, random_state=RANDOM_STATE)

metrics        = {'bal_acc': [], 'sens': [], 'spec': [], 'f1': [], 'auc': []}
fold_results   = []
all_true_pat   = []   # pooled ground truth across all folds
all_prob_pat   = []   # pooled ensemble probabilities
all_pred_pat   = []   # pooled binary predictions
all_thresholds = []

print(f"\n{'='*70}")
print("🔬 10-FOLD STRATIFIED CV (LEAKAGE-FREE)")
print(f"{'='*70}")

for fold, (tr_idx, te_idx) in enumerate(outer_cv.split(valid_pids, pat_labels), 1):

    # Resume from checkpoint if available
    ck = load_checkpoint(fold)
    if ck:
        print(f"\n✅ FOLD {fold}/{N_FOLDS} — loaded from checkpoint | "
              f"BalAcc={ck['bal_acc']*100:.2f}%")
        for k in metrics: metrics[k].append(ck[k])
        fold_results.append(ck)
        all_true_pat.extend(ck['y_true'])
        all_prob_pat.extend(ck['y_prob'])
        all_pred_pat.extend(ck['y_pred'])
        all_thresholds.append(ck['th_ens'])
        continue

    print(f"\n📌 FOLD {fold}/{N_FOLDS}")

    tr_pids = valid_pids[tr_idx];  te_pids = valid_pids[te_idx]
    y_tr    = pat_labels[tr_idx];  y_te    = pat_labels[te_idx]
    nms_tr  = pat_nms[tr_idx];    nms_te  = pat_nms[te_idx]

    # ── [LEAKAGE POINT 1] MiniRocket: fit on training segments only ───────
    print(f"   🚀 MiniRocket {N_KERNELS//1000}K kernels (training segments only)...")
    tr_segs_arr, tr_counts = segments_array(tr_pids)
    te_segs_arr, te_counts = segments_array(te_pids)

    rocket = MiniRocketMultivariate(num_kernels=N_KERNELS,
                                    random_state=RANDOM_STATE, n_jobs=-1)
    X_r_tr = rocket.fit_transform(tr_segs_arr)   # fit + transform on TRAIN
    X_r_tr = X_r_tr.values if hasattr(X_r_tr, 'values') else np.array(X_r_tr)
    del tr_segs_arr; gc.collect()

    X_r_te = rocket.transform(te_segs_arr)        # transform only on TEST
    X_r_te = X_r_te.values if hasattr(X_r_te, 'values') else np.array(X_r_te)
    del te_segs_arr; gc.collect()

    # ── Patient-level aggregation (mean + std) ────────────────────────────
    X_pat_tr = build_patient_features(X_r_tr, tr_counts)
    X_pat_te = build_patient_features(X_r_te, te_counts)
    del X_r_tr, X_r_te; gc.collect()

    # ── Signal branch: RidgeClassifierCV ─────────────────────────────────
    print("   📐 RidgeClassifierCV + OOF decision scores...")
    # Signal branch: RidgeClassifierCV with balanced class weights
    ridge = RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced')
    ridge.fit(X_pat_tr, y_tr)

    # OOF decision scores for threshold calibration (training only)
    oof_sig = cross_val_predict(
        RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced'),
        X_pat_tr, y_tr, cv=inner_cv, method='decision_function')

    sig_df_te   = ridge.decision_function(X_pat_te)
    sig_prob_te = 1 / (1 + np.exp(-sig_df_te))    # sigmoid for ensemble

    # ── NMS branch: Logistic Regression ──────────────────────────────────
    print("   📋 LR (NMS) + OOF probabilities...")
    nms_pipe = Pipeline([
        ('sc', StandardScaler()),
        ('lr', LogisticRegression(C=1.0, class_weight='balanced',
                                   max_iter=1000, random_state=RANDOM_STATE))
    ])
    nms_pipe.fit(nms_tr, y_tr)

    oof_nms = cross_val_predict(
        Pipeline([('sc', StandardScaler()),
                  ('lr', LogisticRegression(C=1.0, class_weight='balanced',
                                             max_iter=1000, random_state=RANDOM_STATE))]),
        nms_tr, y_tr, cv=inner_cv, method='predict_proba')[:, 1]
    nms_prob_te = nms_pipe.predict_proba(nms_te)[:, 1]

    # ── [LEAKAGE POINT 2] Ensemble threshold: derived from OOF only ───────
    oof_sig_prob = 1 / (1 + np.exp(-oof_sig))
    oof_ens      = (oof_sig_prob + oof_nms) / 2.0
    th_ens       = youden_threshold(y_tr, oof_ens)  # uses y_tr only — no test leakage

    # ── Test-set evaluation ───────────────────────────────────────────────
    ens_prob_te = (sig_prob_te + nms_prob_te) / 2.0
    y_pred      = (ens_prob_te >= th_ens).astype(int)
    y_true      = y_te

    ba = balanced_accuracy_score(y_true, y_pred)
    se = recall_score(y_true, y_pred, pos_label=1, zero_division=0)
    sp = recall_score(y_true, y_pred, pos_label=0, zero_division=0)
    f1 = f1_score(y_true, y_pred, zero_division=0)
    au = roc_auc_score(y_true, ens_prob_te)

    for k, v in zip(['bal_acc', 'sens', 'spec', 'f1', 'auc'], [ba, se, sp, f1, au]):
        metrics[k].append(v)

    fd = {'fold': fold, 'bal_acc': ba, 'sens': se, 'spec': sp,
          'f1': f1, 'auc': au, 'th_ens': th_ens, 'n_test': len(y_true),
          'y_true': list(y_true), 'y_prob': list(ens_prob_te), 'y_pred': list(y_pred)}
    fold_results.append(fd)
    save_checkpoint(fold, fd)

    all_true_pat.extend(list(y_true))
    all_prob_pat.extend(list(ens_prob_te))
    all_pred_pat.extend(list(y_pred))
    all_thresholds.append(th_ens)

    print(f"   ✅ BalAcc={ba*100:.2f}%  Se={se*100:.2f}%  "
          f"Sp={sp*100:.2f}%  F1={f1*100:.2f}%  AUC={au:.3f}  τ*={th_ens:.3f}")
    gc.collect()

all_true_pat = np.array(all_true_pat)
all_prob_pat = np.array(all_prob_pat)
all_pred_pat = np.array(all_pred_pat)

# ── Summary metrics ───────────────────────────────────────────────────────
our_ba  = np.mean(metrics['bal_acc']) * 100;  std_ba  = np.std(metrics['bal_acc']) * 100
our_se  = np.mean(metrics['sens'])    * 100;  std_se  = np.std(metrics['sens'])    * 100
our_sp  = np.mean(metrics['spec'])    * 100;  std_sp  = np.std(metrics['spec'])    * 100
our_f1  = np.mean(metrics['f1'])      * 100;  std_f1  = np.std(metrics['f1'])      * 100
our_auc = np.mean(metrics['auc'])     * 100;  std_auc = np.std(metrics['auc'])     * 100

print(f"\n{'='*70}")
print("🏆 FINAL RESULTS")
print(f"{'='*70}")
print(f"\n{'Metric':<18} {'Mean':>9} {'±SD':>8}")
print("-" * 37)
for k, label in [('bal_acc', 'Balanced Acc'), ('sens', 'Sensitivity'),
                  ('spec', 'Specificity'), ('f1', 'F1-Score'), ('auc', 'AUC-ROC')]:
    m = np.mean(metrics[k]) * 100; s = np.std(metrics[k]) * 100
    print(f"{label:<18} {m:>8.2f}%  ±{s:.2f}%")

print(f"\nBenchmark [C1]:  {BENCHMARK['BA']:.2f}% ± {BENCHMARK['BA_sd']:.2f}%  (5-fold nested CV)")
print(f"Proposed method: {our_ba:.2f}% ± {std_ba:.2f}%  (10-fold CV)")
print(f"Gender-matched benchmark: {BENCHMARK['BA_matched']:.2f}%  |  "
      f"Difference: {our_ba - BENCHMARK['BA_matched']:+.2f} pp")
print(f"\nImplied Varghese specificity: "
      f"(2×{BENCHMARK['BA']:.2f}) − {BENCHMARK['Se']:.2f} = "
      f"{2*BENCHMARK['BA'] - BENCHMARK['Se']:.2f}%  (derived, interpreted cautiously)")
print(f"Proposed specificity: {our_sp:.2f}%  "
      f"(+{our_sp - (2*BENCHMARK['BA'] - BENCHMARK['Se']):.2f} pp)")

# ── Bootstrap 95% CI (patient-level, paired indices) ─────────────────────
print("\nComputing 95% bootstrap CI...")
np.random.seed(RANDOM_STATE)
boot_ba = []
for _ in range(2000):
    idx = np.random.choice(len(all_true_pat), len(all_true_pat), replace=True)
    if len(np.unique(all_true_pat[idx])) < 2: continue
    boot_ba.append(balanced_accuracy_score(all_true_pat[idx], all_pred_pat[idx]) * 100)
ci_lo, ci_hi = np.percentile(boot_ba, [2.5, 97.5])
print(f"95% CI: [{ci_lo:.2f}%, {ci_hi:.2f}%]")
print(f"Benchmark ({BENCHMARK['BA']:.2f}%) within CI: "
      f"{'YES ✅' if ci_lo <= BENCHMARK['BA'] <= ci_hi else 'NO'}")

# ── Fold-level detail ─────────────────────────────────────────────────────
print(f"\n{'Fold':>4}  {'BA':>8}  {'Se':>8}  {'Sp':>8}  {'F1':>8}  "
      f"{'AUC':>8}  {'τ*':>7}")
print("-" * 60)
for fd in fold_results:
    print(f"{fd['fold']:>4}  {fd['bal_acc']*100:>7.2f}%  "
          f"{fd['sens']*100:>7.2f}%  {fd['spec']*100:>7.2f}%  "
          f"{fd['f1']*100:>7.2f}%  {fd['auc']*100:>7.2f}%  "
          f"{fd['th_ens']:>7.3f}")
mean_th = np.mean(all_thresholds)
print(f"\nMean τ*: {mean_th:.3f}")

# ============================================================================
# FIGURES (publication quality, 600 DPI)
# ============================================================================
print(f"\n{'='*70}")
print("📊 Generating figures...")
print(f"{'='*70}")

fold_ba   = [fd['bal_acc']*100 for fd in fold_results]
fold_se   = [fd['sens']*100    for fd in fold_results]
fold_sp   = [fd['spec']*100    for fd in fold_results]
fold_auc  = [fd['auc']*100     for fd in fold_results]
fold_nums = [fd['fold']        for fd in fold_results]

# ── Fig 1: ROC Curve ──────────────────────────────────────────────────────
# Pooled ROC from actual OOF ensemble probabilities across all 10 folds.
# Varghese specificity not reported → cannot plot their operating point.
fpr_s, tpr_s, _ = roc_curve(all_true_pat, all_prob_pat)   # real OOF data
global_auc = roc_auc_score(all_true_pat, all_prob_pat)
op_fpr = 1 - our_sp/100
op_tpr = our_se/100

fig, ax = plt.subplots(figsize=(3.5, 3.5))
ax.plot(fpr_s, tpr_s, color=C['blue'], linewidth=2.0,
        label=f'Proposed Method (AUC = {global_auc:.3f})')
ax.plot([0, 1], [0, 1], 'k--', linewidth=0.8, label='Random Classifier')
ax.scatter([op_fpr], [op_tpr], color=C['blue'], s=80, zorder=5,
           marker='*', linewidths=0,
           label=f'Mean OP (Se={our_se:.1f}%, Sp={our_sp:.1f}%)')
ax.annotate(f'  Se={our_se:.1f}%\n  Sp={our_sp:.1f}%',
            xy=(op_fpr, op_tpr), xytext=(op_fpr+0.12, op_tpr-0.12),
            fontsize=7, color=C['blue'],
            arrowprops=dict(arrowstyle='->', color=C['blue'],
                           lw=0.8, connectionstyle='arc3,rad=0.2'))
ax.set_xlim([0, 1]); ax.set_ylim([0, 1.02])
ax.set_xlabel('False Positive Rate (1 − Specificity)')
ax.set_ylabel('True Positive Rate (Sensitivity)')
ax.set_title("ROC Curve — Parkinson's Disease Detection")
ax.legend(loc='lower right', framealpha=0.9, fontsize=7.5)
ax.grid(True); fig.tight_layout()
save_fig(fig, 'fig1_roc_curve')

# ── Fig 2: Confusion Matrix ───────────────────────────────────────────────
cm = confusion_matrix(all_true_pat, all_pred_pat)
cm_norm = cm.astype(float) / cm.sum(axis=1, keepdims=True)

fig, ax = plt.subplots(figsize=(3.2, 3.0))
im = ax.imshow(cm_norm, interpolation='nearest', cmap='Blues', vmin=0, vmax=1)
plt.colorbar(im, ax=ax, fraction=0.046, pad=0.04, label='Proportion')
for i in range(2):
    for j in range(2):
        col = 'white' if cm_norm[i, j] > 0.5 else 'black'
        ax.text(j, i, f'{cm[i, j]}\n({cm_norm[i, j]*100:.1f}%)',
                ha='center', va='center', color=col, fontsize=9, fontweight='bold')
ax.set_xticks([0, 1]); ax.set_yticks([0, 1])
ax.set_xticklabels(['Predicted HC', 'Predicted PD'])
ax.set_yticklabels(['True HC', 'True PD'])
ax.set_title('Confusion Matrix (Pooled 10-Fold CV)')
fig.tight_layout()
save_fig(fig, 'fig2_confusion_matrix')

# ── Fig 3: Metric Comparison ──────────────────────────────────────────────
# Blue bars: proposed method. Red bars: Varghese et al. [C1] (where reported).
# N/R = not reported in original study.
metric_names = ['Balanced\nAccuracy', 'Sensitivity', 'Specificity', 'F1-Score', 'AUC-ROC']
our_means    = [our_ba, our_se, our_sp, our_f1, our_auc]
our_stds     = [std_ba, std_se, std_sp, std_f1, std_auc]
varg_means   = [BENCHMARK['BA'], BENCHMARK['Se'], None, BENCHMARK['F1'], None]
varg_stds    = [BENCHMARK['BA_sd'], BENCHMARK['Se_sd'], None, BENCHMARK['F1_sd'], None]

x = np.arange(len(metric_names)); w = 0.32

fig, ax = plt.subplots(figsize=(6.0, 3.8))
bars_our = ax.bar(x - w/2, our_means, w, yerr=our_stds,
                  color=C['blue'], alpha=0.85, capsize=3,
                  label='Proposed Method', error_kw={'linewidth': 1.0})

for i, (vm, vs) in enumerate(zip(varg_means, varg_stds)):
    if vm is not None:
        b = ax.bar(x[i] + w/2, vm, w, yerr=vs, color=C['red'], alpha=0.85,
                   capsize=3, error_kw={'linewidth': 1.0},
                   label='Varghese et al. [C1]' if i == 0 else '_nolegend_')
        for rect in b:
            ax.text(rect.get_x() + rect.get_width()/2, vm + vs + 0.9,
                    f'{vm:.1f}%', ha='center', va='bottom',
                    fontsize=7.0, fontweight='bold', color=C['red'])

for bar, mean, std in zip(bars_our, our_means, our_stds):
    ax.text(bar.get_x() + bar.get_width()/2, mean + std + 0.9,
            f'{mean:.1f}%', ha='center', va='bottom',
            fontsize=7.0, fontweight='bold', color=C['blue'])

for i, (vm, vs) in enumerate(zip(varg_means, varg_stds)):
    if vm is None:
        ax.text(x[i] + w/2, 65.5, 'N/R', ha='center', va='bottom',
                fontsize=6.5, color='gray', style='italic')

ax.set_xticks(x); ax.set_xticklabels(metric_names)
ax.set_ylabel('Performance (%)'); ax.set_ylim([64, 107])
ax.set_title('Classification Performance — 10-Fold CV (Mean ± SD)')
ax.legend(loc='lower right', framealpha=0.9)
ax.grid(True, axis='y')
ax.yaxis.set_major_formatter(mticker.FormatStrFormatter('%.0f%%'))
fig.tight_layout()
save_fig(fig, 'fig3_metric_comparison')

# ── Fig 4: Cross-Validation Stability ────────────────────────────────────
varg_ba    = BENCHMARK['BA'];     varg_ba_sd = BENCHMARK['BA_sd']

fig, axes = plt.subplots(1, 2, figsize=(7.0, 3.2))

ax = axes[0]
ax.plot(fold_nums, fold_ba, 'o-', color=C['blue'], markersize=5,
        linewidth=1.5, label='Balanced Accuracy')
ax.axhline(our_ba, color=C['blue'], linestyle='--', linewidth=1.0,
           alpha=0.7, label=f'Mean = {our_ba:.1f}%')
ax.axhline(varg_ba, color=C['red'], linestyle=':', linewidth=1.2,
           label=f'Varghese [C1]: {varg_ba:.2f}%')
ax.fill_between(fold_nums, [our_ba - std_ba]*N_FOLDS, [our_ba + std_ba]*N_FOLDS,
                alpha=0.12, color=C['blue'])
ax.fill_between(fold_nums, [varg_ba - varg_ba_sd]*N_FOLDS,
                [varg_ba + varg_ba_sd]*N_FOLDS,
                alpha=0.07, color=C['red'], label=f'±SD benchmark ({varg_ba_sd:.2f}%)')
ax.set_xlabel('Fold'); ax.set_ylabel('Balanced Accuracy (%)')
ax.set_title('Fold-level Balanced Accuracy')
ax.set_xticks(fold_nums); ax.set_ylim([70, 104])
ax.legend(fontsize=6.5, framealpha=0.9); ax.grid(True)

ax = axes[1]
ax.plot(fold_nums, fold_se, 's-', color=C['green'],
        markersize=5, linewidth=1.5, label='Sensitivity')
ax.plot(fold_nums, fold_sp, 'd-', color=C['amber'],
        markersize=5, linewidth=1.5, label='Specificity')
ax.axhline(our_se, color=C['green'], linestyle='--', linewidth=0.8, alpha=0.6)
ax.axhline(our_sp, color=C['amber'], linestyle='--', linewidth=0.8, alpha=0.6)
ax.set_xlabel('Fold'); ax.set_ylabel('Score (%)')
ax.set_title('Sensitivity vs. Specificity per Fold')
ax.set_xticks(fold_nums); ax.set_ylim([55, 107])
ax.legend(fontsize=7, framealpha=0.9); ax.grid(True)

fig.suptitle('Cross-Validation Stability Analysis', fontsize=10, y=1.01)
fig.tight_layout()
save_fig(fig, 'fig4_fold_stability')

# ── Fig 5: Ensemble Probability Distribution ──────────────────────────────
pd_probs = all_prob_pat[all_true_pat == 1]
hc_probs = all_prob_pat[all_true_pat == 0]

fig, ax = plt.subplots(figsize=(4.0, 3.2))
bins = np.linspace(0, 1, 26)
ax.hist(hc_probs, bins=bins, color=C['green'], alpha=0.6,
        label=f'HC (n={len(hc_probs)})', edgecolor='white', linewidth=0.5)
ax.hist(pd_probs, bins=bins, color=C['red'], alpha=0.6,
        label=f'PD (n={len(pd_probs)})', edgecolor='white', linewidth=0.5)
ax.axvline(mean_th, color='black', linewidth=1.5, linestyle='--',
           label=f'Mean τ* = {mean_th:.3f}')
ax.set_xlabel('Ensemble Probability Score')
ax.set_ylabel('Count')
ax.set_title('Predicted Probability Distribution\nby True Class Label')
ax.legend(framealpha=0.9); ax.grid(True, axis='y')
fig.tight_layout()
save_fig(fig, 'fig5_probability_distribution')

# ── Save results ──────────────────────────────────────────────────────────
ts = datetime.now().strftime("%Y%m%d_%H%M%S")
results = {
    'method':         'MiniRocket_Ridge_NMS_OOF_Leakage_Free',
    'n_folds':        N_FOLDS,
    'n_kernels':      N_KERNELS,
    'balanced_acc':   our_ba,   'std_ba':   std_ba,
    'sensitivity':    our_se,   'std_se':   std_se,
    'specificity':    our_sp,   'std_sp':   std_sp,
    'f1':             our_f1,   'std_f1':   std_f1,
    'auc':            our_auc,  'std_auc':  std_auc,
    'ci_95':          [ci_lo, ci_hi],
    'mean_threshold': mean_th,
    'global_auc':     global_auc,
    'benchmark':      BENCHMARK,
    'all_metrics':    metrics,
    'fold_results':   fold_results,
    'confusion_matrix': cm.tolist(),
}
fp = f'{OUTPUT_DIR}/FINAL_{ts}.pkl'
with open(fp, 'wb') as f: pickle.dump(results, f)

print(f"\n{'='*70}")
print("✅ DONE")
print(f"{'='*70}")
print(f"Results  : {fp}")
print(f"Figures  : {FIGURE_DIR}/")
for i in range(1, 6): print(f"           fig{i}_*.png")
print(f"\nFinal: {our_ba:.2f}% ± {std_ba:.2f}%  |  95% CI [{ci_lo:.2f}%, {ci_hi:.2f}%]")
print(f"Benchmark: {BENCHMARK['BA']:.2f}% ± {BENCHMARK['BA_sd']:.2f}%  "
      f"(gender-matched: {BENCHMARK['BA_matched']:.2f}%)")
print(f"Implied Varghese Sp ≈ {2*BENCHMARK['BA']-BENCHMARK['Se']:.2f}%  |  "
      f"Our Sp = {our_sp:.2f}%  (+{our_sp-(2*BENCHMARK['BA']-BENCHMARK['Se']):.2f} pp)")
print("=" * 70)

