# ============================================================================
# FIGURE REGENERATION SCRIPT — v4 Results
# ============================================================================
# Loads the saved checkpoint files from 01_final_pipeline_v4.py and
# regenerates all 5 publication-quality figures at 600 DPI.
#
# USAGE:
#   1. Make sure ./final_results/ckpt_fold_*.pkl files exist
#      (produced by 01_final_pipeline_v4.py)
#   2. Run this script:  python 00_regenerate_figures.py
#   3. Figures saved to: ./final_results/figures/
#
# No PADS dataset or MiniRocket needed — uses saved predictions only.
# ============================================================================

import os, sys, subprocess, glob, pickle, warnings
import numpy as np

warnings.filterwarnings('ignore')

def install(pkg):
    try: __import__(pkg.split('[')[0].replace('-', '_'))
    except:
        subprocess.check_call([sys.executable, '-m', 'pip', 'install', pkg, '-q',
                               '--break-system-packages'],
                              stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

for pkg in ['numpy', 'matplotlib', 'scikit-learn']:
    install(pkg)

import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
from sklearn.metrics import (roc_curve, roc_auc_score, confusion_matrix,
                              balanced_accuracy_score)

# ── Config ────────────────────────────────────────────────────────────────
OUTPUT_DIR = './final_results'
FIGURE_DIR = f'{OUTPUT_DIR}/figures'
os.makedirs(FIGURE_DIR, exist_ok=True)
DPI = 600

BENCHMARK = {
    'label': 'Varghese et al. [C1]',
    'BA': 91.16, 'BA_sd': 4.92,
    'Se': 92.40, 'Se_sd': 2.64,
    'F1': 94.62, 'F1_sd': 2.21,
}

plt.rcParams.update({
    'font.family': 'DejaVu Sans', 'font.size': 9,
    'axes.titlesize': 10, 'axes.labelsize': 9,
    'xtick.labelsize': 8, 'ytick.labelsize': 8,
    'legend.fontsize': 8, 'figure.dpi': DPI, 'savefig.dpi': DPI,
    'axes.linewidth': 0.8, 'axes.spines.top': False, 'axes.spines.right': False,
    'lines.linewidth': 1.5, 'grid.linewidth': 0.5, 'grid.alpha': 0.4,
})
C = {'blue': '#2563EB', 'red': '#DC2626', 'green': '#16A34A', 'amber': '#D97706'}

def save_fig(fig, name):
    path = f'{FIGURE_DIR}/{name}.png'
    fig.savefig(path, dpi=DPI, bbox_inches='tight', facecolor='white')
    plt.close(fig)
    print(f"   💾 {path}")

# ── Load checkpoints ──────────────────────────────────────────────────────
ckpt_files = sorted(glob.glob(f'{OUTPUT_DIR}/ckpt_fold_*.pkl'))
if not ckpt_files:
    print(f"❌ No checkpoint files found in {OUTPUT_DIR}/")
    print("   Run 01_final_pipeline_v4.py first to generate checkpoints.")
    sys.exit(1)

print(f"✅ Found {len(ckpt_files)} checkpoint file(s)")

fold_results   = []
all_true_pat   = []
all_prob_pat   = []
all_pred_pat   = []
all_thresholds = []
metrics        = {'bal_acc': [], 'sens': [], 'spec': [], 'f1': [], 'auc': []}

for ck_path in ckpt_files:
    with open(ck_path, 'rb') as f:
        ck = pickle.load(f)
    fold_results.append(ck)
    all_true_pat.extend(ck['y_true'])
    all_prob_pat.extend(ck['y_prob'])
    all_pred_pat.extend(ck['y_pred'])
    all_thresholds.append(ck['th_ens'])
    for k in metrics:
        metrics[k].append(ck[k])
    print(f"   Fold {ck['fold']:2d}: BA={ck['bal_acc']*100:.2f}%  "
          f"Se={ck['sens']*100:.2f}%  Sp={ck['spec']*100:.2f}%  "
          f"AUC={ck['auc']*100:.2f}%  τ*={ck['th_ens']:.3f}")

all_true_pat = np.array(all_true_pat)
all_prob_pat = np.array(all_prob_pat)
all_pred_pat = np.array(all_pred_pat)

# ── Summary metrics ───────────────────────────────────────────────────────
our_ba  = np.mean(metrics['bal_acc']) * 100;  std_ba  = np.std(metrics['bal_acc']) * 100
our_se  = np.mean(metrics['sens'])    * 100;  std_se  = np.std(metrics['sens'])    * 100
our_sp  = np.mean(metrics['spec'])    * 100;  std_sp  = np.std(metrics['spec'])    * 100
our_f1  = np.mean(metrics['f1'])      * 100;  std_f1  = np.std(metrics['f1'])      * 100
our_auc = np.mean(metrics['auc'])     * 100;  std_auc = np.std(metrics['auc'])     * 100
mean_th = np.mean(all_thresholds)
N_FOLDS = len(fold_results)

print(f"\n{'='*60}")
print(f"  BA  : {our_ba:.2f}% ± {std_ba:.2f}%")
print(f"  Se  : {our_se:.2f}% ± {std_se:.2f}%")
print(f"  Sp  : {our_sp:.2f}% ± {std_sp:.2f}%")
print(f"  F1  : {our_f1:.2f}% ± {std_f1:.2f}%")
print(f"  AUC : {our_auc:.2f}% ± {std_auc:.2f}%")
print(f"  τ*  : {mean_th:.3f}")
print(f"{'='*60}")

fold_ba   = [fd['bal_acc']*100 for fd in fold_results]
fold_se   = [fd['sens']*100    for fd in fold_results]
fold_sp   = [fd['spec']*100    for fd in fold_results]
fold_nums = [fd['fold']        for fd in fold_results]

# ============================================================================
# FIG 1: ROC CURVE — pooled from real OOF predictions
# ============================================================================
print("\n📊 Generating figures...")
fpr_s, tpr_s, _ = roc_curve(all_true_pat, all_prob_pat)
global_auc = roc_auc_score(all_true_pat, all_prob_pat)
op_fpr = 1 - our_sp / 100
op_tpr = our_se / 100

fig, ax = plt.subplots(figsize=(3.5, 3.5))
ax.plot(fpr_s, tpr_s, color=C['blue'], linewidth=2.0,
        label=f'Proposed Method (AUC = {global_auc:.3f})')
ax.plot([0, 1], [0, 1], 'k--', linewidth=0.8, label='Random Classifier')
ax.scatter([op_fpr], [op_tpr], color=C['blue'], s=80, zorder=5,
           marker='*', linewidths=0,
           label=f'Mean OP (Se={our_se:.1f}%, Sp={our_sp:.1f}%)')
ax.annotate(f'  Se={our_se:.1f}%\n  Sp={our_sp:.1f}%',
            xy=(op_fpr, op_tpr), xytext=(op_fpr + 0.12, op_tpr - 0.12),
            fontsize=7, color=C['blue'],
            arrowprops=dict(arrowstyle='->', color=C['blue'],
                            lw=0.8, connectionstyle='arc3,rad=0.2'))
ax.set_xlim([0, 1]); ax.set_ylim([0, 1.02])
ax.set_xlabel('False Positive Rate (1 − Specificity)')
ax.set_ylabel('True Positive Rate (Sensitivity)')
ax.set_title("ROC Curve — Parkinson's Disease Detection")
ax.legend(loc='lower right', framealpha=0.9, fontsize=7.5)
ax.grid(True); fig.tight_layout()
save_fig(fig, 'fig1_roc_curve')

# ============================================================================
# FIG 2: CONFUSION MATRIX
# ============================================================================
cm = confusion_matrix(all_true_pat, all_pred_pat)
cm_norm = cm.astype(float) / cm.sum(axis=1, keepdims=True)

fig, ax = plt.subplots(figsize=(3.2, 3.0))
im = ax.imshow(cm_norm, interpolation='nearest', cmap='Blues', vmin=0, vmax=1)
plt.colorbar(im, ax=ax, fraction=0.046, pad=0.04, label='Proportion')
for i in range(2):
    for j in range(2):
        col = 'white' if cm_norm[i, j] > 0.5 else 'black'
        ax.text(j, i, f'{cm[i, j]}\n({cm_norm[i, j]*100:.1f}%)',
                ha='center', va='center', color=col, fontsize=9, fontweight='bold')
ax.set_xticks([0, 1]); ax.set_yticks([0, 1])
ax.set_xticklabels(['Predicted HC', 'Predicted PD'])
ax.set_yticklabels(['True HC', 'True PD'])
ax.set_title('Confusion Matrix (Pooled 10-Fold CV)')
fig.tight_layout()
save_fig(fig, 'fig2_confusion_matrix')

# ============================================================================
# FIG 3: METRIC COMPARISON (proposed vs Varghese)
# ============================================================================
metric_names = ['Balanced\nAccuracy', 'Sensitivity', 'Specificity', 'F1-Score', 'AUC-ROC']
our_means    = [our_ba, our_se, our_sp, our_f1, our_auc]
our_stds     = [std_ba, std_se, std_sp, std_f1, std_auc]
varg_means   = [BENCHMARK['BA'], BENCHMARK['Se'], None, BENCHMARK['F1'], None]
varg_stds    = [BENCHMARK['BA_sd'], BENCHMARK['Se_sd'], None, BENCHMARK['F1_sd'], None]

x = np.arange(len(metric_names)); w = 0.32

fig, ax = plt.subplots(figsize=(6.0, 3.8))
bars_our = ax.bar(x - w/2, our_means, w, yerr=our_stds,
                  color=C['blue'], alpha=0.85, capsize=3,
                  label='Proposed Method', error_kw={'linewidth': 1.0})

for i, (vm, vs) in enumerate(zip(varg_means, varg_stds)):
    if vm is not None:
        b = ax.bar(x[i] + w/2, vm, w, yerr=vs, color=C['red'], alpha=0.85,
                   capsize=3, error_kw={'linewidth': 1.0},
                   label='Varghese et al. [C1]' if i == 0 else '_nolegend_')
        for rect in b:
            ax.text(rect.get_x() + rect.get_width()/2, vm + vs + 0.9,
                    f'{vm:.1f}%', ha='center', va='bottom',
                    fontsize=7.0, fontweight='bold', color=C['red'])

for bar, mean, std in zip(bars_our, our_means, our_stds):
    ax.text(bar.get_x() + bar.get_width()/2, mean + std + 0.9,
            f'{mean:.1f}%', ha='center', va='bottom',
            fontsize=7.0, fontweight='bold', color=C['blue'])

for i, (vm, _) in enumerate(zip(varg_means, varg_stds)):
    if vm is None:
        ax.text(x[i] + w/2, 65.5, 'N/R', ha='center', va='bottom',
                fontsize=6.5, color='gray', style='italic')

ax.set_xticks(x); ax.set_xticklabels(metric_names)
ax.set_ylabel('Performance (%)'); ax.set_ylim([64, 107])
ax.set_title('Classification Performance — 10-Fold CV (Mean ± SD)')
ax.legend(loc='lower right', framealpha=0.9)
ax.grid(True, axis='y')
ax.yaxis.set_major_formatter(mticker.FormatStrFormatter('%.0f%%'))
fig.tight_layout()
save_fig(fig, 'fig3_metric_comparison')

# ============================================================================
# FIG 4: CROSS-VALIDATION STABILITY
# ============================================================================
varg_ba    = BENCHMARK['BA']
varg_ba_sd = BENCHMARK['BA_sd']

fig, axes = plt.subplots(1, 2, figsize=(7.0, 3.2))

ax = axes[0]
ax.plot(fold_nums, fold_ba, 'o-', color=C['blue'], markersize=5,
        linewidth=1.5, label='Balanced Accuracy')
ax.axhline(our_ba, color=C['blue'], linestyle='--', linewidth=1.0,
           alpha=0.7, label=f'Mean = {our_ba:.1f}%')
ax.axhline(varg_ba, color=C['red'], linestyle=':', linewidth=1.2,
           label=f'Varghese [C1]: {varg_ba:.2f}%')
ax.fill_between(fold_nums,
                [our_ba - std_ba] * N_FOLDS, [our_ba + std_ba] * N_FOLDS,
                alpha=0.12, color=C['blue'])
ax.fill_between(fold_nums,
                [varg_ba - varg_ba_sd] * N_FOLDS, [varg_ba + varg_ba_sd] * N_FOLDS,
                alpha=0.07, color=C['red'], label=f'±SD benchmark ({varg_ba_sd:.2f}%)')
ax.set_xlabel('Fold'); ax.set_ylabel('Balanced Accuracy (%)')
ax.set_title('Fold-level Balanced Accuracy')
ax.set_xticks(fold_nums); ax.set_ylim([70, 104])
ax.legend(fontsize=6.5, framealpha=0.9); ax.grid(True)

ax = axes[1]
ax.plot(fold_nums, fold_se, 's-', color=C['green'],
        markersize=5, linewidth=1.5, label='Sensitivity')
ax.plot(fold_nums, fold_sp, 'd-', color=C['amber'],
        markersize=5, linewidth=1.5, label='Specificity')
ax.axhline(our_se, color=C['green'], linestyle='--', linewidth=0.8, alpha=0.6)
ax.axhline(our_sp, color=C['amber'], linestyle='--', linewidth=0.8, alpha=0.6)
ax.set_xlabel('Fold'); ax.set_ylabel('Score (%)')
ax.set_title('Sensitivity vs. Specificity per Fold')
ax.set_xticks(fold_nums); ax.set_ylim([55, 107])
ax.legend(fontsize=7, framealpha=0.9); ax.grid(True)

fig.suptitle('Cross-Validation Stability Analysis', fontsize=10, y=1.01)
fig.tight_layout()
save_fig(fig, 'fig4_fold_stability')

# ============================================================================
# FIG 5: ENSEMBLE PROBABILITY DISTRIBUTION
