"""
PADS — shared data loading and preprocessing.
Imported by 01_final_pipeline.py and 02_ablation_baselines.py so that BOTH
scripts see exactly the same patients, in exactly the same order, with exactly
the same preprocessing. This is what makes the ablation's A1 baseline identical
to the headline result instead of 1.5 pp below it.

Do not edit the ordering lines marked [DETERMINISM]. They are the fix for the
bug that made the earlier results irreproducible.
"""

import os, sys, subprocess, warnings, json, pickle
from glob import glob

import numpy as np
import pandas as pd

try:
    from tqdm import tqdm
except ImportError:                      # progress bar is cosmetic
    def tqdm(x, **kw):
        return x

warnings.filterwarnings('ignore')

RANDOM_STATE = 42
N_KERNELS    = 8000
N_FOLDS      = 10
SEG_LEN      = 400

np.random.seed(RANDOM_STATE)


def install(pkg):
    try:
        __import__(pkg.split('[')[0].replace('-', '_'))
    except Exception:
        subprocess.check_call(
            [sys.executable, '-m', 'pip', 'install', pkg, '-q', '--break-system-packages'],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


def ensure_packages(extra=()):
    for pkg in ['numpy', 'pandas', 'scipy', 'scikit-learn', 'sktime', 'matplotlib', *extra]:
        install(pkg)


# ---------------------------------------------------------------- discovery
def find_file(name):
    for p in [f"/content/{name}", f"/content/drive/MyDrive/{name}",
              f"/content/drive/MyDrive/Parkinson/{name}", f"./{name}"]:
        if os.path.exists(p):
            return p
    if os.path.exists("/content/drive"):
        r = subprocess.getoutput(
            f"find /content/drive -name '{name}' -type f 2>/dev/null | head -1")
        if r.strip():
            return r.strip()
    return None


def find_data():
    import zipfile as zf
    dirs = ["./pads_data_extracted", "/content/pads_data_extracted",
            "/content/pads_extracted",
            "/content/drive/MyDrive/Parkinson/pads_data_extracted"]
    for d in dirs:
        if os.path.exists(d) and len(glob(f"{d}/**/*.txt", recursive=True)) > 10:
            return d
    zp = find_file("pads-parkinsons-disease-smartwatch-dataset-1.0.0.zip")
    if zp:
        print("Extracting PADS dataset...")
        with zf.ZipFile(zp, 'r') as z:
            z.extractall("./pads_data_extracted")
        return "./pads_data_extracted"
    raise FileNotFoundError("PADS dataset not found. Upload the zip to Colab.")


# ---------------------------------------------------------------- load
def load_pads(verbose=True):
    """Returns a dict with valid_pids, pat_labels, pat_nms, patient_segments, max_ch."""
    from scipy.signal import detrend, resample

    try:
        if not os.path.exists('/content/drive'):
            from google.colab import drive
            drive.mount('/content/drive')
    except Exception:
        pass

    data_path = find_data()
    if verbose:
        print(f"Data: {data_path}")

    # -- patient labels (PD=1, HC=0; the 114 DD participants are excluded) --
    patient_info = {}
    meta_path = find_file("subjects.csv")
    if meta_path and os.path.exists(meta_path):
        df_meta = pd.read_csv(meta_path)
        for _, r in df_meta[df_meta['label'].isin([0, 1])].iterrows():
            patient_info[str(r['id']).zfill(3)] = {
                'label': int(r['label']), 'age': r['age'], 'gender': str(r['gender'])}
    else:
        for pf in sorted(glob(f"{data_path}/**/patient_*.json", recursive=True)):
            try:
                d = json.load(open(pf))
                pid = str(d.get('id', ''))
                cond = d.get('condition', '').lower()
                lbl = (1 if "parkinson" in cond else
                       0 if any(k in cond for k in ["healthy", "control"]) else -1)
                if lbl >= 0 and pid:
                    patient_info[pid] = {'label': lbl, 'age': d.get('age', 60),
                                         'gender': str(d.get('gender', 'unknown'))}
            except Exception:
                pass
    if verbose:
        print(f"   {len(patient_info)} patients (PD + HC only; DD excluded)")

    # -- NMS questionnaire (30 binary items) --
    nms_data = {}
    for qf in sorted(glob(f"{data_path}/**/questionnaire_response_*.json", recursive=True)):
        try:
            q = json.load(open(qf))
            pid = str(q.get('subject_id', ''))
            if pid not in patient_info:
                continue
            ans = [0] * 30
            for it in q.get('item', []):
                try:
                    i = int(it.get('link_id', '99')) - 1
                    if 0 <= i < 30:
                        ans[i] = 1 if it.get('answer') else 0
                except Exception:
                    pass
            nms_data[pid] = ans
        except Exception:
            pass
    if verbose:
        print(f"   {len(nms_data)} NMS questionnaire records")

    # -- signals: drop first 50 samples, linear detrend, resample to 400 steps --
    # [DETERMINISM] sorted() — glob returns filesystem order, which is arbitrary
    s_files = sorted([f for f in glob(f"{data_path}/**/*.txt", recursive=True)
                      if "LICENSE" not in f and "README" not in f])

    patient_segments = {}
    it = tqdm(s_files, desc="   Loading segments", ncols=70) if verbose else s_files
    for fp in it:
        try:
            pid = os.path.basename(fp).split('_')[0]
            if pid not in patient_info:
                continue
            raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
            if len(raw) < 100:
                continue
            if len(raw) > 50:
                raw = raw[50:, :]
            raw = detrend(raw, axis=0)
            if raw.shape[0] > raw.shape[1]:
                raw = raw.T
            raw = resample(raw, SEG_LEN, axis=1)
            patient_segments.setdefault(pid, []).append(raw)
        except Exception:
            continue

    # [DETERMINISM] sorted() — dict iteration order follows insertion order,
    # and StratifiedKFold assigns folds by index, so patient order changes folds.
    valid_pids = np.array(sorted([p for p in patient_segments if p in patient_info]))
    pat_labels = np.array([patient_info[p]['label'] for p in valid_pids])
    pat_nms    = np.array([nms_data.get(p, [0] * 30) for p in valid_pids], dtype=np.float32)
    pat_gender = np.array([patient_info[p].get('gender', 'unknown') for p in valid_pids])
    max_ch     = max(s.shape[0] for p in valid_pids for s in patient_segments[p])
    n_seg      = sum(len(patient_segments[p]) for p in valid_pids)

    if verbose:
        print(f"   {len(valid_pids)} patients | PD={int((pat_labels==1).sum())} "
              f"| HC={int((pat_labels==0).sum())} | segments={n_seg} | channels={max_ch}")

    return dict(valid_pids=valid_pids, pat_labels=pat_labels, pat_nms=pat_nms,
                pat_gender=pat_gender, patient_segments=patient_segments,
                max_ch=max_ch, n_seg=n_seg)


# ---------------------------------------------------------------- features
def make_segments_array(patient_segments, max_ch, pids):
    segs, counts = [], []
    for pid in pids:
        cnt = len(patient_segments[pid])
        for seg in patient_segments[pid]:
            padded = np.zeros((max_ch, SEG_LEN), dtype=np.float32)
            padded[:seg.shape[0], :] = seg
            segs.append(padded)
        counts.append(cnt)
    return np.array(segs, dtype=np.float32), counts


def aggregate_patient(rocket_segs, seg_counts, with_std=True):
    """Channel-wise mean (+ std) of a patient's segment features."""
    fd = rocket_segs.shape[1]
    out_dim = fd * 2 if with_std else fd
    X = np.zeros((len(seg_counts), out_dim), dtype=np.float32)
    idx = 0
    for i, cnt in enumerate(seg_counts):
        segs = rocket_segs[idx:idx + cnt]
        X[i, :fd] = segs.mean(axis=0)
        if with_std:
            X[i, fd:] = segs.std(axis=0)
        idx += cnt
    return X


def youden_threshold(y_true, scores):
    from sklearn.metrics import roc_curve
    fpr, tpr, ths = roc_curve(y_true, scores)
    return float(ths[np.argmax(tpr - fpr)])


def wilson_ci(k, n, z=1.96):
    p = k / n
    d = 1 + z * z / n
    c = (p + z * z / (2 * n)) / d
    h = z * np.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / d
    return 100 * (c - h), 100 * (c + h)


def holm(pvals):
    p = np.asarray(pvals, dtype=float)
    order = np.argsort(p)
    m = len(p)
    adj = np.empty(m)
    running = 0.0
    for i, idx in enumerate(order):
        running = max(running, (m - i) * p[idx])
        adj[idx] = min(running, 1.0)
    return adj

# =============================================================================
# PADS — SINGLE-CELL FINAL RUN
# MiniRocket + RidgeClassifierCV + NMS ensemble, leakage-free 10-fold CV
# Headline result + ablation + classifier comparison + all figures, in one pass.
# =============================================================================
# Paste this whole thing into ONE Colab cell and run it. Nothing to upload.
#
# WHY ONE FILE IS BETTER HERE
#   MiniRocket is fitted once per fold and reused by every configuration, so the
#   headline result and the ablation's A1 are literally the same computation
#   rather than two computations that have to agree. The "two different numbers
#   for our own method" problem in the manuscript disappears by construction.
#
# WHAT MUST COME OUT (identical modelling to your cell 81)
#   Balanced Acc  87.91% ±6.08%   Sensitivity 87.25% ±8.31%
#   Specificity   88.57% ±8.79%   F1 91.39% ±5.27%   AUC 95.90% ±3.17%
#   If these do not appear, stop and tell me before anything else.
#
# TWO FIXES vs. your old ablation cell
#   1. MiniRocket now fits per fold on training segments only (was: once on all
#      data). Removes the leakage caveat.
#   2. The proposed Ridge no longer has a StandardScaler in front of it, matching
#      the headline pipeline. Your old ablation had one and the manuscript never
#      disclosed it.
#
# RUNTIME  RUN_ABLATION = False  ->  ~1-2 h   (headline only; verify 87.91 first)
#          RUN_ABLATION = True   ->  ~4-7 h   (everything)
#   Checkpoints after every fold, so interrupting and re-running is safe.
#
# SEND ME:  ./pads_final/results.json
# =============================================================================

RUN_ABLATION = True          # False = headline only (faster, run this first if unsure)
PURGE_CHECKPOINTS = True     # False only when resuming a crashed run
OUTPUT_DIR = './pads_final'

# ----------------------------------------------------------------- packages
import sys, subprocess, os, json, pickle, gc, time, warnings
from glob import glob
warnings.filterwarnings('ignore')

def _install(pkg):
    try:
        __import__(pkg.split('[')[0].replace('-', '_'))
    except Exception:
        subprocess.check_call([sys.executable, '-m', 'pip', 'install', pkg, '-q'],
                              stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

for _p in ['numpy', 'pandas', 'scipy', 'scikit-learn', 'sktime', 'matplotlib', 'xgboost', 'tqdm']:
    _install(_p)

import numpy as np
import pandas as pd
try:
    from tqdm import tqdm
except ImportError:
    def tqdm(x, **kw): return x

from scipy.signal import detrend, resample
from scipy.stats import wilcoxon
from sklearn.model_selection import StratifiedKFold, cross_val_predict
from sklearn.linear_model import RidgeClassifierCV, LogisticRegression
from sklearn.ensemble import RandomForestClassifier
from sklearn.svm import SVC
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import Pipeline
from sklearn.metrics import (balanced_accuracy_score, recall_score, f1_score,
                             roc_auc_score, roc_curve, precision_recall_curve,
                             average_precision_score, matthews_corrcoef,
                             brier_score_loss)
from sklearn.calibration import calibration_curve
from sktime.transformations.panel.rocket import MiniRocketMultivariate
from xgboost import XGBClassifier

import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

# ----------------------------------------------------------------- config
RANDOM_STATE = 42
N_KERNELS    = 8000
N_FOLDS      = 10
SEG_LEN      = 400
DPI          = 600
np.random.seed(RANDOM_STATE)

FIGURE_DIR = f'{OUTPUT_DIR}/figures'
os.makedirs(FIGURE_DIR, exist_ok=True)
if PURGE_CHECKPOINTS:
    for _f in os.listdir(OUTPUT_DIR):
        if _f.startswith('ckpt_fold_'):
            os.remove(os.path.join(OUTPUT_DIR, _f))

BENCHMARK = {'BA': 91.16, 'BA_sd': 4.92, 'Se': 92.40, 'Se_sd': 2.64,
             'F1': 94.62, 'F1_sd': 2.21, 'BA_matched': 89.25}
BENCH_SP_DERIVED = 2 * BENCHMARK['BA'] - BENCHMARK['Se']

plt.rcParams.update({
    'font.family': 'DejaVu Sans', 'font.size': 9, 'axes.titlesize': 10,
    'axes.labelsize': 9, 'xtick.labelsize': 8, 'ytick.labelsize': 8,
    'legend.fontsize': 8, 'figure.dpi': DPI, 'savefig.dpi': DPI,
    'axes.linewidth': 0.8, 'axes.spines.top': False, 'axes.spines.right': False,
    'lines.linewidth': 1.5, 'grid.linewidth': 0.5, 'grid.alpha': 0.4})
C = {'blue': '#2563EB', 'red': '#DC2626', 'green': '#16A34A', 'amber': '#D97706'}

def save_fig(fig, name):
    p = f'{FIGURE_DIR}/{name}.png'
    fig.savefig(p, dpi=DPI, bbox_inches='tight', facecolor='white')
    plt.close(fig)
    print(f"   saved {p}")

def youden_threshold(y_true, scores):
    fpr, tpr, ths = roc_curve(y_true, scores)
    return float(ths[np.argmax(tpr - fpr)])

def wilson_ci(k, n, z=1.96):
    p = k / n; d = 1 + z * z / n
    c = (p + z * z / (2 * n)) / d
    h = z * np.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / d
    return 100 * (c - h), 100 * (c + h)

def holm(pvals):
    p = np.asarray(pvals, float); order = np.argsort(p); m = len(p)
    adj = np.empty(m); run = 0.0
    for i, idx in enumerate(order):
        run = max(run, (m - i) * p[idx]); adj[idx] = min(run, 1.0)
    return adj

t_start = time.time()
print("=" * 74)
print("PADS FINAL RUN — headline + ablation, leakage-free, deterministic")
print("=" * 74)

# ================================================================= DATA
try:
    if not os.path.exists('/content/drive'):
        from google.colab import drive; drive.mount('/content/drive')
except Exception:
    pass

def find_file(name):
    for p in [f"/content/{name}", f"/content/drive/MyDrive/{name}",
              f"/content/drive/MyDrive/Parkinson/{name}", f"./{name}"]:
        if os.path.exists(p): return p
    if os.path.exists("/content/drive"):
        r = subprocess.getoutput(f"find /content/drive -name '{name}' -type f 2>/dev/null | head -1")
        if r.strip(): return r.strip()
    return None

def find_data():
    import zipfile as zf
    for d in ["./pads_data_extracted", "/content/pads_data_extracted",
              "/content/pads_extracted", "/content/drive/MyDrive/Parkinson/pads_data_extracted"]:
        if os.path.exists(d) and len(glob(f"{d}/**/*.txt", recursive=True)) > 10:
            return d
    zp = find_file("pads-parkinsons-disease-smartwatch-dataset-1.0.0.zip")
    if zp:
        print("Extracting PADS dataset...")
        with zf.ZipFile(zp, 'r') as z: z.extractall("./pads_data_extracted")
        return "./pads_data_extracted"
    raise FileNotFoundError("PADS dataset not found. Upload the zip to Colab.")

data_path = find_data()
print(f"Data: {data_path}")

# -- labels: PD=1, HC=0; the 114 differential-diagnosis participants are excluded
patient_info = {}
meta_path = find_file("subjects.csv")
if meta_path and os.path.exists(meta_path):
    df_meta = pd.read_csv(meta_path)
    for _, r in df_meta[df_meta['label'].isin([0, 1])].iterrows():
        patient_info[str(r['id']).zfill(3)] = {'label': int(r['label']),
                                               'age': r['age'], 'gender': str(r['gender'])}
else:
    for pf in sorted(glob(f"{data_path}/**/patient_*.json", recursive=True)):
        try:
            d = json.load(open(pf)); pid = str(d.get('id', ''))
            cond = d.get('condition', '').lower()
            lbl = (1 if "parkinson" in cond else
                   0 if any(k in cond for k in ["healthy", "control"]) else -1)
            if lbl >= 0 and pid:
                patient_info[pid] = {'label': lbl, 'age': d.get('age', 60),
                                     'gender': str(d.get('gender', 'unknown'))}
        except Exception: pass
print(f"   {len(patient_info)} patients (PD + HC only; DD excluded)")

# -- NMS questionnaire, 30 binary items
nms_data = {}
for qf in sorted(glob(f"{data_path}/**/questionnaire_response_*.json", recursive=True)):
    try:
        q = json.load(open(qf)); pid = str(q.get('subject_id', ''))
        if pid not in patient_info: continue
        ans = [0] * 30
        for it in q.get('item', []):
            try:
                i = int(it.get('link_id', '99')) - 1
                if 0 <= i < 30: ans[i] = 1 if it.get('answer') else 0
            except Exception: pass
        nms_data[pid] = ans
    except Exception: pass
print(f"   {len(nms_data)} NMS questionnaire records")

# -- signals: drop first 50 samples, linear detrend, resample to 400 steps
# [DETERMINISM] sorted() — glob returns filesystem order, which is arbitrary.
s_files = sorted([f for f in glob(f"{data_path}/**/*.txt", recursive=True)
                  if "LICENSE" not in f and "README" not in f])

patient_segments = {}
for fp in tqdm(s_files, desc="   Loading segments", ncols=70):
    try:
        pid = os.path.basename(fp).split('_')[0]
        if pid not in patient_info: continue
        raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
        if len(raw) < 100: continue
        if len(raw) > 50: raw = raw[50:, :]
        raw = detrend(raw, axis=0)
        if raw.shape[0] > raw.shape[1]: raw = raw.T
        raw = resample(raw, SEG_LEN, axis=1)
        patient_segments.setdefault(pid, []).append(raw)
    except Exception: continue

# [DETERMINISM] sorted() — dict order follows insertion order, and StratifiedKFold
# assigns folds by index, so patient order silently changes every fold.
valid_pids = np.array(sorted([p for p in patient_segments if p in patient_info]))
pat_labels = np.array([patient_info[p]['label'] for p in valid_pids])
pat_nms    = np.array([nms_data.get(p, [0] * 30) for p in valid_pids], dtype=np.float32)
max_ch     = max(s.shape[0] for p in valid_pids for s in patient_segments[p])
n_seg      = sum(len(patient_segments[p]) for p in valid_pids)
POS_RATIO  = float((pat_labels == 0).sum() / (pat_labels == 1).sum())

print(f"   {len(valid_pids)} patients | PD={int((pat_labels==1).sum())} "
      f"| HC={int((pat_labels==0).sum())} | segments={n_seg} | channels={max_ch}")

def segments_array(pids):
    segs, counts = [], []
    for pid in pids:
        counts.append(len(patient_segments[pid]))
        for seg in patient_segments[pid]:
            padded = np.zeros((max_ch, SEG_LEN), dtype=np.float32)
            padded[:seg.shape[0], :] = seg
            segs.append(padded)
    return np.array(segs, dtype=np.float32), counts

def aggregate_patient(rocket_segs, seg_counts, with_std=True):
    fd = rocket_segs.shape[1]
    X = np.zeros((len(seg_counts), fd * 2 if with_std else fd), dtype=np.float32)
    idx = 0
    for i, cnt in enumerate(seg_counts):
        s = rocket_segs[idx:idx + cnt]
        X[i, :fd] = s.mean(axis=0)
        if with_std: X[i, fd:] = s.std(axis=0)
        idx += cnt
    return X

# ================================================================= MODELS
def ridge_raw():                       # the proposed model — NO scaler
    return RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced')
def ridge_scaled():                    # scaling sanity check only
    return Pipeline([('sc', StandardScaler()), ('m', ridge_raw())])
def lr_model():
    return Pipeline([('sc', StandardScaler()),
                     ('m', LogisticRegression(C=1.0, class_weight='balanced',
                                              max_iter=2000, random_state=RANDOM_STATE))])
def rf_model():
    return RandomForestClassifier(n_estimators=300, class_weight='balanced',
                                  n_jobs=-1, random_state=RANDOM_STATE)
def xgb_model():
    return XGBClassifier(n_estimators=300, max_depth=4, learning_rate=0.05,
                         scale_pos_weight=POS_RATIO, eval_metric='logloss',
                         random_state=RANDOM_STATE, verbosity=0, n_jobs=-1)
def svm_model():
    return Pipeline([('sc', StandardScaler()),
                     ('m', SVC(kernel='rbf', class_weight='balanced', probability=True,
                               C=1.0, random_state=RANDOM_STATE))])
def nms_model():
    return Pipeline([('sc', StandardScaler()),
                     ('lr', LogisticRegression(C=1.0, class_weight='balanced',
                                               max_iter=1000, random_state=RANDOM_STATE))])

# name, model factory (None = questionnaire only), feature set, use NMS branch
HEAD = 'A1_Full_Signal+NMS'
CONFIGS = [(HEAD, ridge_raw, 'full', True)]
if RUN_ABLATION:
    CONFIGS += [
        ('A2_Signal_Only',        ridge_raw,    'full', False),
        ('A3_NMS_Only',           None,         None,   True),
        ('A4_MeanOnly_No_Std',    ridge_raw,    'mean', True),
        ('B0_Ridge_Scaled',       ridge_scaled, 'full', True),
        ('B1_LogisticRegression', lr_model,     'full', True),
        ('B2_RandomForest',       rf_model,     'full', True),
        ('B3_XGBoost',            xgb_model,    'full', True),
        ('B4_SVM_RBF',            svm_model,    'full', True),
    ]
CONFIG_NAMES = [c[0] for c in CONFIGS]

def scores_from(model_fn, X_tr, y_tr, X_te, inner_cv):
    """Fit; return (train OOF score, test score). Decision functions are sigmoid-squashed."""
    m = model_fn(); m.fit(X_tr, y_tr)
    if hasattr(m, 'decision_function'):
        oof = cross_val_predict(model_fn(), X_tr, y_tr, cv=inner_cv, method='decision_function')
        return 1 / (1 + np.exp(-oof)), 1 / (1 + np.exp(-m.decision_function(X_te)))
    oof = cross_val_predict(model_fn(), X_tr, y_tr, cv=inner_cv, method='predict_proba')[:, 1]
    return oof, m.predict_proba(X_te)[:, 1]

# ================================================================= CV LOOP
outer_cv = StratifiedKFold(n_splits=N_FOLDS, shuffle=True, random_state=RANDOM_STATE)
inner_cv = StratifiedKFold(n_splits=5,       shuffle=True, random_state=RANDOM_STATE)

results = {n: {'bal_acc': [], 'sens': [], 'spec': [], 'f1': [], 'auc': []} for n in CONFIG_NAMES}
head_folds, all_true, all_prob, all_pred, all_th = [], [], [], [], []
feat_dim, t_fold = None, []

print("\n" + "=" * 74)
print(f"10-FOLD STRATIFIED CV  |  {len(CONFIGS)} configuration(s) per fold")
print("=" * 74)

for fold, (tr_idx, te_idx) in enumerate(outer_cv.split(valid_pids, pat_labels), 1):
    ck_path = f'{OUTPUT_DIR}/ckpt_fold_{fold}.pkl'
    ck = pickle.load(open(ck_path, 'rb')) if os.path.exists(ck_path) else None
    if ck and all(n in ck['configs'] for n in CONFIG_NAMES):
        for n in CONFIG_NAMES:
            for k in results[n]:
                results[n][k].append(ck['configs'][n][k])
        head_folds.append(ck['head']); feat_dim = ck.get('feat_dim', feat_dim)
        all_true.extend(ck['head']['y_true']); all_prob.extend(ck['head']['y_prob'])
        all_pred.extend(ck['head']['y_pred']); all_th.append(ck['head']['th'])
        print(f"FOLD {fold}/{N_FOLDS} — from checkpoint | "
              f"BA={ck['head']['bal_acc']*100:.2f}%")
        continue

    t0 = time.time()
    print(f"\nFOLD {fold}/{N_FOLDS}")
    tr_pids, te_pids = valid_pids[tr_idx], valid_pids[te_idx]
    y_tr, y_te       = pat_labels[tr_idx], pat_labels[te_idx]
    nms_tr, nms_te   = pat_nms[tr_idx],    pat_nms[te_idx]

    # ---- [LEAKAGE POINT 1] MiniRocket fitted on TRAINING segments only,
    #      computed ONCE and reused by every configuration in this fold.
    print(f"   MiniRocket {N_KERNELS//1000}K kernels (training segments only)...")
    tr_segs, tr_counts = segments_array(tr_pids)
    te_segs, te_counts = segments_array(te_pids)
    rocket = MiniRocketMultivariate(num_kernels=N_KERNELS,
                                    random_state=RANDOM_STATE, n_jobs=-1)
    R_tr = rocket.fit_transform(tr_segs)
    R_tr = R_tr.values if hasattr(R_tr, 'values') else np.array(R_tr)
    del tr_segs; gc.collect()
    R_te = rocket.transform(te_segs)
    R_te = R_te.values if hasattr(R_te, 'values') else np.array(R_te)
    del te_segs; gc.collect()
    feat_dim = R_tr.shape[1]

    F = {'full': (aggregate_patient(R_tr, tr_counts, True),
                  aggregate_patient(R_te, te_counts, True))}
    if RUN_ABLATION:
        F['mean'] = (aggregate_patient(R_tr, tr_counts, False),
                     aggregate_patient(R_te, te_counts, False))
    del R_tr, R_te; gc.collect()

    # ---- questionnaire branch, computed once and shared
    nms_oof, nms_te_prob = scores_from(nms_model, nms_tr, y_tr, nms_te, inner_cv)

    fold_cfgs, head_pack = {}, None
    for name, model_fn, featset, use_nms in CONFIGS:
        if model_fn is None:
            oof_ens, ens_te = nms_oof, nms_te_prob
        else:
            X_tr, X_te = F[featset]
            sig_oof, sig_te = scores_from(model_fn, X_tr, y_tr, X_te, inner_cv)
            if use_nms:
                oof_ens = (sig_oof + nms_oof) / 2.0        # [LEAKAGE POINT 2]
                ens_te  = (sig_te + nms_te_prob) / 2.0
            else:
                oof_ens, ens_te = sig_oof, sig_te

        th = youden_threshold(y_tr, oof_ens)               # training OOF only
        y_pred = (ens_te >= th).astype(int)
        vals = {'bal_acc': balanced_accuracy_score(y_te, y_pred),
                'sens': recall_score(y_te, y_pred, pos_label=1, zero_division=0),
                'spec': recall_score(y_te, y_pred, pos_label=0, zero_division=0),
                'f1':   f1_score(y_te, y_pred, zero_division=0),
                'auc':  roc_auc_score(y_te, ens_te)}
        fold_cfgs[name] = vals
        for k, v in vals.items():
            results[name][k].append(v)
        if name == HEAD:
            head_pack = dict(vals, fold=fold, th=float(th), n_test=int(len(y_te)),
                             y_true=[int(v) for v in y_te],
                             y_prob=[float(v) for v in ens_te],
                             y_pred=[int(v) for v in y_pred])
        marker = '  <- headline' if name == HEAD else ''
        print(f"      {name:<24} BA={vals['bal_acc']*100:6.2f}%{marker}")

    dt = time.time() - t0; t_fold.append(dt)
    pickle.dump({'configs': fold_cfgs, 'head': head_pack, 'feat_dim': feat_dim},
                open(ck_path, 'wb'))
    head_folds.append(head_pack)
    all_true.extend(head_pack['y_true']); all_prob.extend(head_pack['y_prob'])
    all_pred.extend(head_pack['y_pred']); all_th.append(head_pack['th'])
    print(f"   fold done in {dt/60:.1f} min")
    del F; gc.collect()

all_true = np.array(all_true); all_prob = np.array(all_prob)
all_pred = np.array(all_pred); all_th = np.array(all_th)

# ================================================================= HEADLINE
def ms(key):
    # identical arithmetic to `agg` below, so the headline numbers and the
    # A1 row are bit-identical rather than merely equal to two decimals
    v = np.array(results[HEAD][key])
    return np.mean(v) * 100, np.std(v, ddof=0) * 100, np.std(v, ddof=1) * 100

print("\n" + "=" * 74)
print("HEADLINE RESULTS  (= configuration A1)")
print("=" * 74)
print(f"{'Metric':<18}{'Mean':>9}{'SD(n)':>9}{'SD(n-1)':>10}")
print("-" * 46)
summary = {}
for k, lbl in [('bal_acc', 'Balanced Acc'), ('sens', 'Sensitivity'),
               ('spec', 'Specificity'), ('f1', 'F1-Score'), ('auc', 'AUC-ROC')]:
    m, s0, s1 = ms(k); summary[k] = {'mean': m, 'sd_n': s0, 'sd_n1': s1}
    print(f"{lbl:<18}{m:>8.2f}%{s0:>8.2f}%{s1:>9.2f}%")
print(f"\ntau*: mean={all_th.mean():.3f}  SD={all_th.std(ddof=0):.3f}  "
      f"range {all_th.min():.3f}-{all_th.max():.3f}")

tp = int(((all_true == 1) & (all_pred == 1)).sum())
fn = int(((all_true == 1) & (all_pred == 0)).sum())
tn = int(((all_true == 0) & (all_pred == 0)).sum())
fp = int(((all_true == 0) & (all_pred == 1)).sum())
pool_se, pool_sp = tp / (tp + fn), tn / (tn + fp)
pool_ba = 0.5 * (pool_se + pool_sp)
pool_f1 = 2 * tp / (2 * tp + fp + fn)
mcc = matthews_corrcoef(all_true, all_pred)
se_lo, se_hi = wilson_ci(tp, tp + fn)
sp_lo, sp_hi = wilson_ci(tn, tn + fp)
pooled_auc = roc_auc_score(all_true, all_prob)
ap = average_precision_score(all_true, all_prob)
brier = brier_score_loss(all_true, all_prob)

print(f"\nPOOLED  TN={tn}  FP={fp}  FN={fn}  TP={tp}")
print(f"  Se={pool_se*100:.2f}% (Wilson {se_lo:.1f}-{se_hi:.1f})   "
      f"Sp={pool_sp*100:.2f}% (Wilson {sp_lo:.1f}-{sp_hi:.1f})")
print(f"  BA={pool_ba*100:.2f}%  F1={pool_f1*100:.2f}%  MCC={mcc:.4f}")
print(f"  pooled AUC={pooled_auc*100:.2f}%  AvgPrecision={ap*100:.2f}%  Brier={brier:.4f}")

print("\nBootstrap 95% CI (2000 patient-level resamples, percentile, seed 42)...")
np.random.seed(RANDOM_STATE)
boot = []
for _ in range(2000):
    idx = np.random.choice(len(all_true), len(all_true), replace=True)
    if len(np.unique(all_true[idx])) < 2: continue
    boot.append(balanced_accuracy_score(all_true[idx], all_pred[idx]) * 100)
ci_lo, ci_hi = np.percentile(boot, [2.5, 97.5])
print(f"  95% CI: [{ci_lo:.2f}%, {ci_hi:.2f}%]   "
      f"benchmark 91.16 inside: {'YES' if ci_lo <= 91.16 <= ci_hi else 'NO'}")

print("\nScreening performance (pooled Se/Sp; PPV range from the Sp Wilson CI)")
print(f"{'Prev':>6}{'PPV':>9}{'PPV range':>16}{'NPV':>9}{'flag/1000':>11}{'ref/case':>10}")
print("-" * 62)
screening = {}
for pi in (0.003, 0.01, 0.02):
    ppv = lambda sp_: pool_se * pi / (pool_se * pi + (1 - sp_) * (1 - pi)) * 100
    p_hat, p_lo, p_hi = ppv(pool_sp), ppv(sp_lo / 100), ppv(sp_hi / 100)
    npv = pool_sp * (1 - pi) / (pool_sp * (1 - pi) + (1 - pool_se) * pi) * 100
    n_pd = 1000 * pi; tpk, fpk = n_pd * pool_se, (1000 - n_pd) * (1 - pool_sp)
    screening[f"{pi:.3f}"] = {'PPV': p_hat, 'PPV_lo': p_lo, 'PPV_hi': p_hi, 'NPV': npv,
                              'flagged_per_1000': tpk + fpk,
                              'referrals_per_case': (tpk + fpk) / tpk}
    print(f"{pi*100:>5.1f}%{p_hat:>8.1f}%{f'{p_lo:.1f}-{p_hi:.1f}%':>16}"
          f"{npv:>8.2f}%{tpk+fpk:>11.1f}{(tpk+fpk)/tpk:>10.1f}")

ba_m, sp_m = summary['bal_acc']['mean'], summary['spec']['mean']
print(f"\nBenchmark BA 91.16 vs ours {ba_m:.2f}  -> {ba_m-91.16:+.2f} pp")
print(f"Benchmark gender-matched 89.25 vs ours {ba_m:.2f}  -> {ba_m-89.25:+.2f} pp")
print(f"Benchmark derived Sp {BENCH_SP_DERIVED:.2f} vs ours {sp_m:.2f}  "
      f"-> {sp_m-BENCH_SP_DERIVED:+.2f} pp")

print(f"\n{'Fold':>4}{'BA':>9}{'Se':>9}{'Sp':>9}{'F1':>9}{'AUC':>9}{'tau*':>8}")
print("-" * 60)
for h in head_folds:
    print(f"{h['fold']:>4}{h['bal_acc']*100:>8.2f}%{h['sens']*100:>8.2f}%"
          f"{h['spec']*100:>8.2f}%{h['f1']*100:>8.2f}%{h['auc']*100:>8.2f}%{h['th']:>8.3f}")

# ================================================================= ABLATION
