# =====================================================================
import os, sys, zipfile, subprocess, shutil, numpy as np, pandas as pd
from glob import glob
from collections import Counter
from scipy.signal import detrend

ZIP_NAME  = "pads-parkinsons-disease-smartwatch-dataset-1.0.0.zip"
EXTRACT   = "/content/pads_data_extracted"
DRIVE_DIR = "/content/drive/MyDrive/Parkinson"
# PhysioNet acik erisim; asagidaki iki yol da denenir.
ZIP_URL   = ("https://physionet.org/static/published-projects/"
             "parkinsons-disease-smartwatch/" + ZIP_NAME)
FILES_URL = "https://physionet.org/files/parkinsons-disease-smartwatch/1.0.0/"

MIN_FILES = 200

def sig_files(d):
    return sorted([f for f in glob(f"{d}/**/*.txt", recursive=True)
                   if "LICENSE" not in f and "README" not in f])

def validate(d):
    fs = sig_files(d)
    if len(fs) < MIN_FILES:
        return len(fs), False
    for fp in fs[:5]:
        try:
            raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
            if raw.ndim == 2 and raw.shape[0] >= 100 and raw.shape[1] >= 2:
                return len(fs), True
        except Exception:
            continue
    return len(fs), False

# --- 0) Drive -------------------------------------------------------
if not os.path.exists("/content/drive/MyDrive"):
    try:
        from google.colab import drive; drive.mount("/content/drive")
    except Exception as e:
        print(f"Drive yok ({e}) — zip yedeklenmeyecek.")

# --- 1) Zaten var mi? -----------------------------------------------
n, ok = validate(EXTRACT)
if ok:
    print(f"Cikarilmis veri zaten var: {EXTRACT} ({n} txt)")
else:
    # --- 2) Zip: once Drive, sonra internet -------------------------
    local_zip = f"/content/{ZIP_NAME}"
    drive_zip = f"{DRIVE_DIR}/{ZIP_NAME}"
    if os.path.exists(drive_zip) and os.path.getsize(drive_zip) > 10e6:
        print(f"Zip Drive'da bulundu, kopyalaniyor: {drive_zip}")
        shutil.copy(drive_zip, local_zip)
    elif not (os.path.exists(local_zip) and os.path.getsize(local_zip) > 10e6):
        print(f"PhysioNet'ten indiriliyor:\n  {ZIP_URL}")
        subprocess.run(["wget", "-q", "--show-progress", "-O", local_zip, ZIP_URL])
        # HTML hata sayfasi mi geldi? (zip magic = 'PK')
        good = (os.path.exists(local_zip) and os.path.getsize(local_zip) > 10e6
                and open(local_zip, "rb").read(2) == b"PK")
        if not good:
            print("  Zip URL calismadi, dosya dizini uzerinden cekiliyor "
                  "(daha yavas)...")
            if os.path.exists(local_zip):
                os.remove(local_zip)
            os.makedirs(EXTRACT, exist_ok=True)
            subprocess.run(["wget", "-q", "--show-progress", "-r", "-N", "-c", "-np",
                            "-nH", "--cut-dirs=3", "-P", EXTRACT, FILES_URL])
            local_zip = None

    if local_zip and os.path.exists(local_zip):
        print("Aciliyor...")
        with zipfile.ZipFile(local_zip, "r") as zf:
            zf.extractall(EXTRACT)
        # gelecekte tekrar inmesin diye Drive'a kopyala
        try:
            os.makedirs(DRIVE_DIR, exist_ok=True)
            if not os.path.exists(f"{DRIVE_DIR}/{ZIP_NAME}"):
                shutil.copy(local_zip, f"{DRIVE_DIR}/{ZIP_NAME}")
                print(f"Zip Drive'a kopyalandi: {DRIVE_DIR}/{ZIP_NAME}")
        except Exception as e:
            print(f"Drive'a kopyalanamadi ({e}) — sorun degil.")

    n, ok = validate(EXTRACT)
    if not ok:
        found = sorted({os.path.dirname(f) for f in sig_files(EXTRACT)})[:10]
        raise SystemExit(
            f"Veri hazirlanamadi ({n} txt bulundu). Bulunan klasorler: {found}\n"
            f"PhysioNet erisilemiyorsa zipi elle indirip Colab'a yukleyin.")

data_path = EXTRACT
files = sig_files(data_path)
print(f"\nVeri: {data_path}  |  {len(files)} sinyal dosyasi")

# --- 3) HER dosyada kac sayisal sutun var? --------------------------
# Final run'daki satirin birebir aynisi:
#   raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
counts, by_ncol, sample_raw, sample_fp, skipped = Counter(), {}, None, None, 0
for fp in files:
    try:
        raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
        if raw.ndim != 2 or raw.shape[0] < 100:
            skipped += 1; continue
        counts[raw.shape[1]] += 1
        by_ncol.setdefault(raw.shape[1], fp)
        if sample_raw is None:
            sample_raw, sample_fp = raw, fp
    except Exception:
        skipped += 1

print("\n" + "=" * 64)
print("1) Sayisal sutun sayisi dagilimi (select_dtypes sonrasi)")
print("=" * 64)
if not counts:
    raise SystemExit(f"Hicbir dosya okunamadi ({skipped} atlandi).")
for ncol, k in sorted(counts.items()):
    print(f"   {ncol} sutun  ->  {k} dosya      ornek: {os.path.basename(by_ncol[ncol])}")
print(f"\n   toplam okunan: {sum(counts.values())}   atlanan: {skipped}")
print(f"   max_ch (kodun kullandigi deger) = {max(counts)}")
