    print(f"{pi*100:>5.1f}%{p_hat:>8.1f}%{f'{p_lo:.1f}-{p_hi:.1f}%':>16}"
          f"{npv:>8.2f}%{tpk+fpk:>11.1f}{(tpk+fpk)/tpk:>10.1f}")

