def youden_threshold(y_true, scores):
    fpr, tpr, ths = roc_curve(y_true, scores)
    return float(ths[np.argmax(tpr - fpr)])


# ================================================================= BOLUM A — kalibrasyon
R = pickle.load(open(f'{RUN_DIR}/raw_predictions.pkl', 'rb'))
yA = np.asarray(R['all_true']).astype(float)
pA = np.clip(np.asarray(R['all_prob']).astype(float), 1e-6, 1 - 1e-6)
lp = np.log(pA / (1 - pA))

def _logit_fit(X, y, offset=None, iters=100):
    """Cezasiz lojistik regresyon (Newton-Raphson)."""
    X = np.column_stack([np.ones(len(y))] + ([X] if X is not None else []))
    off = np.zeros(len(y)) if offset is None else offset
    b = np.zeros(X.shape[1])
    for _ in range(iters):
        eta = X @ b + off; mu = 1 / (1 + np.exp(-eta))
        W = mu * (1 - mu); g = X.T @ (y - mu); H = X.T @ (X * W[:, None]) + 1e-8 * np.eye(X.shape[1])
        step = np.clip(np.linalg.solve(H, g), -5, 5); b += step
        if np.max(np.abs(step)) < 1e-10: break
    return b

citl  = _logit_fit(None, yA, offset=lp)[0]          # egim 1'e sabit: kalibrasyon-in-the-large
slope = _logit_fit(lp, yA)[1]                       # kalibrasyon egimi
