if RUN_PART_B:
    # ================================================================= DATA
    def find_file(name):
        for p in [f"/content/{name}", f"/content/drive/MyDrive/{name}",
                  f"/content/drive/MyDrive/Parkinson/{name}", f"./{name}"]:
            if os.path.exists(p): return p
        if os.path.exists("/content/drive"):
            r = subprocess.getoutput(f"find /content/drive -name '{name}' -type f 2>/dev/null | head -1")
            if r.strip(): return r.strip()
        return None

    def find_data():
        import zipfile as zf
        for d in ["./pads_data_extracted", "/content/pads_data_extracted",
                  "/content/pads_extracted", "/content/drive/MyDrive/Parkinson/pads_data_extracted"]:
            if os.path.exists(d) and len(glob(f"{d}/**/*.txt", recursive=True)) > 10:
                return d
        zp = find_file("pads-parkinsons-disease-smartwatch-dataset-1.0.0.zip")
        if zp:
            print("Extracting PADS dataset (to local disk — fast, and re-extractable)...")
            with zf.ZipFile(zp, 'r') as z: z.extractall("./pads_data_extracted")
            return "./pads_data_extracted"
        raise FileNotFoundError("PADS dataset not found. Upload the zip to Colab or Drive.")

    data_path = find_data()
    print(f"Data: {data_path}")

    # -- labels: PD=1, HC=0; the 114 differential-diagnosis participants are excluded
    #
    # [FIX 2] Labels come from the dataset's own patient_*.json, never from a
    # subjects.csv found elsewhere in Drive. Matching is EXACT, not substring:
    # `"parkinson" in cond` also matches "Atypical Parkinsonism".
    PD_CONDITIONS = {"parkinson", "parkinsons", "parkinson's",
                     "parkinson disease", "parkinsons disease", "parkinson's disease"}
    HC_CONDITIONS = {"healthy", "healthy control", "healthy controls", "control"}

    def _norm(s):
        return " ".join(str(s).strip().lower().replace("\u2019", "'").split())

    def label_of(cond):
        c = _norm(cond)
        if c in PD_CONDITIONS: return 1
        if c in HC_CONDITIONS: return 0
        return -1

    from collections import Counter as _Counter
    patient_info, _cond_map = {}, _Counter()
    _pfiles = sorted(glob(f"{data_path}/**/patient_*.json", recursive=True))
    if not _pfiles:
        raise FileNotFoundError("No patient_*.json under data_path — wrong folder?")
    for pf in _pfiles:
        try:
            d = json.load(open(pf)); pid = str(d.get('id', ''))
            cond = d.get('condition', '')
            lbl = label_of(cond)
            _cond_map[(_norm(cond), lbl)] += 1
            if lbl >= 0 and pid:
                patient_info[pid] = {'label': lbl, 'age': d.get('age', 60),
                                     'gender': str(d.get('gender', 'unknown'))}
        except Exception: pass

    print("   condition -> label mapping (inspect this):")
    for (c, l), k in sorted(_cond_map.items(), key=lambda x: -x[1]):
        tag = {1: 'PD ', 0: 'HC ', -1: 'excluded'}[l]
        print(f"      {k:4d}  {tag:9s} {c!r}")
    _npd = sum(1 for v in patient_info.values() if v['label'] == 1)
    _nhc = sum(1 for v in patient_info.values() if v['label'] == 0)
    print(f"   {len(patient_info)} patients (PD={_npd}, HC={_nhc}; DD excluded)")
    assert (_npd, _nhc) == (276, 79), (
        f"Expected 276 PD / 79 HC, got {_npd}/{_nhc}. Check the mapping printed "
        f"above before running anything else.")

    # -- NMS questionnaire, 30 binary items
    nms_data = {}
    for qf in sorted(glob(f"{data_path}/**/questionnaire_response_*.json", recursive=True)):
        try:
            q = json.load(open(qf)); pid = str(q.get('subject_id', ''))
            if pid not in patient_info: continue
            ans = [0] * 30
            for it in q.get('item', []):
                try:
                    i = int(it.get('link_id', '99')) - 1
                    if 0 <= i < 30: ans[i] = 1 if it.get('answer') else 0
                except Exception: pass
            nms_data[pid] = ans
        except Exception: pass
    print(f"   {len(nms_data)} NMS questionnaire records")

    # -- signals: drop first 50 samples, linear detrend, resample to 400 steps
    # [DETERMINISM] sorted() — glob returns filesystem order, which is arbitrary.
    # [FIX 3] SHA256SUMS.txt is a .txt with 12,689 rows and no numeric columns.
    _SKIP = ("LICENSE", "README", "SHA256SUMS", "RECORDS")
    s_files = sorted([f for f in glob(f"{data_path}/**/*.txt", recursive=True)
                      if not any(s in os.path.basename(f).upper() for s in _SKIP)])
    print(f"   {len(s_files)} signal files")

    patient_segments = {}
    _bad_shape = []          # files whose column count is not what we expect
    for fp in tqdm(s_files, desc="   Loading segments", ncols=70):
        try:
            pid = os.path.basename(fp).split('_')[0]
            if pid not in patient_info: continue
            raw = pd.read_csv(fp, header=None).select_dtypes(include=[np.number]).values
            if len(raw) < 100: continue
            # [FIX 1] Column 0 is time: strictly monotone, r(index) = 1.0000 in every
            # one of the 10,318 files. select_dtypes keeps it because it is numeric.
            # NOTE: recorded rather than raised, because the enclosing `except
            # Exception: continue` would swallow an exception and silently drop the
            # file. Anything collected here is reported loudly after the loop.
            if DROP_TIME_COL:
                if raw.shape[1] != N_CHANNELS + 1:
                    _bad_shape.append((fp, raw.shape))
                    continue
                raw = raw[:, 1:]
            if len(raw) > 50: raw = raw[50:, :]
            raw = detrend(raw, axis=0)
            if raw.shape[0] > raw.shape[1]: raw = raw.T
            raw = resample(raw, SEG_LEN, axis=1)
            patient_segments.setdefault(pid, []).append(raw)
        except Exception: continue

    if _bad_shape:
        print(f"   !! {len(_bad_shape)} file(s) with an unexpected column count:")
        for fp, sh in _bad_shape[:5]:
            print(f"      {sh}  {os.path.basename(fp)}")
        raise SystemExit("Unexpected channel layout — stop and inspect before running.")

    # [DETERMINISM] sorted() — dict order follows insertion order, and StratifiedKFold
    # assigns folds by index, so patient order silently changes every fold.
    valid_pids = np.array(sorted([p for p in patient_segments if p in patient_info]))
    pat_labels = np.array([patient_info[p]['label'] for p in valid_pids])
    pat_nms    = np.array([nms_data.get(p, [0] * 30) for p in valid_pids], dtype=np.float32)
    max_ch     = max(s.shape[0] for p in valid_pids for s in patient_segments[p])
    min_ch     = min(s.shape[0] for p in valid_pids for s in patient_segments[p])
    n_seg      = sum(len(patient_segments[p]) for p in valid_pids)
    if DROP_TIME_COL:
        assert max_ch == min_ch == N_CHANNELS, (
            f"channels must be exactly {N_CHANNELS} after dropping the time column, "
            f"got min={min_ch} max={max_ch}")
    POS_RATIO  = float((pat_labels == 0).sum() / (pat_labels == 1).sum())

    print(f"   {len(valid_pids)} patients | PD={int((pat_labels==1).sum())} "
          f"| HC={int((pat_labels==0).sum())} | segments={n_seg} | channels={max_ch}")
    assert (int((pat_labels == 1).sum()), int((pat_labels == 0).sum())) == (276, 79), \
        "patient counts drifted after segment loading"
    assert n_seg == 7810, f"expected 7810 segments, got {n_seg}"
    print(f"   [checks passed] 276 PD / 79 HC | {n_seg} segments | {max_ch} channels")

    def segments_array(pids):
        segs, counts = [], []
        for pid in pids:
            counts.append(len(patient_segments[pid]))
            for seg in patient_segments[pid]:
                padded = np.zeros((max_ch, SEG_LEN), dtype=np.float32)
                padded[:seg.shape[0], :] = seg
                segs.append(padded)
        return np.array(segs, dtype=np.float32), counts

    def aggregate_patient(rocket_segs, seg_counts, with_std=True):
        fd = rocket_segs.shape[1]
        X = np.zeros((len(seg_counts), fd * 2 if with_std else fd), dtype=np.float32)
        idx = 0
        for i, cnt in enumerate(seg_counts):
            s = rocket_segs[idx:idx + cnt]
            X[i, :fd] = s.mean(axis=0)
            if with_std: X[i, fd:] = s.std(axis=0)
            idx += cnt
        return X

    # ================================================================= MODELS
    def ridge_raw():                       # the proposed model — NO scaler
        return RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced')
    def ridge_scaled():                    # scaling sanity check only
        return Pipeline([('sc', StandardScaler()), ('m', ridge_raw())])
    def lr_model():
        return Pipeline([('sc', StandardScaler()),
                         ('m', LogisticRegression(C=1.0, class_weight='balanced',
                                                  max_iter=2000, random_state=RANDOM_STATE))])
    def rf_model():
        return RandomForestClassifier(n_estimators=300, class_weight='balanced',
                                      n_jobs=-1, random_state=RANDOM_STATE)
    def xgb_model():
        return XGBClassifier(n_estimators=300, max_depth=4, learning_rate=0.05,
                             scale_pos_weight=POS_RATIO, eval_metric='logloss',
                             random_state=RANDOM_STATE, verbosity=0, n_jobs=-1)
    def svm_model():
        # probability=True would run an internal 5-fold Platt calibration on every
        # fit. The decision function is sigmoid-squashed downstream instead, exactly
        # as for Ridge, which is both faster and more consistent across models.
        return Pipeline([('sc', StandardScaler()),
                         ('m', SVC(kernel='rbf', class_weight='balanced',
                                   C=1.0, random_state=RANDOM_STATE))])
    def nms_model():
        return Pipeline([('sc', StandardScaler()),
                         ('lr', LogisticRegression(C=1.0, class_weight='balanced',
                                                   max_iter=1000, random_state=RANDOM_STATE))])


def ridge_raw():
    return RidgeClassifierCV(alphas=np.logspace(-3, 3, 10), class_weight='balanced')
def nms_model():
    return Pipeline([('sc', StandardScaler()),
                     ('lr', LogisticRegression(C=1.0, class_weight='balanced',
                                               max_iter=1000, random_state=RANDOM_STATE))])
sig = lambda z: 1 / (1 + np.exp(-z))

# ================================================================= BOLUM B — kolları ayri sakla
if RUN_PART_B:
    from sktime.transformations.panel.rocket import MiniRocketMultivariate
    outer_cv = StratifiedKFold(n_splits=N_FOLDS, shuffle=True, random_state=RANDOM_STATE)
    inner_cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=RANDOM_STATE)
    folds = []
    for fold, (tr_idx, te_idx) in enumerate(outer_cv.split(valid_pids, pat_labels), 1):
        ck = f'{CKPT_DIR}/fold_{fold}.pkl'
        if os.path.exists(ck):
            folds.append(pickle.load(open(ck, 'rb'))); print(f"FOLD {fold}: checkpoint"); continue
        t0 = time.time()
        tr_pids, te_pids = valid_pids[tr_idx], valid_pids[te_idx]
        y_tr, y_te = pat_labels[tr_idx], pat_labels[te_idx]
        tr_segs, tr_counts = segments_array(tr_pids)
        te_segs, te_counts = segments_array(te_pids)
        rocket = MiniRocketMultivariate(num_kernels=N_KERNELS, random_state=RANDOM_STATE, n_jobs=-1)
        R_tr = rocket.fit_transform(tr_segs); R_tr = R_tr.values if hasattr(R_tr, 'values') else np.array(R_tr)
        R_te = rocket.transform(te_segs);     R_te = R_te.values if hasattr(R_te, 'values') else np.array(R_te)
        del tr_segs, te_segs; gc.collect()
        X_tr = aggregate_patient(R_tr, tr_counts, True); X_te = aggregate_patient(R_te, te_counts, True)
        del R_tr, R_te; gc.collect()
        m = ridge_raw().fit(X_tr, y_tr)
        s_oof = sig(cross_val_predict(ridge_raw(), X_tr, y_tr, cv=inner_cv, method='decision_function'))
        s_te  = sig(m.decision_function(X_te))
        q = nms_model().fit(pat_nms[tr_idx], y_tr)
        n_oof = cross_val_predict(nms_model(), pat_nms[tr_idx], y_tr, cv=inner_cv, method='predict_proba')[:, 1]
        n_te  = q.predict_proba(pat_nms[te_idx])[:, 1]
        pack = dict(fold=fold, y_tr=y_tr, y_te=y_te, s_oof=s_oof, s_te=s_te, n_oof=n_oof, n_te=n_te)
        pickle.dump(pack, open(ck, 'wb')); folds.append(pack)
        print(f"FOLD {fold}/{N_FOLDS} bitti ({(time.time()-t0)/60:.1f} dk)")

    def evaluate(w):
        ba, se, sp, auc = [], [], [], []
        for f in folds:
            oof = w * f['s_oof'] + (1 - w) * f['n_oof']; te = w * f['s_te'] + (1 - w) * f['n_te']
            th = youden_threshold(f['y_tr'], oof); pr = (te >= th).astype(int)
            ba.append(balanced_accuracy_score(f['y_te'], pr) * 100)
            se.append(recall_score(f['y_te'], pr, pos_label=1) * 100)
            sp.append(recall_score(f['y_te'], pr, pos_label=0) * 100)
            auc.append(roc_auc_score(f['y_te'], te) * 100)
        return np.array(ba), np.array(se), np.array(sp), np.array(auc)

    print("\n" + "=" * 74); print("B1) FUZYON AGIRLIGI (w = hareket kolu agirligi)"); print("=" * 74)
    res_w = {}
    ref = evaluate(0.5)[0]
    for w in WEIGHTS:
        ba, se, sp, auc = evaluate(w)
        try: W_, p_ = wilcoxon(ref, ba) if w != 0.5 else (np.nan, 1.0)
        except ValueError: W_, p_ = 0.0, 1.0
        res_w[w] = dict(ba=ba.mean(), ba_sd=ba.std(), se=se.mean(), sp=sp.mean(), auc=auc.mean(), p=float(p_))
        print(f"   w={w:4.2f}  BA {ba.mean():6.2f} ± {ba.std():5.2f}  Se {se.mean():6.2f}  Sp {sp.mean():6.2f}  "
              f"AUC {auc.mean():6.2f}  p(vs 0.5) {p_:.3f}")
    chk = {0.5: 88.16, 0.0: 86.71, 1.0: 77.42}
    ok = all(abs(res_w[w]['ba'] - v) < 0.01 for w, v in chk.items())
    print(f"   [saglama] w=0.5/0/1 yayinlanan A1/A3/A2 ile {'ESLESTI' if ok else 'ESLESMEDI — sayilari kullanmayin'}")

    print("\n" + "=" * 74); print("B2) ANKET-ONCE IKI ASAMALI AKIS"); print("=" * 74)
    TP = FN = TN = FP = 0; n_watch = 0; n_all = 0
    for f in folds:
        yt, no = f['y_tr'], f['n_oof']
        # alt esik: egitimde PD'lerin %95'i bu esigin uzerinde (Se >= 0.95) -> altindakiler negatif
        lo = np.quantile(no[yt == 1], 1 - STAGE1_TARGET)
        # ust esik: egitimde kontrollerin %95'i bu esigin altinda (Sp >= 0.95) -> ustundekiler pozitif
        hi = np.quantile(no[yt == 0], STAGE1_TARGET)
        if hi < lo: lo, hi = hi, lo
        fused_oof = 0.5 * f['s_oof'] + 0.5 * f['n_oof']
        th = youden_threshold(yt, fused_oof)
        nt, st, ye = f['n_te'], f['s_te'], f['y_te']
        pred = np.where(nt < lo, 0, np.where(nt > hi, 1, ((0.5 * st + 0.5 * nt) >= th).astype(int)))
        mid = (nt >= lo) & (nt <= hi)
        n_watch += int(mid.sum()); n_all += len(ye)
        TP += int(((ye == 1) & (pred == 1)).sum()); FN += int(((ye == 1) & (pred == 0)).sum())
        TN += int(((ye == 0) & (pred == 0)).sum()); FP += int(((ye == 0) & (pred == 1)).sum())
    se2, sp2 = TP / (TP + FN) * 100, TN / (TN + FP) * 100
    frac = n_watch / n_all * 100
    print(f"   havuzlanmis Se {se2:.2f}%  Sp {sp2:.2f}%  BA {(se2+sp2)/2:.2f}%  | saat kaydi gereken: "
          f"{n_watch}/{n_all} ({frac:.1f}%)")
    print("   (karsilastirma: tek asamali tam sistem havuzlanmis Se 85.14, Sp 91.14, BA 88.14; saat herkese)")

    out.update({'weights': {str(k): v for k, v in res_w.items()}, 'weights_check_ok': bool(ok),
                'two_stage': dict(se=se2, sp=sp2, ba=(se2 + sp2) / 2, watch_n=n_watch, n=n_all, watch_pct=frac)})
    lo_w = min(res_w[w]['ba'] for w in (0.25, 0.5, 0.75)); hi_w = max(res_w[w]['ba'] for w in (0.25, 0.5, 0.75))
    print("\n" + "=" * 74); print("MAKALEYE / ONLINE RESOURCE'A YAPISTIRILACAK CUMLELER"); print("=" * 74)
    sig_w = [w for w in (0.25, 0.75) if res_w[w]['p'] < 0.05]
    tail = ("and neither 0.25 nor 0.75 differed significantly from equal weighting (Wilcoxon p = "
            f"{res_w[0.25]['p']:.3f} and {res_w[0.75]['p']:.3f}), so the conclusions do not depend on the 50:50 rule."
            if not sig_w else
            "; the weights " + ", ".join(f"{w:.2f} (p = {res_w[w]['p']:.3f})" for w in sig_w) +
            " differed from equal weighting, so the fusion weight matters and must be discussed.  <-- KONTROL EDIN")
    print(f"Fusion weight: with the motion-branch weight varied from 0.25 to 0.75, mean balanced accuracy ranged from "
          f"{lo_w:.2f}% to {hi_w:.2f}%, " + tail)
    print(f"Questionnaire-first: deciding on the questionnaire alone outside two training-derived thresholds and using "
          f"the smartwatch only in between gave a pooled sensitivity of {se2:.2f}% and specificity of {sp2:.2f}%, with "
          f"{frac:.1f}% of participants requiring a smartwatch recording.")
    print(f"Calibration: calibration-in-the-large {citl:+.2f} and calibration slope {slope:.2f} for the fused score.")

json.dump(out, open(f'{RUN_DIR}/weights_triage_check.json', 'w'), indent=2, default=float)
print(f"\nKaydedildi: {RUN_DIR}/weights_triage_check.json")

